# -*- coding: utf-8 -*-
"""German calendar entries. TEXT = {English name: {type, life, patron}}.

The calendar's life is the short one the day panel shows; the long one is in
tools/saint_lives/de.py, and a saint is written in both places at once so that
neither has to be come back to.

Only the fields that have been written are given; anything absent falls back
to the English.
"""
TEXT = {

"Martyr Tathuil, and his sister, Bebaia":
{"type": "Märtyrer · 2. Jh.", "life": "Die heiligen Märtyrer Tathuil und seine Schwester Bebaia litten zu Edessa in den Tagen des Kaisers Hadrian für Christus, um ihrer kühnen und fruchtbaren Predigt des Evangeliums unter den Heiden willen. Tathuil, den einige Berichte Thiphael nennen, hatte sich vom Dienste der Götzen zum wahren Gott gewandt, und durch seine Worte wurden viele zum Glauben gebracht.", "patron": "Angerufen um kühne Predigt; um standhaftes Bekenntnis."},

"Uncovering of the relics of Saint Gurias, first Archbishop of Kazan, and Saint Barsanuphius, Bishop of Tver":
{"type": "Erzbischof · 16. Jh.", "life": "An diesem Tag begeht die Kirche die Auffindung der Reliquien der heiligen Hierarchen Gurij, des ersten Erzbischofs von Kasan, und Warsonofij, des Bischofs von Twer, die im Jahr 1595 zu Kasan geschah, als in dem Kloster, das Warsonofij gegründet hatte, eine neue steinerne Kirche der Verklärung erbaut wurde und man die Gräber der beiden Hierarchen unter der alten hölzernen Kirche fand.", "patron": "Angerufen um die Missionare; um die Lehrer."},

"Greatmartyr Paraskevi of Iconium":
{"type": "Grossmärtyrerin · 3. Jh.", "life": "Die heilige Grossmärtyrerin Paraskewi von Ikonion lebte im dritten Jahrhundert, einer reichen und frommen Familie geboren, die den Freitag des Leidens des Herrn besonders in Ehren hielt und ihre Tochter darum Paraskewi nannte, was Freitag bedeutet. Da sie von Jugend auf die Reinheit liebte, gelobte sie Christus ihre Jungfräulichkeit und gab nach der Entschlafung ihrer Eltern ihr Vermögen den Armen und widmete sich der Erleuchtung der Heiden ihrer Stadt mit dem Lichte des Evangeliums.", "patron": "Angerufen um die Kaufleute; um die Händler."},

"Saint Maximus, Metropolitan of Kyiv":
{"type": "Metropolit · 14. Jh.", "life": "Der heilige Hierarch Maximos, Metropolit von Kyjiw und ganzer Rus, ein Grieche von Geburt, wurde im Jahr 1283 aus Konstantinopel gesandt, um die Kirche der Rus in der tiefen Nacht des tatarischen Joches zu weiden, als Kyjiw, zweimal verwüstet, halb in Trümmern lag und der Hof des Metropoliten selbst inmitten der Öde kaum unterhalten werden konnte.", "patron": "Angerufen um die Hierarchen; um die Hirtensorge in einem verwüsteten Lande."},

"Martyrs Theodore and his son, John, of Kyiv":
{"type": "Laien · 10. Jh.", "life": "Die heiligen Märtyrer Feodor der Waräger und sein Sohn Iwan waren die ersten Märtyrer des Landes der Rus und lebten im zehnten Jahrhundert zu Kyjiw, in den Tagen vor der Annahme des Glaubens durch den Fürsten Wladimir. Feodor, ein Waräger von Abstammung und ein Christ, war mit seinem jungen Sohne Iwan nach Kyjiw zurückgekehrt.", "patron": "Angerufen um das Bekenntnis vor dem Götzendienste."},

"Venerable Auxentius of Bithynia":
{"type": "Einsiedler · 5. Jh.", "life": "Der ehrwürdige Auxentios von Bithynien war ein Syrer von Geburt, der zu Konstantinopel in die Reitergarde des Kaisers Theodosios des Jüngeren aufstieg, ein Höfling, in der Hauptstadt für Frömmigkeit, Bildung und eine von Kirchenmännern gesuchte Weisheit berühmt; und auf der Höhe jenes Ansehens verschwand er, setzte über die Meerenge nach Bithynien und verbarg sich als Einsiedler auf dem Berge Oxia bei Chalkedon, der bis heute den Namen des Berges des heiligen Auxentios trägt.", "patron": "Angerufen um die Vorsänger; um die, welche das Volk singen lehren."},

"Saint Alexander, Patriarch of Constantinople":
{"type": "Patriarch · 4. Jh.", "life": "Der heilige Hierarch Alexander war Bischof unter dem heiligen Metrophanes, dem ersten Patriarchen von Konstantinopel, und wurde wegen des hohen Alters des Metrophanes an dessen Statt zum Ersten Ökumenischen Konzil nach Nicäa gesandt, wo die arianische Irrlehre verurteilt wurde; und nach der Entschlafung des Metrophanes, der ihn in seinem Testamente genannt hatte, folgte Alexander auf dem Throne der Kaiserstadt nach.", "patron": "Angerufen um die Rechtgläubigkeit gegen den Arianismus."},

"Leavetaking of the Nativity of our Lord":
{"type": "Fest", "life": "Die Verabschiedung der Geburt unseres Herrn, die Apodosis, wird am einunddreissigsten Dezember gehalten, und an ihr singt die Kirche das Fest noch einmal in beinahe seiner ganzen festlichen Fülle, denn die Hymnen und der Kanon von Bethlehem kehren mit voller Kraft wieder wie am Feste selbst, so dass die Zeit nicht verklingt, sondern mit einem letzten Aufleuchten endet und die Tür des Festes von innen mit Gesang geschlossen wird.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Gerontius, and those with him, of Saint David Gareji Monastery, Georgia":
{"type": "Mönche · 19. Jh.", "life": "Die heiligen Neumärtyrer des Klosters Dawit-Garedscha in der georgischen Wildnis gaben im Sommer des Jahres 1851 ihr Leben für Christus, als ein Heer aus Dagestan über jene alte Lawra herfiel, die der heilige David gegründet hatte. Die Räuber plünderten das Kloster, schleppten seine heiligen Gefässe und Bücher fort und nahmen die Mönche gefangen und folterten und töteten die standhaftesten unter ihnen.", "patron": "Angerufen um die Mönche; um standhaftes Bekenntnis in der Verfolgung."},

"Martyrs Nikephoros, Antoninus, and Germanus of Caesarea, in Palestine":
{"type": "Märtyrer · 4. Jh.", "life": "Die heiligen Märtyrer Antoninos, Nikephoros und Germanos litten um das Jahr 308 zu Kaisareia in Palästina unter der Regierung des Maximinus, als der Statthalter Firmilian die Verfolgung mit öffentlichen Opfern und Schauspielen gegen die Kirche vorantrieb. Während die heidnischen Riten vor der versammelten Stadt gefeiert wurden, traten die drei Christen aus freiem Willen hervor, tadelten vor dem Statthalter die Verehrung lebloser Götzen und bekannten mit lauter Stimme den einen wahren Gott und seinen Christus.", "patron": "Angerufen um Freimütigkeit vor den Verfolgern."},

"Venerable Sebastian of Poshekhonye":
{"type": "Abt · 16. Jh.", "life": "Der ehrwürdige Sewastian von Poschechonje arbeitete um die Wende des sechzehnten Jahrhunderts im Waldlande jenseits der Wolga, einer aus der stillen Schar von Gründern, welche in den Geschlechtern nach Sergij von Radonesch die Lampe des Einsiedlers Fluss um Fluss nach Norden trugen, bis die ganze Wildnis Russlands mit Klöstern durchzogen war.", "patron": "Angerufen um die Gründer; um die Einsiedler der nördlichen Wälder."},

"Hieromartyr Hermogenes, Patriarch of Moscow, Wonderworker of All Russia":
{"type": "Patriarch, Priestermärtyrer · 17. Jh.", "life": "Der Priestermärtyrer Hermogen, Patriarch von Moskau und ganzem Russland, war der Anker, der eine ertrinkende Nation hielt, und er hielt sie aus einer Hungerzelle. Um das Jahr 1530 geboren, diente er als Gemeindepriester zu Kasan und stand im Jahr 1579 bei jenem Ereignisse, das sein Leben bezeichnete, bei der Auffindung der Kasaner Ikone der Gottesmutter, und trug das neu offenbarte Bild mit eigenen Händen in der Prozession und verfasste später den Bericht ihrer Erscheinung und den Gottesdienst zu ihren Ehren, so dass der Priester der erste Geschichtsschreiber der Ikone wurde.", "patron": "Angerufen um die Patriarchen; um die Verteidiger der Seele eines Volkes."},

"Venerable Irenarchus, Abbot of Solovki":
{"type": "Abt · 17. Jh.", "life": "Der ehrwürdige Irinarch empfing im Kloster von Solowki im fernen Norden Russlands die Mönchsweihe, wo er die Gründer jenes heiligen Ortes, die ehrwürdigen Sosima und Sawwatij, in ihren asketischen Mühen eifrig nachahmte. Im Jahr 1614, nach dem Tode des Abtes Antonij, wurde er zu dessen Nachfolger erwählt, und er leitete die Gemeinschaft treu in einem schweren Zeitalter, da das Kloster von Solowki als ein Bollwerk zur Verteidigung der nördlichen Länder gegen die Schweden und die Dänen stand.", "patron": "Angerufen um die Mönche; um das Mönchsleben."},

"Saints Xanthippi and Polyxeni of Spain":
{"type": "Heilige · 2. Jh.", "life": "Die heiligen Xanthippe und Polyxene waren Schwestern aus Spanien, Schülerinnen der Apostel, die im Jahr 109 in Frieden entschliefen. Xanthippe, die Frau des Probus, eines angesehenen Mannes, empfing den Glauben an Christus durch die Predigt des heiligen Apostels Paulus, als das Evangelium zum ersten Male in den fernen Westen gelangte, und diente mit ihrem Manne dem Herrn in Heiligkeit.", "patron": "Angerufen um die Jüngerinnen; um die bewahrte Keuschheit."},

"Apostle Ananias of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Der heilige Apostel Ananias aus der Zahl der Siebzig war ein Jünger des Herrn, der zu Damaskus wohnte und dem der Herr in einem Gesichte erschien und ihn hiess, in die Gasse zu gehen, die man die Gerade nennt, und dem Saulus von Tarsus die Hände aufzulegen, dem Verfolger der Kirche, der dort blind im Gebete war.", "patron": "Angerufen um die Heilung der Blindheit; um den Gehorsam gegen den Ruf Gottes."},

"Saint Meletius, Archbishop of Khar'kov and Akhtyrsk":
{"type": "Erzbischof · 19. Jh.", "life": "Der heilige Hierarch Meletij, Erzbischof von Charkow und Achtyrka, als Leontowitsch im Poltawaer Lande geboren, war einer jener verborgenen Asketen, welche die synodale Kirche des neunzehnten Jahrhunderts beinahe gegen sich selbst auf ihre Throne erhob. In den Schulen glänzend, lehrte und leitete er an den geistlichen Akademien, war Rektor und Erzieher eines ganzen Geschlechtes von Geistlichen und ging durch das Bischofsamt mehrerer Sitze, ehe er im Jahr 1835 nach Charkow kam.", "patron": "Angerufen um die Hierarchen der Nachtwache; um die Asketen im Amte."},

"Hieromartyr Autonomus, Bishop in Italy":
{"type": "Bischof · 4. Jh.", "life": "Der Priestermärtyrer Autonomos war in den Tagen der Verfolgung Diokletians Bischof in Italien, und da er vor dem Sturme auswich, kam er nach Soreoi in Bithynien, wo ihn ein frommer Mann namens Kornelios aufnahm, und statt in der Sicherheit zu ruhen, gab er sich der unermüdlichen Predigt hin und bekehrte eine so grosse Menge von Heiden, dass er den Kornelios für die von ihm gesammelte Herde zum Diakon und später zum Bischofe weihte.", "patron": "Angerufen um die Missionare; um die missionarische Predigt."},

"Venerable Dositheus, Abbot of Verkneostrov, Pskov":
{"type": "Abt · 15. Jh.", "life": "Der ehrwürdige Dosifej von Werchni Ostrow war ein Schüler des grossen Ältesten Euphrosin von Pskow, unter dessen Führung er in den strengen Überlieferungen der Pskower Wildnis geformt wurde, im Gehorsame, im Fasten und im unaufhörlichen Gebete. Da er einen Ort der Stille suchte, liess er sich auf der Oberen Insel, Werchni Ostrow, unter den Inseln des Pskower Sees nieder, wo die Wasser seine Einsamkeit schirmten.", "patron": "Angerufen um die Mönche; um das Mönchsleben auf den Inseln."},

"Martyr Anastasius the Fuller at Salona in Dalmatia":
{"type": "Märtyrer · 4. Jh.", "life": "Der heilige Märtyrer Anastasios der Walker wurde zu Aquileia in Italien geboren und übte das Handwerk des Walkers zu Salona in Dalmatien in den Tagen der Verfolgung Diokletians. Da er sich weigerte, jenen Glauben zu verbergen, für den andere starben, malte er das Kreuz Christi offen auf die Tür seiner Werkstatt, damit alle Vorübergehenden wüssten, wessen Diener darin arbeitete.", "patron": "Angerufen um die Walker; um die Handwerker."},

"Venerable Sebastian, Abbot of Pshekhonye Monastery, Vologda":
{"type": "Abt · 16. Jh.", "life": "Der ehrwürdige Sewastian von Poschechonje arbeitete um die Wende des sechzehnten Jahrhunderts in den nördlichen Wäldern Russlands und gründete am Flusse Sochot im Lande von Poschechonje gegen Wologda hin eine Einsiedelei der Verklärung des Herrn und sammelte um sich eine Bruderschaft, die auf das strenge gemeinsame Leben gegründet war: nichts wurde besessen, alles geteilt, und jeder Mund von der Arbeit der eigenen Hände genährt.", "patron": "Angerufen um die Weber; um die Mönche, die mit ihren Händen arbeiten."},

"Hieromartyr Silvanus of Gaza":
{"type": "Bischof · 4. Jh.", "life": "Der heilige Priestermärtyrer Silvanos von Gaza war aus jener Stadt gebürtig, zuerst Soldat und hernach Priester, und in seinem Alter wurde er zum Bischofe erhoben und weidete die Kirche von Gaza in den Jahren der grossen Verfolgung. Falsch angeklagt und verurteilt, wurde er zur Zwangsarbeit in den Kupfergruben von Phaeno verurteilt, wo er, betagt und aufgerieben, die erdrückende Mühe mit ungebrochenem Glauben trug, die vielen mit ihm verurteilten Bekenner stärkte und nie aufhörte, sie wie ein wahrer Vater zu unterweisen und zu trösten.", "patron": "Angerufen um die Gefangenen; um die Bergleute."},

"Martyr Arethas and 4,299 Martyrs with him":
{"type": "Märtyrer · 6. Jh.", "life": "Der heilige Märtyrer Arethas und mit ihm viertausendzweihundertneunundneunzig Märtyrer litten im Jahr 523 in der Stadt Nadschran in Arabien, wo der christliche Glaube tiefe Wurzeln geschlagen hatte. Dunaan, der Herrscher der Himjariten und ein Verfolger der Kirche, belagerte die christliche Stadt, und da er sie mit Gewalt nicht nehmen konnte, schwor er falsch, er werde niemandem etwas antun, und stellte die Gläubigen, nachdem man ihn eingelassen hatte, vor die Wahl, Christus zu verleugnen oder zu sterben.", "patron": "Angerufen um die verfolgten Christen; um ganze Städte, die bis in den Tod treu sind."},

"Saint Theodora the Empress":
{"type": "Heilige · 6. Jh.", "life": "Die heilige Kaiserin Theodora, die Gemahlin des heiligen Justinian, wird von der Kirche als eine Büsserin geehrt, welche die Gnade aus der Tiefe auf den Thron erhob. In ihrer Jugend eine Schauspielerin der Theater und eine Frau von berüchtigtem Lebenswandel und eine Zeitlang dem Irrtume der Monophysiten zugeneigt, tat sie von ganzem Herzen Busse.", "patron": "Angerufen um die Busse; um den Schutz der gefallenen Frauen."},

"Glorification of Saint Innocent, Metropolitan of Moscow, Enlightener of the Aleuts, Apostle to the Americas":
{"type": "Metropolit · 19. Jh.", "life": "An diesem Tag begeht die Kirche die Verherrlichung des heiligen Innokentij, des Metropoliten von Moskau, des Erleuchters der Aleuten und Apostels Amerikas, der am sechsten Oktober 1977 auf die Bitte der Orthodoxen Kirche in Amerika von der Russischen Orthodoxen Kirche unter die Heiligen aufgenommen wurde. Er wurde im Jahr 1797 als Iwan Popow-Weniaminow in einem sibirischen Dorfe geboren.", "patron": "Angerufen um die Missionare; um die Übersetzer."},

"Martyrs Akepsimas and Aithalas of Egypt":
{"type": "Märtyrer · 4. Jh.", "life": "Die heiligen Märtyrer Akepsimas und Aithalas litten zu Arbela im Lande Persien in jenen Verfolgungen, welche die persischen Könige gegen die Kirche erhoben, als die Magier die Christen des Reiches drängten, die Sonne und das Feuer zu verehren, und ihre Weigerungen mit Blut besiegelten. Die Überlieferung jener leidenden Kirche berichtet, dass Aithalas selbst zu Arbela ein Priester der Götzen gewesen war, ehe die Gnade Christi ihn fand, so dass die Verfolger einen ihrer eigenen Altardiener an das Evangelium verloren, eine Wunde, die sie nie verziehen.", "patron": "Angerufen um die Kirche unter Persien; um die bekehrten Götzenpriester."},

"Finding of the relics of Monastic Martyr Adrian of Poshekhonsk, Yaroslavl":
{"type": "Abt · 16. Jh.", "life": "An diesem Tag begeht die Kirche die Auffindung der Reliquien des Mönchsmärtyrers Adrian von Poschechonje, die am neunzehnten November 1625 geschah. Der ehrwürdige Adrian, ein Mönch und begabter Ikonenmaler, in der Überlieferung der grossen nördlichen Klöster geformt, hatte mit einem Mitasketen in den Wäldern von Poschechonje im Jaroslawler Lande ein Kloster der Entschlafung der Allheiligen Gottesgebärerin gegründet und arbeitete dort in Fasten, Gebet und im Malen heiliger Ikonen und sammelte um die Kirche in der Wildnis eine Bruderschaft.", "patron": "Angerufen um die Ikonenmaler; um die Mönche."},

"Saint Gurias, Archbishop of Kazan":
{"type": "Erzbischof · 16. Jh.", "life": "Der heilige Hierarch Gurij, der erste Erzbischof von Kasan, in der Welt Grigorij Rugotin, wurde zu Radonesch einer armen Familie von Hofleuten geboren und diente in seiner Jugend als Verwalter der Güter des Fürsten Iwan Penkow; und dort schmiedete der Neid der Menschen seine Heiligkeit, denn man verleumdete ihn als Ehebrecher mit der Frau des Fürsten, und der Fürst, der die Lüge glaubte, warf ihn in eine unterirdische Zelle, wo der Unschuldige zwei Jahre lang im Dunkeln auf Stroh sass und man ihm Hafer und Wasser hinabwarf.", "patron": "Angerufen um die Gefangenen; um die Lehrer der Kinder."},

"First Translation of the relics of Saint Herman, Archbishop of Kazan":
{"type": "Erzbischof · 16. Jh.", "life": "Der heilige Hierarch German, Erzbischof von Kasan, wurde zu Stariza aus dem adligen Geschlechte der Sadyrew-Polew geboren, und da er im Kloster von Wolokolamsk die Mönchsweihe empfing, wurde er in der Schule des ehrwürdigen Iosif geformt und für seine Gelehrsamkeit, sein asketisches Leben und seine Arbeit am Abschreiben von Büchern bekannt. Als die neu eroberten Länder von Kasan dem Evangelium geöffnet wurden, wurde er mit dem ehrwürdigen Gurij zu ihrer Erleuchtung gesandt und gründete zu Swijaschsk das Kloster der Entschlafung der Gottesmutter, das zum Mittelpunkte der Mission unter den Völkern an der Wolga wurde.", "patron": "Angerufen um die Missionare; um die Erleuchtung der Länder von Kasan."},

"Venerable Longinus the Gatekeeper of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Der ehrwürdige Longin der Pförtner von den Höhlen von Kyjiw erfüllte seinen mönchischen Gehorsam an den Toren der grossen Lawra, und sein inständiges Gebet und seine demütige Arbeitsliebe wurden vom Herrn mit der Gabe der Unterscheidung belohnt, so dass der Pförtner des Klosters ein Pförtner der Seelen wurde.", "patron": "Angerufen um die Pförtner; um die Türhüter."},

"Hieromartyrs John the Bishop and Jacob (James) the Presbyter, of Persia":
{"type": "Märtyrer · 4. Jh.", "life": "Die Priestermärtyrer Johannes der Bischof und Jakob der Presbyter, der Eiferer genannt, litten in Persien unter der Regierung des Königs Schapur des Zweiten, des grossen Verfolgers der Kirche jenseits der östlichen Grenze des Reiches. Da sie den wahren Glauben mit Freimut predigten, zogen sie viele fromme Seelen zu Christus, und das Wachstum der Kirche durch ihre Arbeit brachte sie vor den König.", "patron": "Angerufen um die Kirche unter der persischen Verfolgung."},

"Leavetaking of the Nativity of the Mother of God":
{"type": "Fest", "life": "Dies ist die Verabschiedung des Festes der Geburt der Allheiligen Gottesgebärerin, der letzte Tag jener Festzeit, in welcher die Kirche die Geburt der Gottesmutter feiert. An diesem Tage werden die Hymnen und die Lesungen des Festes noch einmal in ihrer Fülle gesungen, und die Gläubigen nehmen von dem Feste Abschied, nachdem sie mit seiner Freude erfüllt worden sind.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Uncovering of the relics of Saint Vsévolod (Gabriel) of Pskov":
{"type": "Fürst · 12. Jh.", "life": "An diesem Tag begeht die Kirche die Auffindung der Reliquien des heiligen Fürsten Wsewolod von Pskow, in der heiligen Taufe Gabriel genannt, die im Jahr 1192 geschah. Als Enkel Wladimir Monomachs und Sohn des heiligen Mstislaw des Grossen herrschte Wsewolod von Jugend auf über Nowgorod mit Gerechtigkeit und offenen Händen, baute Kirchen, speiste in der Hungersnot die Armen auf eigene Kosten und führte die Heere der Stadt.", "patron": "Angerufen um die Herrscher; um die Erbauer."},

"Venerable Arethus the Recluse of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Der ehrwürdige Arefa der Klausner von den Höhlen von Kyjiw war in der Welt reich gewesen, und auch im Kloster hielt ihn die Leidenschaft des Geizes, denn er bewahrte in seiner Zelle einen verborgenen Schatz und gab den Armen nichts und gönnte selbst sich nichts. Als Diebe seinen Hort stahlen, geriet Arefa in solchen Kummer, dass er wider Gott murrte und Unschuldige beschuldigte, und da er in seiner Bedrängnis dem Tode nahe kam, lag er da wie ein schon Gerichteter.", "patron": "Angerufen um die Befreiung von der Geldliebe; um die Danksagung im Verluste."},

"Saint Aidan, Bishop of Lindesfarne":
{"type": "Bischof · 7. Jh.", "life": "Der heilige Hierarch Aidan, der Erleuchter von Northumbrien, wurde in Irland geboren und wurde Mönch auf der Insel Iona, im Kloster des heiligen Columba, wo er für seine strenge Askese und seine Sanftmut bekannt war. Als Oswald, der christliche König von Northumbrien, um einen Bischof bat, der seinem noch heidnischen Volke das Evangelium bringe, wurde Aidan gesandt, und er richtete seinen Bischofssitz auf der Insel Lindisfarne nahe der königlichen Burg ein und wählte einen stillen Ort abseits der Welt.", "patron": "Angerufen um die Missionare; um die missionarische Erleuchtung."},

"Synaxis of the Hierarchs of Kazan":
{"type": "Synaxis", "life": "An diesem Tag hält die Kirche die Synaxis der Hierarchen von Kasan und ehrt gemeinsam jene heiligen Bischöfe, welche die Kirche in den Ländern an der Wolga nach dem Falle des Khanates pflanzten und begossen: den heiligen Gurij, den ersten Erzbischof von Kasan und Apostel der neu gewonnenen Gegend.", "patron": "Angerufen um die Erleuchtung der Länder von Kasan."},

"Martyr Sophia and her three daughters at Rome":
{"type": "Märtyrer · 2. Jh.", "life": "Die heilige Märtyrerin Sophia und ihre drei jungen Töchter Glaube, Hoffnung und Liebe litten um das Jahr 137 zu Rom unter der Regierung des Kaisers Hadrian. Sophia, deren Name Weisheit bedeutet, war eine christliche Witwe, die ihre Töchter nach den drei grossen Tugenden benannt und sie in brennender Liebe zu Christus erzogen hatte.", "patron": "Angerufen um die Mütter."},

"Virgin Martyr Julia of Carthage":
{"type": "Jungfrau", "life": "Die heilige Julia war eine adlige und fromme Jungfrau von Karthago in Nordafrika, die, als die Stadt ihren Feinden anheimfiel, verschleppt und in die Sklaverei verkauft wurde. Sie diente ihrem Herrn treu und demütig und gab alle ihre freien Stunden dem Gebete und dem Fasten und wollte sich von ihrem Glauben an Christus nicht trennen lassen.", "patron": "Angerufen um die Gefangenen; um die Reinheit."},

"Saint John [Maximovitch], Archbishop of Shanghai and San Francisco":
{"type": "Erzbischof · 20. Jh.", "life": "Der heilige Hierarch Johannes, Erzbischof von Schanghai und San Francisco, einer der grossen Wundertäter des zwanzigsten Jahrhunderts, wurde im Jahr 1896 als Michail Maximowitsch im Gebiete von Charkiw einer frommen adligen Familie geboren. Auf der Flucht vor der bolschewistischen Umwälzung studierte er zu Belgrad Theologie und wurde im Jahr 1926 mit dem Namen Johannes zum Mönche geweiht, und im Jahr 1934 wurde er zum Bischofe geweiht und nach Schanghai gesandt.", "patron": "Angerufen um die Flüchtlinge und die Vertriebenen; um die Kranken."},

"Saint Frumentius, Archbishop of Abyssinia, Ethiopia":
{"type": "Erzbischof · 4. Jh.", "life": "Der heilige Hierarch Frumentios, Erzbischof von Abessinien und Erleuchter Äthiopiens, wurde zu Tyrus geboren; und als er noch ein Knabe war und mit seinem Verwandten Aedesius in der Begleitung eines Gelehrten das Rote Meer befuhr, warf ihn die Vorsehung Gottes in die seltsamste aller Sendungen, denn als das Schiff die afrikanische Küste berührte, wurde die Mannschaft erschlagen, und nur die beiden Knaben wurden verschont und an den königlichen Hof von Aksum gebracht.", "patron": "Angerufen um die Missionare; um die Erzieher."},

"Passion-Bearer Gleb (in Baptism David)":
{"type": "Fürst · 11. Jh.", "life": "Der heilige Leidensdulder Gleb, in der heiligen Taufe David genannt, war unter den ersten Heiligen, die im Lande der Rus verherrlicht wurden, und litt im Jahr 1015 zusammen mit seinem Bruder Boris durch die Hand ihres Bruders Swjatopolk des Verfluchten. Als ihr Vater, der Grossfürst Wladimir, gestorben war, liess Swjatopolk, der Boris schon ermordet hatte, dem jungen Gleb sagen, sein Vater sei krank, und rief ihn nach Kyjiw und zog mit dieser List einen weiteren rechtmässigen Erben in den Tod.", "patron": "Angerufen um die unschuldig Leidenden; um den Frieden unter den Verwandten."},

"Holy and Righteous Ancestors of God, Joachim and Anna":
{"type": "Heilige · 1. Jh.", "life": "Am Tage nach der Geburt der Gottesgebärerin hält die Kirche die Synaxis der heiligen und gerechten Gotteseltern Joachim und Anna und versammelt sich, um jene zu ehren, durch die der Welt die Gottesmutter gegeben wurde. Joachim war aus dem königlichen Geschlechte Davids und Anna aus der priesterlichen Abstammung Aarons, und sie lebten in Gerechtigkeit und gaben ein Drittel ihres Einkommens Gott und ein Drittel den Armen.", "patron": "Angerufen um die kinderlosen Ehepaare; um die Grosseltern."},

"Righteous James the Brother of the Lord":
{"type": "Bischof · 1. Jh.", "life": "Des heiligen und gerechten Jakobus, des Bruders des Herrn, wird in den Tagen nach der Geburt Christi zusammen mit Joseph dem Verlobten, seinem Vater, und David dem Könige gedacht, in der Synaxis der Verwandten des Herrn nach dem Fleische; sein volles Gedächtnis als Apostel, als erster Bischof von Jerusalem und als Märtyrer hält die Kirche im Oktober, und hier gedenkt sie seiner gerade als eines Angehörigen.", "patron": "Angerufen um die Bischöfe; um die, welche die Gottesdienste ordnen."},

"Venerable Nicholas Sviatosha Prince of Chernihiv, and Wonderworker of the Kyiv Near Caves":
{"type": "Fürst · 12. Jh.", "life": "Der ehrwürdige Nikolaus Swjatoscha, Fürst von Tschernihiw und Wundertäter der Höhlen von Kyjiw, war ein Urenkel Jaroslaws des Weisen und ein Sohn des Fürsten Dawid von Tschernihiw und herrschte als Fürst von Luzk und hatte Frau und Kinder. Am siebzehnten Februar 1106 verliess er Familie und Fürstentum und wurde im Höhlenkloster von Kyjiw zum Mönche geweiht, als der erste unter den Fürsten der Rus, der die Krone gegen die Kapuze vertauschte.", "patron": "Angerufen um die Pförtner; um die Gärtner."},

"Martyrs Eustratius, Auxentius, Eugene, Mardarius, and Orestes, at Sebaste":
{"type": "Märtyrer · 3. Jh.", "life": "Die heiligen Märtyrer Eustratios, Auxentios, Eugenios, Mardarios und Orestes, die Fünf Gefährten, leuchteten in der Verfolgung des Diokletian und des Maximian um das Jahr 296 wie fünf Sterne über Armenien, und ihr Kampf ist eine Kette freier Bekenntnisse, denn ein jeder trat ungezwungen hervor. Auxentios, ein Priester von Arauraka, wurde als erster von den Statthaltern Lysias und Agricolaus ergriffen.", "patron": "Angerufen um die Soldaten; um die Archivare."},

"Venerable Job of Ushchelsk":
{"type": "Priestermönch · 17. Jh.", "life": "Der ehrwürdige Iow, der Schluchtbewohner genannt, war ein Mönch des Klosters von Solowki, der im Jahr 1608 vom Metropoliten Isidor von Nowgorod zum Priestermönch geweiht wurde. Im Jahr 1614 wurde er in die ferne nördliche Gegend der Mesen gesandt, und dort, an einem Orte namens Uschtschelje, wo der Fluss Esega auf die Mesen trifft, gründete er eine Einsiedelei und errichtete eine Kirche und sammelte in jener entlegenen Wildnis eine kleine Bruderschaft um sich.", "patron": "Angerufen um die Mönche."},

"Forefeast of the Nativity of our Lord":
{"type": "Fest", "life": "Die Vorfeier der Geburt unseres Herrn umfasst die Tage vom zwanzigsten Dezember bis zur Vigil des Festes, und in ihnen macht sich die Kirche bereit wie Bethlehem in den Hymnen. Die Gottesdienste wenden sich ganz der Höhle zu: bei den Stichiren eines jeden Tages erschallt der Ruf, Bethlehem, bereite dich.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyrs Pamphilius the Presbyter, Valens the Deacon, and those with them, at Caesarea in Palestine":
{"type": "Priestermärtyrer · 4. Jh.", "life": "Die heiligen Märtyrer Pamphilos der Presbyter, Valens der Diakon, Paulus, Porphyrios, Seleukos, Theodulos, Julian und die fünf ägyptischen Jünglinge Elias, Jeremias, Jesaja, Samuel und Daniel litten um das Jahr 309 zu Kaisareia in Palästina, im siebten Jahre der grossen Verfolgung, und ihren Kampf zeichnete ein Augenzeuge auf, der sie liebte, der Geschichtsschreiber Eusebios, der ihre Schar ein vollkommenes Bild einer ganzen Kirche nannte.", "patron": "Angerufen um die Gelehrten; um die Abschreiber."},

"Repose of Venerable Cornelius of Pereyaslavl":
{"type": "Mönch · 17. Jh.", "life": "Der ehrwürdige Kornilij von Pereslawl, in der Welt Konon genannt, war der Sohn eines Kaufmannes von Rjasan. In seiner Jugend verliess er das Haus seiner Eltern und diente fünf Jahre als Novize unter dem Ältesten Pawel in der Wüste von Lukianowo und ging hernach in das Kloster der heiligen Boris und Gleb auf den Sanden zu Pereslawl über.", "patron": "Angerufen um die Mönche; um das Schweigen."},

"Martyrs Paul and Juliana of Syria":
{"type": "Märtyrer · 3. Jh.", "life": "Die heiligen Märtyrer Paulus und seine Schwester Juliana litten unter der Regierung des Kaisers Aurelian für Christus in der phönizischen Stadt Ptolemais. Als der Kaiser in jene Stadt kam, machte Paulus, der ihm in der Menge begegnete, das Kreuzzeichen, und dafür wurde er ergriffen und ins Gefängnis geworfen, und am nächsten Tage vor Gericht gestellt, bekannte er seinen Glauben an Christus offen und ohne Furcht, wofür er grausam gefoltert wurde.", "patron": "Angerufen um die Reinheit; um standhaftes Bekenntnis."},

"Martyrs Timothy, Agapius, and Thekla, of Palestine":
{"type": "Märtyrer · 4. Jh.", "life": "Die heiligen Märtyrer Timotheos, Agapios und Thekla litten im Jahr 304 in der Verfolgung unter Diokletian für Christus. Der heilige Timotheos war aus Kaisareia in Palästina gebürtig, hatte die heiligen Schriften studiert und wurde, da ihm die Gabe der Rede verliehen war, ein Lehrer des christlichen Glaubens. Verhaftet und aufgefordert, Christus zu verleugnen und den Götzen zu opfern, weigerte er sich mit Festigkeit und wurde, nachdem er grausame Martern ertragen hatte, bei lebendigem Leibe verbrannt.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Venerable Sabbatius, Wonderworker of Solovki":
{"type": "Mönch · 15. Jh.", "life": "Der ehrwürdige Sawwatij, der Wundertäter von Solowki, war ein Mönch von Walaam am Ladogasee, wo seine Demut und die Strenge seines Lebens ihm eine solche Verehrung der Brüder eintrugen, dass der Heilige das Lob der Menschen floh und eine Wildnis suchte, wo ihn niemand kennen würde. Da er von der unbewohnten Insel Solowki im Weissen Meere hörte, zwei Tagesfahrten vom Ufer entfernt, machte er sich dorthin auf.", "patron": "Angerufen um die Mönche; um die äusserste Einsamkeit."},

"Saint Theodota, mother of the Unmercenaries Cosmas and Damian":
{"type": "Heilige · 3. Jh.", "life": "Die heilige Theodota, die Mutter der heiligen uneigennützigen Ärzte Kosmas und Damian aus Kleinasien, war eine christliche Frau jener Gegend, deren heidnischer Mann starb, als ihre Kinder noch klein waren, so dass sie sie allein aufziehen musste. Sie erzog ihre Söhne in christlicher Frömmigkeit und lehrte sie durch ihr eigenes Beispiel und dadurch, dass sie ihnen aus den heiligen Schriften vorlas.", "patron": "Angerufen um die Mütter; um die Witwen."},

"Venerable Euthymius the New of Thessalonica, and Monk of Mount Athos":
{"type": "Diakon · 9. Jh.", "life": "Der ehrwürdige Euthymios der Neue von Thessaloniki wurde im Jahr 824 im Dorfe Opso in Galatien geboren und Nikitas genannt; in seiner Jugend im Gehorsam gegen seine Mutter verheiratet und mit einer Tochter beschenkt, zog er nach deren Geburt fort, nachdem er für sein Haus gesorgt hatte, und empfing auf dem Berge Olymp in Bithynien die Mönchsweihe mit dem Namen Euthymios, wo er viele Jahre lang im Gehorsame und in der Stille geformt wurde.", "patron": "Angerufen um die Mönche; um die Wegbereiter des Athos."},

"Right-believing Princess Juliana of Vyazma":
{"type": "Fürstin · 15. Jh.", "life": "Die heilige rechtgläubige Fürstin Juliana von Wjasma, eine keusche Leidensdulderin, war die Gemahlin des Fürsten Simeon Mstislawitsch von Wjasma und teilte seine Verbannung, als Smolensk und Wjasma an Litauen fielen und die enteigneten Fürsten zu Torschok im Dienste des Fürsten Jurij von Smolensk Zuflucht nahmen. Dort wurde ihre Schönheit zu ihrem Kreuze: Jurij, von einer Leidenschaft für die Frau seines eigenen treuen Gefährten entbrannt und ihre Tugend unbeweglich findend, fasste einen bösen Entschluss.", "patron": "Angerufen um die Ehefrauen; um die Frauen in Gefahr."},

"Hieromartyr Phocas, Bishop of Sinope":
{"type": "Bischof · 2. Jh.", "life": "Der Priestermärtyrer Phokas, Bischof von Sinope am Schwarzen Meere, führte von Jugend auf ein tugendhaftes Leben und bekehrte als Bischof seiner Vaterstadt viele Heiden zum Glauben an Christus. In der Verfolgung unter dem Kaiser Trajan forderte der Statthalter von ihm, den Herrn zu verleugnen, und als der Heilige sich weigerte, wurde er heftigen Martern unterworfen und zuletzt in ein geheiztes Bad eingeschlossen, wo er im Jahr 117 die Krone des Martyriums empfing.", "patron": "Angerufen um die Seeleute; um den Schutz vor dem Feuer."},

"The Entry of the Most Holy Mother of God into the Temple":
{"type": "Fest", "life": "Der Einzug in den Tempel feiert, dass das Kind Maria von seinen Eltern Joachim und Anna im Alter von drei Jahren in den Tempel zu Jerusalem gebracht wurde, in Erfüllung des Gelübdes, das sie getan hatten, es Gott zu weihen. Nach der Überlieferung der Kirche wurde sie vom Priester Sacharja empfangen und in das Allerheiligste geführt, wo sie bis zu ihrer Jugend im Gebete lebte.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyrs Philemon, Apollonios, Arrian, and Theonas of Alexandria":
{"type": "Märtyrer · 3. Jh.", "life": "Die heiligen Märtyrer Philemon, Apollonios, Arrianos und Theonas litten um das Jahr 286 in Ägypten, und ihre Geschichte ist ein Staffellauf der Gnade, in dem ein jeder Läufer die Krone dem nächsten weiterreicht. Apollonios, ein Vorleser der Kirche von Antinoe, der die Folter fürchtete, dingte den Heiden Philemon, einen in ganz Ägypten berühmten Flötenspieler, dass er sich in seine Kleider hülle und in seinem Namen das Opfer darbringe.", "patron": "Angerufen um die Musiker; um die Flötenspieler."},

"Kazan Icons of the Mother of God in Kazan, St. Petersburg, and Moscow":
{"type": "Ikone · 16. Jh.", "life": "Dieses Fest begeht die Erscheinung der Kasaner Ikone der Gottesmutter, die im Jahr 1579 in der Stadt Kasan auf wunderbare Weise offenbart wurde, als die Gottesgebärerin ein junges Mädchen in einem Gesichte an jene Stelle wies, wo die Ikone in der Asche eines abgebrannten Hauses verborgen lag.", "patron": "Angerufen um den Schutz Russlands; um die Ehe und die Familien."},

"Saint Paul the New, Patriarch of Constantinople":
{"type": "Patriarch · 8. Jh.", "life": "Der heilige Hierarch Paulus, der Neue genannt, war ein Zypriote von Geburt, der unter der Regierung der bilderfeindlichen Kaiser Patriarch von Konstantinopel wurde, ein tugendhafter und frommer Mann, aber von zaghaftem Herzen. Da er die Leiden sah, welche die Rechtgläubigen um der heiligen Ikonen willen ertrugen, verbarg er zuerst seine eigene Überzeugung und ging mit den Bilderfeinden mit, aber sein Gewissen liess ihm keine Ruhe.", "patron": "Angerufen um die Busse; um die Verehrung der Ikonen."},

"Finding of the relics of Righteous Saint Νikόdēmos":
{"type": "Gerechter · 1. Jh.", "life": "Der heilige Nikodemus war ein Pharisäer und ein Oberster der Juden, der bei Nacht zum Herrn Jesus kam, wie das Evangelium des Johannes berichtet, und von ihm von der neuen Geburt aus Wasser und Geist hörte. Obwohl er zuerst aus Furcht vor den Juden heimlich kam, verteidigte er den Erlöser vor dem Hohen Rate, und nach der Kreuzigung kam er offen mit Joseph von Arimathäa und brachte eine Mischung von Myrrhe und Aloe und half, den Leib des Herrn zu salben und zu bestatten.", "patron": "Angerufen um die heimlichen Jünger; um die Sucher der Wahrheit."},

"Venerable Romanus the Melodist, “Sweet-Singer”":
{"type": "Diakon · 6. Jh.", "life": "Der ehrwürdige Romanos der Melode, der Süsse Sänger der Kirche, wurde zu Emesa in Syrien geboren und diente in den Tagen des Kaisers Anastasios zuerst zu Beirut und dann zu Konstantinopel als Diakon, tat Dienst an der Kirche der Gottesgebärerin zu Kyros und hielt nachts Wache zu Blachernae.", "patron": "Angerufen um die Sänger; um die Hymnendichter."},

"20,000 Martyrs of Nicomedia":
{"type": "Märtyrer · 4. Jh.", "life": "Die heiligen zwanzigtausend Märtyrer von Nikomedien litten im Jahr 302, als der Kaiser Maximian, der erfuhr, wie mächtig der Glaube in seiner eigenen Hauptstadt gewachsen war, beschloss, die Christen der Stadt in einer einzigen Nacht zu vernichten, und dafür jene Nacht wählte, in der sie alle versammelt sein würden: das Fest der Geburt Christi.", "patron": "Angerufen um die bedrohten Gemeinden; um die Taufbewerber."},

"Holy Martyr and Confessor Michael and his councilor, Theodore, Wonderworkers of Chernihiv":
{"type": "Fürst · 13. Jh.", "life": "Der heilige Märtyrer und Bekenner Michail, Fürst von Tschernigow, und sein treuer Ratgeber, der Bojar Feodor, litten im Jahr 1246 bei der Goldenen Horde. Fürst Michail, der von Kindheit an für Frömmigkeit und Sanftmut bekannt war, hatte in den Jahren des mongolischen Sturmes über Nowgorod und Kyjiw geherrscht; und als er zur Horde gerufen wurde, um von Batu das Recht auf sein Fürstentum zu empfangen, verlangten die Heiden, dass er zuvor zwischen den Feuern hindurchgehe.", "patron": "Angerufen um die Herrscher; um die Ratgeber."},

"Venerable Anthousa the Confessor":
{"type": "Äbtissin · 8. Jh.", "life": "Die ehrwürdige Anthusa die Bekennerin lebte im achten Jahrhundert zu Mantineia in Paphlagonien, im Zeitalter des bilderfeindlichen Kaisers Konstantin Kopronymos, und wurde von ihren frommen Eltern Strategios und Febronia in der Gottesfurcht erzogen. Sie ergriff das Mönchsleben und wurde Äbtissin einer Gemeinschaft von Nonnen, und als der Kaiser gegen die heiligen Ikonen Krieg führte, stand sie fest als eine Bekennerin des Glaubens und weigerte sich, ihre Verehrung aufzugeben.", "patron": "Angerufen um die Nonnen; um die Verehrung der Ikonen."},

"Righteous Eudocimus of Cappadocia":
{"type": "Heerführer · 9. Jh.", "life": "Der gerechte Eudokimos, aus Kappadokien gebürtig, lebte im neunten Jahrhundert unter der Regierung des Kaisers Theophilos und war der Sohn frommer und vornehmer Eltern, des Basileios und der Eudokia, die ihn in der Zucht und Ermahnung des Herrn erzogen. Seinem Namen getreu, der den Wohlbeleumundeten bezeichnet, hatte er in jeder Tugend Erfolg und widmete sein Leben dem Wohlgefallen Gottes und dem Dienste am Nächsten.", "patron": "Angerufen um den häuslichen Herd; um die Waisen und die Witwen."},

"Martyr Lucian the Presbyter of Antioch":
{"type": "Priester · 4. Jh.", "life": "Der heilige Märtyrer Lukian, Presbyter von Antiochien, wurde zu Samosata geboren und gab, früh verwaist, sein Erbe den Armen und sich selbst der heiligen Gelehrsamkeit und wurde Presbyter zu Antiochien und der Meister ihrer berühmten Schule der Schriften, wo er an der Berichtigung des griechischen Textes des Alten Testamentes gegen die eingeschlichenen Verderbnisse arbeitete und viele Schüler im genauen Studium heranbildete.", "patron": "Angerufen um die Gelehrten; um die Übersetzer."},

"Venerable Dositheus of Palestine, disciple of Venerable Abba Dorotheus":
{"type": "Mönch · 6. Jh.", "life": "Der ehrwürdige Dositheos von Palästina ist der Beweis der Kirche dafür, dass der Gehorsam allein heiligen kann, und sein Ältester Dorotheos von Gaza hat ihn als das erste und liebste Beispiel seiner Lehre bewahrt. Als Page im Hause eines Feldherrn, jung, verwöhnt und Gottes so unkundig, dass er den Glauben nie hatte predigen hören, besuchte Dositheos mit dem Hause Jerusalem und stand vor einer Ikone des furchtbaren Gerichtes.", "patron": "Angerufen um die Novizen; um die Kranken, die nicht fasten können."},

"Venerable Paisios the Athonite (1994)":
{"type": "Mönch (Ältester) · 20. Jh.", "life": "Der ehrwürdige Paisios vom Heiligen Berge, einer der geliebtesten Ältesten des zwanzigsten Jahrhunderts, wurde im Jahr 1924 als Arsenios Esnepidis zu Pharasa in Kappadokien geboren und vom heiligen Arsenios von Kappadokien getauft, der voraussagte, dass das Kind ein Mönch werden würde. Als Säugling beim Bevölkerungsaustausche nach Griechenland gebracht, wuchs er zu Konitsa auf, arbeitete als Zimmermann und diente im Heere als Funker.", "patron": "Angerufen um die Mönche; um die Bedrängten."},

"Venerable Polycarp of Briansk":
{"type": "Abt · 17. Jh.", "life": "Der ehrwürdige Polikarp von Brjansk wirkte um die Wende des siebzehnten Jahrhunderts, in jenen Jahren, da die Wirrenzeit über das russische Land hereinbrach, und seine Heiligkeit nahm jene Gestalt an, welche das Zeitalter am nötigsten hatte, den Wiederaufbau eines Hauses Gottes inmitten des allgemeinen Ruins. Die Überlieferung von Brjansk hält fest, dass er ein Mann von hoher Geburt war, aus dem fürstlichen Dienstadel.", "patron": "Angerufen um die Büsser von Rang; um die Erneuerer der Klöster."},

"Martyr Christodoulos":
{"type": "Märtyrer · 4. Jh.", "life": "Des heiligen Märtyrers Christodulos wird an diesem Tage unter den Zeugen der frühen Kirche gedacht, und sein Name ist seine Lebensbeschreibung: Christodulos, der Knecht Christi, jener Titel, den die Märtyrer der ersten Jahrhunderte vor den Gerichten als ihre ganze rechtliche Person in Anspruch nahmen und mit dem sie Familie, Stadt und Stand in der einen Treue hinwegfegten, die das Reich weder besteuern noch befehlen konnte.", "patron": "Angerufen um alle, die den Namen Christi tragen; um den bis ans Ende bekannten Namen."},

"The Nativity of our Lord God and Savior Jesus Christ":
{"type": "Fest", "life": "Die Geburt Christi feiert die Geburt des Sohnes Gottes im Fleische, geboren von der Jungfrau Maria in einer Höhle bei Bethlehem und in eine Krippe gelegt, weil in der Herberge kein Raum war. Die Kirche verkündet dies als das Geheimnis der Menschwerdung: das ewige Wort, durch das alles gemacht ist, tritt in das Seine ein.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Hieromartyr Kuksha and Venerable Pimen of the Kyiv Near Caves":
{"type": "Priestermönch · 12. Jh.", "life": "Der Priestermärtyrer Kuksha war ein Mönch der Höhlen von Kyjiw, der auszog, um den Wjatitschen das Evangelium zu predigen, einem wilden heidnischen Volke, das in den Wäldern am Flusse Oka wohnte und, wie der Chronist sagte, nur für den heutigen Tag lebte und vom Gesetze Gottes nichts wusste.", "patron": "Angerufen um die Missionare; um die missionarische Erleuchtung."},

"Martyr Troadius of Neocaesarea":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Troadios litt zu Neokaisareia unter Kaiser Decius. Der heilige Gregorios der Wundertäter, der damals die Kirche von Neokaisareia leitete, sah im Geist sein Leiden und seinen Tod."},

"Martyrs Maximus, Theodotus, Hesychius, and Asclepiodota, of Adrianopolis":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Maximos, Theodotos, Hesychios und die Märtyrerin Asklepiodote litten zu Adrianopolis in Thrakien unter Kaiser Maximian."},

"Venerable Titus the Soldier, of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Titos war Kriegsmann, ehe er Mönch im Höhlenkloster zu Kiew wurde, und wird in den Fernen Höhlen bestattet."},

"Venerable Savva the Sanctified":
{"type": "Archimandrit · 6. Jh.", "life": "Ehrwürdiger Sabbas der Geheiligte wurde zu Mutalaska in Kappadokien geboren, kam mit achtzehn Jahren nach Palästina und gründete im Tal des Kedron die Grosse Lawra, die seinen Namen trägt."},

"12 Greeks who built the Dormition Cathedral in the Kyiv Caves, Far Caves, Lavra":
{"type": "Baumeister, Mönche · 11. Jh.", "life": "Zwölf griechische Baumeister, welche die Dormitio-Kirche des Kiewer Höhlenklosters errichteten und darauf selbst dort Mönche wurden. Sie ruhen in den Fernen Höhlen."},

"Saint Simeon Stylites, the Elder":
{"type": "Mönch · 5. Jh.", "life": "Ehrwürdiger Symeon der Stylit stand siebenunddreissig Jahre auf einer Säule bei Antiochien und ist der erste der Säulensteher."},

"Apostle Philip of the Seventy, One of the Seven Deacons":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Philippos, einer der sieben Diakone, taufte den Kämmerer der Königin von Äthiopien und verkündete das Evangelium zu Samaria und Kaisareia."},

"7 Holy Maccabee Martyrs":
{"type": "Jünglinge · 2. Jh. v. Chr.", "life": "Die sieben heiligen Makkabäer-Märtyrer, ihre Mutter Solomone und ihr Lehrer Eleasar litten zu Antiochien unter Antiochos Epiphanes, weil sie das Gesetz der Väter nicht verlassen wollten."},

"Great Martyr Euphemia the All-praised":
{"type": "Grossmärtyrerin · 4. Jh.", "life": "Heilige Grossmärtyrerin Euphemia die Allgepriesene war die Tochter frommer Christen zu Chalkedon und litt dort im Jahre 303 unter Diokletian. Auf dem Vierten Ökumenischen Konzil, das in ihrer Kirche zusammentrat, offenbarte sie durch ein Wunder an ihren Reliquien das rechte Bekenntnis.", "patron": "Angerufen um Reinheit; um die Bewährung der Orthodoxie."},

"Translation of the relics of the Hieromartyr Phocas, Bishop of Sinope":
{"type": "Bischof · 2. Jh.", "life": "Gedächtnis der Übertragung der Reliquien des heiligen Hieromärtyrers Phokas, Bischofs von Sinope, aus seiner Stadt nach Konstantinopel im Jahre 403 oder 404. Zu Sinope am Schwarzen Meer geboren, führte er von Jugend auf ein tugendhaftes Leben und bekehrte als Bischof viele Heiden zu Christus.", "patron": "Angerufen von Seeleuten; um Bewahrung vor Feuer."},

"Venerable John of Damascus":
{"type": "Hieromonach · 8. Jh.", "life": "Ehrwürdiger Johannes von Damaskus, der letzte der grossen Väter der alten Kirche, wurde um 675 zu Damaskus geboren, verliess das Amt seines Vaters am Hofe des Kalifen und wurde Mönch in der Lawra des heiligen Sabbas. Er verteidigte die Verehrung der heiligen Ikonen und dichtete die Kanones der Kirche.", "patron": "Angerufen von Theologen; von Hymnendichtern."},

"Venerable Palladius of Thessalonica":
{"type": "Mönch · 7. Jh.", "life": "Ehrwürdiger Palladios asketisierte zu Thessalonike im sechsten oder siebten Jahrhundert, als jene Stadt unter dem Schutz des Grossmärtyrers Demetrios eine Feste der Orthodoxie und eine Mutter der Mönche war.", "patron": "Angerufen von Mönchen; um das verborgene Leben."},

"Venerable Stephen (in monasticism Simeon), the Myrrhgusher and Prince of Serbia":
{"type": "Mönch, vormals Grossžupan · 12. Jh.", "life": "Ehrwürdiger Symeon der Myrrhenströmende, als Fürst Stefan Nemanja Grossžupan von Serbien, einigte die serbischen Lande und erwarb ihnen die Unabhängigkeit; darauf legte er die Herrschaft nieder, wurde Mönch und gründete mit seinem Sohn, dem heiligen Sava, das Kloster Chilandar auf dem Athos.", "patron": "Angerufen von Herrschern, welche die Welt verlassen; von Vätern der Heiligen."},

"Martyr Serapion":
{"type": "Laie · 3. Jh.", "life": "Heiliger Märtyrer Serapion litt für Christus unter Kaiser Severus. Vor den Statthalter Achilles geführt und zum Abfall aufgefordert, bekannte er sich freimütig als Christ und wurde nach schweren Martern in den Kerker geworfen.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Saint Arkadios the Wonderworker, Bishop of Arsinoe, Cyprus":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Arkadios der Wundertäter wurde zu Arsinoe auf Zypern als Sohn frommer Eltern, Michael und Anna, geboren. Zu Konstantinopel erzogen, kehrte er in seine Vaterstadt zurück, wurde dort um seiner asketischen Mühen willen zum Bischof erwählt und wirkte viele Wunder.", "patron": "Angerufen um Demut; um Enthaltsamkeit."},

"Venerable Euphrosynē of Suzdal":
{"type": "Nonne · 13. Jh.", "life": "Ehrwürdige Euphrosyne von Susdal war die älteste Tochter des heiligen Fürsten Michael von Tschernigow und hiess in der Taufe Theodulia. Als ihr Bräutigam am Vorabend der Hochzeit starb, erkannte sie darin Gottes Fügung, nahm das Kloster an und lehrte dort die Schwestern.", "patron": "Angerufen von Nonnen; von Lehrerinnen der Frauen."},

"Repose of Saint Arsenius, Archbishop of Serbia":
{"type": "Erzbischof · 13. Jh.", "life": "Heiliger Arsenije, Erzbischof von Serbien, wurde in Syrmien geboren und wurde unter dem heiligen Sava Mönch zu Žiča, der ihn um seines strengen Lebens willen zum Abt jenes königlichen Klosters setzte. Als ungarische Heere das Land bedrohten, sandte Sava ihn südwärts, um der Kirche einen sichereren Sitz zu suchen, und er fand ihn zu Peć.", "patron": "Angerufen von Hierarchen; für die serbische Kirche."},

"“Kozel'shchansk” Icon of the Mother of God":
{"type": "Ikone der Gottesmutter · 19. Jh.", "life": "Die Ikone der Gottesmutter von Koselschtschina war das Hausbild der Grafen Kapnist auf ihrem Gut im Poltawaer Lande. Sie zeigt die Gottesmutter mit dem Kinde und daneben eine Schale mit einem Löffel, worin die Kranken seit jeher ihre Heilung gelesen haben.", "patron": "Angerufen von Gelähmten; von Mädchen und jungen Frauen."},

"Saint Agapitos the Confessor and Wonderworker, Bishop of Synnada in Phrygia":
{"type": "Bischof, Bekenner · 4. Jh.", "life": "Heiliger Agapitos der Bekenner und Wundertäter, Bischof von Synnada in Phrygien, stammte aus Kappadokien und ging in der Jugend ins Kloster. Durch Fasten, Gehorsam und Gebet erhielt er früh die Gabe der Wunder und heilte die Kranken, die man an die Pforte brachte.", "patron": "Angerufen von Eingezogenen; von Streitern des Glaubens."},

"Finding of the relics of Saint Abibas":
{"type": "Gerechter · 1. Jh.", "life": "Auffindung der Reliquien des heiligen Abibos, des Sohnes des gerechten Gamaliel, des Lehrers des Apostels Paulus. Mit seinem Vater empfing er von den Aposteln die heilige Taufe, entschlief in Reinheit noch jung und wurde zu Kaphargamala bestattet, wo schon der Erzmärtyrer Stephanos und der heilige Nikodemos lagen.", "patron": "Angerufen um Reinheit."},

"Saint Hilarion of Tvali":
{"type": "Abt (Igumen) · 11. Jh.", "life": "Ehrwürdiger Ilarion von Tvali, Tulaschwili genannt, war zu Beginn des elften Jahrhunderts Abt des Klosters Chachuli im südwestlichen Georgien. Er war berühmt um seiner Tugend und seiner asketischen Mühen willen und ein hervorragender Theologe, Schriftsteller und Übersetzer.", "patron": "Angerufen von Mönchen; von Übersetzern."},

"Saint Charitina, Princess of Lithuania":
{"type": "Nonne · 13. Jh.", "life": "Ehrwürdige Charitina, Fürstin von Litauen, verliess in den unruhigen Zeiten des dreizehnten Jahrhunderts ihre Heimat und fand zu Nowgorod Zuflucht. Dort nahm sie im Frauenkloster der heiligen Apostel Petros und Paulos auf dem Sinitschja-Berge das Mönchsgewand an.", "patron": "Angerufen von Äbtissinnen; von Verbannten."},

"Martyrs Carpus, Papylus, Agathadorus, and Agathonica, at Pergamum":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Karpos, Papylos, Agathodoros und die Märtyrerin Agathonike litten zu Pergamon im Jahre 251 unter Decius. Karpos war Bischof von Thyateira und Papylos sein Diakon, der seine Habe den Armen gegeben hatte; da sie die heidnischen Feste nicht hielten, wurden sie vor Gericht gestellt und blieben im Bekenntnis Christi unerschütterlich.", "patron": "Angerufen um standhaftes Bekenntnis; um Heilung."},

"Martyr Agathonicus of Nicomedia, and those with him, who suffered under Maximian":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Agathonikos litt samt Zotikos, Theoprepios, Akindynos, Severianos, Zenon und anderen unter Maximian. Er war von vornehmem Geschlecht und wohnte zu Nikomedeia; der Heiligen Schrift wohl kundig, führte er viele vom Götzendienst zu Christus, darunter einen der Ersten des Rates.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Uncovering of the relics Saint Acacius, Bishop of Melitene":
{"type": "Bischof · 3. Jh.", "life": "Auffindung der Reliquien des heiligen Akakios des Bekenners, Bischofs von Melitene in Armenien. Unter Decius als Christ ergriffen und vor den Statthalter Markianos geführt, bekannte er freimütig Christus und widerlegte die Torheit des Götzendienstes; er wurde gefoltert, doch nicht getötet, und leitete seine Kirche noch lange Zeit.", "patron": "Angerufen von Bekennern; um Ausdauer in der Marter."},

"Martyrs Sergius and Bacchus in Syria":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Sergios und Bakchos waren vornehme Römer und hohe Offiziere der Leibwache Kaiser Maximians, der sie ehrte, ohne zu wissen, dass sie Christen waren. Als gemeldet wurde, dass sie mit dem Hofe die Tempel nicht betraten, gebot der Kaiser ihnen zu opfern, und sie weigerten sich.", "patron": "Angerufen von Soldaten; um heilige Freundschaft."},

"Hieromartyr Cyril, Bishop of Gortyna in Crete":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Kyrillos war Bischof von Gortyna auf Kreta und weidete seine Herde fünfzig Jahre lang. Als die Verfolgung seine Stadt erreichte, war er hochbetagt; ergriffen und zum Opfer aufgefordert, weigerte er sich und wurde zum Feuertod verurteilt.", "patron": "Angerufen um standhafte Verkündigung."},

"Martyrs Rusticus the Presbyter and Eleutherius the Deacon":
{"type": "Märtyrer · 1. Jh.", "life": "Heilige Märtyrer Rustikos der Presbyter und Eleutherios der Diakon waren die treuen Gefährten des heiligen Hieromärtyrers Dionysios des Areopagiten in seinen apostolischen Mühen im Abendland. Sie teilten seine Verkündigung, seine Gefahren und seine Fesseln und bekehrten zu Rom und darüber hinaus viele zu Christus.", "patron": "Angerufen um treue Gefährtenschaft im Evangelium."},

"Saint John, Bishop of Polybotum":
{"type": "Bischof · 8. Jh.", "life": "Heiliger Johannes, Bischof von Polybotos in Phrygien, weidete seine Herde im achten Jahrhundert, als Kaiser Leon der Isaurier die Hand gegen die heiligen Ikonen erhob. Der Bischof der kleinen phrygischen Stadt widerstand dem Gebieter des Reiches und blieb der Verehrung der Bilder Christi, seiner Mutter und der Heiligen treu.", "patron": "Angerufen um die Verehrung der heiligen Ikonen; um Heilung und Befreiung."},

"Saint Gennadius, Patriarch of Constantinople":
{"type": "Patriarch · 5. Jh.", "life": "Heiliger Gennadios bestieg im Jahre 458 unter Kaiser Leon dem Grossen den Patriarchenthron von Konstantinopel und leitete die Kirche der Kaiserstadt dreizehn Jahre lang. Er war ausgezeichnet durch Milde, Reinheit und Enthaltsamkeit und weihte niemanden, der den Psalter nicht auswendig kannte.", "patron": "Angerufen wider die Simonie; um den Frieden der Kirche."},

"Venerable Theophanes the Faster of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Theophanes der Faster mühte sich im zwölften Jahrhundert in den Nahen Höhlen der Kiewer Lawra, im ersten grossen Zeitalter des Klosters der heiligen Antonios und Theodosios. Sein Beiname ist sein Leben: er war ein Faster, einer jener Kämpfer der Enthaltsamkeit, in denen die Höhlen den sichersten Weg zur Reinheit des Herzens sahen.", "patron": "Angerufen von Fastenden; um das Fasten."},

"Prophet Daniel":
{"type": "Prophet · 6. Jh. v. Chr.", "life": "Heiliger Prophet Daniel, aus königlichem Geschlecht Judas, wurde als Jüngling in der ersten Wegführung nach Babylon gebracht, etwa sechshundert Jahre vor Christus. Mit seinen drei Gefährten wies er die Speise des Königs zurück und empfing dafür Weisheit über alle Weisen des Reiches.", "patron": "Angerufen von Verbannten; von Auslegern."},

"Martyr Lupus, slave of Saint Demetrius of Thessalonica":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Lupos lebte um die Wende des vierten Jahrhunderts und war der treue Diener des heiligen Grossmärtyrers Demetrios von Thessalonike. Beim Tode seines Herrn zugegen, tauchte er sein Gewand in dessen Blut und nahm den Ring von seiner Hand.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Venerable Nikon the Dry, of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Nikon der Trockene, aus den Nahen Höhlen, stammte aus reichem und angesehenem Kiewer Hause, das er um der Höhlen des heiligen Antonios willen verliess. Bei einem Polowzereinfall wurde er in die Steppe verschleppt; sein Herr forderte ein hohes Lösegeld, doch er verbot den Seinen, es zu zahlen.", "patron": "Angerufen von Gefangenen; von Kriegsgefangenen."},

"Venerable Barlaam, Abbot of Khutyn, Novgorod":
{"type": "Abt (Igumen) · 12. Jh.", "life": "Ehrwürdiger Warlaam von Chutyn, einer der grössten Heiligen Nowgorods, wurde dort frommen und wohlhabenden Eltern geboren und hiess Alexij. Nach ihrem Tod verschenkte er sein Erbe, nahm das Mönchsgewand an und wählte zur Wohnstatt den Hügel Chutyn an der Wolchow, den das Volk als bösen Ort mied und den der Asket gerade darum erwählte.", "patron": "Angerufen von Mönchen; um die Heiligung böser Orte."},

"Saint Eustathius, Archbishop of Antioch":
{"type": "Erzbischof, Bekenner · 4. Jh.", "life": "Heiliger Eustathios, Erzbischof von Antiochien, war einer der ersten Väter des Ersten Ökumenischen Konzils und der erste, den der arianische Gegenschlag traf. Zu Side in Pamphylien geboren und zuerst Bischof von Beroia, wurde er auf den grossen Thron von Antiochien erhoben und um seines Bekenntnisses willen verleumdet und abgesetzt.", "patron": "Angerufen von Verleumdeten; von abgesetzten Hierarchen."},

"Presbyters and Confessors Eugene and Macarius, at Antioch":
{"type": "Presbyter, Bekenner · 4. Jh.", "life": "Heilige Presbyter und Bekenner Eugenios und Makarios litten zu Antiochien unter Julian dem Abtrünnigen. Ihren Namen als Bekenner erwarben sie auf die geradeste Weise, welche die Kirche kennt: sie sagten dem Kaiser ins Angesicht die Wahrheit über ihn.", "patron": "Angerufen von Priestern in der Verbannung; von denen, welche die Macht zurechtweisen."},

"Saint Tikhon, Bishop of Voronezh, Wonderworker of Zadonsk and All Russia":
{"type": "Bischof · 18. Jh.", "life": "Heiliger Tichon von Sadonsk, als Timofej im Jahre 1724 im Nowgoroder Lande geboren, war der Sohn eines armen Dorfvorsängers, und nach dem Tode des Vaters litt die Familie solche Not, dass die Mutter ihn beinahe fortgab. Durch die Sorge seines Bruders konnte er lernen, lehrte am Nowgoroder Seminar und wurde später Bischof.", "patron": "Angerufen von geistlichen Schriftstellern; um Demut."},

"Venerable Euphrosyne of Alexandria":
{"type": "Nonne · 5. Jh.", "life": "Ehrwürdige Euphrosyne von Alexandreia lebte im fünften Jahrhundert und war die einzige, innig geliebte Tochter eines reichen und frommen Mannes namens Paphnutios. Der Jungfräulichkeit im Herzen gelobt und der vom Vater bestimmten Ehe nicht entgehend, empfing sie heimlich das Mönchsgewand, kleidete sich als Mann und trat in ein Männerkloster ein.", "patron": "Angerufen um verborgene Askese; um Jungfräulichkeit."},

"Hieromartyr Emilian and with him Martyrs Hilarion, Dionysius, and Hermippus":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Aimilianos, Bischof von Trebia, litt samt Hilarion, Dionysios und Hermippos. Die Brüder wurden in Armenien geboren und zogen nach dem Tode der Eltern mit ihrem Lehrer Hilarion nach Italien in die Stadt Spoleto. Dort verkündete Aimilianos den Heiden das Evangelium und wurde um seines strengen Lebens willen zum Bischof geweiht.", "patron": "Angerufen um die Verkündigung unter den Völkern."},

"Saint Clement the Stylite who lived as an ascetic on Mount Ságmata in Boeotia":
{"type": "Stylit · 12. Jh.", "life": "Ehrwürdiger Klemens der Stylit asketisierte auf dem Berge Sagmata in Boiotien und entschlief im Jahre 1111, ein später und einsamer Erbe der Säulensteher. Von der Welt zurückgezogen auf den Gipfel über der boiotischen Ebene, im Angesicht des alten Theben, bestieg er die Säule und blieb darauf bis zu seinem Ende.", "patron": "Angerufen von Säulenstehern; von Einsiedlern der Berge."},

"Apostle Silas of the Seventy":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Apostel Silas, einer der Siebzig, war ein angesehenes Glied der ersten Kirche zu Jerusalem und wurde zu den Ersten unter den Brüdern gezählt. Als das Apostelkonzil zu Jerusalem entschied, dass die Heidenchristen das Gesetz Mose nicht zu halten hätten, wurde er erwählt, dessen Beschluss den Gläubigen zu Antiochien zu bringen und auszulegen.", "patron": "Angerufen um die Verkündigung unter den Völkern."},

"Saint James the Wonderworker, Bishop of Rostov":
{"type": "Bischof · 14. Jh.", "life": "Heiliger Jakow der Wundertäter, Bischof von Rostow, weidete jenen alten Stuhl im vierzehnten Jahrhundert. Er widerlegte den Häretiker Markian, der die Rostower Kirche verwirrte, und war seiner Herde ein Vater; offenbar aber wurde seine Heiligkeit durch ein Werk der Barmherzigkeit, das ihn alles kostete.", "patron": "Angerufen von Richtern; von Bischöfen."},

"10 Holy Martyrs of Crete":
{"type": "Märtyrer · 3. Jh.", "life": "Die zehn heiligen Märtyrer von Kreta, Theodulos, Saturninos, Euporos, Gelasios, Eunikianos, Zotikos, Pompios, Agathopus, Basilides und Euaristos, litten im Jahre 250 unter Kaiser Decius, dessen Statthalter auf der Insel den Glauben aus Kreta auszurotten suchte.", "patron": "Angerufen um Freude im Angesicht des Todes; um den Kranz, um den in Liebe gestritten wird."},

"Martyr Boniface at Tarsus in Cilicia, and Righteous Aglaϊa of Rome":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Bonifatius war der Verwalter der reichen jungen Römerin Aglaida, mit der er in Sünde lebte, obgleich er barmherzig gegen die Armen und gastfrei gegen die Fremden war. Als sie heilige Reliquien zum Schutz ihrer Seele zu haben wünschte, sandte sie ihn in den Osten, wo die Verfolgung wütete; dort bekannte er selbst Christus und starb als Märtyrer.", "patron": "Angerufen von Verwaltern; von Dienenden."},

"Venerable John, Ascetic of the Syrian Deserts":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdiger Johannes, Asket der syrischen Wüsten, wird an diesem Tage mit der Schar jener Einsiedler des freien Himmels begangen, deren Mühen Theodoretos von Kyrros, ihr Nachbar und Bischof, der Kirche aufgezeichnet hat. Johannes hielt seinen Stand auf kahler Höhe etwa fünfundzwanzig Jahre, ohne Dach, Zelle oder Obdach.", "patron": "Angerufen von Einsiedlern; von denen, die ohne Zeugen ausharren."},

"Venerable Sophia of Suzdal, the Wonderworker":
{"type": "Nonne · 16. Jh.", "life": "Ehrwürdige Sophia von Susdal, in der Welt die Grossfürstin Solomonija Saburowa, wurde um 1490 als Tochter des Bojaren Juri Saburow geboren und 1505 unter fünfhundert Jungfrauen ganz Russlands zur Braut des Thronerben Wassilij erwählt; Metropolit Simon segnete ihre Ehe in der Dormitio-Kathedrale des Kreml.", "patron": "Angerufen von Frauen, denen in der Ehe Unrecht geschah; von Kinderlosen."},

"Saint Macarius the Roman of Mesopotamia":
{"type": "Mönch · 4. Jh.", "life": "Ehrwürdiger Makarios der Römer aus Mesopotamien ist der Kirche durch die alte Erzählung dreier mesopotamischer Mönche bekannt, Theophilos, Sergios und Hyginos, die ostwärts zogen und die Enden der Erde suchten. Nach langer Wanderung fanden sie in einer Wüste jenseits aller Wohnstätten eine Höhle und einen ehrwürdigen Greis, allein in das weisse Haar seines hohen Alters gekleidet.", "patron": "Angerufen von Einsiedlern; um die Busse."},

"Forefeast of the Elevation of the Cross":
{"type": "Vorfest", "life": "Vorfest der Weltweiten Erhöhung des kostbaren und lebenspendenden Kreuzes, an dem die Kirche das grosse Fest des morgigen Tages zu feiern beginnt. In den Gottesdiensten erklingen die Gesänge des Kreuzes und rufen die Gläubigen, ihre Seelen zu reinigen, damit sie das heilige Holz erhöht inmitten der Erde schauen.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Dometius of Persia and his two disciples":
{"type": "Diakon · 4. Jh.", "life": "Heiliger Märtyrer Dometios lebte im vierten Jahrhundert in Persien und wurde in der Jugend durch einen Gläubigen namens Uaros zu Christus bekehrt. Er verliess seine Heimat, kam in die Grenzstadt Nisibis, wurde dort getauft und Mönch und trat später in das Kloster der heiligen Sergios und Bakchos unter dem strengen Archimandriten Urbelos ein.", "patron": "Angerufen um Heilung; um die asketische Mühe."},

"Martyr Barulas the Youth of Caesarea":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Barulas der Knabe war ein kleines Kind zu Antiochien, das Gott zum Zeugen der Wahrheit vor den Mächtigen dieser Welt machte. Als der Diakon Romanos vor dem Präfekten Asklepiades stand und seines Glaubens wegen verspottet wurde, wies er auf einen Knaben in der Menge und sprach, dass selbst ein Kind den einen wahren Gott kenne.", "patron": "Angerufen von Kindern; um das Zeugnis der Kinder."},

"Martyr Mamas of Caesarea in Cappadocia":
{"type": "Grossmärtyrer · 3. Jh.", "life": "Heiliger Grossmärtyrer Mamas wurde im dritten Jahrhundert in Paphlagonien geboren, als Sohn der vornehmen Christen Theodotos und Rufina, die zu Kaisareia in Kappadokien um des Bekenntnisses willen in den Kerker geworfen wurden. Dort starb der Vater, und die Mutter gebar ihn im Gefängnis, befahl ihn Gott und entschlief, sodass das Kind zwischen den Leibern seiner Eltern zurückblieb.", "patron": "Angerufen von Hirten; von Viehhaltern."},

"Holy Apostles of the Seventy and Deacons: Prochorus, Nicanor, Timon, and Parmenas":
{"type": "Diakon · 1. Jh.", "life": "Heilige Apostel der Siebzig und Diakone Prochoros, Nikanor, Timon und Parmenas waren unter den sieben Männern voll Heiligen Geistes und Weisheit, welche die zwölf Apostel erwählten und zu den ersten Diakonen der Kirche weihten, wie die Apostelgeschichte erzählt.", "patron": "Angerufen von Diakonen; um den Dienst am Altar."},

"Church New Year":
{"type": "Fest", "life": "Am ersten September begeht die Kirche den Beginn der Indiktion, das kirchliche Neujahr. Die Väter des Ersten Ökumenischen Konzils zu Nikaia setzten fest, dass das Jahr der Kirche an diesem Tage beginne, nach der alten Rechnung, in welcher der September, der Monat der Ernte, bei den Hebräern das Jahr eröffnete.", "patron": "Angerufen um das neue Jahr; um die Danksagung."},

"Translation of the relics of the Protomartyr and Archdeacon Stephen from Jerusalem to Constantinople":
{"type": "Fest · 5. Jh.", "life": "Übertragung der Reliquien des heiligen Erzmärtyrers und Erzdiakons Stephanos von Jerusalem nach Konstantinopel. Nach seiner Steinigung blieb sein Leib unbestattet vor der Stadt liegen; bei Nacht aber nahm ihn der berühmte Gesetzeslehrer Gamaliel, ein heimlicher Jünger Christi, auf und legte ihn in eine Höhle auf seinem Gut zu Kaphargamala.", "patron": "Angerufen um Heilung."},

"Holy, Righteous Anna the Prophetess":
{"type": "Prophetin · 1. Jh.", "life": "Heilige gerechte Prophetin Anna steht am Fest der Begegnung des Herrn neben Symeon, die zweite betagte Zeugin, die Gott am vierzigsten Tage im Tempel bereitgestellt hatte. Der Evangelist Lukas, der allein von ihr berichtet, stellt sie sorgfältig vor: Anna, eine Prophetin, die Tochter Phanuels, aus dem Stamme Asser.", "patron": "Angerufen von Witwen; von Betagten."},

"Translation of the relics of Venerable Theodosius of the Kyiv Far Caves":
{"type": "Abt (Igumen) · 11. Jh.", "life": "Übertragung der Reliquien des ehrwürdigen Theodosios von den Kiewer Fernen Höhlen, des Vaters des gemeinsamen Mönchslebens im Lande der Rus. Zu Wassiljewo bei Kiew geboren, war er von Kindheit an zum asketischen Leben gezogen, verschmähte die Spiele der Kinder, kleidete sich ärmlich und arbeitete auf dem Felde, bis er sein Haus verliess, um Gott im Mönchsstand zu suchen.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Protomartyr and Equal of the Apostles Thekla":
{"type": "Märtyrerin · 1. Jh.", "life": "Heilige Erzmärtyrerin und Apostelgleiche Thekla wurde zu Ikonion aus vornehmem Geschlecht geboren. Mit achtzehn Jahren, einem Jüngling der Stadt verlobt, hörte sie von ihrem Fenster aus die Predigt des Apostels Paulos über die Jungfräulichkeit und das Reich Gottes, und ihr Herz entbrannte so, dass sie drei Tage weder ass noch trank, sondern an seinen Worten hing.", "patron": "Angerufen von Jungfrauen; von denen, die um Christi willen alles verlassen."},

"Saint Ignatius, Patriarch of Constantinople":
{"type": "Patriarch · 9. Jh.", "life": "Heiliger Ignatios, Patriarch von Konstantinopel, wurde als Niketas geboren, Sohn des Kaisers Michael Rangabe. Als sein Vater gestürzt wurde, verschnitt man den Vierzehnjährigen und schloss ihn in ein Kloster; er nahm den Untergang seiner weltlichen Hoffnungen als Ruf Gottes an, wurde ein wahrer Mönch und mit der Zeit Abt, berühmt um seiner Strenge und seiner Barmherzigkeit willen.", "patron": "Angerufen von Hierarchen; um Festigkeit im Recht."},

"Protomartyr and Archdeacon Stephen":
{"type": "Erzdiakon · 1. Jh.", "life": "Heiliger Erzmärtyrer und Erzdiakon Stephanos war der erste der sieben von den Aposteln erwählten Diakone, ein Mann voll Glaubens und Heiligen Geistes, voll Gnade und Kraft, der grosse Wunder unter dem Volke tat.", "patron": "Angerufen von Diakonen; von Predigern."},

"Venerable Lazarus the Iconographer, of Constantinople":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Lazaros der Ikonenmaler, Mönch zu Konstantinopel, war berühmt um seines heiligen Lebens und seiner Kunst willen und malte die heiligen Ikonen in den Jahren, da Kaiser Theophilos, der letzte der Bilderstürmer, sowohl die Bilder als auch die Hände verfolgte, die sie schufen. Als ihm geboten wurde, sein Werk zu lassen, antwortete er, indem er malte.", "patron": "Angerufen von Ikonenmalern; von Malern."},

"Saint Joasaph, Bishop of Belgorod":
{"type": "Bischof · 18. Jh.", "life": "Heiliger Joasaph, Bischof von Belgorod, wurde am achten September 1705, dem Fest der Geburt der Gottesmutter, zu Priluki im Poltawaer Lande aus dem alten ukrainischen Adelsgeschlecht der Gorlenko geboren und in der Taufe Joachim genannt. Als er noch ein Knabe war, schaute sein Vater in einer Vision die Gottesmutter, wie ein Engel dem Kinde den Mantel eines Hierarchen umwarf.", "patron": "Angerufen von Bischöfen; von Klerikern unter Strafe."},

"Martyr Andrew Stratelates, and 2,593 soldiers with him, in Cilicia":
{"type": "Heerführer · 4. Jh.", "life": "Heiliger Märtyrer Andreas war Heerführer im römischen Heer unter Kaiser Maximian, von allen um seiner Tapferkeit und seiner Gerechtigkeit willen geliebt, und als ein grosses persisches Heer in die syrischen Lande einfiel, wurde ihm der Oberbefehl mit dem Titel Stratelates gegeben. Er wählte eine kleine Schar tapferer Soldaten, wie einst Gedeon seine dreihundert, und zog dem Feinde entgegen.", "patron": "Angerufen von Soldaten; von Heerführern."},

"The Annunciation of our Most Holy Lady, the Theotokos and Ever-Virgin Mary":
{"type": "Grosses Fest", "life": "Die Verkündigung feiert den Tag, an dem der Erzengel Gabriel nach Nazareth zur Jungfrau Maria gesandt wurde mit dem Gruss: Freue dich, Begnadete, der Herr ist mit dir; und verkündete, dass sie den Sohn Gottes empfangen und gebären werde. Als Maria fragte, wie dies geschehen könne, antwortete der Engel, der Heilige Geist werde über sie kommen und die Kraft des Höchsten sie überschatten.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Repose of Saint Raphael, Bishop of Brooklyn":
{"type": "Bischof · 20. Jh.", "life": "Entschlafen des heiligen Raphael, Bischofs von Brooklyn, des guten Hirten der verlorenen Schafe Amerikas und des ersten orthodoxen Bischofs, der in der Neuen Welt geweiht wurde. Zu Beirut im Jahre 1860 einer armen damaszenischen Familie auf der Flucht geboren, wurde er von der Kirche erzogen, die ihn erkannte: an der Patriarchatsschule, auf Chalki und an der Geistlichen Akademie zu Kiew.", "patron": "Angerufen von Auswanderern; von Missionsbischöfen."},

"Icon of the Mother of God of Pochaiv":
{"type": "Ikone der Gottesmutter", "life": "Die Ikone der Gottesmutter von Potschajiw ist einer der grössten Schätze der orthodoxen Welt und wird seit mehr als vier Jahrhunderten in der Lawra von Potschajiw in Wolhynien verwahrt. Metropolit Neophytos brachte sie im Jahre 1559 aus Konstantinopel und segnete mit ihr die fromme Edelfrau Anna Hojska, die ihn in ihrem Hause aufgenommen hatte.", "patron": "Angerufen um Schutz; um Heilung."},

"Entrance of the Apostle Andrew into Georgia":
{"type": "Fest", "life": "An diesem Tage begeht die Kirche Georgiens den Eintritt des heiligen Apostels Andreas des Erstberufenen in die georgischen Lande, die apostolische Grundlage, auf der jene alte Kirche steht. Die Überlieferung Georgiens erzählt, dass beim Los der Apostel über die Völker Iberien der Allheiligen Gottesmutter selbst zufiel.", "patron": "Angerufen um die apostolische Grundlage der georgischen Kirche; um die Gottesmutter als Schirmherrin Georgiens."},

"Martyr Trophimus and 14 Others in Lycia":
{"type": "Laien · 4. Jh.", "life": "Heilige Märtyrer Trophimos, Theophilos und dreizehn andere mit ihnen litten für Christus in Lykien unter Kaiser Diokletian. Vor Gericht gestellt, bekannten sie sich freimütig als Christen und weigerten sich, den Götzen zu opfern; nach schweren Martern zerbrach man ihnen die Beine und warf sie ins Feuer.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Saint Flavian the Confessor, Patriarch of Constantinople":
{"type": "Patriarch, Bekenner · 5. Jh.", "life": "Heiliger Flavianos der Bekenner, Patriarch von Konstantinopel, bezahlte mit dem Leben für die zwei Naturen Christi, und sein Sarg stand dem Konzil vor, das ihn rechtfertigte. Im Jahre 446 auf den Thron erhoben, ein Mann asketischen Lebens und schlichter Redlichkeit, machte er sich sogleich Feinde, weil er nichts zu geben hatte.", "patron": "Angerufen von Hierarchen unter Gewalt; von den gerechtfertigten Toten."},

"Martyr Agathocleia":
{"type": "Märtyrerin · 3. Jh.", "life": "Heilige Märtyrerin Agathokleia war die Magd eines gewissen Nikolaos und seiner Frau Paulina; der Herr war Christ, die Herrin aber Götzendienerin und wütete gegen den Glauben ihrer Magd. Lange Jahre ertrug Agathokleia harte Arbeit, Schläge und jede Art von Qual, mit der man sie zum Abfall zwingen wollte, und trug alles mit Geduld.", "patron": "Angerufen von Dienenden; von Bedrückten."},

"Martyr Anastasius the Fuller of Salona in Dalmatia":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Anastasios der Walker lebte am Ende des dritten Jahrhunderts zu Salona in Dalmatien, ein Handwerker, der seine Walkstube zur Kanzel machte. Er verkündete Christus offen in der Stadt mit Wort und Zeichen und malte das Kreuz sichtbar auf seine Tür, sodass sein Gewerbe und sein Glaube zugleich ausgehängt standen.", "patron": "Angerufen von Walkern; von Wäschern."},

"Hieromartyr Alexander, Bishop of Comana":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Hieromärtyrer Alexandros lebte im dritten Jahrhundert bei Neokaisareia, ein Mann, der in der Schrift und in vielen Wissenschaften bewandert war und dennoch die verborgene Mühe der Torheit um Christi willen auf sich nahm: er lebte in Armut und verkaufte Kohlen auf dem Markt. Sein Angesicht war stets von Kohlenstaub geschwärzt, und viele sahen mit Verachtung auf ihn.", "patron": "Angerufen um Demut; um verborgene Weisheit."},

"Martyr Julian of Dalmatia":
{"type": "Laie · 2. Jh.", "life": "Heiliger Märtyrer Julianos litt für Christus unter Kaiser Antoninus Pius in der italischen Landschaft Kampanien. Als der Statthalter Flavianus die Christen aufspüren liess, um sie vor Gericht zu stellen, fand man den jungen Julianos, der aus Dalmatien nach Kampanien gekommen war, als einen Nachfolger Christi.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Fathers of the First Six Councils":
{"type": "Bischöfe", "life": "Gedächtnis der heiligen Väter der ersten sechs Ökumenischen Konzilien, der gottragenden Hierarchen und Lehrer, die aus allen Teilen der christlichen Welt zusammenkamen, um den apostolischen Glauben gegen die Häresien zu verteidigen. Zu Nikaia und auf dem Ersten Konzil von Konstantinopel verkündeten sie die Gottheit des Sohnes und des Heiligen Geistes und gaben der Kirche das Glaubensbekenntnis.", "patron": "Angerufen um die orthodoxe Lehre; um den wahren Glauben."},

"Translation of the relics of Venerable Lazarus of Mount Galesius near Ephesus":
{"type": "Mönch (Stylit) · 11. Jh.", "life": "Übertragung der Reliquien des ehrwürdigen Lazaros des Wundertäters vom Berge Galesion. Zu Magnesia in Lydien geboren, war er ein gelehrter Jüngling, der Gott von Jugend auf liebte; er zog ins Heilige Land, empfing in der Lawra des heiligen Sabbas das Mönchsgewand und mühte sich dort zehn Jahre, bis er zum Priester geweiht wurde.", "patron": "Angerufen von Mönchen; um den asketischen Kampf."},

"Venerable Athanasius “the Resurrected One”, Recluse of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Athanasios der Auferweckte, Klausner der Nahen Höhlen, mühte sich im zwölften Jahrhundert in der Kiewer Höhlenlawra, ein Zeitgenosse des Archimandriten Polykarp. Nach langer schwerer Krankheit starb er; die Brüder bereiteten ihn zur Bestattung, und am dritten Tage, als der Abt mit den Vätern kam, ihn zu begraben, fanden sie ihn lebend.", "patron": "Angerufen um das Gedenken des Todes; um die Busse zu jeder Stunde."},

"Translation of the relics of Righteous Simeon of Verkhoturye":
{"type": "Gerechter · 17. Jh.", "life": "Übertragung der Reliquien des gerechten Symeon von Werchoturje. Er war ein Edelmann aus dem europäischen Russland, der in den Wirren des frühen siebzehnten Jahrhunderts seine Herkunft verbarg, in die neu besiedelten Lande jenseits des Urals kam und im Dorfe Merkuschino als armer Wanderer lebte. Sein Brot verdiente er, indem er den Bauern Pelzröcke nähte.", "patron": "Angerufen von Schneidern; von Fischern."},

"Hieromartyr Nestor, Bishop of Magydos in Pamphylia":
{"type": "Hieromärtyrer · 3. Jh.", "life": "Heiliger Hieromärtyrer Nestor, Bischof von Magydos in Pamphylien, litt im Jahre 250 in der Verfolgung des Decius. Als das kaiserliche Edikt Pamphylien erreichte und die Jagd begann, rief er seine Herde nicht zu gemeinsamem Stand, sondern schickte alle fort und blieb als letzter und allein.", "patron": "Angerufen von Bischöfen, die bleiben; von Hirten verfolgter Herden."},

"Venerable Makarios, Abbot of Zheltovod and Unzha":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Makarij wurde im Jahre 1349 zu Nischni Nowgorod frommen Eltern geboren und verliess mit zwölf Jahren sein Haus, um im Himmelfahrts-Höhlenkloster unter dem heiligen Abt Dionysij das Mönchsgewand zu empfangen; mit dem Eifer der Jugend gab er sich dem Werke des Heils hin.", "patron": "Angerufen von Mönchen; von Gefangenen."},

"Saint Eulogius, Archbishop of Alexandria":
{"type": "Patriarch · 7. Jh.", "life": "Heiliger Eulogios, Patriarch von Alexandreia, war einer der erleuchteten Hierarchen seiner Zeit, ein Syrer der Bildung nach, der den Stuhl des Markos an der Wende zum siebten Jahrhundert siebenundzwanzig Jahre leitete. Zuvor war er Abt des Gottesmutter-Klosters zu Antiochien, wo seine Gelehrsamkeit und seine Festigkeit im Glauben von Chalkedon seinen Namen begründeten.", "patron": "Angerufen von Hierarchen; von Theologen."},

"Saint Flavian, Archbishop of Antioch":
{"type": "Erzbischof · 5. Jh.", "life": "Heiliger Flavianos, Erzbischof von Antiochien, folgte im Jahre 381 dem Bekenner Meletios, dem er durch die Verbannungen und Spaltungen der arianischen Wirren als Priester und Mitasket zur Seite gestanden hatte. Sein langes Bischofsamt heilte durch Geduld die Wunden, welche der Streit offen gehalten hatte, und das alte Schisma von Antiochien schloss sich unter seiner milden Beharrlichkeit.", "patron": "Angerufen von Friedensstiftern; von Fürbittern für die Städte."},

"Uncovering of the relics of Venerable Martinian, Abbot of Belozersk":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Auffindung der Reliquien des ehrwürdigen Martinian, Abtes von Beloosero, im Jahre 1514. Im Jahre 1370 als Michail in einem Dorfe am Weissen See geboren, kam er mit dreizehn Jahren heimlich zum heiligen Kirill vom Weissen See, unter dem er im vollkommenen Gehorsam gebildet wurde, das Lesen lernte und mit dem Segen seines Ältesten Bücher abschrieb.", "patron": "Angerufen von Abschreibern; von Mönchen."},

"Venerable Dalmatus the Ascetic of the Dalmatian Monastery at Constantinople":
{"type": "Abt (Igumen) · 5. Jh.", "life": "Ehrwürdiger Dalmatos diente als Soldat im Heere Kaiser Theodosios' des Grossen und stand in seiner Gunst, doch ergriff ihn das Verlangen, dem himmlischen König statt einem irdischen Herrscher zu dienen. Zwischen den Jahren 381 und 383 verliess er das Heer und kam mit seinem Sohn Faustos in das Kloster des heiligen Isaakios bei Konstantinopel, wo beide das Mönchsgewand empfingen.", "patron": "Angerufen von Mönchen; um das Fasten."},

"Saint Pitirim, Bishop of Tambov":
{"type": "Bischof · 17. Jh.", "life": "Heiliger Pitirim, Bischof von Tambow, wurde im Jahre 1645 als Prokopij zu Wjasma geboren, und von Kindheit an bereitete ihn der Herr zum geistlichen Dienst: er liebte die Kirche, lernte früh lesen und schreiben und hatte Freude an den Gottesdiensten. Nachdem er Mönch und Abt geworden war, weihte ihn Patriarch Joachim im Jahre 1685 zum Bischof von Tambow.", "patron": "Angerufen um die Erleuchtung der Völker; um das Gebet."},

"Hieromartyr Athanasios, Venerable Anthousa, and others":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Hieromärtyrer Athanasios, Bischof von Tarsos in Kilikien, litt samt den Seinen im dritten Jahrhundert für Christus. Die ehrwürdige Anthusa, eine Jungfrau aus Seleukeia in Syrien und Tochter wohlhabender Heiden, hatte vom christlichen Glauben gehört und begehrte, von ihm unterwiesen zu werden; darum kam sie unter dem Vorwand einer anderen Reise mit ihren beiden Dienern Charisimos und Neophytos nach Tarsos.", "patron": "Angerufen um die Bekehrung; um standhaftes Bekenntnis."},

"Repose of Saint Alexander Nevsky":
{"type": "Fürst · 13. Jh.", "life": "Entschlafen des heiligen rechtgläubigen Fürsten Alexander Newskij, des Verteidigers der Rus in ihrem dunkelsten Jahrhundert. Im Jahre 1220 zu Perejaslawl-Salesskij als Sohn des Fürsten Jaroslaw geboren, war er noch ein Jüngling von zwanzig Jahren, als die Schweden die Newa herauf gegen Nowgorod zogen.", "patron": "Angerufen von Soldaten; von Unterhändlern."},

"Martyrs Hermes, Serapion, and Polyaenus of Rome":
{"type": "Märtyrer · 2. Jh.", "life": "Heilige Märtyrer Hermes, Serapion und Polyainos waren Bürger Roms im zweiten Jahrhundert und eiferten für die Ausbreitung des Glaubens Christi und die Widerlegung der Heiden. Ergriffen und vor die Obrigkeit geführt, blieben sie im Bekenntnis fest und wollten den Götzen nicht opfern; darum wurden sie grausam geschlagen und in einen finsteren Kerker geworfen.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Righteous Deborah":
{"type": "Prophetin · 12. Jh. v. Chr.", "life": "Die gerechte Debora, Prophetin und Richterin Israels, sass unter ihrer Palme zwischen Rama und Bethel im Gebirge Ephraim, und die Kinder Israels kamen zu ihr um Recht, in jenem dunklen Geschlecht, da Jabin von Kanaan und sein Feldherr Sisera mit neunhundert eisernen Wagen die Stämme zwanzig Jahre bedrückten.", "patron": "Angerufen von Richtern; von Frauen, die führen."},

"Uncovering of the relics of Venerable Maximus of Moscow the Fool-for-Christ":
{"type": "Narr in Christo · 15. Jh.", "life": "Auffindung der Reliquien des seligen Maxim von Moskau, des Narren in Christo, der einen der härtesten Wege zum Heil erwählte. Von seinen Eltern und seiner Geburt ist nichts bekannt, nur dass er Sommer und Winter kaum bekleidet umherging, Kälte und Hitze, Hunger und den Spott der Menschen ertrug, um sein Fleisch zu kreuzigen und seine Heiligkeit vor den Augen der Welt zu verbergen.", "patron": "Angerufen um Geduld in der Not; um die Busse."},

"Hieromartyrs Nicander, Bishop of Myra, and Hermas, the Presbyter":
{"type": "Märtyrer · 1. Jh.", "life": "Heilige Hieromärtyrer Nikandros, Bischof von Myra, und Hermas der Presbyter waren Jünger des Apostels Titos, des Gefährten des Paulos, und wurden von ihm in Lykien zum heiligen Dienst geweiht. Sie verbanden unablässige Hirtenarbeit mit dem asketischen Leben und bekehrten viele Heiden zu Christus; darum wurden sie angezeigt und vor den Präfekten Libanios geführt.", "patron": "Angerufen um die Ausdauer im Hirtenamt."},

"Blessed Yaropolk (in Baptism Peter), Prince of Volodymyr-Volhynia":
{"type": "Fürst · 11. Jh.", "life": "Heiliger rechtgläubiger Fürst Jaropolk von Wolodymyr in Wolhynien, in der heiligen Taufe Petro genannt, war der Sohn des Grossfürsten Isjaslaw von Kiew und Enkel Jaroslaws des Weisen. Sein kurzes Leben war eine Schule der Entäusserung, denn er teilte die wiederholten Verbannungen seines Vaters bei den Polen und den Deutschen und lernte früh, dass Throne geliehen und nicht gegeben sind.", "patron": "Angerufen von Herrschern; von Fürsten, die Unrecht ohne Rache tragen."},

"Hieromartyr Pancratius, Bishop of Taormina in Sicily":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Hieromärtyrer Pankratios, Bischof von Tauromenion auf Sizilien, wurde in den Tagen geboren, da der Herr auf Erden wandelte, und stammte von Eltern aus Antiochien. Sein Vater hörte von dem grossen Lehrer, nahm den jungen Pankratios mit sich nach Jerusalem, und da er die Wunder sah und die göttliche Lehre hörte, glaubte er an Christus und schloss sich den Aposteln an, besonders dem Petros.", "patron": "Angerufen um die Verkündigung unter den Völkern."},

"Venerable Eudokia (in monasticism Euphrosyne), Grand Duchess of Moscow":
{"type": "Grossfürstin · 15. Jh.", "life": "Ehrwürdige Euphrosyne, in der Welt Jewdokija genannt, war die Tochter des Fürsten von Susdal und seit 1367 die Gemahlin des Grossfürsten Dimitrij Donskoj; ihre Ehe war ein Pfand des Friedens zwischen Moskau und Susdal. Vom heiligen Alexij von Moskau und vom heiligen Sergij von Radonesch geistlich geleitet, trug sie die Sorgen einer regierenden Fürstin und übte im Verborgenen strenge Askese.", "patron": "Angerufen um verborgene Askese."},

"Venerable Anthony of the Kyiv Far Caves":
{"type": "Mönch (Einsiedler) · 11. Jh.", "life": "Ehrwürdiger Antonij, der Vater des Mönchtums im Lande der Rus, wurde im Jahre 983 zu Ljubetsch bei Tschernigow geboren und in der Taufe Antipas genannt. Von Jugend an zum Mönchsleben gezogen, zog er zum Berge Athos, empfing dort das Mönchsgewand und wurde im asketischen Kampf geübt, bis der Abt ihn auf Gottes Antrieb in die Heimat zurücksandte, um dort den Mönchsstand zu pflanzen.", "patron": "Angerufen von Mönchen; um das Mönchsleben in der Rus."},

"Saint George, Bishop of Amastris on the Black Sea":
{"type": "Bischof · 9. Jh.", "life": "Heiliger Georgios, Bischof von Amastris am Schwarzen Meer, wurde zu Kromna bei jener Stadt auf das Gebet seiner betagten Eltern hin geboren. Als junger Mann floh er in die Berge Paphlagoniens, mühte sich als Einsiedler und darauf in einer Bruderschaft und gedachte, zeitlebens verborgen zu bleiben.", "patron": "Angerufen von Verteidigern der Städte; von Bischöfen der Küsten."},

"Martyr Gorazd of Prague, Bohemia and Moravo-Cilezsk":
{"type": "Bischof · 20. Jh.", "life": "Heiliger Hieromärtyrer Gorazd, Bischof von Prag und von Böhmen und Mährisch-Schlesien, wurde 1879 in Mähren geboren und in der Taufe Matěj genannt. Zuerst in der römischen Kirche geweiht, kam er nach dem Ersten Weltkrieg zur Orthodoxie und führte Zehntausende seiner Landsleute in die orthodoxe Kirche; unter dem serbischen Patriarchat für die böhmischen Lande zum Bischof geweiht, nahm er den Namen Gorazd an.", "patron": "Angerufen von denen, die Verfolgte bergen; für die tschechischen und slowakischen Gläubigen."},

"Martyr Hyacinth of Caesarea, in Cappadocia, and those with him":
{"type": "Kämmerer (Kubikularios) · 2. Jh.", "life": "Heiliger Märtyrer Hyakinthos stammte aus Kaisareia in Kappadokien, wuchs in einem christlichen Hause auf und diente Kaiser Trajan als Kämmerer, wobei er seinen Glauben an Christus verborgen hielt. Als der Kaiser mit seinem Hofe eines Tages den Götzen opferte, zog der junge Hyakinthos sich in ein Gemach zurück und betete inbrünstig zu Christus.", "patron": "Angerufen um Beständigkeit im Glauben."},

"Afterfeast of the Entry of the Most Holy Mother of God into the Temple":
{"type": "Nachfest", "life": "In den Tagen des Nachfestes des Einzugs der Allheiligen Gottesmutter in den Tempel bleibt die Kirche im Licht des Festes, singt weiter seine Gesänge und betrachtet sein Geheimnis: das dreijährige Kind, von Joachim und Anna nach ihrem Gelübde gebracht, steigt die grossen Stufen des Tempels ohne Hilfe hinauf, wird vom Hohenpriester Zacharias empfangen und wider allen Brauch in das Allerheiligste geführt.", "patron": "Angerufen um das Verweilen in der Gnade des Festes."},

"Martyr Sebastian at Rome, and his companions":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Sebastianos und seine Gefährten litten zu Rom im Jahre 288 unter Diokletian. Sebastianos war Hauptmann der prätorianischen Garde, von den Kaisern geehrt und heimlich ein Christ, und gebrauchte seinen Rang als Schild für die Kirche.", "patron": "Angerufen von Soldaten; von Bogenschützen."},

"Saint Theodore, Prince of Smolensk and Yaroslav, and his sons Saints David and Constantine":
{"type": "Fürst · 13. Jh.", "life": "Heiliger rechtgläubiger Fürst Feodor von Smolensk und Jaroslawl, der Schwarze genannt, wurde in den schrecklichen Tagen des Mongoleneinfalls geboren und nach dem Grossmärtyrer Theodoros Stratelates benannt. Zuerst erhielt er nur das kleine Moschaisk zum Anteil und regierte es so gut, dass es wuchs und gedieh; durch seine Ehe wurde er Fürst von Jaroslawl.", "patron": "Angerufen von Herrschern; um den Kirchenbau."},

"Monastic Martyr Macarius of Saint Anne Skete, Mount Athos":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Neumärtyrer Makarios wurde zu Kios in Bithynien geboren und in der Jugend, in den Tagen des osmanischen Joches, mit Gewalt und List zum Glauben der Eroberer gezogen, eine Wunde, die fortan in seinem Gewissen brannte. Er floh zum Heiligen Berge Athos, kam in die Skite der heiligen Anna und wurde dort in Busse, Gebet und Tränen unter dem Ältesten gebildet.", "patron": "Angerufen um die im Blut besiegelte Busse; um standhaftes Bekenntnis."},

"Martyr Christina of Tyre":
{"type": "Jungfrau · 3. Jh.", "life": "Heilige Märtyrerin Christina lebte im dritten Jahrhundert und war die Tochter eines reichen Mannes namens Urbanus, der Statthalter von Tyros war. Da er sie zur heidnischen Priesterin bestimmt hatte, schloss er sie mit vielen goldenen und silbernen Götzen ein und gebot ihr, vor ihnen Weihrauch zu opfern.", "patron": "Angerufen um die Bekehrung; um Standhaftigkeit."},

"Commemoration of the Holy Fathers of the Seventh Ecumenical Council":
{"type": "Väter des Konzils", "life": "Gedächtnis der heiligen Väter des Siebten Ökumenischen Konzils, das im Jahre 787 zu Nikaia zusammentrat, in den Tagen der Kaiserin Irene und ihres Sohnes Konstantin, unter dem Vorsitz des heiligen Tarasios, Patriarchen von Konstantinopel. Etwa dreihundertfünfzig Väter versammelten sich wider die Häresie der Bilderstürmer, die jahrzehntelang die Kirche verwüstet hatte.", "patron": "Angerufen um die Verehrung der heiligen Ikonen; um die Fülle der orthodoxen Lehre."},

"Right-Believing Prince Roman of Uglich":
{"type": "Fürst · 13. Jh.", "life": "Heiliger rechtgläubiger Fürst Roman von Uglitsch herrschte über sein Wolga-Teilfürstentum im dreizehnten Jahrhundert, in den bitteren ersten Geschlechtern des Mongolenjoches, und hinterliess den seltensten Ruf des Mittelalters: eine Herrschaft, an die man sich einzig um ihrer Güte willen erinnert. Als Sohn des frommen Fürsten Wladimir von Uglitsch wurde er in der Furcht Gottes erzogen.", "patron": "Angerufen von Herrschern; von Erbauern der Kirchen und der Spitäler."},

"Venerable Alexei (Kabalyuk)":
{"type": "Archimandrit · 20. Jh.", "life": "Ehrwürdiger Alexij von der Karpatenrus, in der Welt Alexander Kabaljuk, der Apostel der Karpatenrus, wurde am ersten September 1877 in Transkarpatien in eine Holzfällerfamilie geboren und nach dem heiligen Fürsten Alexander Newskij benannt. Zuerst Novize in einem unierten Kloster, zog er zum Heiligen Berge Athos und wurde dort im russischen Kloster des Grossmärtyrers Panteleimon in die Orthodoxie aufgenommen.", "patron": "Angerufen von Glaubensboten; von Bekennern."},

"Apostles of the Seventy: Erastus, Olympas, Herodion, Sosipater, Quartus, and Tertius":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heilige Apostel der Siebzig Erastos, Olympas, Herodion, Sosipatros, Quartus und Tertius waren Jünger und Mitarbeiter des heiligen Apostels Paulos, der sie im Römerbrief grüsst. Erastos, den Paulos den Rentmeister der Stadt nennt, verwaltete die Kirche zu Jerusalem und war darauf Bischof von Paneas in Palästina.", "patron": "Angerufen von Bischöfen; von Schatzmeistern."},

"Synaxis of the Saints of North America":
{"type": "Synaxis", "life": "Am zweiten Sonntag nach Pfingsten begeht die Orthodoxe Kirche in Amerika alle Heiligen, die auf diesem Erdteil aufgeleuchtet sind, die verherrlichten wie die allein Gott bekannten. Ihre Geschichte beginnt im Jahre 1794, als eine kleine Schar von Mönchen aus Walaam, unter ihnen der heilige German von Alaska, mit dem Licht des Evangeliums zu den Ureinwohnern Alaskas kam.", "patron": "Angerufen für die Kirche in Nordamerika."},

"Venerable Anatolius the Recluse of the Kyiv Far Caves":
{"type": "Mönch (Klausner) · 13. Jh.", "life": "Ehrwürdiger Anatolij der Klausner mühte sich im dreizehnten Jahrhundert in den Fernen Höhlen zu Kiew, eingeschlossen in Stille und unablässigem Gebet. Wenig ist von ihm überliefert, doch wird er unter den ehrwürdigen Klausnern und Vätern der Höhlen geehrt, deren Reliquien unverwest in der Lawra ruhen, und mit der ganzen Schar der Kiewer Höhlenheiligen begangen.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Hieromartyr Gregory, Bishop of Greater Armenia, Equal of the Apostles, Enlightener of Armenia":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Gregorios, Bischof von Grossarmenien, Apostelgleicher und Erleuchter Armeniens, war der Sohn des parthischen Edlen Anak, der den armenischen König erschlagen hatte. Das Kind, aus der Rache gerettet, die sein Haus vernichtete, wurde nach Kaisareia in Kappadokien gebracht und dort im christlichen Glauben erzogen.", "patron": "Angerufen von Glaubensboten; um die Erleuchtung der Völker."},

"Saint Theodoulus, Eparch of Constantinople":
{"type": "Mönch · 5. Jh.", "life": "Ehrwürdiger Theodulos, Eparch von Konstantinopel, bekleidete unter Kaiser Theodosios dem Grossen das höchste Amt der Kaiserstadt und sah von jener Höhe die Eitelkeit ihres Ruhmes. Betrübt über das Unrecht, dem kein Amt abhelfen konnte, und vom Tode seiner frommen Gemahlin getroffen, verteilte er sein grosses Vermögen an die Armen und legte das Amt nieder.", "patron": "Angerufen von Beamten, welche die Macht verlassen; um die verborgene Tugend, die offenbar wird."},

"Martyr Felicitas of Rome, and her seven sons":
{"type": "Märtyrerin · 2. Jh.", "life": "Heilige Märtyrerin Felizitas von Rom, eine reiche und vornehme Witwe, litt mit ihren sieben Söhnen um das Jahr 164 unter Kaiser Mark Aurel; die Kirche hat sie immer neben die Mutter der Makkabäer gestellt, die beiden Mütter von sieben, die ihre ganze Nachkommenschaft vor sich in die Herrlichkeit eingehen sahen.", "patron": "Angerufen von Müttern; von Witwen."},

"New Martyr John Kalphes, the Apprentice":
{"type": "Neumärtyrer · 16. Jh.", "life": "Heiliger Neumärtyrer Johannes Kalphes litt zu Konstantinopel im Jahre 1575, im zweiten Geschlecht nach dem Fall der Stadt, und sein Beiname ist sein Handwerk: Kalphes, der Werkmeister. Er war ein geschickter junger Handwerker der kaiserlichen Werkstätten, ein Christ, dessen Können ihn in den Dienst des osmanischen Hofes selbst geführt hatte.", "patron": "Angerufen von Bauleuten; von Zimmerleuten."},

"Martyr Valerian":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Valerianos wird an diesem Tage zusammen mit dem Märtyrer Philumenos von Ankyra begangen, unter denen, die um das Jahr 274 in Galatien unter Kaiser Aurelian litten. Die griechischen Synaxarien halten fest, dass er durch das Schwert vollendet wurde: er bekannte Christus vor den Verfolgern, verweigerte jedes Opfer und wurde enthauptet.", "patron": "Angerufen für die Gläubigen, deren Namen niemand aufschrieb."},

"Beheading of Venerable Cornelius, Abbot of the Pskov Caves":
{"type": "Abt (Igumen), Märtyrer · 16. Jh.", "life": "Enthauptung des ehrwürdigen Hieromärtyrers Kornilij, Abtes des Pskower Höhlenklosters. Im Jahre 1501 zu Pskow den Edlen Stephan und Maria geboren, wurde er im Misosch-Kloster in der ganzen Bildung des nördlichen Mönchtums geformt: er zog Kerzen, hieb Holz, schrieb und schmückte Bücher und malte Ikonen; und als der Schreiber Missjur Munechin den Jüngling zum armen Höhlenkloster im Walde führte, ergriff ihn die Schönheit des Ortes.", "patron": "Angerufen von Äbten; von Chronisten."},

"Venerable Cyril, Abbot of Chelma Hill":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Kirill vom Tschelma-Berge, Erleuchter der Tschuden, wurde am Weissen See geboren und im Kloster des heiligen Antonij des Römers zu Nowgorod eingekleidet, wo er sechs Jahre die Gehorsame des gemeinsamen Lebens durchlief; nach drei Jahren der Wanderung durch die nördliche Wildnis liess er sich auf dem Tschelma-Berge bei Kargopol nieder und blieb dort.", "patron": "Angerufen von Glaubensboten; von Einsiedlern."},

"Saint Theodosius (Prince Theodore of Ostrog) of the Kyiv Caves":
{"type": "Mönch · 15. Jh.", "life": "Ehrwürdiger Theodosij, als Fürst Feodor von Ostroh in Wolhynien, stammte vom heiligen Fürsten Wolodymyr ab und erwarb Ruhm sowohl durch den Bau von Kirchen als auch durch die Verteidigung des orthodoxen Glaubens in seinem Lande gegen den Druck der Lateiner. Als tapferer Herrscher nahm er am grossen Siege über den Deutschen Orden bei Grunwald teil und half den bedrängten Orthodoxen der Nachbarlande.", "patron": "Angerufen um die Verteidigung der Orthodoxie."},

"Translation of the Relics of Venerable Sergius and Herman, Wonderworkers of Valaam":
{"type": "Mönch", "life": "Übertragung der Reliquien der ehrwürdigen Sergij und German, der Wundertäter von Walaam, der Gründer des grossen Verklärungsklosters auf der Insel Walaam im Ladogasee, des nördlichen Athos des russischen Landes. Alte Überlieferung hält sie für griechische Hieromonachen, die in die Nowgoroder Lande kamen, sich auf der Felseninsel niederliessen und unter den heidnischen Stämmen Kareliens das Licht der Orthodoxie pflanzten.", "patron": "Angerufen von Mönchen; um das Mönchtum des Nordens."},

"Recovery of the relics of Saint Job of Pochaiv":
{"type": "Abt (Igumen) · 17. Jh.", "life": "Auffindung der Reliquien des ehrwürdigen Iow von Potschajiw, des Abtes und Wundertäters, eines der grossen Verteidiger der Orthodoxie in den westrussischen Landen im Zeitalter der Union von Brest, als die Gläubigen Wolhyniens hart bedrängt wurden, sich Rom zu unterwerfen. In der Jugend eingekleidet und später zur Leitung des Klosters auf dem Berge Potschajiw berufen, stärkte er die Bedrängten.", "patron": "Angerufen von Mönchen; um die Verteidigung der Orthodoxie."},

"Saint Antiochus":
{"type": "Mönch · 7. Jh.", "life": "Ehrwürdiger Antiochos, Mönch der Grossen Lawra des heiligen Sabbas, durchlebte die dunkelste Stunde des palästinischen Mönchtums und machte aus ihrem Untergang ein Buch. Ein Galater von Herkunft und ein Sabbait von Bildung, war er Mönch der Lawra, als der Perseneinfall des Jahres 614 über das Heilige Land hereinbrach, und wurde zum Augenzeugen und Chronisten ihrer Märtyrer.", "patron": "Angerufen von Schriftstellern; von Bibliothekaren."},

"Martyr Romanus the Deacon of Caesarea":
{"type": "Diakon · 4. Jh.", "life": "Heiliger Märtyrer Romanos, Diakon der Kirche von Kaisareia in Palästina, war zu Antiochien, als die Verfolgung Diokletians über jene Stadt hereinbrach. Als er die Christen voll Furcht zum heidnischen Feste strömen sah, um ihr Leben durch ein Opfer zu retten, stand er am Tore und rief ihnen zu, Christi zu gedenken, und wandte viele auf der Schwelle des Tempels vom Abfall zurück.", "patron": "Angerufen von Diakonen; von Predigern."},

"Martyrs Heliodorus and Dosa of Persia":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Heliodoros und Dosa litten im Jahre 380 in Persien für Christus, in der langen Verfolgung der Christen unter dem König Sapor. Von ihrem Kampf ist wenig bewahrt, doch weiss man, dass sie den Glauben bekannten und den Tod erduldeten, statt ihren Herrn zu verleugnen oder das Feuer und die Sonne anzubeten, wie die Perser taten.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Martyr Menas of Egypt":
{"type": "Grossmärtyrer · 4. Jh.", "life": "Heiliger Grossmärtyrer Menas war Ägypter und Soldat und diente zu Kotyaion in Phrygien. Als die Erlasse Diokletians allen zu opfern geboten, legte er den Soldatengürtel ab, statt Christus zu verleugnen, und zog sich in die Berge zurück, wo er sich in Fasten und Gebet auf einen grösseren Kampf bereitete.", "patron": "Angerufen von Soldaten; von Kaufleuten."},

"Venerable Daniel the Stylite of Constantinople":
{"type": "Hieromonach · 5. Jh.", "life": "Ehrwürdiger Daniel der Stylit wurde im Jahre 409 zu Maratha bei Samosata geboren, das Kind des gelobten und erhörten Gebetes seiner Mutter Martha, und trat mit zwölf Jahren in den Mönchsstand. Zweimal zog er zur Säule des heiligen Symeon des Styliten und empfing dessen Segen; nach Symeons Entschlafen erhielt er sein ledernes Gewand.", "patron": "Angerufen von Ratgebern der Herrscher; um das Ausharren in der einen Berufung."},

"Monastic Martyr Damascene of the Lavra":
{"type": "Mönch · 17. Jh.", "life": "Ehrwürdiger Mönchsmärtyrer Damaskenos von der Lawra wurde im Stadtteil Galata zu Konstantinopel den frommen Eltern Kyriakos und Kyriake geboren, die ihren Sohn Diamantes nannten. Früh verwaist und ohne Führung, geriet der Knabe in ein ungeordnetes Leben, und als man ihn eines Tages bei einer unerlaubten Tat ergriff, rettete er sich vor der Strafe, indem er in den Islam einwilligte.", "patron": "Angerufen um die Busse nach der Verleugnung; um die Abwaschung des Abfalls im Blute."},

"Martyrs Demetrius, his wife Euanthia, and their son Demetrian, at Skepsis on the Hellespont":
{"type": "Märtyrer · 1. Jh.", "life": "Heilige Märtyrer Demetrios, seine Gemahlin Euanthia und ihr Sohn Demetrianos litten im ersten Jahrhundert für Christus in der Stadt Skepsis am Hellespont. Demetrios war Herr jener Stadt und wurde nach der Überlieferung der Kirche durch die Predigt und die Wunder des heiligen Hieromärtyrers Kornelios des Hauptmanns zum Glauben geführt, desselben, den der Apostel Petros getauft hatte.", "patron": "Angerufen von christlichen Familien; um standhaftes Bekenntnis."},

"Martyr Vincent of Spain":
{"type": "Diakon · 4. Jh.", "life": "Heiliger Märtyrer Vinzenz von Spanien war Erzdiakon der Kirche von Saragossa unter dem betagten Bischof Valerius, dessen Sprachgebrechen der beredte Diakon ersetzte, indem er im Namen seines Bischofs das Wort Gottes verkündete. Als die Verfolgung Diokletians Spanien erreichte, liess der Statthalter Dacianus beide ergreifen und in Ketten nach Valencia bringen.", "patron": "Angerufen von Diakonen; von Predigern."},

"Venerable Sergius, Abbot of Nurma, disciple of Venerable Sergius of Radonezh, Vologda":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Sergij von Nurma, der Wundertäter von Wologda, war ein Grieche von Geburt und mühte sich auf dem Heiligen Berge Athos. Obgleich schon ein erfahrener Ältester, zog er in das Land der Rus, um den heiligen Sergij von Radonesch zu befragen und sich seiner Führung zu unterstellen, und verbrachte einige Jahre als Jünger des grossen Abbas.", "patron": "Angerufen von Mönchen; um das Leben in der Einöde."},

"Forefeast of the Entry into the Temple of the Most Holy Theotokos":
{"type": "Vorfest", "life": "An diesem Tage begeht die Kirche das Vorfest des Einzugs der Allheiligen Gottesmutter in den Tempel und steht an der Schwelle des Festes, wie das Kind Maria an der Schwelle des Heiligtums stand. Die Gesänge des Vorfestes rufen die Gläubigen zur Bereitung: Lasset uns Gläubige heute fröhlich sein, dem Herrn Psalmen singen und sein geheiligtes Zelt ehren, die lebendige Lade, die das unfassbare Wort aufnahm.", "patron": "Angerufen um die Bereitung auf die Feste der Gottesmutter."},

"“O All-Hymned Mother” Icon of the Mother of God":
{"type": "Ikone der Gottesmutter", "life": "Die Ikone der Gottesmutter mit dem Namen Allbesungene Mutter hat ihren Namen von den Anfangsworten des dreizehnten Kontakions des Akathistos: Allbesungene Mutter, die du das Wort geboren hast, das heiliger ist als alle Heiligen; und sie wird an diesem Tage gefeiert.", "patron": "Angerufen um das Lob der Gottesmutter; um Hilfe in jeder Not."},

"Saint Ambrose, Bishop of Milan":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Ambrosios, Bischof von Mailand, einer der grossen Väter des Abendlandes, wurde um 340 zu Trier geboren, als Sohn des prätorianischen Präfekten Galliens; und die Überlieferung erzählt, dass ein Bienenschwarm sich auf die Lippen des Kindes setzte und ohne Schaden davonflog, ein Vorzeichen der honigsüssen Rede, die kommen sollte.", "patron": "Angerufen von Bischöfen; von Statthaltern."},

"The Three Holy Youths: Ananias, Azarias and Misael":
{"type": "Gerechte · 6. Jh. v. Chr.", "life": "Die drei heiligen Jünglinge Ananias, Asarias und Misael, zu Babylon Schadrach, Meschach und Abednego genannt, waren Gefährten des Propheten Daniel in der Gefangenschaft, Jünglinge Judas, die das ganze Gesetz ihres Gottes im Herzen des Reiches hielten, das seinen Tempel verbrannt hatte. Als Nebukadnezar sein goldenes Bild auf der Ebene Dura aufrichtete, weigerten sie sich, niederzufallen.", "patron": "Angerufen von allen, die im Feuerofen der Prüfung stehen; von Bekennern vor den Herrschern."},

"Saint Porphyrius, Bishop of Gaza":
{"type": "Bischof · 5. Jh.", "life": "Heiliger Porphyrios, Bischof von Gaza, dessen Leben sein treuer Gefährte, der Diakon Markos, von innen her aufschrieb, wurde 347 zu Thessalonike aus reichem Hause geboren und verliess mit fünfundzwanzig Jahren alles um der Wüste von Sketis willen. Fünf Jahre mühte er sich unter den ägyptischen Vätern und fünf weitere in einer Höhle am Jordan, wo die Feuchte und die Strenge seine Gesundheit brachen.", "patron": "Angerufen von Bischöfen feindlicher Städte; von Hütern des Kreuzes."},

"Translation of the relics of Venerable Zosimas and Sabbatius of Solovki":
{"type": "Mönche · 15. Jh.", "life": "Übertragung der Reliquien der ehrwürdigen Sossima und Sawwatij von Solowki, der Gründer des grossen Klosters auf seiner Insel im kalten Weissen Meer des russischen Nordens. Der ehrwürdige Sawwatij suchte die völlige Einsamkeit und liess sich als erster auf der unbewohnten Insel nieder, wo er sich mühte und im Jahre 1435 entschlief.", "patron": "Angerufen von Imkern; von Mönchen."},

"Venerable Anatolius of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Anatolij war ein Mönch der Kiewer Höhlen und mühte sich im zwölften Jahrhundert in den Nahen Höhlen. Von den Einzelheiten seines Lebens ist wenig überliefert, doch wird er zu den ehrwürdigen Vätern der Höhlen gezählt, die sich dem Gebet, dem Fasten und dem Gehorsam hingaben und deren Reliquien unverwest in den Höhlen der Lawra ruhen.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Afterfeast of the Elevation of the Cross":
{"type": "Nachfest", "life": "Die Tage des Nachfestes der Weltweiten Erhöhung des kostbaren und lebenspendenden Kreuzes, an denen die Kirche das grosse Fest des Kreuzes des Herrn weiter feiert. Die Gesänge der Erhöhung treten zu den täglichen Gottesdiensten, und die Gläubigen verehren weiter das heilige Holz, das inmitten der Erde erhöht ist.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Saint Varnava (Nastic)":
{"type": "Bischof · 20. Jh.", "life": "Heiliger Varnava der neue Bekenner, Bischof von Hvosno, wurde als Vojislav Nastić am einunddreissigsten Januar 1914 zu Gary in Indiana serbischen Auswanderern geboren und war das erste Kind, das in der dortigen Sava-Kirche getauft wurde, wo er als Knabe am Altar diente; so zählt die serbische Kirche einen Sohn Amerikas unter ihre Bekenner.", "patron": "Angerufen von Katecheten; für die Kirche unter dem Kommunismus."},

"Saint Marcian of Cyrrhus":
{"type": "Mönch · 4. Jh.", "life": "Ehrwürdiger Markianos von Kyrros wurde einem vornehmen Hause jener syrischen Stadt geboren und verliess Rang und Reichtum, um in die Wüste von Chalkis zu ziehen. Dort schloss er sich in eine Zelle ein, die so klein war, dass er darin weder aufrecht stehen noch sich ausstrecken konnte, und lebte in Fasten, unablässigem Gebet und Psalmengesang.", "patron": "Angerufen von Einsiedlern; um das Mass in der Strenge."},

"Martyrs Eutropius, Cleonicus, and Basiliscus of Amasea":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Eutropios, Kleonikos und Basiliskos litten um das Jahr 308 zu Amaseia in Pontos. Ihr Kampf setzt einen berühmten fort, denn die drei waren Gefährten des Grossmärtyrers Theodoros des Rekruten, Basiliskos sein Verwandter dem Blute nach und alle drei ihm verwandt in den Waffen; sie wurden in derselben Verfolgung ergriffen und im selben Kerker gehalten.", "patron": "Angerufen von Verwandten und Gefährten in der Prüfung; von Streitern Christi."},

"Martyr Antonina of Nicea, in Bithynia":
{"type": "Märtyrerin · 4. Jh.", "life": "Heilige Märtyrerin Antonina von Nikaia in Bithynien litt in der Verfolgung, die unter Maximian an der Wende zum vierten Jahrhundert erhoben wurde, als die kaiserlichen Erlasse die Gerichte Kleinasiens wieder mit Christen füllten, die für ihr Leben kein Körnchen Weihrauch geben wollten.", "patron": "Angerufen von Frauen vor Gericht; um das Bekenntnis, das durch die Wasser bewahrt wird."},

"Saint Averkios the Wonderworker, Bishop of Hieropolis, Equal of the Apostles":
{"type": "Bischof · 2. Jh.", "life": "Heiliger Aberkios der Wundertäter, Bischof von Hierapolis in Phrygien, Apostelgleicher, weidete seine kleine Herde in einer den Götzen ergebenen Stadt in den Tagen Mark Aurels. In einer Vision geheissen, den Trug der Dämonen zu zerstören, trat er bei Nacht in den Tempel und stürzte die Götzen um.", "patron": "Angerufen um Heilung; um die Bekehrung der Städte."},

"Martyr Irenarchus and Seven Women Martyrs at Sebaste":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Irenarchos von Sebasteia in Armenien diente unter Diokletian als Scharfrichter, einer von denen, welche die Bekenner Christi folterten; und Gott, der Paulos auf dem Wege und den Schächer am Kreuze rief, rief Irenarchos bei den Werkzeugen seines Handwerks.", "patron": "Angerufen von bekehrten Henkern; von denen, die ihrer Grausamkeit wegen Busse tun."},

"The Placing of the Honorable Robe of the Most Holy Mother of God at Blachernae":
{"type": "Fest · 5. Jh.", "life": "Niederlegung des ehrwürdigen Gewandes der Allheiligen Gottesmutter in der Kirche zu Blachernae in Konstantinopel unter Kaiser Leon dem Grossen. Nach der Überlieferung vermachte die Jungfrau vor ihrer Entschlafung eines ihrer Kleider einer frommen Jungfrau, und es wurde von Geschlecht zu Geschlecht in einer gottesfürchtigen Familie in Palästina bewahrt und wirkte viele Heilungen.", "patron": "Angerufen um den Schutz der Städte und der Gläubigen."},

"Greatmartyr James the Persian":
{"type": "Grossmärtyrer · 5. Jh.", "life": "Heiliger Grossmärtyrer Jakobos der Perser, der Zerschnittene genannt, war ein christlicher Edler Persiens, reich, geehrt und dem König Yezdegerd lieb. Seine Seele, von der Freundschaft des Königs umstrickt, fiel in die grosse Sünde seines Lebens: als der König sich gegen die Christen wandte, verleugnete Jakobos, um die Gunst nicht zu verlieren, mit dem Hofe Christus.", "patron": "Angerufen von Höflingen; um die Busse nach der Verleugnung."},

"“Chukhloma” Icon of the Mother of God from Galich":
{"type": "Ikone der Gottesmutter · 14. Jh.", "life": "Die Ikone der Gottesmutter von Tschuchloma, auch die Galitscher Ikone genannt und vom Typus der Zärtlichkeit, erschien im Jahre 1350 dem heiligen Awraamij von Galitsch, der mit dem Segen des heiligen Sergij von Radonesch zu asketischer Mühe in die nördliche Wildnis gekommen war. An den wilden Ufern des Galitscher Sees, bei einem grossen, im dichten Walde verborgenen Berge, betete er zur Gottesmutter.", "patron": "Angerufen um die Zärtlichkeit; um die mütterliche Fürbitte."},

"Venerable Joseph, Abbot of Volokolamsk, Volotsk":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Iossif von Wolokolamsk, in der Welt Iwan Sanin, wurde 1440 in einem Dorfe bei Wolokolamsk geboren; als Knabe dem Ältesten Arsenij zum Unterricht gegeben, beherrschte er den Psalter in einem einzigen Jahre und die ganze Schrift im nächsten und setzte alle durch sein Gedächtnis in Staunen.", "patron": "Angerufen von Mönchen; von Theologen."},

"Martyrs and Unmercenaries Cosmas and Damian in Cilicia, and their brothers, Leontius, Anthimus, and Eutropius":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer und Uneigennützigen Kosmas und Damianos aus Arabien, welche die Kirche von den beiden anderen Paaren heiliger uneigennütziger Brüder gleichen Namens unterscheidet, waren Ärzte und zogen durch Städte und Dörfer, die Kranken ohne Bezahlung zu heilen, und forderten von den Geheilten nur den Glauben an Christus.", "patron": "Angerufen von Ärzten; von Heilkundigen."},

"Saint Theophilus of the Kyiv Caves, Bishop of Novgorod":
{"type": "Erzbischof · 15. Jh.", "life": "Heiliger Feofil, Erzbischof von Nowgorod, wurde im Jahre 1470 durch das Los auf jenen grossen Stuhl erwählt, in den letzten unruhigen Jahren der Unabhängigkeit Nowgorods, und im folgenden Jahre zu Moskau geweiht. Er weidete seine Herde im Sturm des Falles der Stadt, trat für die Besiegten ein und begrub die Erschlagenen.", "patron": "Angerufen von Hierarchen; um die Geduld in der Schmach."},

"Martyr Antiochus the Physician of Sebaste":
{"type": "Arzt · 4. Jh.", "life": "Heiliger Märtyrer Antiochos stammte aus Sebasteia in Kappadokien und war Arzt von Beruf, ein Bruder des heiligen Märtyrers Platon. Als den Heiden bekannt wurde, dass er Christ sei, wurde er ergriffen und vor Gericht gestellt, und obgleich man ihn schwer folterte, blieb er im Bekenntnis Christi standhaft.", "patron": "Angerufen von Ärzten; von Kranken."},

"Martyr Markella of Chios":
{"type": "Jungfrau · 14. Jh.", "life": "Heilige Märtyrerin Markella lebte im Dorfe Volissos auf der Insel Chios. Ihre Eltern waren fromm und unter den wohlhabendsten des Dorfes; nach dem frühen Tode der Mutter sorgte der Vater, der Dorfälteste, für ihre Erziehung, und sie wuchs sittsam und rein heran und mied jede Gesellschaft, die ihrer Seele hätte schaden können.", "patron": "Angerufen um Reinheit; um den Schutz der Keuschheit."},

"Prophet Joel":
{"type": "Prophet · 9. Jh. v. Chr.", "life": "Heiliger Prophet Joel, der Sohn Petuels, weissagte im Königreich Juda etwa achthundert Jahre vor Christus, und sein kurzes Buch steht unter den zwölf kleinen Propheten. Aus Anlass einer verheerenden Heuschreckenplage und Dürre, die das Land kahl frassen, rief er Priester und Volk zu Fasten und Busse: Zerreisset eure Herzen und nicht eure Kleider und kehret um zum Herrn, eurem Gott.", "patron": "Angerufen um die Busse; um die Ausgiessung des Heiligen Geistes."},

"Synaxis of the Most Holy Mother of God":
{"type": "Fest · 1. Jh.", "life": "Am Tage nach der Geburt Christi feiert die Kirche die Synaxis der Allheiligen Gottesmutter, die Versammlung der Gläubigen, um sie zu preisen, durch die die Menschwerdung geschah; und dies ist allem Anschein nach das älteste Fest der Gottesmutter in der christlichen Überlieferung, der Anfang ihrer gottesdienstlichen Verehrung, über das schon die Väter des vierten Jahrhunderts predigten.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Apostle Epenetus of the Seventy":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Apostel Epainetos, einer der Siebzig, war ein Jünger des Erlösers, den der Apostel Paulos im Römerbrief herzlich grüsst als seinen geliebten Epainetos, den Erstling Achaias für Christus. Er wurde zum Bischof von Karthago bestellt und mühte sich dort unter vielen Bedrängnissen von seiten der Götzendiener, die Heiden zur Erkenntnis des wahren Gottes zu führen.", "patron": "Angerufen um die Verkündigung unter den Völkern."},

"Venerable Matrona, Abbess of Constantinople":
{"type": "Nonne · 5. Jh.", "life": "Ehrwürdige Matrona von Konstantinopel wurde zu Perge in Pamphylien geboren und einem Edlen namens Dometianos zur Ehe gegeben, dem sie eine Tochter gebar. Als sie nach Konstantinopel kam, entbrannte sie in den Kirchen und Vigilien der Hauptstadt so in der Liebe zu Gott, dass sie ihr Kind einer frommen Frau anvertraute und sich ganz dem Herrn hingab.", "patron": "Angerufen von Äbtissinnen; von Nonnen."},

"Virgin Martyr Eupraxia of Tabenna":
{"type": "Nonne · 5. Jh.", "life": "Ehrwürdige Eupraxia war die Tochter des Antigonos, eines vornehmen Würdenträgers zu Konstantinopel und Verwandten Kaiser Theodosios' des Grossen, und seiner frommen Gemahlin, die ebenfalls Eupraxia hiess und im Almosengeben freigebig war. Nach dem Tode des Vaters brachte die Mutter das Mädchen nach Ägypten, und dort zog es das siebenjährige Kind so sehr zu einem Frauenkloster bei Tabennisi, dass es dort bleiben wollte.", "patron": "Angerufen von Nonnen; um die Jungfräulichkeit."},

"Apostle Aquila of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Akylas, einer der Siebzig, war ein Jude aus Pontos und lebte mit seiner Frau Priskilla zu Rom, bis unter Kaiser Claudius die Juden aus der Stadt gewiesen wurden und das Paar sich zu Korinth niederliess. Dort trafen sie den Apostel Paulos, der desselben Handwerks war, bei ihnen wohnte und mit ihnen Zelte machte; von ihm empfingen sie die Taufe.", "patron": "Angerufen von Zeltmachern; von Eheleuten."},

"Synaxis of the Venerable Fathers of the Kyiv Near Caves":
{"type": "Synaxis", "life": "Synaxis der ehrwürdigen Väter der Kiewer Nahen Höhlen, der grossen Schar von Heiligen, deren unverweste Reliquien in den Höhlen des heiligen Antonij der Kiewer Höhlenlawra ruhen. Zu dieser heiligen Gemeinschaft zählen die ersten Väter des russischen Mönchtums und ihre unzähligen Kinder im Geiste: Antonij der Gründer, der das Mönchsleben im Lande der Rus pflanzte, und alle nach ihm.", "patron": "Angerufen von Mönchen; für das Land der Rus."},

"Icon of the Mother of God “of the Sign”, the “Kursk-Root”":
{"type": "Ikone der Gottesmutter", "life": "Die Kursker Wurzelikone der Gottesmutter vom Zeichen ist eine der am meisten verehrten wundertätigen Ikonen des russischen Landes. Sie wurde am achten September des Jahres 1295 gefunden, als ein Jäger im Walde am Flusse Tuskar, nahe der von den Tataren verwüsteten Stadt Kursk, eine Ikone mit dem Antlitz nach unten an der Wurzel eines Baumes liegen sah.", "patron": "Angerufen um Schutz; für die russische Diaspora."},

"Venerable Anthony, Abbot of Leokhnov, Novgorod":
{"type": "Abt (Igumen) · 17. Jh.", "life": "Ehrwürdiger Antonij von Leochnowo stammte aus vornehmem Hause und verliess in der Jugend die Welt, um in die Wildnis der Nowgoroder Lande zu ziehen, wo er zuerst als Einsiedler an einem einsamen Orte namens Rubljowo lebte. Von einer Stimme Gottes gewiesen, liess er sich zu Leochnowo nieder, empfing dort das Mönchsgewand und gründete ein Kloster zu Ehren der Verklärung des Herrn.", "patron": "Angerufen von Mönchen; um das Leben in der Einöde."},

"Apostle Tertius of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Tertius, einer der Siebzig, hat seinen eigenen Gruss in der Heiligen Schrift hinterlassen, denn seine Hand schrieb den Brief des Apostels Paulos an die Römer nach dessen Diktat, und dort setzte er: Ich, Tertius, der ich diesen Brief geschrieben habe, grüsse euch im Herrn.", "patron": "Angerufen von Schreibern; von Abschreibern."},

"Martyrs Victorinus, Victor, Nikēphóros, Claudius, Diodorus, Serapion, and Papias, of Egypt":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Viktorinos, Viktor, Nikephoros, Klaudios, Diodoros, Serapion und Papias litten im Jahre 251 zu Korinth in der Verfolgung unter Kaiser Decius, sieben Christen jener Stadt, die in der reichsweiten Ernte ergriffen wurden, als Decius jedem Untertan gebot, zu opfern oder zu sterben. Vor das Gericht geführt, bekannten die sieben mit einer Stimme.", "patron": "Angerufen von Freundesscharen; von denen, die verschiedene Prüfungen zu bestehen haben."},

"Leavetaking of the Dormition of the Mother of God":
{"type": "Fest", "life": "Abschluss des Festes der Entschlafung der Allheiligen Gottesmutter, der letzte Tag, an dem die Kirche ihr seliges Entschlafen und ihre Aufnahme in die Herrlichkeit feiert, ehe sie das Fest beschliesst. An diesem Tage wird der Festgottesdienst noch einmal gesungen, damit die Gläubigen vom Fest Abschied nehmen, neu erfüllt von seiner Freude und seinem Trost.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Matrona of Chios":
{"type": "Nonne · 15. Jh.", "life": "Ehrwürdige Matrona von Chios wurde im Dorfe Volissos auf jener Insel wohlhabenden und frommen Eltern, Leon und Anna, geboren und hiess in der Welt Maria. Von Jugend an zum Mönchsleben geneigt, floh sie die Ehe, welche die Ihren ihr bestimmt hatten, und zog sich an einen einsamen Ort der Insel zurück, wo sie sich dem Fasten und dem Gebet hingab.", "patron": "Angerufen von Nonnen; um die Jungfräulichkeit."},

"Righteous Benjamin":
{"type": "Gerechter Vorvater · 17. Jh. v. Chr.", "life": "Der gerechte Benjamin, der jüngste der zwölf Söhne des Patriarchen Jakob, war das zweite Kind der geliebten Rahel, die bei seiner Geburt auf dem Wege nach Ephrata starb und ihn mit dem letzten Atem Ben-oni nannte, Sohn meines Schmerzes; sein Vater aber nannte ihn Benjamin, Sohn der rechten Hand, und das Kind der Trauer wurde der Liebling des Alters des Patriarchen.", "patron": "Angerufen von den Jüngsten und Liebsten; um die Trauer, die zur Stärke wird."},

"Venerable Sophrony (Sakharov) of Essex (1993)":
{"type": "Archimandrit · 20. Jh.", "life": "Ehrwürdiger Sophronios von Essex, einer der grossen Ältesten des zwanzigsten Jahrhunderts, wurde 1896 als Sergej Sacharow zu Moskau geboren und ging in der Jugend dem Leben eines Malers nach. In den Umwälzungen seiner Zeit verliess er Russland, kam nach einer Zeit des Suchens zum Berge Athos, wurde im Kloster des heiligen Panteleimon Mönch und der nahe Jünger des heiligen Siluan vom Athos.", "patron": "Angerufen von Mönchen; von geistlichen Vätern."},

"Greatmartyr Procopius of Caesarea, in Palestine":
{"type": "Prokonsul (Heerführer) · 4. Jh.", "life": "Heiliger Grossmärtyrer Prokopios, vor seiner Taufe Neanias genannt, stammte aus Jerusalem und lebte unter Kaiser Diokletian. Nach dem Tode seines christlichen Vaters von der heidnischen Mutter Theodosia erzogen, erhielt er eine treffliche Bildung, stieg im kaiserlichen Dienst rasch auf und wurde als Prokonsul nach Alexandreia gesandt, um die Christen zu verfolgen.", "patron": "Angerufen von Soldaten; um die Bekehrung."},

"Venerable Akepsimas the Hermit of Cyrrhus in Syria":
{"type": "Hieromonach · 4. Jh.", "life": "Ehrwürdiger Akepsimas der Einsiedler lebte im vierten Jahrhundert bei Kyrros in Syrien, und Theodoretos hat seinen Kampf unter den Herrlichkeiten der syrischen Wüste aufgezeichnet. In eine kleine Zelle eingeschlossen, verbrachte er sechzig Jahre, ohne gesehen zu werden und ohne zu sprechen, und empfing seine spärliche Nahrung durch ein schräg durch die Mauer gegrabenes Fenster, damit kein Auge dem seinen begegne.", "patron": "Angerufen von Klausnern; um die völlige Einschliessung für Gott."},

"Prophet Haggai":
{"type": "Prophet · 6. Jh. v. Chr.", "life": "Heiliger Prophet Haggai, der zehnte der zwölf kleinen Propheten, wurde während der Gefangenschaft zu Babylon geboren und zog mit den Heimkehrenden nach Jerusalem hinauf. Im zweiten Jahre des Königs Darius, etwa fünfhundertzwanzig Jahre vor Christus, als der Bau des Tempels ein Geschlecht lang darniederlag, während das Volk seine eigenen getäfelten Häuser baute, erging das Wort des Herrn durch ihn.", "patron": "Angerufen von Bauleuten; von denen, die wieder aufbauen, was verloren war."},

"Afterfeast of the Transfiguration of our Lord":
{"type": "Nachfest", "life": "Der erste Tag des Nachfestes der Verklärung des Herrn, an dem die Kirche die auf dem heiligen Berge offenbarte Herrlichkeit weiter feiert. Die Gesänge des Festes rufen das Staunen der Apostel Petros, Jakobos und Johannes in Erinnerung, als sie ihren Meister vor sich verklärt sahen, sein Antlitz und seine Kleider heller leuchtend als die Sonne, und verkünden seine Gleichheit mit dem Vater.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Synaxis of the Saints of Volhynia":
{"type": "Synaxis", "life": "Synaxis der Heiligen Wolhyniens, welche die heiligen Männer und Frauen jenes westlichen Grenzlandes der Rus in einem Feste versammelt, das durch Jahrhunderte der Prüfung den orthodoxen Glauben bewahrt hat. In diesem Chore werden die heiligen Bischöfe Stefan und Amphilochij von Wolodymyr in Wolhynien geehrt, welche die Kirche dort in den Geschlechtern nach der Taufe der Rus pflanzten.", "patron": "Angerufen für das wolhynische Land; um die Treue zur Orthodoxie in den westlichen Landen."},

"Martyr Varus, and seven Monastic Martyrs with him":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Varos war Heerführer in Ägypten in den Tagen der Verfolgung unter Maximian und heimlich ein Christ; bei Nacht besuchte er die gefangenen Bekenner, brachte ihnen Speise, verband ihre Wunden und stärkte ihre Seelen. Einmal verbrachte er die ganze Nacht im Kerker mit sieben asketischen Lehrern der Christen, die auf die Hinrichtung warteten, und staunte über ihren Mut.", "patron": "Angerufen von Soldaten; für die Verstorbenen, die ausserhalb des Glaubens starben."},

"Virgin Martyr Euthalia of Sicily":
{"type": "Jungfrau und Märtyrerin · 3. Jh.", "life": "Heilige Jungfrau und Märtyrerin Euthalia von Sizilien lebte mit ihrer Mutter und ihrem Bruder zu Leontinoi, und ihr kurzes Leben wendete sich ganz an dem Traum einer einzigen Nacht im Schlafe einer anderen. Ihre Mutter, eine Heidin, litt seit langen Jahren am Blutfluss, den kein Arzt stillen konnte, die Krankheit der Frau des Evangeliums, heimgesucht an einer, die das Evangelium nie gehört hatte.", "patron": "Angerufen von Töchtern geteilter Häuser; von den Neugetauften."},

"Venerable Cherimon (Chaeremon) of Egypt":
{"type": "Mönch · 5. Jh.", "life": "Ehrwürdiger Cherimon war ein Asket der ägyptischen Wüste und lebte am Ende des vierten und zu Beginn des fünften Jahrhunderts in der Einöde von Sketis. Er wohnte in einer Höhle fern von der Kirche und von der nächsten Quelle, sodass schon das Wasserholen und der Gang zum Gottesdienst grosse Mühe kosteten, und ermüdete durch solche Härte seinen Leib um seiner Seele willen.", "patron": "Angerufen um die asketische Mühe; um die Stille."},

"Venerable Paphnutius and Euphrosynē of Alexandria":
{"type": "Mönche · 5. Jh.", "life": "Ehrwürdiger Paphnutios von Alexandreia wird an diesem Tage mit seiner Tochter Euphrosyne begangen, deren Hauptfest die Kirche im September hält; das Gedächtnis im Februar gilt besonders dem Vater und dem seltsamsten Trost in den Leben der Heiligen. Paphnutios war ein reicher und frommer Bürger Alexandreias, dessen lange kinderlose Ehe mit einer einzigen Tochter erhört wurde.", "patron": "Angerufen von Vätern geweihter Kinder; von Eltern der Verschwundenen."},

"Venerable Neilos the Ascetic of Sinai":
{"type": "Hieromonach · 5. Jh.", "life": "Ehrwürdiger Neilos der Asket vom Sinai war ein Mann von hohem Rang zu Konstantinopel, Präfekt der Hauptstadt, verheiratet und Vater zweier Kinder, und ein Jünger des heiligen Johannes Chrysostomos, dessen Lehre in ihm das Verlangen nach dem englischen Leben entzündete. Mit der Zustimmung seiner Frau teilte sich die Familie um Gottes willen.", "patron": "Angerufen von Schriftstellern; von geistlichen Führern."},

"Martyr Eleazar the Teacher of the Holy Seven Maccabee Martyrs":
{"type": "Ältester · 2. Jh. v. Chr.", "life": "Heiliger Märtyrer Eleasar lebte im zweiten Jahrhundert vor Christus und war ein Schriftgelehrter und Lehrer, ein Mann von grosser Würde und hohem Alter. Als Antiochos Epiphanes die Juden zwingen wollte, das Gesetz Mose zu verlassen und Schweinefleisch wider den Bund zu essen, weigerte sich Eleasar, obwohl neunzig Jahre alt, sein Leben durch einen so kleinen Kompromiss zu retten oder auch nur Gehorsam vorzutäuschen.", "patron": "Angerufen von Lehrern; um die Lauterkeit im Alter."},

"Venerable Zeno the Faster, of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Zenon der Faster und Arbeitsame aus den Kiewer Fernen Höhlen lebte im vierzehnten Jahrhundert, und die zwei Beinamen, welche die Lawra ihm gab, sind sein ganzes Leben, genau und ausreichend: der Faster und der Arbeitsame. In den Höhlen des heiligen Theodosij, in den harten Geschlechtern nach dem Mongolensturm, führte er den doppelten Kampf.", "patron": "Angerufen von Fastenden; von Arbeitenden."},

"Afterfeast of the Nativity of our Lord and Savior Jesus Christ":
{"type": "Fest", "life": "Das Nachfest der Geburt unseres Herrn trägt die Feier durch die Tage nach dem Feste, denn die Kirche schliesst die Höhle von Bethlehem nicht nach einem Tage, sondern verweilt darin: bei jedem Gottesdienst wiederholt sie Troparion und Kontakion des Festes und singt Christus ist geboren, preiset ihn, über den Heiligen und den Mühen eines jeden Tages.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Chariton of Syanzhemsk, Vologda":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Chariton von Sjanschema war der Jünger und geistliche Sohn des ehrwürdigen Jewfimij von Sjanschema, eines der Einödbewohner des Wologdaer Nordens, und mühte sich unter dessen Führung im Himmelfahrtskloster, das Jewfimij am Flusse Sjanschema errichtet hatte. Er wurde im vollkommenen Gehorsam und in den strengen Überlieferungen der nördlichen Wildnis geformt.", "patron": "Angerufen von Mönchen; um den Gehorsam."},

"Venerable Theoctistus":
{"type": "Abt (Igumen) · 5. Jh.", "life": "Ehrwürdiger Theoktistos war ein grosser Asket der judäischen Wüste und der enge Gefährte des heiligen Euthymios des Grossen, mit dem ihn solche Liebe und Einmütigkeit verband, dass die beiden eine Seele in zwei Leibern zu sein schienen. Jedes Jahr nach dem Fest der Theophanie zogen sie sich gemeinsam in die Wüste zurück, um in der Einsamkeit zu beten, und kehrten erst zum Palmsonntag zurück.", "patron": "Angerufen von Mönchen; um den mönchischen Gehorsam."},

"Martyr Theodota at Nicea":
{"type": "Märtyrerin · 3. Jh.", "life": "Heilige Märtyrerin Theodota litt um das Jahr 230 zu Nikaia in Bithynien unter Kaiser Alexander Severus für Christus. Als Christin angezeigt, wurde sie in den Kerker geworfen und lange festgehalten; vor Gericht geführt, bekannte sie ihren Herrn ohne Wanken.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Repose of Saint Cyril, Equal of the Apostles and Teacher of the Slavs":
{"type": "Apostelgleicher · 9. Jh.", "life": "Entschlafen des heiligen apostelgleichen Kyrillos, des Lehrers der Slawen, der am vierzehnten Februar 869 zu Rom starb; sein gemeinsames Fest mit seinem Bruder Methodios wird im Mai begangen, dieser Tag aber gehört ihm selbst.", "patron": "Angerufen von Übersetzern; von Lehrern."},

"Apostle Timon the Deacon of the Seventy":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Apostel Timon war einer der sieben Diakone, welche die Apostel bestellten, wie die Apostelgeschichte berichtet, als die Zwölf Männer voll Heiligen Geistes und Weisheit erwählten, den notleidenden Witwen der Jerusalemer Kirche zu dienen, Stephanos und Philippos an ihrer Spitze und Timon unter ihrer Zahl, die ersten geweihten Diener der Barmherzigkeit der Kirche.", "patron": "Angerufen von Diakonen; von Bischöfen der Grenzstühle."},

"First and second finding of the Honorable Head of the Holy Glorious Prophet, Forerunner, and Baptist of the Lord, John":
{"type": "Fest · 5. Jh.", "life": "Erste und zweite Auffindung des ehrwürdigen Hauptes des heiligen ruhmreichen Propheten, Vorläufers und Täufers Johannes, die beiden frühesten Abschnitte im seltsamen Weg der nach den Werkzeugen des Leidens meistverehrten Reliquie der Christenheit. Als Herodias das Haupt des Täufers auf der Schale ihrer Rache erlangt hatte, wollte sie nicht dulden, dass es mit seinem Leibe bestattet würde.", "patron": "Angerufen von allen, die das Verborgene suchen; von Hütern der Reliquien."},

"Finding of the relics of Venerable Maximus the Greek (July 4, 1996)":
{"type": "Mönch · 16. Jh.", "life": "Auffindung der Reliquien des ehrwürdigen Maxim des Griechen, des gelehrten Mönches und Bekenners. Um 1470 als Michael Trivolis zu Arta in Griechenland geboren, studierte er in Italien, wurde darauf Mönch auf dem Berge Athos und wurde 1518 nach Russland gesandt, um die heiligen Bücher zu übersetzen und zu berichtigen.", "patron": "Angerufen von Übersetzern und Gelehrten; von den zu Unrecht Gefangenen."},

"Venerable Athanasius, founder of the Great Lavra and Coenobitic Monasticism on Mount Athos, and his six disciples":
{"type": "Abt (Igumen) · 10. Jh.", "life": "Ehrwürdiger Athanasios der Athonit, Gründer der Grossen Lawra und des gemeinsamen Mönchslebens auf dem Heiligen Berge, wurde zu Trapezunt geboren und in der Taufe Abraham genannt. Früh verwaist und von einer frommen Nonne erzogen, deren Lebensweise er sich zu eigen machte, wurde er zu Konstantinopel gebildet und zog sich, zum asketischen Leben gezogen, auf den Athos zurück, um Stille und Einsamkeit zu suchen.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Saint Piamoun":
{"type": "Jungfrau · 4. Jh.", "life": "Heilige Jungfrau Piamun, deren Gedächtnis die Kirche aus der Geschichte der heiligen Asketen des Palladios empfing, erwies, dass die Wüste ein Zustand und keine Anschrift ist, denn sie lebte ihr ganzes geweihtes Leben in der Hütte ihrer Mutter in einem Dorfe am ägyptischen Nil. Dort, unbemerkt von der Welt, der sie entsagt hatte, ohne sie zu verlassen, hielt sie ihre Regel.", "patron": "Angerufen von Asketen im eigenen Hause; von Spinnerinnen und Weberinnen."},

"Hieromartyr Mίlos (or Milēs) the Wonderworker, and two disciples":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Milos der Wundertäter war in der Jugend Soldat und Befehlshaber; er verliess den Dienst der irdischen Könige, wurde Mönch und mit der Zeit zum Bischof der alten Stadt Susa geweiht, wo der Prophet Daniel seine Gesichte geschaut hatte. Um seines asketischen Lebens willen schmückte Gott ihn mit den Gaben der Heilung und der Weissagung.", "patron": "Angerufen um prophetischen Freimut; für die persische Kirche."},

"Saint Eumenius, Bishop of Gortyna":
{"type": "Bischof · 7. Jh.", "life": "Heiliger Eumenios, Bischof von Gortyna auf Kreta, leuchtete im siebten Jahrhundert als Asket und Wundertäter auf. Von Jugend an entsagte er der Welt und ihren Gütern, gab seine Habe den Armen und machte sich arm um Christi willen; durch seine Demut stieg er zu den Höhen der Tugend auf und wurde des Bischofsthrones von Gortyna gewürdigt.", "patron": "Angerufen um Demut; um Regen in der Dürre."},

"Holy Wonderworkers and Unmercenaries Cosmas and Damian of Mesopotamia":
{"type": "Uneigennützige · 3. Jh.", "life": "Heilige Wundertäter und Uneigennützige Kosmas und Damianos aus Asien, das erste der drei Paare heiliger uneigennütziger Brüder dieses Namens, wurden in Kleinasien geboren; ihr heidnischer Vater starb, als sie klein waren, und die heilige Theodota erzog sie in Frömmigkeit und in der Lesung der göttlichen Bücher.", "patron": "Angerufen von Ärzten; von Wundärzten."},

"Martyr Domnina of Anazarbus":
{"type": "Märtyrerin · 3. Jh.", "life": "Heilige Märtyrerin Domnina von Anazarbos in Kilikien litt für Christus unter Kaiser Diokletian und wurde vor Lysias, den Statthalter jener Gegend, geführt. Da sie sich als Christin bekannte und den Götzen nicht opfern wollte, wurde sie unbarmherzig mit Ruten geschlagen und anderen Qualen unterworfen und darauf in den Kerker geworfen, wo sie ihren Geist aufgab.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Dedication of the Church of the Greatmartyr George at Kyiv":
{"type": "Fest", "life": "Gedächtnis der Weihe der Kirche des heiligen Grossmärtyrers Georgios zu Kiew. Es war frommer Brauch der Fürsten der Rus, seit dem heiligen Wolodymyr, Kirchen zu Ehren ihrer Namenspatrone zu errichten: Wolodymyr, in der Taufe Wassilij genannt, baute zu Kiew und Wyschhorod Kirchen des heiligen Basileios, und seine Söhne folgten ihm darin.", "patron": "Angerufen um die Verehrung des Grossmärtyrers Georgios in der Rus; für Kirchen, die aus Dank errichtet werden."},

"Saint Philogonius, Bishop of Antioch":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Philogonios, Bischof von Antiochien, wurde geradewegs aus den Gerichtshöfen auf jenen grossen Stuhl erhoben, und der Sprung sagt, wer er war: als Anwalt war er in der ganzen Stadt als Verteidiger der Unterdrückten berühmt, der Rechtsbeistand des Armen, dessen Beredsamkeit ein Schutzdach war, und sein Leben als Gatte und Vater von untadeliger Tugend entsprach seiner öffentlichen Gerechtigkeit.", "patron": "Angerufen von Rechtsgelehrten; von Anwälten."},

"Venerable Abramius, Archimandrite of Rostov":
{"type": "Archimandrit · 11. Jh.", "life": "Ehrwürdiger Awraamij, Archimandrit von Rostow, mühte sich in den frühen Geschlechtern nach der Taufe der Rus, als im Rostower Lande viele noch an den alten Göttern hingen und am Tschudischen Ende der Stadt ein steinernes Bild des Weles stand, dem das Volk Verehrung darbrachte.", "patron": "Angerufen von Glaubensboten; um den Sturz der Götzen."},

"Martyrs Probus, Tarachus, and Andronicus, at Tarsus in Cilicia":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Probos, Tarachos und Andronikos litten im Jahre 304 in Kilikien in der Verfolgung unter Diokletian. Tarachos war ein betagter römischer Soldat von fünfundsechzig Jahren, der das Heer verlassen hatte, statt Christus zu verleugnen; Probos war ein Mann aus Side, der den Reichtum um des Glaubens willen liess.", "patron": "Angerufen von Soldaten; von Betagten."},

"Hieromartyr Cyprian, Bishop of Carthage":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Hieromärtyrer Kyprianos, Bischof von Karthago, einer der grössten Väter der frühen Kirche, wurde um das Jahr 200 in jener Stadt als Sohn eines reichen heidnischen Senators geboren und wurde ein berühmter Lehrer der Redekunst und der Weisheit und ein Anwalt vor Gericht. Lange, wie er später bekannte, blieb er in tiefer Finsternis, fern vom Lichte der Wahrheit.", "patron": "Angerufen von Theologen; um die Einheit der Kirche."},

"Venerable Damian the Healer, Jeremiah, and Matthew, Clairvoyants, of the Kyiv Caves":
{"type": "Mönch · 11. Jh.", "life": "Ehrwürdige Damian der Presbyter und Heiler, Jeremija und Matfej die Hellsichtigen, Asketen der Nahen Höhlen zu Kiew, hat der heilige Nestor der Chronist unter dem ersten Geschlecht der Jünger der heiligen Antonij und Theodosij beschrieben. Damian, ein eifriger Nachahmer des Theodosij, war sanft, arbeitsam und gehorsam, verbrachte ganze Nächte im Gebet und in der Lesung der Schrift.", "patron": "Angerufen von Ärzten; von Heilkundigen."},

"Venerable Abramius the Wonderworker, Archimandrite of Smolensk":
{"type": "Archimandrit · 13. Jh.", "life": "Ehrwürdiger Awraamij von Smolensk war ein Prediger der Busse und des furchtbaren Gerichtes und wurde in der Mitte des zwölften Jahrhunderts wohlhabenden Eltern geboren, die bei zwölf Töchtern lange um einen Sohn gebeten hatten. Von Kindheit an liebte er die Kirche und die Lesung der Bücher, und nach dem Tode der Eltern gab er all sein Gut den Klöstern, den Kirchen und den Armen.", "patron": "Angerufen von Predigern; um die Busse."},

"Holy Righteous Joseph the Betrothed":
{"type": "Gerechter · 1. Jh.", "life": "Heiliger gerechter Joseph der Verlobte, aus dem königlichen Geschlecht Davids, war ein Zimmermann zu Nazareth, ein betagter Witwer mit Söhnen und Töchtern, unter ihnen Jakobos, Joses, Simon und Judas, welche die Evangelien die Brüder des Herrn nennen; ihm, als einem bewährten Hüter, verlobten die Priester des Tempels die Jungfrau Maria, als ihre Jahre im Heiligtum erfüllt waren.", "patron": "Angerufen von Zimmerleuten; von Hütern."},

"Prophet Jonah":
{"type": "Prophet · 8. Jh. v. Chr.", "life": "Heiliger Prophet Jonas, der Sohn Amathis, stammte aus Gath-Hepher in Galiläa und weissagte im achten Jahrhundert vor Christus; sein Buch wird in der Kirche vor allem in der Vigil des Pascha gelesen, denn in ihm gab der Herr selbst das Zeichen seines Todes und seiner Auferstehung.", "patron": "Angerufen um die Busse; von denen, die in der Tiefe sind."},

"Righteous Simeon, Wonderworker of Verkhoturye":
{"type": "Gerechter · 17. Jh.", "life": "An diesem Tage begeht die Kirche die Verherrlichung des gerechten Symeon von Werchoturje, des Wundertäters des Urals und ganz Sibiriens, dessen Reliquien am achtzehnten Dezember 1694 feierlich übertragen und verherrlicht wurden. Aus vornehmem Hause im europäischen Russland geboren, begrub er seinen Rang im tiefsten Versteck, das einem russischen Edelmann offenstand: im Leben eines armen Wanderers.", "patron": "Angerufen von Schneidern; von Fischern."},

"Saint Philip, Abbot of Irap Near Novgorod":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Filipp von Irap, in der Welt Feofil, kannte seine Eltern nie: als Waise, die um Brot bat, wanderte der zwölfjährige Knabe umher, bis er sich beim Komeler Kloster niederliess und von der Barmherzigkeit der Brüder lebte. Der heilige Kornilij von Komel, der in seinem Klosterhof ein Waisenhaus gebaut hatte und die Armen wie Christi eigene liebte, nahm das Kind auf und kleidete es mit der Zeit ein.", "patron": "Angerufen von Waisen; von Mönchen."},

"Saints Eutychius and Florentius of Nursia":
{"type": "Mönch · 6. Jh.", "life": "Ehrwürdige Eutychios und Florentios lebten im sechsten Jahrhundert als Asketen in einem Kloster bei Nursia in Italien, und ihr Gedächtnis ist in den Dialogen des heiligen Gregorios bewahrt. Eutychios zog viele durch seine Lehre zu Gott, und als der Abt eines benachbarten Klosters starb, bat man ihn, jener Gemeinschaft als Vorsteher zu dienen.", "patron": "Angerufen von Mönchen; um Regen in der Dürre."},

"Martyr Tryphaίnē at Cyzicus":
{"type": "Märtyrerin · 1. Jh.", "life": "Heilige Märtyrerin Tryphaina von Kyzikos, der Stadt am Hellespont, war die Tochter des Senators Anastasios und seiner frommen Gemahlin Sokratia und wurde in einer Frömmigkeit erzogen, die ihr Kampf öffentlich machte; denn als die Verfolgung über die Stadt kam und sie die Schwachen unter den Christen zum Abfall wanken sah, wartete sie nicht, bis man sie fand, sondern bekannte ihren Glauben freimütig und offen.", "patron": "Angerufen von stillenden Müttern; von Frauen, welche die Schwachen stärken."},

"Hieromartyr Dionysius the Areopagite, Bishop of Athens":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Hieromärtyrer Dionysios der Areopagit war ein vornehmer Athener, in aller Weisheit der Griechen bewandert, der als junger Mann während seiner Studien zu Heliopolis in Ägypten die Finsternis sah, die zur Stunde der Kreuzigung die Erde bedeckte, und sprach: Entweder leidet Gott, oder die Welt geht zu Ende.", "patron": "Angerufen von Theologen; von Weisheitsliebenden."},

"Hieromartyr Philip, Bishop of Heraclea and with him the Martyrs Severus, Memnon, and 37 Soldiers in Thrace":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Philippos, Bischof von Herakleia, litt für Christus in der Stadt Philippopolis in Thrakien samt einer grossen Schar von Gläubigen in der Verfolgung unter Diokletian. Unter ihnen war der heilige Severos, der den Hauptmann Memnon zum Glauben an Christus geführt hatte; als dies dem Statthalter bekannt wurde, übergab er den Soldaten der Folter, und auch Severos wurde grausam gequält.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Venerable Gerasimus the New Ascetic of Cephalonia":
{"type": "Hieromonach · 16. Jh.", "life": "Ehrwürdiger Gerasimos der Neue Asket von Kephallenia, der grosse Wundertäter jener Insel, wurde 1506 zu Trikala auf der Peloponnes aus dem vornehmen Hause der Notaras geboren. Auf der Insel Zakynthos wurde er Mönch und auf dem Heiligen Berge Athos vollendet, wo er das grosse Schema empfing.", "patron": "Angerufen von Beschwörern; von Besessenen."},

"Hieromartyr Babylas, Bishop of Antioch, and those with him":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Hieromärtyrer Babylas, Bischof von Antiochien, litt unter Kaiser Decius samt den drei jungen Brüdern Urbanos, Prilidianos und Epolonios und ihrer Mutter Christodula. Als der Kaiser während eines heidnischen Festes aus Neugier die Kirche betreten wollte, in welcher der heilige Bischof die göttliche Liturgie feierte, trat Babylas hinaus und vertrat ihm den Weg.", "patron": "Angerufen um den Freimut vor den Herrschern; um standhaftes Bekenntnis."},

"Hieromartyr Alexander, Bishop of Jerusalem":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Hieromärtyrer Alexandros, Bischof von Jerusalem, wurde an der Katechetenschule zu Alexandreia unter Klemens gebildet, ein Mitschüler und lebenslanger Freund des Origenes, und wurde Bischof einer Stadt in Kappadokien, wo die Verfolgung des Septimius Severus ihn jahrelang in Ketten legte, ein Bekenner, ehe er Hierarch war.", "patron": "Angerufen von Bibliothekaren; von Gelehrten."},

"Icon of the Mother of God of Rzhevsk":
{"type": "Ikone der Gottesmutter · 16. Jh.", "life": "Die Rschewer Ikone der Gottesmutter, auch die Okowezkaja genannt, erschien im Jahre 1539 in einem Walde bei der Stadt Rschew, wo an einem Baume ein wundertätiges Kreuz und eine Ikone der Gottesmutter mit dem heiligen Nikolaos gefunden wurden. Vielen, die im Glauben kamen, wurde Heilung geschenkt, und die Kunde von den Wundern verbreitete sich, sodass die heiligen Bilder eine Zeitlang nach Moskau gebracht wurden.", "patron": "Angerufen um Heilung."},

"Venerable Sebastian Dabovich":
{"type": "Archimandrit · 20. Jh.", "life": "Ehrwürdiger Sebastian von Jackson und San Francisco, der Apostel Amerikas, wurde als Jovan Dabović am einundzwanzigsten Juni 1863 zu San Francisco serbischen Auswanderern geboren und war der erste in den Vereinigten Staaten Geborene, der zum orthodoxen Priester geweiht wurde; so schaut die amerikanische Orthodoxie in ihm ihren eigenen Erstling.", "patron": "Angerufen von Glaubensboten; von Schriftstellern."},

"Saint Nektarios, Metropolitan of Pentapolis, Wonderworker of Aegina (1920)":
{"type": "Metropolit · 20. Jh.", "life": "Heiliger Nektarios von Ägina, einer der meistgeliebten Wundertäter der neueren Zeit, wurde 1846 als Anastasios Kephalas zu Selymbria in Thrakien einer armen und frommen Familie geboren. Nachdem er sich zu Konstantinopel unter Mühen gebildet und auf Chios gelehrt hatte, wurde er dort 1876 Mönch und später geweiht; unter dem Schutz des Patriarchen von Alexandreia studierte er zu Athen Theologie.", "patron": "Angerufen von denen, die Arbeit suchen; bei Krebs und schwerer Krankheit."},

"Venerable Bassian of Tiksnensk, Vologda":
{"type": "Mönch · 17. Jh.", "life": "Ehrwürdiger Wassian von Tiksna war ein Bauer der Wologdaer Lande und arbeitete als Schneider bei Totma, ehe er die Welt verliess; im Erlöserkloster zu Totma aufgenommen, wurde er eingekleidet und liess sich nach einigen Jahren, grössere Stille suchend, am Flusse Tiksna bei einer Nikolaos-Kirche nieder, wo er eine Zelle baute und in völliger Einsamkeit lebte.", "patron": "Angerufen von Schneidern; um die verborgene Askese."},

"Venerable Arcadius of Novotorsk":
{"type": "Mönch · 11. Jh.", "life": "Ehrwürdiger Arkadij von Nowotorschok wurde zu Beginn des elften Jahrhunderts in der Stadt Wjasma einer frommen Kaufmannsfamilie geboren und nahm in der Jugend die harte Mühe der Torheit um Christi willen auf sich. Vor jeder Kreuzprozession nahm er einen Besen und kehrte zwei Tage lang die Strassen von der Kathedrale bis zur Kirche und lehrte dadurch, dass die Seele rein gemacht werden muss.", "patron": "Angerufen von Mönchen; um den Gehorsam."},

"Martyr Ananias of Persia":
{"type": "Märtyrer", "life": "Heiliger Märtyrer Ananias der Perser bekannte Christus im Lande der Feueranbeter und besiegelte sein Bekenntnis mit seinem Blute. Ergriffen und zum Abfall aufgefordert, weigerte er sich und wurde den Qualen übergeben; mitten in seinen Leiden aber öffnete Gott ihm die Augen, sodass der Märtyrer vor allen rief: Ich sehe eine Leiter, die zum Himmel führt, und leuchtende Männer, die mich in eine wunderbare Stadt des Lichtes rufen.", "patron": "Angerufen um die Gesichte, welche den Leidenden geschenkt werden."},

"Venerable Gregory the Decapolite":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Gregorios der Dekapolit wurde zu Eirenupolis in der Dekapolis Isauriens geboren und floh in der Jugend vor der Ehe, welche die Eltern ihm bestimmt hatten; er gab sich Gott im Mönchsstande hin, wurde unter einem unterscheidungsfähigen Ältesten geformt und in jahrelanger Abgeschiedenheit in einer Höhle geprüft, wo er die offenen Angriffe der Dämonen erduldete.", "patron": "Angerufen von denen, die um der Wahrheit willen reisen; um die Verteidigung der heiligen Ikonen."},

"Venerable Cyril the Wonderworker, Abbot of Novoezersk, Novgorod":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Kirill der Wundertäter von Nowojesero war von Gott gezeichnet, ehe er atmete: als seine Mutter in der Kirche bei der göttlichen Liturgie stand, rief das Kind in ihrem Schosse: Heilig, heilig, heilig, Herr Sabaoth; das ungeborene Kind stimmte in den Engelsgesang ein, und die Eltern verstanden, dass der Knabe ihnen nicht gehörte.", "patron": "Angerufen von Gründern; von Kindern, die für Gott gezeichnet sind."},

"Saint Hilarion, Metropolitan of Suzdal and Yuriev":
{"type": "Metropolit · 18. Jh.", "life": "Heiliger Ilarion, Metropolit von Susdal und Jurjew, wurde 1631 im Nischni Nowgoroder Lande als Sohn eines Priesters geboren und ging in der Jugend den Weg des Mönches. Sein erstes grosses Werk war die Florischtschewer Dormitio-Einsiedelei bei Gorochowez, die er aus einer armen Waldsiedlung zu einem blühenden Kloster ausbaute.", "patron": "Angerufen von Erbauern der Kirchen; von Gefangenen."},

"Procession of the Honorable Wood of the Life-Giving Cross of the Lord (First of the three “Feasts of the Savior” in August)":
{"type": "Fest", "life": "Am ersten August feiert die Kirche die Prozession des kostbaren und lebenspendenden Kreuzes des Herrn, das erste der drei Erlöserfeste dieses Monats und den Tag, an dem das Fasten vor der Entschlafung beginnt. Das Fest hat seinen Ursprung in Konstantinopel, wo es wegen der Krankheiten, welche die Hitze des August brachte, Brauch war, das ehrwürdige Holz durch die Strassen zu tragen.", "patron": "Angerufen um die Befreiung von Krankheit; um die Segnung der Wasser."},

"Saint Paul the Confessor, Archbishop of Constantinople":
{"type": "Patriarch · 4. Jh.", "life": "Heiliger Paulos der Bekenner, Erzbischof von Konstantinopel, stammte aus Thessalonike und war Schreiber des betagten Erzbischofs Alexandros der Hauptstadt, der ihn auf dem Sterbebett als des Thrones würdigsten nannte. Paulos wurde 337 erwählt, in den Jahren, da die arianische Häresie, vom Kaiser Constantius begünstigt, in den Palästen Macht hatte, wenn auch nicht in der Wahrheit.", "patron": "Angerufen von Hierarchen; um den nizänischen Glauben."},

"Hieromartyr Alexander, Bishop of Adrianopolis, and the Martyrs Heraclius, Anna, Elizabeth, Theodota, and Glyceria":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Alexandros der Bischof, Herakleios der Soldat und die Frauen Anna, Elisabeth, Theodota und Glykeria litten zu Adrianopolis in Thrakien im Zeitalter der Verfolgungen. Alexandros, Bischof jener Stadt, verkündete das Evangelium mit Freimut und weigerte sich, den Götzen zu opfern; darum wurde er langen und grausamen Martern unterworfen.", "patron": "Angerufen um die Bekehrung durch das Zeugnis der Märtyrer."},

"Saint Fulvian (in Baptism Matthew), Prince of Ethiopia":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Fulvianos, Fürst von Äthiopien, in der heiligen Taufe Matthäus genannt, war eben der Herrscher, der den Apostel Matthäus töten liess, und wurde durch Gottes Erbarmen zum Erben des Apostelamtes seines Opfers. Obgleich der Apostel seine Frau und seinen Sohn von unreinen Geistern geheilt hatte, klagte Fulvianos ihn aus Furcht um die Götter der Väter der Zauberei an und verurteilte ihn zum Feuer.", "patron": "Angerufen von Herrschern; von Büssenden."},

"Martyr Manetha of Cæsarea in Palestine":
{"type": "Märtyrerin · 4. Jh.", "life": "Heilige Märtyrerin Manetha litt um das Jahr 308 zu Kaisareia in Palästina in der Verfolgung unter Maximinus und wurde zusammen mit den heiligen Märtyrern Antoninos, Nikephoros und Germanos ergriffen, die an diesem Tage mit ihr begangen werden. Als eine Christus geweihte Jungfrau wurde sie vielen Martern unterworfen, um ihre Beständigkeit zu brechen.", "patron": "Angerufen um die Reinheit unter dem Spott."},

"Hieromartyr Eutyches, disciple of Saint John the Theologian":
{"type": "Bischof · 2. Jh.", "life": "Heiliger Hieromärtyrer Eutyches war ein Jünger der heiligen Apostel Johannes des Theologen und Paulos, und obgleich er nicht zu den Siebzig gehörte, wird er um seiner Mühen an ihrer Seite willen mit dem Namen eines Apostels geehrt; von ihnen wurde er zum Bischof gemacht. In der Stadt Sebasteia in Samaria geboren, folgte er zuerst dem Apostel Johannes und verkündete darauf mit Paulos das Evangelium.", "patron": "Angerufen von Glaubensboten; um die Verkündigung."},

"Venerable Alypius the Stylite of Adrianopolis":
{"type": "Hieromonach · 7. Jh.", "life": "Ehrwürdiger Alypios der Stylit wurde zu Adrianopolis in Paphlagonien geboren; seine früh verwitwete Mutter gab den Sohn dem Bischof Theodoros zur Erziehung, verteilte ihre Habe an die Armen und diente der Kirche als Diakonisse und lehrte ihr Kind die Entsagung, indem sie sie lebte. Von Jugend an nach dem einsamen Leben verlangend, wurde Alypios sein Weg von der heiligen Märtyrerin Euphemia in einem Gesicht gewiesen.", "patron": "Angerufen von Säulenstehern; um das Ausharren bis ins höchste Alter."},

"Martyr and Archdeacon Laurence, and those with him, of Rome":
{"type": "Diakon · 3. Jh.", "life": "Heiliger Erzdiakon Laurentios und die Seinen litten im Jahre 258 zu Rom in der Verfolgung unter Kaiser Valerian. Der heilige Sixtus, ein Athener, der vor seinem Christwerden Philosoph gewesen war, war damals Bischof von Rom, und als man ihn mit seinen Diakonen Felicissimus und Agapitos ergriff, folgte Laurentios ihm weinend und bat, mit ihm zu leiden.", "patron": "Angerufen von Diakonen; von Köchen."},

"Venerable Antiochus and Antoninus, ascetics of the Syrian Deserts":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdige Antiochos und Antoninos, Asketen der syrischen Wüsten, werden an diesem Tage unter der Schar der Einsiedler des freien Himmels begangen, deren Leben der selige Theodoretos von Kyrros in seine Geschichte der Mönche Syriens gesammelt hat, jenes Geschlecht von Kämpfern, das im fünften Jahrhundert die Hügel jenes Landes mit einem Streit erfüllte, den die Städte darunter kaum ahnten.", "patron": "Angerufen von Gefährten in der Askese; um den offenen Himmel, gemeinsam ertragen."},

"Apostle Onesimus of the Seventy":
{"type": "Apostel der Siebzig, Märtyrer · 2. Jh.", "life": "Heiliger Apostel Onesimos, einer der Siebzig, ist der eine Mann des Neuen Testaments, der zugleich sein Gegenstand ist, denn der kürzeste Brief des Paulos ist ganz über ihn geschrieben. Als Sklave des Philemon, des Christen zu Kolossai, tat er seinem Herrn Unrecht und floh, und der Weg des Entlaufenen endete in Rom, zu den Füssen des gefangenen Paulos.", "patron": "Angerufen von Dienenden; von den ehemals Versklavten."},

"New Martyr Anastasius of Epirus":
{"type": "Märtyrer · 18. Jh.", "life": "Heiliger Neumärtyrer Anastasios von Paramythia in Epeiros litt im Jahre 1750 unter dem osmanischen Joch. Ein junger griechischer Christ jener Stadt, wurde er von den Leuten des Ortsherrn ergriffen und, fälschlich angeklagt, vor die Wahl gestellt, die so viele seines Geschlechts brach oder krönte: den Islam anzunehmen und in Ehren zu leben oder Christ zu bleiben und zu sterben.", "patron": "Angerufen für die geknechtete Kirche; um das Zeugnis, welches das Haus des Verfolgers bekehrt."},

"Venerable Arsenius of Novgorod the Fool-For-Christ":
{"type": "Narr in Christo · 16. Jh.", "life": "Ehrwürdiger Arsenij von Nowgorod, der Narr in Christo, nahm um der Liebe Gottes willen den harten und demütigenden Weg der Torheit auf sich, verbarg seine Heiligkeit unter dem Anschein des Wahnsinns und ertrug Kälte, Hunger und den Spott der Menschen. Er lebte im sechzehnten Jahrhundert zu Gross Nowgorod, in den furchtbaren Tagen des Zaren Iwan des Schrecklichen, und empfing die Gaben der Weissagung und des Freimuts.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Theocteristus, Abbot of Symbola on Mount Olympus, Bithynia":
{"type": "Abt (Igumen) · 9. Jh.", "life": "Ehrwürdiger Theokteristos war Abt des Klosters Symbola auf dem bithynischen Olymp, jenem heiligen Berge, der im achten und neunten Jahrhundert die grösste Pflanzstätte des Mönchtums im christlichen Osten war; seine Hänge waren voll von Lawren und Zellen, und seine Klöster waren die Bollwerke des Glaubens durch die Stürme des Bildersturms.", "patron": "Angerufen von Äbten; um die Treue unter dem Bildersturm."},

"Martyr Zoticus the Keeper of Orphans":
{"type": "Priester · 4. Jh.", "life": "Heiliger Hieromärtyrer Zotikos, der Waisenpfleger, war ein berühmter und reicher Römer im Dienste des heiligen Konstantin des Grossen und kam mit dem Kaiser in die neue Hauptstadt am Bosporus, wo er zum Priester geweiht wurde und wo sein Reichtum seine Bestimmung fand. Als ein Erlass aus Furcht vor der Ansteckung gebot, die Aussätzigen der Stadt zu ertränken, ging er zum Kaiser und erbat Gold.", "patron": "Angerufen von Waisen; von Aussätzigen."},

"Martyr Athanasius, Abbot of Bretsk":
{"type": "Abt (Igumen) · 17. Jh.", "life": "Heiliger Hieromärtyrer Afanassij, Abt von Brest, wurde um 1597 einer frommen weissrussischen Familie namens Filippowitsch geboren und erhielt eine gründliche Bildung; in der Jugend war er Lehrer, ehe er im Kloster des Heiligen Geistes zu Wilna eingekleidet wurde. Zum Hieromonachen geweiht und später zum Vorsteher des Symeon-Klosters zu Brest bestellt, wurde er einer der freimütigsten Verteidiger der Orthodoxie.", "patron": "Angerufen um die Verteidigung der Orthodoxie; um den Freimut vor den Herrschern."},

"The Placing of the Cincture (Sash) of the Mother of God":
{"type": "Fest", "life": "Gedächtnis der Niederlegung des ehrwürdigen Gürtels der Allheiligen Gottesmutter in der Gottesmutterkirche zu Chalkoprateia in Konstantinopel. Nach der Überlieferung gab die Gottesmutter bei ihrer Entschlafung ihren Gürtel dem Apostel Thomas; später wurde er aus Zela in die Kaiserstadt gebracht und dort in einem versiegelten Schrein verwahrt.", "patron": "Angerufen um Schutz; um Heilung."},

"Monastic Martyr Anastasia of Rome":
{"type": "Nonne · 3. Jh.", "life": "Ehrwürdige Märtyrerin Anastasia die Römerin wurde mit drei Jahren Waise und in einer Gemeinschaft von Jungfrauen bei Rom von der heiligen Ältesten Sophia erzogen, die sie im Gebet, im Fasten und in der Liebe zu Christus formte, sodass die Schönheit ihrer Seele beim Heranwachsen die grosse Schönheit ihres Angesichts überstrahlte.", "patron": "Angerufen von Nonnen; um die Jungfräulichkeit."},

"Saint Menas, Patriarch of Constantinople":
{"type": "Patriarch · 6. Jh.", "life": "Heiliger Menas, Patriarch von Konstantinopel, war zuerst Presbyter jener Stadt und Vorsteher des Sampson-Hospizes, wo er in den Tagen Kaiser Justinians die Armen und die Kranken mit grossem Erbarmen pflegte. Als der Patriarch Anthimos wegen seines heimlichen monophysitischen Irrtums abgesetzt wurde, erwählte man Menas, einen Mann von erwiesener Heiligkeit, an seiner Statt.", "patron": "Angerufen von den Armen und Kranken; um die Barmherzigkeit."},

"Greatmartyr Niketas the Goth":
{"type": "Grossmärtyrer · 4. Jh.", "life": "Heiliger Grossmärtyrer Niketas war ein Gote, an den Ufern der Donau geboren und wohnhaft, und wurde von Theophilos, dem Bischof der Goten, getauft, der am Ersten Ökumenischen Konzil teilgenommen hatte. Als der Krieg sein Volk spaltete und der heidnische Fürst Athanarich eine harte Verfolgung gegen die Christen unter den Goten erhob, hatte Niketas durch seine Predigt und sein heiliges Leben schon viele der Seinen gewonnen.", "patron": "Angerufen von Soldaten; von Kindern."},

"Venerable Isaac the Recluse of the Kyiv Near Caves":
{"type": "Klausner · 11. Jh.", "life": "Ehrwürdiger Issaakij der Klausner aus den Kiewer Nahen Höhlen war der erste der getäuschten Einsiedler der Höhlen, und das Paterikon erzählt seinen Fall und seinen Sieg mit gleicher Aufrichtigkeit, denn die Kirche braucht beide Hälften. Als reicher Kaufmann aus Toropez verschenkte er alles, kam zum heiligen Antonij und übertraf alle an Strenge: in eine Zelle von vier Ellen eingemauert, trug er ein rohes Ziegenfell.", "patron": "Angerufen von den Getäuschten und Wiederhergestellten; von Küchenarbeitern."},

"Venerable Limnaeus, Hermit of Syria":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdiger Limnaios, Einsiedler in Syrien, begann seinen asketischen Lauf unter dem heiligen Thalassios auf dem Hügel bei Targala und blieb bei ihm, wie der Geschichtsschreiber Theodoretos berichtet, lange genug, um die Tugenden seines Lehrers zu erwerben: Schlichtheit der Sitten, Sanftmut und Demut; der Jünger ahmte nicht zuerst die Strengen des Ältesten nach, sondern seinen Charakter, was die rechte Ordnung ist.", "patron": "Angerufen von Blinden; von Asketen unter freiem Himmel."},

"Venerable Cassian of Uglich":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Kassian von Uglitsch, der Grieche genannt, hiess in der Welt Konstantin und stammte von den griechischen Fürsten von Mangup auf der Krim; er kam mit dem Gefolge nach Russland, das die Fürstin Sofia Palaiologina zu ihrer Vermählung mit dem Grossfürsten von Moskau begleitete. Am Hofe geehrt und mit hohem Rang bedacht, wählte er stattdessen die Gesellschaft heiliger Männer.", "patron": "Angerufen von Mönchen; von Verbannten."},

"Venerable Julian the Hermit of Mesopotamia":
{"type": "Mönch · 4. Jh.", "life": "Ehrwürdiger Julianos der Einsiedler aus Mesopotamien, den das Volk Sabas, den Ältesten, nannte, richtete seine Zelle in der Wüste von Osrhoene am Euphrat ein und fand in der Tiefe der Einöde eine nicht von Händen gemachte Höhle, die er den goldenen Palästen vorzog; dort mühte er sich ein halbes Jahrhundert in Fasten und unablässigem Gebet, seine Speise Hirsebrot mit Salz, sein Trank Wasser, einmal in der Woche genommen.", "patron": "Angerufen von Einsiedlern; um den unablässigen Psalmengesang."},

"Righteous Child Artemius of Verkola":
{"type": "Gerechtes Kind · 16. Jh.", "life": "Heiliges gerechtes Kind Artemij von Werkola wurde um 1532 in einem Dorfe am Flusse Pinega im fernen Norden frommen Bauern geboren und war von den ersten Jahren an sanft, gehorsam, dem Gebet ergeben und in jedem guten Werke fleissig, ein Kind, das anderen Kindern nicht glich.", "patron": "Angerufen von Kindern; um die Kinder."},

"Uncovering of the relics of the Holy Martyrs at the Gate of Eugenius at Constantinople":
{"type": "Märtyrer · 5. Jh.", "life": "Auffindung der Reliquien der heiligen Märtyrer am Eugenios-Tor zu Konstantinopel, eines jener stillen Feste, mit denen die Kirche bekennt, dass der Boden der christlichen Stadt ein ungelesener Reliquienschrein ist. In den Tagen Kaiser Arkadios', zu Beginn des fünften Jahrhunderts, begannen am Tor und Turm des Eugenios am Rande der Hauptstadt Heilungen zu geschehen.", "patron": "Angerufen für die vergessenen Gläubigen; von den Suchern der verborgenen Heiligkeit."},

"Venerable Gregory, Abbot of Pelsheme and Wonderworker of Vologda":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Grigorij von Pelschma, der Wundertäter von Wologda, stammte aus dem Bojarengeschlecht der Lopotow im Fürstentum Galitsch; in der Jugend wies er sowohl die Ehe als auch das Erbe zurück, empfing das Mönchsgewand und leuchtete so in der Tugend, dass man ihn zum Abt machte und ihm noch höhere Ehre antrug, vor der er in die nördlichen Wälder floh.", "patron": "Angerufen von Mönchen; um den Freimut vor den Fürsten."},

"Repose of Saint John Chrysostom, Archbishop of Constantinople":
{"type": "Erzbischof · 5. Jh.", "life": "Entschlafen des heiligen Johannes Chrysostomos, des Goldmundes, so genannt um seiner unvergleichlichen Beredsamkeit willen und als einer der Drei Hierarchen geehrt. Um das Jahr 347 zu Antiochien geboren und von seiner verwitweten Mutter Anthusa in Frömmigkeit erzogen, in der Redekunst unter dem berühmten Libanios geschult, liess er eine glänzende weltliche Laufbahn, wurde vom heiligen Meletios getauft und gab sich dem asketischen Leben hin.", "patron": "Angerufen von Predigern; von Rednern."},

"Venerable John the Long-Suffering of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Johann der Vielleidende mühte sich in der Kiewer Höhlenlawra und trägt seinen Namen von dem harten, lebenslangen Kampf, den er um der Reinheit willen führte. Von Jugend an quälte ihn die Leidenschaft des Fleisches, und weder Hunger noch Durst noch das Tragen schwerer Ketten konnten ihn davon befreien.", "patron": "Angerufen um die Keuschheit; von denen, die von der Wollust versucht werden."},

"Martyr Anna":
{"type": "Nonne · 8. Jh.", "life": "Heilige Märtyrerin Anna war eine vornehme Frau zu Konstantinopel, die, von der Liebe zu Christus entzündet, all ihr Gut verkaufte, das Geld den Armen gab und vom heiligen Stephanos dem Neuen, während er sich auf dem Berge Auxentios mühte, das Mönchsgewand empfing; er sandte sie in das Frauenkloster Trichinarion, wo sie im Fasten und im Gehorsam leuchtete.", "patron": "Angerufen von Nonnen; um die Weigerung des falschen Zeugnisses."},

"Hieromartyr Polycarp, Bishop of Smyrna":
{"type": "Hieromärtyrer · 2. Jh.", "life": "Heiliger Hieromärtyrer Polykarpos, Bischof von Smyrna, ist das grosse Gelenk zwischen den Aposteln und der Kirche der Jahrhunderte: ein Jünger des Johannes des Theologen selbst, auf den Stuhl von Smyrna in der Nachfolge des Bukolos gesetzt, und der Freund, dem der verurteilte Ignatios vom Wege schrieb: Stehe fest wie ein Amboss unter dem Hammer.", "patron": "Angerufen von Bischöfen; von den betagten Gläubigen."},

"Forefeast of the Nativity of the Mother of God":
{"type": "Vorfest", "life": "Vorfest der Geburt der Allheiligen Gottesmutter, an dem die Kirche das erste der grossen Feste des neuen Kirchenjahres zu feiern beginnt, die Geburt der Gottesmutter aus den gerechten Joachim und Anna. An diesem Tage beginnen die Gesänge des kommenden Festes in den Gottesdiensten zu erklingen und rufen die Gläubigen, ihre Herzen zu bereiten, um die Jungfrau zu begrüssen.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Repose of the Holy Right-believing Princess Anna of Kashin":
{"type": "Nonne · 14. Jh.", "life": "Entschlafen der heiligen rechtgläubigen Fürstin Anna von Kaschin, der Tochter des Fürsten Dimitrij von Rostow, die 1294 die Gemahlin des heiligen Grossfürsten Michail von Twer wurde. Gott bestimmte ihr ein Leben fast ununterbrochener Trauer: sie begrub ihre kleine Tochter und ihren Vater, sah Twer brennen und die Pest über das Land gehen, und 1318 wurde ihr Gemahl in der Horde gefoltert und getötet.", "patron": "Angerufen von Witwen; von denen, die durch Gewalt Angehörige verloren."},

"Apostle Titus of the Seventy and Bishop of Crete":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Titos, einer der Siebzig, stammte aus Kreta und war der Sohn eines vornehmen heidnischen Hauses; in der Jugend studierte er die Weisheit und die Dichtung der Griechen und hielt sich doch von ihren Lastern fern. Zur Wahrheit gezogen, wurde er ein Jünger und geliebter Mitarbeiter des Apostels Paulos, der ihn sein rechtes Kind im gemeinsamen Glauben nannte und zum ersten Bischof von Kreta machte.", "patron": "Angerufen von Glaubensboten; für Kreta."},

"Saint Maruthas, Bishop of Martyropolis in Mesopotamia":
{"type": "Bischof · 5. Jh.", "life": "Heiliger Maruthas, Bischof von Martyropolis, war der Arzt und Gesandte, den Gott an das Gelenk zweier Reiche stellte, Hirte von Mayperqat an der römisch-persischen Grenze an der Wende zum fünften Jahrhundert, in der Heilkunde, in der syrischen Schrift und in den Wegen der Höfe bewandert. Zweimal sandten ihn die Kaiser von Konstantinopel als Gesandten zum persischen König Yazdegerd.", "patron": "Angerufen von Ärzten; von Gesandten."},

"Translation of the relics of Venerable Theodore, Abbot of Studion":
{"type": "Abt (Igumen) · 9. Jh.", "life": "Übertragung der Reliquien des ehrwürdigen Theodoros, Abtes von Studion, dessen Hauptfest im November begangen wird; das Gedächtnis im Januar erinnert an den Tag, da der grosse Bekenner heimkehrte. Theodoros hatte sein Leben lang die heiligen Ikonen und die Freiheit der Kirche gegen die Kaiser verteidigt und Geisselung, Kerker und wiederholte Verbannung erduldet.", "patron": "Angerufen von Mönchen; von den gerechtfertigten Bekennern."},

"Venerable Therapon, Abbot of Monza":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Ferapont von Monsa mühte sich in der zweiten Hälfte des sechzehnten Jahrhunderts; im Moskauer Lande zum Mönchsleben geformt, hielt er das Gedächtnis und das Beispiel des seligen Wassilij, des grossen Narren in Christo, in Ehren. Die Stille suchend, zog er sich in die nördlichen Wälder des Kostromaer Landes zurück und liess sich im Kloster am Flusse Monsa bei Galitsch nieder, das darauf seinen Namen trug.", "patron": "Angerufen von Bauern in der Hungersnot; um die Warnung vor dem Unglück."},

"Venerable Stephen, Abbot of Makhrishche, Vologda":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Stefan von Machrischtsche stammte aus Kiew und empfing im Höhlenkloster das Mönchsgewand, wo er einige Jahre in Gehorsam und Gebet verbrachte. Als die Bedrängnis durch die Lateiner das Leben schwer machte, zog er nordwärts nach Moskau, wo der Grossfürst Iwan ihn freundlich aufnahm und ihm gestattete, sich in der Wildnis von Machra niederzulassen, unweit des Klosters des heiligen Sergij.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Holy Wonderworking Unmercenary Physicians Cosmas and Damian at Rome":
{"type": "Ärzte · 3. Jh.", "life": "Heilige Märtyrer und uneigennützige Ärzte Kosmas und Damianos von Rom waren Brüder, zu Rom geboren und zu Ärzten ausgebildet, und empfingen von Gott die Gabe der Heilung. Sie nahmen für die Pflege der Kranken keine Bezahlung, weshalb man sie die Uneigennützigen nennt, behandelten alle, die im Namen Christi kamen, und führten viele zum Glauben.", "patron": "Angerufen von Ärzten; von Wundärzten."},

"Saint Hosius the Confessor, Bishop of Córdoba":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hosius der Bekenner war im vierten Jahrhundert mehr als sechzig Jahre lang Bischof von Cordoba in Spanien und stand um seiner Weisheit und Heiligkeit willen in solchem Ansehen, dass der heilige Kaiser Konstantin der Grosse ihn zu seinen engsten Ratgebern zählte. Hosius riet dem Kaiser, das Erste Ökumenische Konzil zu Nikaia wider die Häresie des Areios zu berufen.", "patron": "Angerufen um die Orthodoxie wider die Häresie; für das Konzil von Nikaia."},

"Venerable Anthony of the Kyiv Far Caves, Founder of Monasticism in Russia":
{"type": "Mönch (Einsiedler) · 11. Jh.", "life": "Ehrwürdiger Antonij, der Vater des Mönchtums im Lande der Rus, wurde im Jahre 983 zu Ljubetsch bei Tschernigow geboren und in der Taufe Antipas genannt. Von Jugend an zum Mönchsleben gezogen, zog er zum Berge Athos, empfing dort das Mönchsgewand und wurde im asketischen Kampf geübt, bis der Abt ihn auf Gottes Antrieb in die Heimat zurücksandte, um dort den Mönchsstand zu pflanzen.", "patron": "Angerufen von Mönchen; um das Mönchsleben in der Rus."},

"Hieromartyr Theodotus, Bishop of Cyrenia":
{"type": "Hieromärtyrer, Bekenner · 4. Jh.", "life": "Heiliger Hieromärtyrer Theodotos, Bischof von Kyrenia auf Zypern, stammte aus Galatien in Kleinasien und kam in der letzten und schlimmsten Zeit der Verfolgungen auf jenen zyprischen Stuhl, als Licinius, mit seinem Mitkaiser Konstantin brechend, im Osten den Schrecken erneuerte, den das Edikt von Mailand beendet haben sollte.", "patron": "Angerufen von Bischöfen unter der Folter; von denen, die ihre Verfolger überleben."},

"Venerable Cyriacus of Tazlau, Romania":
{"type": "Hieromonach · 17. Jh.", "life": "Ehrwürdiger Chiriac von Tazlău wurde an der Wende zum siebzehnten Jahrhundert im Dorfe Mesteacăn in der Moldau geboren, und als seine Eltern ihn als Kind zu den Gottesdiensten des Klosters Tazlău brachten, der Stiftung Stefans des Grossen, fühlte er seine Seele, wie sein Leben berichtet, von göttlicher Sehnsucht beflügelt.", "patron": "Angerufen von geistlichen Vätern; von Einsiedlern."},

"Righteous Mother Olga of Kwethluk, Tanqilria Arrsamquq, Wonderworker, Matushka of All Alaska":
{"type": "Gerechte · 20. Jh.", "life": "Heilige gerechte Mutter Olga von Kwethluk, Tanqilria Arrsamquq, Matuschka von ganz Alaska, wurde am dritten Februar 1916 im Yup'ik-Dorfe Kwethluk am Kuskokwim geboren, und ihr Name in der Sprache ihres Volkes, Arrsamquq, bedeutet die Geringe und Verborgene, eine Weissagung ihres ganzen Lebens.", "patron": "Angerufen von Hebammen; von Müttern."},

"Commemoration of the Holy Righteous David the King, Joseph the Betrothed, and James the Brother of the Lord":
{"type": "Gerechte · 1. Jh.", "life": "In den Tagen nach der Geburt Christi begeht die Kirche gemeinsam die heiligen Gerechten Joseph den Verlobten, David den König und Jakobos den Bruder des Herrn, die Synaxis der Verwandten des Herrn dem Fleische nach, von alters her für den Sonntag nach dem Feste bestimmt und auch an diesem Tage gehalten.", "patron": "Angerufen von den Familien der Diener des Herrn; um die Verwandtschaft mit Christus durch den Gehorsam."},

"Martyr Aithalas of Persia":
{"type": "Diakon · 4. Jh.", "life": "Heiliger Märtyrer Aithalas, ein Diakon der Kirche in Persien, litt im Jahre 380 für Christus in der Verfolgung der Christen unter dem König Sapor. Da er den Glauben fest bekannte und sich weigerte, das Feuer und die Sonne anzubeten, wie die Perser taten, wurde er auf Befehl des Königs verurteilt und gesteinigt und empfing so den Kranz des Martyriums.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Venerable Anthony, Abbot of Siya, Novgorod":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Antonij von Sija wurde 1477 im Dorfe Kechta an der Nördlichen Dwina geboren und Andrej genannt; von Jugend an begabt, lernte er neben dem Lesen auch die Ikonenmalerei, und nach dem frühen Tode seiner jungen Frau wandte er sich ganz Gott zu und empfing im Kloster des heiligen Pachomij an der Kena das Mönchsgewand mit dem Namen Antonij.", "patron": "Angerufen von Ikonenmalern; von Mönchen."},

"Repose of Saint Cyprian, Metropolitan of Moscow and All Russia":
{"type": "Metropolit · 15. Jh.", "life": "Entschlafen des heiligen Kiprian, Metropoliten von Kiew und Moskau und ganz Russlands, eines Bulgaren aus der Stadt Tarnowo, der in der hesychastischen Überlieferung geformt wurde und sich als Mönch auf dem Heiligen Berge Athos mühte, ehe der Patriarch von Konstantinopel ihn nach Norden sandte. In einer Zeit der Spaltung und der Wirren zum Metropoliten geweiht, erduldete er vieles.", "patron": "Angerufen von Übersetzern; von Hymnendichtern."},

"Commemoration of the Vladimir Icon of the Mother of God and the deliverance of Moscow from the Invasion of Tamerlane":
{"type": "Ikone der Gottesmutter · 14. Jh.", "life": "Gedächtnis der Wladimirer Ikone der Gottesmutter und der Errettung Moskaus vor dem Einfall Timurs. Die Ikone, nach der Überlieferung vom Evangelisten Lukas gemalt und aus Konstantinopel in die Rus gebracht, wurde vom heiligen Andrej Bogoljubskij in die Kathedrale von Wladimir gestellt, von der sie ihren Namen trägt, und wurde die geliebteste und schirmende Ikone des russischen Landes.", "patron": "Angerufen um den Schutz Russlands; um die Errettung vor dem Einfall."},

"Repose of the Holy Apostle and Evangelist John the Theologian":
{"type": "Apostel · 2. Jh.", "life": "Entschlafen des heiligen Apostels und Evangelisten Johannes des Theologen, des geliebten Jüngers, des Sohnes des Zebedaios und der Salome und Bruders des Jakobos, der von seinen Netzen am See von Galiläa gerufen wurde, Christus nachzufolgen, und der von allen Jüngern der Brust des Herrn am nächsten lag.", "patron": "Angerufen von Theologen; von Schriftstellern."},

"Finding of the relics of Saint Gamaliel":
{"type": "Gerechter · 1. Jh.", "life": "Auffindung der Reliquien des heiligen Gamaliel, eines Pharisäers und berühmten Gesetzeslehrers, der unter den Juden in Ehren stand, zur Mässigung gegen die Apostel riet, als man sie vor den Rat führte, wie die Apostelgeschichte erzählt, und der Lehrer des heiligen Paulos gewesen war. Im Verborgenen wurde er ein Jünger Christi, und als der Erzmärtyrer Stephanos gesteinigt und unbestattet liegen gelassen wurde, nahm Gamaliel ihn ehrfürchtig auf.", "patron": "Angerufen von Lehrern; von heimlichen Jüngern."},

"“Virgin of Tenderness” Icon of the Mother of God of the Pskov Caves":
{"type": "Ikone der Gottesmutter · 16. Jh.", "life": "Die Ikone der Zärtlichkeit der Allheiligen Gottesmutter, vom Typus Umilenije, in dem das Christuskind seine Wange an die seiner Mutter drückt, gehört dem Höhlenkloster zu Pskow, wohin sie zu Beginn des sechzehnten Jahrhunderts von frommen Christen gebracht wurde und zur Schirmherrin der Stadt wurde.", "patron": "Angerufen um den Schutz Pskows; um die Errettung vor dem Einfall."},

"Saint Leo of Cappadocia":
{"type": "Mönch, Märtyrer · 9. Jh.", "life": "Ehrwürdiger Leon von Kappadokien wird im Kalender um einer einzigen Tat willen erinnert, und es ist jene, die der Herr selbst als das Höchste der Liebe genannt hat. Als Mönch des kappadokischen Landes im Zeitalter der sarazenischen Einfälle, da die Grenzlande Kleinasiens unter der beständigen Geissel der Menschenraubzüge lebten, sah Leon, wie die Räuber drei seiner Mitbrüder verschleppten, kranke und gebrechliche Männer.", "patron": "Angerufen von Gefangenen; von denen, die andere loskaufen."},

"Martyrs Thyrsos, Leukios, and Kallinikos":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Thyrsos, Leukios und Kallinikos litten um das Jahr 250 zu Apollonia in Bithynien in der Verfolgung des Decius. Leukios eröffnete den Kampf: als er die Grausamkeiten sah, die man den Christen antat, hielt er dem Statthalter Kumbrikios ins Angesicht vor, dass er wider Gott streite, und wurde nach Martern enthauptet, und sein Freimut entzündete die Stadt.", "patron": "Angerufen von Sägern; von Priestern, die sich von den Götzen bekehrten."},

"Venerable Nestor the Chronicler of the Kyiv Caves":
{"type": "Diakon · 12. Jh.", "life": "Ehrwürdiger Nestor der Chronist, der Vater der russischen Geschichtsschreibung, wurde um das Jahr 1050 zu Kiew geboren und kam mit siebzehn Jahren zum heiligen Theodosij ins Höhlenkloster; unter dessen Nachfolger Stefan empfing er das Mönchsgewand und die Weihe zum Hierodiakon. Mit tiefer Demut geschmückt, die aus jeder Seite atmet, die er schrieb, hielt er sich für den Geringsten.", "patron": "Angerufen von Geschichtsschreibern; von Chronisten."},

"Venerable Benjamin of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Wenjamin aus den Kiewer Höhlen lebte im vierzehnten Jahrhundert und war, ehe er das Mönchsgewand empfing, ein grosser Kaufmann, der in den Geschäften dieser Welt gedieh. Einmal, als er beim Gottesdienst stand, hörte er wie zum ersten Male die Worte des Erlösers, dass ein Reicher schwer in das Himmelreich eingehe, und das Wort durchbohrte sein Herz wie ein Schwert.", "patron": "Angerufen von Kaufleuten; um die Entsagung des Reichtums."},

"Blessed John “the Hairy” and Fool-For-Christ at Rostov":
{"type": "Narr in Christo · 16. Jh.", "life": "Seliger Iwan, der Barmherzige und auch der Haarige genannt, nahm zu Rostow die harte und verborgene Mühe der Torheit um Christi willen auf sich und ertrug Kälte, Hunger und Schmähung um der Liebe Gottes willen. Er hatte kein eigenes Haus, sondern fand Obdach bald bei seinem geistlichen Vater, einem Priester der Allerheiligenkirche, bald bei der einen oder anderen armen Witwe der Stadt.", "patron": "Angerufen um Demut; von denen, die kein Haus haben."},

"Martyrs Menas, Hermogenes, and Eugraphus, of Alexandria":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Menas, Hermogenes und Eugraphos litten um das Jahr 313 zu Alexandreia unter Kaiser Maximian, und ihr Kampf ist eine Kette von Bekehrungen, unter der Folter geschmiedet. Menas, ein Athener, der um seiner Beredsamkeit willen berühmt war und den die Griechen Kallikelados, den Süssredenden, nennen, wurde vom Kaiser nach Alexandreia gesandt, um den Streit zwischen Heiden und Christen zu stillen.", "patron": "Angerufen von Rednern; von Richtern."},

"Nun-Martyr Eugenia of Rome":
{"type": "Nonne und Märtyrerin · 3. Jh.", "life": "Heilige Nonne und Märtyrerin Eugenia war die Tochter des Philippos, des Statthalters von Ägypten unter den Römern, und wurde zu Alexandreia in aller Bildung der Zeit erzogen; als sie im Verborgenen die Briefe des Apostels Paulos las, fasste die Tochter des heidnischen Statthalters eine Liebe zu Christus, die ihr Leben umstürzte.", "patron": "Angerufen von Äbtissinnen; von Frauen, die sich um Gottes willen verbergen."},

"Commemoration of the Shepherds in Bethlehem who were watching their flocks, and went to see the Lord":
{"type": "Gerechte · 1. Jh.", "life": "Am ersten Tage der Geburt Christi begeht die Kirche die Hirten von Bethlehem, die bei Nacht auf dem Felde bei ihren Herden Wache hielten, als die Herrlichkeit des Herrn sie umleuchtete, und die als die ersten des Menschengeschlechtes das Evangelium verkündet hörten.", "patron": "Angerufen von Hirten; von Nachtwächtern."},

"Saint Tarasius, Archbishop of Constantinople":
{"type": "Patriarch · 9. Jh.", "life": "Heiliger Tarasios, Erzbischof von Konstantinopel, war der Laie, den die Kirche in Dienst nahm, um eine Häresie zu beenden: erster Staatsschreiber des Reiches und der angesehenste Beamte seines Geschlechts, wurde er 784 von der Kaiserin Irene und dem Zuruf des Volkes auf den verwaisten Patriarchenthron erwählt, und er nahm unter einer einzigen Bedingung an: dass ein Ökumenisches Konzil berufen werde.", "patron": "Angerufen von Patriarchen; von Staatsmännern, die an den Altar gerufen werden."},

"Martyr Nestor of Thessalonica":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Nestor von Thessalonike war ein junger Christ, schön von Gestalt und dem Grossmärtyrer Demetrios bekannt, der ihn im Glauben unterwiesen hatte. Als Kaiser Maximian in der Stadt Spiele hielt, warf sein Kämpfer, ein riesiger Vandale namens Lyaios, Herausforderer um Herausforderer von einer hohen Bühne auf aufgerichtete Speere, zur Freude des Kaisers und zum Verderben vieler.", "patron": "Angerufen von Soldaten; von Wettkämpfern."},

"Holy Apostles Stakhys, Apelles, Amplias, Urban, and Narcissus of the 70":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heilige Apostel der Siebzig Stachys, Apelles, Amplias, Urbanos und Narkissos werden im Römerbrief des Apostels Paulos mit Namen gegrüsst, und die Kirche begeht sie an diesem Tage zusammen mit dem Apostel Aristobulos. Stachys, den Paulos seinen Geliebten nennt, wurde vom Apostel Andreas dem Erstberufenen zum ersten Bischof von Byzanz gemacht, jener kleinen Stadt, die einst Konstantinopel sein sollte.", "patron": "Angerufen von Bischöfen; um die Pflanzung der Ortskirchen."},

"Martyrs Ananias the Presbyter, Peter, and seven soldiers, in Phoenicia":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Ananias der Presbyter, Petros der Kerkerwächter und sieben Soldaten litten im Jahre 295 in Phönizien in der Verfolgung unter Diokletian. Ananias, ein Priester jenes Landes, wurde ergriffen, weil er Christus bekannte und die Götzen verwarf, und vor Maximus, den Statthalter Phöniziens, geführt, der die ganze Kunst der Gerichte an ihm übte.", "patron": "Angerufen von Priestern; von Kerkerwächtern."},

"Holy, All-Praised Apostle Philip":
{"type": "Apostel · 1. Jh.", "life": "Heiliger allgepriesener Apostel Philippos, einer der Zwölf, stammte aus Bethsaida in Galiläa, der Stadt des Andreas und des Petros, und war von Jugend an in der Schrift bewandert; und als der Herr ihn fand und sprach: Folge mir nach, fand Philippos sogleich den Nathanael und beantwortete seine Zweifel mit den Worten, die das ganze Verfahren des Evangeliums bleiben: Komm und sieh.", "patron": "Angerufen von Glaubensboten; um das Finden Christi."},

"Venerable Prince Andrew, in Monasticism Joasaph, of Kubensk, Vologda":
{"type": "Mönch · 15. Jh.", "life": "Ehrwürdiger Ioassaf von Kubenskoje, der Wundertäter von Wologda, hiess in der Welt Fürst Andrej und war der Sohn des frommen Fürsten Dimitrij von Klein-Saoserje, ein Nachkomme des heiligen Fürsten Feodor von Smolensk und Jaroslawl. In tiefer Frömmigkeit erzogen, liess er mit zwanzig Jahren sein fürstliches Erbe und empfing im Spaso-Kamennyj-Kloster auf der Insel im Kubenskoje-See das Mönchsgewand.", "patron": "Angerufen von Mönchen; von der Jugend, die sich Gott hingibt."},

"Monastic Martyr Andrew of Crete":
{"type": "Mönch · 8. Jh.", "life": "Heiliger Mönchsmärtyrer Andreas von Kreta, den die Kirche von dem grossen Hymnendichter gleichen Namens und gleicher Insel unterscheidet, war ein Asket auf Kreta in den Tagen, da Kaiser Konstantin Kopronymos gegen die heiligen Ikonen wütete und die Mönche folterte und tötete, die sie verteidigten. Als er von den Leiden der Bekenner hörte, verliess Andreas seine Stille.", "patron": "Angerufen um die Verehrung der heiligen Ikonen; um den Freimut vor den Kaisern."},

"Dormition of the Righteous Anna, the Mother of the Most Holy Theotokos":
{"type": "Gerechte · 1. Jh.", "life": "Entschlafung der gerechten Anna, der Mutter der Allheiligen Gottesmutter und Grossmutter unseres Herrn dem Fleische nach. Anna war die Tochter des Priesters Matthan, aus dem Stamme Levi und dem Geschlechte Aarons, und trug mit ihrem Gemahl, dem gerechten Joachim, lange Jahre die Schmach der Kinderlosigkeit, bis Gott im Alter ihr Gebet erhörte.", "patron": "Angerufen von Müttern; von Grossmüttern."},

"“Enlightener of Minds” Icon of the Mother of God":
{"type": "Ikone der Gottesmutter", "life": "Die Ikone der Gottesmutter mit dem Namen Erleuchterin der Sinne zeigt die Allheilige Gottesmutter mit ihrem göttlichen Sohne, der die Quelle aller Weisheit und Einsicht ist. Vor diesem Bilde beten die Gläubigen um die Erleuchtung des Sinnes und des Herzens durch die Wahrheit Gottes, und Eltern, deren Kinder schwer lernen, sei es im Glauben oder im weltlichen Wissen, flehen die Gottesmutter an.", "patron": "Angerufen von Lernenden; von Kindern, die schwer lernen."},

"Translation of the Image “Not-Made-By-Hands” of our Lord Jesus Christ from Edessa to Constantinople, the Third “Feast of the Savior in August”":
{"type": "Fest · 10. Jh.", "life": "Gedächtnis der Übertragung des nicht von Händen gemachten Bildes unseres Herrn Jesus Christus von Edessa nach Konstantinopel im Jahre 944, des dritten der Erlöserfeste im August. Als der Herr in Galiläa verkündete, lag Abgar, der Herrscher von Edessa, aussätzig darnieder, und da er von den vielen Wundern Christi gehört hatte, sandte er einen Boten, ihn zu bitten, zu kommen und ihn zu heilen.", "patron": "Angerufen um Heilung; um die Verehrung der heiligen Ikonen."},

"Venerable Theophanes the Merciful of Gaza":
{"type": "Gerechter", "life": "Ehrwürdiger Theophanes der Barmherzige war ein Bürger von Gaza, reich an Gütern und reicher noch an Erbarmen. Sein Haus stand jedem Fremden und Wanderer offen, er kleidete die Nackten, speiste die Hungrigen und pflegte die Kranken und gab seine ganze Habe in Almosen hin, bis er selbst in Not geriet.", "patron": "Angerufen von Almosengebern; um die Barmherzigkeit gegen die Armen."},

"Martyr Barlaam of Caesarea, in Cappadocia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Barlaam war ein betagter Christ und litt um das Jahr 304 in der Verfolgung unter Diokletian; die alten Berichte setzen seinen Kampf nach Kaisareia in Kappadokien oder, wie andere erzählen, nach Antiochien. Ergriffen und vor Gericht geführt, bekannte der Greis sich mit wenigen und schlichten Worten als Christ, denn er war ungelehrt.", "patron": "Angerufen von Betagten; um das Ausharren in der Schwachheit."},

"45 Holy Martyrs at Nicopolis in Armenia":
{"type": "Laien · 4. Jh.", "life": "Die fünfundvierzig heiligen Märtyrer von Nikopolis in Armenien litten unter Kaiser Licinius, der den Osten regierte und die Kirche hart verfolgte und jedem Christen den Tod androhte, der nicht zu den Götzen zurückkehrte. Als die Verfolgung Nikopolis erreichte, beschlossen mehr als vierzig Gläubige unter Leontios, Maurikios, Daniel, Antonios und Alexandros, sich nicht zu verbergen, sondern offen vor den Statthalter zu treten.", "patron": "Angerufen um das freimütige Bekenntnis."},

"Virgin Martyr Irais (Rhais) of Alexandria":
{"type": "Märtyrerin · 4. Jh.", "life": "Heilige Jungfrau und Märtyrerin Irais, auch Rhais genannt, war eine Jungfrau zu Alexandreia in Ägypten. Als sie eines Tages hinausging, um am Brunnen Wasser zu schöpfen, sah sie am Ufer ein Schiff voll Bekenner Christi, Priester, Diakone, Mönche und Jungfrauen, von den Verfolgern in Ketten gehalten.", "patron": "Angerufen um das freiwillige Bekenntnis; um den Mut."},

"First finding of the relics of Saint Metrophanes, first Bishop of Voronezh":
{"type": "Bischof · 18. Jh.", "life": "Erste Auffindung der Reliquien des heiligen Mitrofan, des ersten Bischofs von Woronesch, der 1682 geweiht wurde und um seiner tiefen Frömmigkeit, seiner Sorge für die Armen und seines Eifers für die Kirche willen berühmt war. Als Ratgeber und Förderer Kaiser Peters des Grossen beim Bau der russischen Flotte zu Woronesch scheute er nicht, den Herrscher zurechtzuweisen, als heidnische Standbilder aufgestellt wurden, und wurde gehört.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Saint Gregory, Wonderworker of Neocaesarea":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Gregorios der Wundertäter, Bischof von Neokaisareia, wurde vornehmen heidnischen Eltern in jener Stadt des Pontos geboren, und da er die Weisheit in den Schulen suchte, fand er sie endlich zu Kaisareia in Palästina zu Füssen des Origenes, unter dem er Jahre hindurch lernte und durch den er zu Christus kam.", "patron": "Angerufen von Bischöfen; von Katecheten."},

"Martyr Lupus":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Lupos war der treue Diener des Grossmärtyrers Demetrios von Thessalonike und stand seinem Herrn beim Martyrium bei. Er tauchte den Saum seines Gewandes und einen Ring in das Blut des Grossmärtyrers und bewahrte diese wie einen Schatz; durch sie wirkte der Herr zu Thessalonike viele Wunder, sodass die ganze Stadt es erfuhr.", "patron": "Angerufen von Dienenden; um den treuen Dienst."},

"Apostles Patrobus, Hermes, Linus, Gaius, and Philologus, of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heilige Apostel der Siebzig Patrobas, Hermas, Linos, Gaios und Philologos werden in den Briefen des Apostels Paulos gegrüsst, und jeder von ihnen diente dem Evangelium als Bischof und ertrug die Mühen und Gefahren des ersten Zeitalters der Kirche. Linos, den Paulos in seinem letzten Briefe nennt, wurde nach dem Martyrium der Erzapostel der erste Bischof von Rom.", "patron": "Angerufen von Bischöfen; um die Pflanzung der Kirchen."},

"Saint Xenophon of Robeika":
{"type": "Abt (Igumen) · 13. Jh.", "life": "Ehrwürdiger Xenofont von Robeika war ein Jünger des grossen Warlaam von Chutyn, in der strengsten Schule des Nowgoroder Landes vom Gründer selbst geformt, und erwies sich seiner Bildung so würdig, dass die Bruderschaft ihn nach dem Abte Isidor zum Vorsteher des Chutyn-Klosters erhob.", "patron": "Angerufen von Äbten, die neu beginnen; von Gründern."},

"Holy Woman Olympias (Olympiada) the Deaconess of Constantinople":
{"type": "Diakonisse · 5. Jh.", "life": "Heilige Olympias die Diakonisse wurde zu Konstantinopel einer berühmten Senatorenfamilie geboren und blieb in der Jugend als reiche Erbin zurück. Einem vornehmen Präfekten verlobt, der vor dem Vollzug der Ehe starb, hielt sie sich für eine Witwe, und obgleich der Kaiser und ihre Verwandten sie zu einer neuen Ehe drängten, weigerte sie sich und weihte sich ganz Gott.", "patron": "Angerufen von Diakonissen; um das Almosengeben."},

"The Righteous Gideon":
{"type": "Gerechter · 12. Jh. v. Chr.", "life": "Der gerechte Gedeon, Richter Israels, drosch Weizen in der Kelter, um ihn vor den midianitischen Räubern zu verbergen, als der Engel des Herrn ihm erschien und sprach: Der Herr ist mit dir, du starker Held, und ihm gebot, Israel aus der Hand Midians zu erretten.", "patron": "Angerufen von Soldaten; von den Furchtsamen, die zum Mut gerufen sind."},

"Holy Empress Markianḗ":
{"type": "Kaiserin · 6. Jh.", "life": "Heilige Kaiserin Markiane war die Gemahlin des Kaisers Justin des Ersten, der von 518 bis 527 zu Konstantinopel regierte, jenes Soldatenkaisers bäuerlicher Herkunft, dessen Haus Gott vom Balkanland in den Purpur erhob; und Markiane bewahrte in diesem erstaunlichen Aufstieg die Tugenden, die Throne öfter auflösen.", "patron": "Angerufen von Frauen von Rang; von Wohltäterinnen."},

"Leavetaking of the Entry of the Most Holy Theotokos Into the Temple":
{"type": "Fest", "life": "An diesem Tage begeht die Kirche den Abschluss des Festes des Einzugs der Allheiligen Gottesmutter in den Tempel und sammelt die Gnade der Festtage in eine letzte Feier. Noch einmal kehren die Gottesdienste zu den Gesängen des Festes zurück, und die Kirche schaut das dreijährige Kind die Stufen des Heiligtums hinaufgeführt, von Zacharias empfangen und in das Allerheiligste gebracht.", "patron": "Angerufen um die Besiegelung des Festes im Herzen."},

"Persian Martyrs in Martyropolis in Mesopotamia":
{"type": "Märtyrer · 4. Jh.", "life": "Die heiligen persischen Märtyrer zu Martyropolis, die zusammen mit dem heiligen Maruthas begangen werden, der sie sammelte, sind die Schar derer, die in der grossen Verfolgung des persischen Reiches litten, der längsten, welche die Kirche je erduldet hat, als der zoroastrische Staat unter Schapur dem Zweiten und seinen Nachfolgern etwa vierzig Jahre lang die Christen Mesopotamiens und Persiens zu vernichten suchte.", "patron": "Angerufen für die Verfolgten des Ostens; für die Flüchtlinge des Glaubens."},

"Venerable Martha, mother of Saint Simeon Stylites":
{"type": "Gerechte · 5. Jh.", "life": "Ehrwürdige Martha, die Mutter des heiligen Symeon des Styliten, lebte im vierten und fünften Jahrhundert in Kilikien und stammte aus armem Hause; mit ihrem Manne Sisotion zog sie den Sohn auf, der das Wunder seiner Zeit werden sollte. Als Symeon ohne Wissen der Eltern Mönch wurde und seine Säule bestieg, kam Martha in späteren Jahren und begehrte, ihn zu sehen.", "patron": "Angerufen von Müttern; um die Mutterschaft."},

"Leavetaking of the Elevation of the Cross":
{"type": "Fest", "life": "Abschluss des Festes der Weltweiten Erhöhung des kostbaren und lebenspendenden Kreuzes, der letzte Tag der Festzeit des Kreuzes. Die Gesänge der Erhöhung werden noch einmal in ihrer Fülle gesungen, und die Gläubigen, die das Fest durch seine Nachfesttage gehalten haben, nehmen von ihm Abschied und verehren das heilige Holz ein letztes Mal, ehe es in das Heiligtum zurückgetragen wird.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Translation of the relics of Venerable John, Abbot of Rila, Bulgaria":
{"type": "Mönch · 10. Jh.", "life": "Übertragung der Reliquien des ehrwürdigen Iwan von Rila, des himmlischen Schutzherrn des bulgarischen Volkes. Um das Jahr 876 im Dorfe Skrino geboren, hütete er als armer Waise die Herden seiner Familie, ehe er alles verliess, um Mönch zu werden.", "patron": "Angerufen von Mönchen; von Einsiedlern."},

"Righteous Hezron":
{"type": "Gerechter Vorvater · 17. Jh. v. Chr.", "life": "Der gerechte Hezron, Sohn des Perez und Enkel des Patriarchen Juda, ist einer der stillen Träger der Verheissung, ein Name, den die meisten Leser überschlagen und den der Himmel nie überschlug. Er war unter den Seelen des Hauses Jakob, die in den Tagen Josephs nach Ägypten hinabzogen, als Kind in das Land getragen, in dem die Familie der Verheissung zu einem Volke werden sollte.", "patron": "Angerufen um die verborgenen Glieder der Verheissung Gottes."},

"Second Day of the Nativity of our Lord":
{"type": "Fest", "life": "Der zweite Tag der Geburt unseres Herrn setzt das Fest in voller Kraft fort, denn die Kirche feiert die Menschwerdung nicht an einem Tage, sondern wohnt darin und wiederholt durch alle Tage des Nachfestes die Gesänge von Bethlehem; und dieser zweite Tag trägt seine eigenen Gedächtnisse.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Right-believing Prince Roman of Ryazan":
{"type": "Fürst · 13. Jh.", "life": "Heiliger rechtgläubiger Fürst Roman Olegowitsch von Rjasan regierte sein Fürstentum in den bitteren Jahren des Tatarenjoches, als die russischen Lande unter der Herrschaft der Goldenen Horde lagen. Ein frommer und gerechter Herrscher, der sein Volk und seinen Glauben verteidigte, wurde er von neidischen Männern beim Chan verleumdet, die ihn beschuldigten, die Religion der Tataren geschmäht zu haben.", "patron": "Angerufen um das Bekenntnis des Glaubens unter der Verfolgung."},

"Saint Juvenal, Patriarch of Jerusalem":
{"type": "Patriarch · 5. Jh.", "life": "Heiliger Juvenalios war in den mittleren Jahren des fünften Jahrhunderts Patriarch von Jerusalem und nahm den Thron der Heiligen Stadt achtunddreissig Jahre lang ein, in einem Zeitalter, das solche Leuchten wie Euthymios der Grosse schmückten, mit dem er eng befreundet war. Sein Bischofsamt fiel in eine Zeit grosser Lehrkämpfe, und er nahm daran führenden Anteil.", "patron": "Angerufen um die Verteidigung der orthodoxen Lehre."},

"Saint Theodore, Bishop of Edessa":
{"type": "Bischof · 9. Jh.", "life": "Heiliger Theodoros, Bischof von Edessa, wurde in jener syrischen Stadt geboren, und als er jung zur Waise wurde, gab er sein Erbe den Armen und zog nach Jerusalem, wo er in der Lawra des heiligen Sabbas des Geheiligten das Mönchsgewand empfing. Viele Jahre mühte er sich dort in Stille und Askese und wurde ein Gefäss der Gnade, bis man ihn gegen seinen Willen zum Bischof erwählte.", "patron": "Angerufen um die Verteidigung der Orthodoxie."},

"Saint Photius, Metropolitan of Kyiv":
{"type": "Metropolit · 15. Jh.", "life": "Heiliger Fotij, Metropolit von Kiew und ganz Russland, war ein Grieche aus Monembasia auf der Peloponnes und trat in der Jugend unter einem grossen asketischen Ältesten in den Mönchsstand. Um seiner Gelehrsamkeit und Heiligkeit willen berühmt, wurde er vom Patriarchen von Konstantinopel zur Leitung der russischen Kirche erwählt, 1408 zum Metropoliten geweiht und kam im folgenden Jahre in das Land.", "patron": "Angerufen um die Einheit der Kirche."},

"Venerable Adrian, Abbot of Ondrusov, Valaam":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Adrian von Ondrussowo, in der Welt der Edelmann Andrej Sawalischin, besass ein reiches Gut nahe der Wildnis, in welcher der heilige Alexander von Swir in Einsamkeit lebte; als er im Walde einem Hirsche nachjagte, stiess er auf den verborgenen Asketen. Von jenem Tage an ging er oft zu ihm um Rat und brachte Brot, ihn und die anderen Einsiedler zu erhalten.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Righteous Philaret the Merciful of Amnia in Asia Minor":
{"type": "Gerechter · 8. Jh.", "life": "Gerechter Philaretos der Barmherzige, der Sohn des Georgios und der Anna, lebte im achten Jahrhundert im Dorfe Amnia in Paphlagonien, ein reicher und geehrter Mann mit einer edlen Gemahlin, Theoseba, und drei Kindern, Johannes, Hypatia und Euanthia; und er hielt das Wort des Erlösers von den Geringsten seiner Brüder fest und gab den Bedürftigen, bis er selbst nichts mehr hatte.", "patron": "Angerufen von Bauern; von Almosengebern."},

"Hieromartyr Hippolytus, and those with him":
{"type": "Hieromärtyrer · 3. Jh.", "life": "Heiliger Hieromärtyrer Hippolytos von Rom litt um das Jahr 269 unter Kaiser Claudius mit den Märtyrern Censorinus, Sabinus, der Jungfrau Chryse und zwanzig anderen; und der Kampf dieser Schar begann mit einem Beamten. Censorinus, ein hoher Würdenträger, wurde als Christ angezeigt und eingekerkert, und im Kerker wirkte die Gnade Christi.", "patron": "Angerufen von Theologen; von Schriftstellern."},

"Martyr Mirax of Egypt":
{"type": "Märtyrer · 7. Jh.", "life": "Heiliger Märtyrer Mirax aus Ägypten ist der Märtyrer der zweiten Gelegenheit, und sein Kranz ist der Kranz der Busse. Zu Tennis in Ägypten frommen christlichen Eltern in den Jahren nach der sarazenischen Eroberung geboren, fiel er in der Jugend: vor dem Emir verleugnete er Christus, nahm den Glauben der Eroberer an und lebte Jahre in seiner Verleugnung, während Vater und Mutter für ihn beteten.", "patron": "Angerufen um die Busse nach dem Abfall; um die Rückkehr derer, die verleugnet haben."},

"Saint Julian, Bishop of Cenomanis (Le Mans), Gaul":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Julianos, erster Bischof von Cenomanis in Gallien, der Stadt, die heute Le Mans heisst, wurde vom Apostel Petros zum Bischof geweiht und von ihm ausgesandt, den Heiden des Abendlandes das Evangelium zu verkünden; und manche halten ihn für denselben wie Simon den Aussätzigen des Evangeliums, der bei seiner Taufe den Namen Julianos annahm.", "patron": "Angerufen um die Verkündigung unter den Völkern; um Heilung."},

"Venerable Thomas of Mount Maleos":
{"type": "Mönch (Einsiedler) · 10. Jh.", "life": "Ehrwürdiger Thomas vom Berge Maleon war in seinem früheren Leben Soldat und Heerführer, angesehen und reich, und wandte auf der Höhe seines weltlichen Erfolges sein Herz ganz Gott zu. Er legte seinen Rang nieder, verteilte sein Gut an die Armen, nahm das Mönchsleben an und zog sich, wie die Überlieferung erzählt, vom Propheten Elias geführt, in die Einsamkeit des Berges Maleon zurück.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Paphnutius the Recluse of the Kyiv Caves":
{"type": "Klausner · 13. Jh.", "life": "Ehrwürdiger Pafnutij der Klausner mühte sich im dreizehnten Jahrhundert in den Fernen Höhlen des heiligen Theodosij, und die Überlieferung der Lawra erinnert ihn um einer einzigen, zur Vollendung geführten Mühe willen: Pafnutij weinte. In der Klause eingeschlossen, nahm er als seine eine Betrachtung das Gedenken des Todes.", "patron": "Angerufen von Trauernden; von denen, die das Gedenken des Todes bewahren."},

"Saint Tabitha the Widow, raised from the dead by the Apostle Peter":
{"type": "Gerechte · 1. Jh.", "life": "Heilige Witwe Tabitha, deren Name auf griechisch Dorkas heisst, das ist Gazelle, war eine Jüngerin des Herrn und wohnte in den Tagen der Apostel zu Joppe, und die Schrift gibt ihr das Zeugnis, dass sie voll guter Werke und Almosen war, die sie tat. Mit eigenen Händen nähte sie Röcke und Kleider für die Witwen und die Armen und diente Christus an Nadel und Webstuhl.", "patron": "Angerufen von Näherinnen; von Almosengebern."},

"Venerable Paraskevi (Petka) of Serbia":
{"type": "Nonne · 11. Jh.", "life": "Ehrwürdige Paraskevi die Neue, die das serbische Volk mit Liebe Sveta Petka nennt, wurde im elften Jahrhundert zu Epivato in Thrakien geboren und gab ihre Jugend Christus hin: sie verteilte ihre Kleider und ihr Erbe an die Armen, mühte sich in einem Kloster bei Herakleia und lebte als Asketin in der Wüste am Jordan, bis ein Engel ihr gebot, in die Heimat zurückzukehren.", "patron": "Angerufen von Frauen; von Kranken."},

"Venerable Ignatius, Archimandrite of the Kyiv Caves":
{"type": "Archimandrit · 15. Jh.", "life": "Ehrwürdiger Ignatij, Archimandrit der Kiewer Höhlen, leitete die grosse Lawra im fünfzehnten Jahrhundert, um das Jahr 1435, und sein kurzes Leben ist in der Inschrift überliefert, die man in späteren Zeiten von seinem Grabstein abschrieb: dass der Mönch Ignatij um seines heiligen Lebens willen von Gott die Gabe der Wunder empfing und viele Kranke durch sein Gebet heilte.", "patron": "Angerufen von Priestern, welche die Liturgie feiern; von Kranken."},

"Apostle James, son of Alphaeus":
{"type": "Apostel · 1. Jh.", "life": "Heiliger Apostel Jakobos, der Sohn des Alphaios, war einer der Zwölf und wurde vom Herrn zugleich mit den Fischern Galiläas gerufen; nach der Überlieferung der Kirche war er der Bruder des Apostels und Evangelisten Matthäus, des einstigen Zöllners. Von seinen Worten berichten die Evangelien nichts, doch seine Taten füllen das Schweigen: nach Pfingsten verkündete er das Evangelium unter den Völkern.", "patron": "Angerufen um die Aussaat des Wortes; um die apostolische Mühe."},

"Saint Theodore, Archbishop of Constantinople":
{"type": "Patriarch · 7. Jh.", "life": "Heiliger Theodoros, Erzbischof von Konstantinopel, diente der Grossen Kirche der Hagia Sophia als Presbyter und Synkellos, als vertrauter Ratgeber des Patriarchen, und war in der ganzen Hauptstadt um der Reinheit seines Lebens willen berühmt, ehe er in den Tagen Kaiser Konstantins Pogonatos auf den Patriarchenthron selbst erhoben wurde.", "patron": "Angerufen von Klerikern grosser Kirchen; um die Heiligkeit inmitten der Ränke der Hauptstädte."},

"Venerable Ignatius of Loma and Yaroslav":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Ignatij von Loma und Jaroslawl verbarg seine Anfänge so gut, dass die Umstände seines Lebens in der Welt unbekannt sind, was selbst die erste Tatsache seines Lebens ist: ein Mann, der erst in die Aufzeichnung eintrat, als er in Gottes Dienst trat. Seinen asketischen Weg begann er im Erlöserkloster zu Priluki bei Wologda und empfing im grossen Kloster des heiligen Kirill am Weissen See das Mönchsgewand.", "patron": "Angerufen von Einsiedlern; von Gründern, die sich zurückziehen."},

"Saint Gregory, Bishop of Agrigentum":
{"type": "Bischof · 6. Jh.", "life": "Heiliger Gregorios, Bischof von Akragas auf Sizilien, wurde im Dorfe Pretorium bei jener Stadt den frommen Chariton und Theodota geboren und vom Bischof von Akragas selbst getauft, der die Gnade über dem Kinde voraussah. Ein Knabe von aussergewöhnlichen Gaben, beherrschte er früh die Schrift und zog als junger Mann in den Osten, wurde zu Jerusalem Mönch und vertiefte dort seine Bildung.", "patron": "Angerufen von Verleumdeten; von Auslegern."},

"Hieromartyr Irenaeus, Bishop of Lyons":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Hieromärtyrer Eirenaios, Bischof von Lyon, einer der grossen Lehrer der frühen Kirche, wurde um das Jahr 130 zu Smyrna geboren und erhielt eine treffliche Bildung. Sein Führer im Glauben war der heilige Polykarpos von Smyrna, selbst ein Jünger des Apostels Johannes des Theologen, und im Alter erinnerte sich Eirenaios, wie er als Knabe Polykarpos von seinen Gesprächen mit den Aposteln hatte reden hören.", "patron": "Angerufen von Theologen; um die orthodoxe Theologie."},

"Venerable Thalassius, Hermit of Syria":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdiger Thalassios, Einsiedler in Syrien, lebte im fünften Jahrhundert und zog sich in jungen Jahren auf einen Hügel beim Dorfe Targala zurück, wo er achtunddreissig Jahre im mönchischen Kampf verbrachte, ohne Dach über dem Haupte, ohne Zelle und ohne jedes Obdach; der Himmel Syriens war seine einzige Baukunst durch fast vier Jahrzehnte von Sommern und Wintern.", "patron": "Angerufen von Lehrern der Einsiedler; von den Sanftmütigen."},

"Martyr Phaedrus":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Phaidros wird an diesem Tage zusammen mit dem Märtyrer Philumenos von Ankyra begangen, in der Schar derer, die um das Jahr 274 in Galatien unter Kaiser Aurelian litten. Die griechischen Synaxarien halten die Art seines Kampfes fest: da er Christus nicht verleugnen wollte, wurde er getötet, indem man siedendes Pech über seinen Leib goss.", "patron": "Angerufen für die Gläubigen, deren Namen niemand aufschrieb."},

"Saint Publius the Ascetic of Syria":
{"type": "Abt (Igumen) · 4. Jh.", "life": "Ehrwürdiger Publios der Asket mühte sich im vierten Jahrhundert bei Zeugma am Euphrat, und sein Gedächtnis ist in der Geschichte der syrischen Mönche bewahrt, die Theodoretos von Kyrros schrieb, der die Überlieferungen der Väter jenes Landes noch aus lebendiger Erinnerung sammelte. Als Sohn eines Ersten der Stadt verkaufte Publios bei seiner Bekehrung sein Erbe, verteilte den Erlös an die Armen und liess sich auf einer Höhe nieder.", "patron": "Angerufen von Gemeinschaften vieler Zungen; von Äbten."},

"Icon of the Mother of God of Volokolamsk":
{"type": "Ikone der Gottesmutter · 16. Jh.", "life": "Die Wolokolamsker Ikone der Gottesmutter ist eine wundertätige Abschrift des grossen Wladimirer Bildes, der geliebtesten Ikone des russischen Landes, und ihr Fest begeht den Tag im Jahre 1572, an dem sie feierlich in das Joseph-Wolokolamsker Kloster gebracht, an dessen Pforten von der Bruderschaft in Prozession empfangen und in der Dormitio-Kirche aufgestellt wurde.", "patron": "Angerufen von Klöstern; von Pilgern."},

"Prophet Samuel":
{"type": "Prophet · 11. Jh. v. Chr.", "life": "Heiliger Prophet Samuel war der fünfzehnte und letzte der Richter Israels und der erste der grossen Propheten nach Moses und lebte mehr als elfhundert Jahre vor der Ankunft Christi. Er wurde auf das inbrünstige Gebet seiner Mutter Hanna geboren, die lange unfruchtbar gewesen war, und weil sie ihn vom Herrn erbeten hatte, nannte sie ihn Samuel.", "patron": "Angerufen von Propheten; von denen, die um Kinder bitten."},

"Righteous Priest Aaron":
{"type": "Hoherpriester · 13. Jh. v. Chr.", "life": "Der gerechte Aaron, erster Hoherpriester des alten Bundes, älterer Bruder des Moses und der Mirjam, aus dem Stamme Levi, wurde von Gott zum Munde seines Bruders gegeben, ging mit ihm vor den Pharao und streckte den Stab der Zeichen aus; und am Sinai wurde er mit seinen Söhnen zum Priestertum geweiht, in die heiligen Gewänder gekleidet und mit dem Öl der Weihe gesalbt.", "patron": "Angerufen von Priestern; von Fürsprechern."},

"Venerable Silouan the Athonite (1938)":
{"type": "Mönch · 20. Jh.", "life": "Ehrwürdiger Siluan vom Athos wurde 1866 im Dorfe Schowskoje im Tambower Gouvernement als Sohn frommer Bauern geboren und Semjon genannt. In der Jugend von grosser Leibeskraft und mit einem Herzen, das schon vom Gedenken Gottes verwundet war, kam er 1892 in das russische Kloster des heiligen Panteleimon auf dem Athos, wo er den unsichtbaren Kampf mit vollem Ernst aufnahm.", "patron": "Angerufen von Mönchen; von allen, die beten."},

"Icon of Sophia, the Wisdom of God (Novgorod)":
{"type": "Ikone", "life": "Die Ikone der Sophia, der Weisheit Gottes, vom Nowgoroder Typus erschien zuerst im fünfzehnten Jahrhundert in jener Stadt, obgleich die erste der Heiligen Weisheit geweihte Kirche Russlands schon im zehnten Jahrhundert zu Nowgorod errichtet worden war. In der Mitte des Bildes ist die Weisheit Gottes als geflügelter und feuriger Engel dargestellt, auf goldenem Throne sitzend, den sieben Säulen tragen, nach dem Worte der Sprüche.", "patron": "Angerufen um die göttliche Weisheit; von Kranken."},

"“Our Lady of Sitka” Icon of the Mother of God":
{"type": "Ikone der Gottesmutter · 19. Jh.", "life": "Die Ikone der Gottesmutter von Sitka gehört zu den meistverehrten Ikonen Nordamerikas und wird in der Kathedrale des Erzengels Michael zu Sitka in Alaska verwahrt. Sie wird dem berühmten russischen Ikonenmaler Wladimir Borowikowskij zugeschrieben und kam in den frühen Tagen der orthodoxen Mission nach Alaska, wo sie als wundertätiges Bild und als Schirmherrin der Gläubigen in Amerika geehrt wird.", "patron": "Angerufen um den Schutz Nordamerikas."},

"Martyr Myron the Presbyter of Cyzicus":
{"type": "Priester · 3. Jh.", "life": "Heiliger Märtyrer Myron war Priester in Achaia, ein Mann von reicher und vornehmer Herkunft und dennoch gegen alle sanft und gütig, ein Freund Gottes und des Nächsten und mutig in der Verteidigung seiner Herde. Er litt im Jahre 250 in der Verfolgung unter Decius, als am Feste der Geburt Christi der Statthalter Antipatros während des Gottesdienstes in die Kirche brach, um die Christen zu ergreifen.", "patron": "Angerufen um die Verteidigung der Herde."},

"Hieromartyr Kindeos the Presbyter of Pamphylia":
{"type": "Priester · 4. Jh.", "life": "Heiliger Hieromärtyrer Kindeos war Priester in Pamphylien in Kleinasien während der Verfolgung Kaiser Diokletians. Von der Gefahr nicht geschreckt, mühte er sich eifrig, das Evangelium zu verkünden und die Gläubigen zu stärken; und als er deswegen bei der Obrigkeit angezeigt wurde, ergriff man ihn und tötete ihn um des Namens Christi willen.", "patron": "Angerufen um die eifrige Verkündigung."},

"Uncovering of the relics of Venerable Sergius of Radonezh":
{"type": "Abt (Igumen) · 14. Jh.", "life": "Auffindung der kostbaren Reliquien des ehrwürdigen Sergij von Radonesch, des grossen Abtes und Wundertäters des russischen Landes, am fünften Juli des Jahres 1422, dreissig Jahre nach seinem Entschlafen. Im Jahre 1408 war die Horde Edigeis eingefallen und hatte das Dreifaltigkeitskloster verbrannt, und die Brüder waren mit ihrem Abte, dem heiligen Nikon, geflohen.", "patron": "Angerufen für das russische Land."},

"Venerable Andrew Rublev the Iconographer":
{"type": "Mönch · 15. Jh.", "life": "Ehrwürdiger Andrej Rubljow, der grösste der russischen Ikonenmaler, wurde um das Jahr 1360 bei Moskau geboren und trat in der Jugend in das Dreifaltigkeitskloster ein, wo der heilige Sergij von Radonesch ihn tief prägte. Nach dessen Entschlafen war er Novize unter dem heiligen Nikon und ging später in das Spaso-Andronikow-Kloster zu Moskau, wo er das Mönchsgewand empfing und die heilige Kunst erlernte.", "patron": "Angerufen von Ikonenmalern; um die heilige Kunst."},

"Saint Michael, first Metropolitan of Kyiv":
{"type": "Metropolit · 10. Jh.", "life": "Heiliger Michail, erster Metropolit von Kiew, war nach der Überlieferung der Kirche ein Syrer von Geburt und wurde aus Konstantinopel in das Land der Rus gesandt, als der Grossfürst Wolodymyr die heilige Taufe empfing und sein Volk zu Christus wandte. Er kam im Jahre der Taufe der Rus mit Klerikern nach Kiew und stand dem Fürsten zur Seite.", "patron": "Angerufen von Glaubensboten; von Hierarchen."},

"Icon of the Mother of God “the Joy of All who Sorrow” (with coins) in St. Petersburg":
{"type": "Ikone der Gottesmutter · 19. Jh.", "life": "Diese wundertätige Ikone der Gottesmutter, die Freude aller Betrübten mit den Münzen genannt, wurde im Jahre 1888 zu Sankt Petersburg verherrlicht. Während eines schweren Gewitters schlug der Blitz in eine Kapelle an der Newa, und obgleich das Feuer alles darin versengte und schwärzte, blieb die Ikone der Himmelskönigin unversehrt und erschien sogar erneuert und aufgehellt.", "patron": "Angerufen um den Trost in der Trauer; um Heilung."},

"Apostle Quadratus of the Seventy":
{"type": "Apostel der Siebzig · 2. Jh.", "life": "Heiliger Apostel Kodratos, einer der Siebzig, verkündete das Wort Gottes zu Athen und zu Magnesia und war Bischof von Athen; sein Lebensbeschreiber nennt ihn einen Morgenstern, der inmitten der Wolken des Heidentums leuchtet. Durch seine Predigt wandte er viele Heiden zum wahren Glauben und erduldete dafür Verfolgung, Steinigung und Kerker von den Feinden Christi.", "patron": "Angerufen von Verteidigern des Glaubens; um die Verteidigung des Glaubens."},

"Forefeast of the Transfiguration of our Lord":
{"type": "Vorfest", "life": "Vorfest der Verklärung unseres Herrn, Gottes und Erlösers Jesus Christus, welche die Kirche am sechsten August feiert. Da der Herr seinen Jüngern vor seinem Leiden einen Vorgeschmack der Herrlichkeit des Reiches geben wollte, nahm er Petros, Jakobos und Johannes mit sich, führte sie auf einen hohen Berg und wurde dort vor ihnen verklärt, sodass sein Antlitz leuchtete wie die Sonne.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Saint Anastasius of the Strumitza Eparchy":
{"type": "Märtyrer · 18. Jh.", "life": "Heiliger Neumärtyrer Anastasios wurde im Jahre 1774 im Dorfe Radovište in der Eparchie Strumica geboren und ging als junger Mann nach Thessalonike, um ein Handwerk zu lernen. Dort, als er etwa zwanzig Jahre alt war, geriet er in den Zorn der Türken, die einen Vorwand ergriffen und ihn zwingen wollten, Christus zu verleugnen und den Islam anzunehmen.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Martyr Chronides of Alexandria and those with him":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Chronides litt im dritten Jahrhundert für Christus samt Leontios und Serapion, alle drei Ägypter, in den Verfolgungen jener Zeit. Nachdem sie um ihres Bekenntnisses willen harte Qualen erduldet hatten, wurden die drei an Händen und Füssen gebunden und ins Meer geworfen, wo sie ihre Seelen Gott übergaben.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Martyrs Acindynus, Pegasius, Aphthonius, Elpidephorus, Anempodistus, and 7,000 with them, of Persia":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Akindynos, Pegasios, Aphthonios, Elpidephoros und Anempodistos litten mit siebentausend Märtyrern um das Jahr 341 in Persien unter dem König Schapur dem Zweiten. Akindynos, Pegasios und Anempodistos waren Höflinge des Königs und heimliche Christen; als Schapur seine Verfolgung gegen die Kirche erhob, wurden sie angezeigt und bekannten vor Gericht Christus offen.", "patron": "Angerufen von Höflingen; von Beamten."},

"Venerable Acacius of Sinai, who is mentioned in the Ladder":
{"type": "Mönch (Novize) · 6. Jh.", "life": "Ehrwürdiger Akakios vom Sinai lebte im sechsten Jahrhundert als junger Mönch unter einem Ältesten in einem Kloster in Asien und wird vor allem um seines aussergewöhnlichen Gehorsams willen erinnert. Sein Ältester war ein harter und schwieriger Mann, der ihn über Mass arbeiten liess, ihn hungern liess und ihn ohne Ursache schlug; Akakios aber trug alles sanftmütig und dankte Gott für alles.", "patron": "Angerufen von Novizen; um den Gehorsam."},

"Repose of Saint Jacob Netsvetov, Enlightener of the Peoples of Alaska":
{"type": "Priester · 19. Jh.", "life": "Entschlafen des heiligen Jakow Netswetow, des Erleuchters der Völker Alaskas, der im Jahre 1802 auf der Insel Atka in den Aleuten geboren wurde, als Sohn eines russischen Vaters aus Tobolsk und einer aleutischen Mutter, sodass ihn das Blut selbst mit dem Volke verband, dem er dienen sollte. Gebildet und mit der Zeit zum Priester geweiht, kehrte er nach Atka zurück.", "patron": "Angerufen von Glaubensboten; von Übersetzern."},

"Saint Angelina of Serbia":
{"type": "Nonne · 16. Jh.", "life": "Ehrwürdige Angelina von Serbien, als Mutter von Heiligen geehrt, war die Tochter des Fürsten Georg von Albanien. Sie wurde dem heiligen Stefan Branković zur Ehe gegeben, dem verbannten und zu Unrecht geblendeten Herrscher Serbiens, der am Hofe ihres Vaters Zuflucht gefunden hatte, und teilte seine Leiden mit Glauben und Mut.", "patron": "Angerufen von Witwen und Müttern."},

"Venerable Porphyrios of Kavsokalyvia (1991)":
{"type": "Hieromonach · 20. Jh.", "life": "Ehrwürdiger Porphyrios von Kavsokalyvia, einer der grossen Ältesten des zwanzigsten Jahrhunderts, wurde 1906 als Evangelos Bairaktaris einer armen Familie auf der Insel Euboia geboren; und als er als Knabe das Leben des heiligen Johannes Kalybites las, entbrannte er in solcher Liebe zu Christus, dass er mit etwa zwölf Jahren zum Heiligen Berge floh, in die Skite Kavsokalyvia, wo er sich in völligem Gehorsam hingab.", "patron": "Angerufen von Ärzten; von Krankenhauspriestern."},

"Holy Apostles of the Seventy: Sosthenes, Apollos, Cephas, Tychicus, Epaphroditus, Caesar, and Onesiphorus":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heilige Apostel der Siebzig Sosthenes, Apollos, Kephas, Tychikos, Epaphroditos, Kaisar und Onesiphoros gehörten zu jenem zweiten Chore, den der Herr selbst zu zweien vor seinem Angesicht aussandte, und ihre Mühen sind durch die Briefe des Paulos gewoben. Sosthenes war Vorsteher der Synagoge zu Korinth und wurde beim Aufruhr gegen Paulos vor dem Richterstuhl geschlagen.", "patron": "Angerufen von Predigern; von Briefboten."},

"Leavetaking of the Transfiguration of our Lord":
{"type": "Fest", "life": "Abschluss des Festes der Verklärung des Herrn, der letzte Tag, an dem die Kirche die auf dem heiligen Berge offenbarte Herrlichkeit feiert, ehe sie das Fest beschliesst. An diesem Tage wird fast der ganze Festgottesdienst noch einmal gesungen, damit die Gläubigen vom grossen Feste Abschied nehmen, neu erfüllt vom Lichte des Tabor.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Longinus the Centurion, who stood at the Cross of the Lord":
{"type": "Märtyrer · 1. Jh.", "life": "Heiliger Märtyrer Longinos der Hauptmann war ein römischer Offizier aus Kappadokien und diente in Judäa unter Pontius Pilatus, und seine Abteilung hielt bei der Kreuzigung des Erlösers auf Golgotha Wache. Als er das Erdbeben, die verfinsterte Sonne und die Wunder sah, die den Tod des Herrn begleiteten, glaubte er und bekannte vor allen: Wahrlich, dieser war Gottes Sohn.", "patron": "Angerufen von Soldaten; bei Augenleiden."},

"Martyrs Paul and two sisters, Chionia (Thea) and Alevtina (Valentina), at Cæsarea in Palestine":
{"type": "Laien · 4. Jh.", "life": "Heilige Märtyrer Paulos und die beiden Schwestern Chionia und Alevtina stammten aus Ägypten und litten für Christus in der Verfolgung unter Kaiser Maximian. Um ihres Glaubens willen ergriffen, wurden sie nach Kaisareia in Palästina gebracht, wo sie sich ohne die geringste Furcht vor ihren Richtern als Nachfolger Christi bekannten und den Götzen nicht opfern wollten.", "patron": "Angerufen um das furchtlose Bekenntnis."},

"Venerable Pimen the Much-Ailing of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Pimen der Vielkranke erlangte das Himmelreich durch das geduldige Ertragen schwerer Krankheit. In Krankheit geboren und aufgewachsen, wurde er eben durch sein Gebrechen vor den Krankheiten der Seele bewahrt, und von Jugend an bat er seine Eltern, ihn in das Kiewer Höhlenkloster zu bringen.", "patron": "Angerufen von langwierig Kranken; um die Geduld im Leiden."},

"Martyr Julitta at Caesarea":
{"type": "Laiin · 4. Jh.", "life": "Heilige Märtyrerin Julitta lebte zu Kaisareia in Kappadokien während der Verfolgung unter Kaiser Diokletian. Als ein Heide ihre ganze Habe an sich riss und sie das Gericht um Recht anrief, zeigte ihr Gegner sie vor dem Richter als Christin an, was sie ausserhalb des Schutzes der Gesetze stellte.", "patron": "Angerufen um die Lauterkeit; um Christus den Gütern vorzuziehen."},

"Saint Jonah the Presbyter, father of Saint Theophanes the Hymnographer and Theodore Graptus":
{"type": "Priester · 9. Jh.", "life": "Heiliger Jonas der Presbyter lebte im neunten Jahrhundert in Palästina und wird als Vater zweier grosser Bekenner der Orthodoxie gepriesen: des heiligen Theophanes des Hymnendichters und des heiligen Theodoros, des Gebrandmarkten genannt, denen der bilderstürmerische Kaiser um ihrer Verteidigung der heiligen Ikonen willen Spottverse ins Angesicht brennen liess.", "patron": "Angerufen von Vätern der Kleriker; um die Erziehung der Kinder für Gott."},

"Venerable Isidore of Pelusium":
{"type": "Hieromonach · 5. Jh.", "life": "Ehrwürdiger Isidoros von Pelusion wurde zu Alexandreia frommen Christen geboren, ein Verwandter der Erzbischöfe Theophilos und Kyrillos, und erhielt die beste Bildung der gelehrtesten Stadt jener Zeit; noch als Jüngling verliess er die Welt und zog sich in ein Kloster auf dem Berge bei Pelusion an der östlichen Nilmündung zurück, wo er mit der Zeit zum Priester geweiht wurde.", "patron": "Angerufen von Briefschreibern; von geistlichen Führern."},

"Venerable Stephen of Saint Savva Monastery":
{"type": "Mönch · 8. Jh.", "life": "Ehrwürdiger Stephanos vom Kloster des heiligen Sabbas war ein Neffe des heiligen Johannes von Damaskus und wurde im Jahre 725 geboren. Mit erst zehn Jahren trat er in die Grosse Lawra des heiligen Sabbas des Geheiligten in der judäischen Wüste ein und empfing das Mönchsgewand; dort verbrachte er sein ganzes Leben und zog sich oft in die Wüste zurück, um sich der Einsamkeit und dem geistlichen Kampfe hinzugeben.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Hieromartyr Vitalius, Bishop of Ravenna":
{"type": "Bischof", "life": "Heiliger Hieromärtyrer Vitalis wird unter den frühen Bischöfen und Märtyrern der Stadt Ravenna geehrt und an diesem Tage zusammen mit dem heiligen Hieromärtyrer Apollinaris, dem ersten Bischof jenes Stuhles, begangen. Von seinem Leben ist wenig Genaues bewahrt, doch erinnert die Kirche ihn als einen Hirten, der Christus bekannte und sein Zeugnis in den ersten Jahrhunderten mit dem Martyrium besiegelte.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Zosimas the Hermit of Cilicia":
{"type": "Mönch · 4. Jh.", "life": "Heiliger Märtyrer Zosimas der Einsiedler lebte im vierten Jahrhundert als Wüstenbewohner in Kilikien, nachdem er sich aus der Welt zurückgezogen hatte, um Gott in der Stille zu dienen; und solche Gnade wohnte in ihm, dass die wilden Tiere der Einöde sich zahm um ihn sammelten wie um Adam im Paradiese.", "patron": "Angerufen um den Einklang mit der Schöpfung; um das Ausharren in der Marter."},

"Prophet Zephaniah":
{"type": "Prophet · 7. Jh. v. Chr.", "life": "Heiliger Prophet Zephanja, der neunte der zwölf kleinen Propheten, war königlichen Geblütes und führt sein Geschlecht zu Beginn seines Buches über vier Glieder auf König Hiskia zurück; er weissagte zu Jerusalem in den Tagen des jungen Königs Josia, im siebten Jahrhundert vor Christus, ein Zeitgenosse Jeremias und eine Stimme, welche die grosse Erneuerung jener Regierung vorbereitete.", "patron": "Angerufen um das Suchen der Sanftmut; um die nach dem Gericht verheissene Freude."},

"Apostle Epίmakhos of Alexandria":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Epimachos von Alexandreia war ein Ägypter, der von Jugend an den Herrn liebte und sich in die Gegend von Pelusion zurückzog, wo er in der Wüste als Asket in Fasten und Gebet lebte. Als die Verfolgung des Decius über Alexandreia hereinbrach, kam der Einsiedler, von Eifer entbrannt, in die Stadt hinab, um die Bekenner zu stärken.", "patron": "Angerufen um die Heilung der Augen; um den Eifer für Gott."},

"Venerable Erasmus of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Erasmos aus den Kiewer Nahen Höhlen besass grossen Reichtum und gab ihn ganz Gott in einer bestimmten und schönen Gestalt: er verwandte alles, was er hatte, auf den Schmuck der Höhlenkirche, überzog ihre Ikonen mit Silber, vergoldete die heiligen Bilder und schmückte das Haus der Gottesmutter, bis sein Vermögen ganz in Glanz um den Altar verwandelt war.", "patron": "Angerufen von Wohltätern der Kirchen; von den Verzagten."},

"The Protection of our Most Holy Lady the Mother of God and Ever-Virgin Mary":
{"type": "Fest", "life": "Der Schutz unserer allheiligen Herrin, der Gottesmutter und Immerjungfrau Maria, ist eines der geliebtesten Feste der Kirche und wird vor allem in den Landen der Rus begangen. Zu Beginn des zehnten Jahrhunderts, als die Kaiserstadt von ihren Feinden bedroht war, hielt man in der Kirche zu Blachernae in Konstantinopel, wo das Gewand der Gottesmutter verwahrt wurde, eine Nachtwache.", "patron": "Angerufen um Schutz; um die Fürbitte der Gottesmutter."},

"Appearance of Christ to Saint Martin of Tours":
{"type": "Fest · 4. Jh.", "life": "Gedächtnis der Erscheinung Christi vor dem heiligen Martin von Tours, jenes Gesichtes, das am Anfang eines der geliebtesten Leben des Abendlandes steht und in einer einzigen nächtlichen Begebenheit das ganze fünfundzwanzigste Kapitel des Matthäus verkündet. Martin war damals ein junger Soldat der römischen Reiterei in Gallien und noch Katechumene, nicht getauft.", "patron": "Angerufen von Soldaten; von Almosengebern."},

"Icon of the Mother of God of Armatia":
{"type": "Ikone der Gottesmutter", "life": "Die Ikone der Gottesmutter von Armatia wurde zu Konstantinopel im Armatia-Kloster verehrt, das seinen Namen von dem Orte Armation trug, der mit dem Magister Armatios in den Tagen Kaiser Zenons verbunden ist. Die Feier dieser wundertätigen Ikone wurde zum Dank für die Befreiung der Kirche von der Häresie des Bildersturms eingesetzt.", "patron": "Angerufen um die Verehrung der heiligen Ikonen."},

"Eve of the Nativity of our Lord":
{"type": "Fest", "life": "Der Vorabend der Geburt unseres Herrn, die Paramonie genannt, ist die Schwelle des Festes, und die Kirche hält ihn, wie sonst nur den Vorabend der Theophanie, mit strengem Fasten und der feierlichsten Bereitung ihres Jahres. Am Morgen werden die Königlichen Stunden gesungen, so genannt, weil einst die Kaiser ihnen beiwohnten: zu jeder Stunde die Psalmen der Menschwerdung, die Weissagungen, der Apostel und das Evangelium.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Cosmas of Yakhrom":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Kosma von Jachroma war ein Diener, und seine Heiligkeit begann in der vollkommenen Erfüllung der Pflicht eines Dieners. Von Jugend an einem Bojaren zugehörig, den lange Krankheit gebrochen hatte, begleitete Kosma seinen Herrn auf den mühsamen Fahrten von Arzt zu Arzt und von Heiligtum zu Heiligtum, las ihm vor, pflegte ihn und trug die Hoffnung des Kranken, wenn der Kranke sie nicht tragen konnte.", "patron": "Angerufen von Dienenden; von Pflegern der Kranken."},

"Martyrs Gervasius, Nazarius, Protasius, and Celsus of Milan":
{"type": "Märtyrer · 1. Jh.", "life": "Heilige Märtyrer Nazarios, Gervasios, Protasios und Celsus von Mailand litten unter Kaiser Nero. Nazarios, zu Rom von der Christin Perpetua geboren und, wie die Überlieferung erzählt, von Linos, dem Nachfolger des Petros, getauft, gab seine Jugend der Verkündigung Christi und der Sorge für die verfolgten Christen hin; und als er nach Mailand kam, fand er dort die Zwillingsbrüder Gervasios und Protasios im Kerker.", "patron": "Angerufen um die Sorge für die gefangenen Christen; um die Erziehung der Kinder für Gott."},

"Priestmartyr John Kochurov":
{"type": "Priester · 20. Jh.", "life": "Heiliger Hieromärtyrer Iwan Kotschurow, der erste Priestermärtyrer der russischen Revolution, wurde 1871 im Rjasaner Gouvernement als Sohn eines Dorfpriesters geboren und meldete sich nach der Geistlichen Akademie zu Sankt Petersburg freiwillig zur amerikanischen Mission, wo er von 1895 an die Wolodymyr-Gemeinde zu Chicago leitete.", "patron": "Angerufen von Glaubensboten; von Gemeindepriestern."},

"Venerable Stephen the Hymnographer of Saint Savva Monastery":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Stephanos der Hymnendichter lebte asketisch in der grossen Lawra des heiligen Sabbas in der judäischen Wüste, jener Schule der Hymnendichter, die der Kirche den heiligen Johannes von Damaskus und den heiligen Kosmas von Maiuma gab; dort, in Fasten, Vigil und dem unablässigen Kreis des Psalmengesanges geformt, empfing er die Gabe des heiligen Gesanges.", "patron": "Angerufen von Hymnendichtern; von Sängern."},

"Venerable Dionysius of Aegina":
{"type": "Bischof · 17. Jh.", "life": "Ehrwürdiger Dionysios von Ägina ist derselbe Heilige, den die Kirche an diesem Tage als Dionysios von Zakynthos verherrlicht, hier unter dem Titel des Stuhles genannt, dem er diente: 1547 auf Zakynthos aus dem vornehmen Hause Sigouros geboren, auf den Strophaden zum Mönch geformt, wurde er trotz seiner Einwände der Unwürdigkeit zum Bischof von Ägina geweiht und weidete jene Insel mit solcher Lehre und Weisheit, dass viele gewonnen wurden.", "patron": "Angerufen von Bischöfen, die aus Demut ihr Amt niederlegen; um die Flucht vor der eitlen Ehre."},

"Righteous Anna the Prophetess and Daughter of Phanuel, who met the Lord at the Temple in Jerusalem":
{"type": "Prophetin · 1. Jh.", "life": "Die gerechte Prophetin Anna war aus dem Stamme Asser und die Tochter Phanuels; da sie mit ihrem Manne nur sieben Jahre gelebt hatte, ehe er starb, gab sie den ganzen Rest ihres langen Lebens Gott hin. Wie das Evangelium des Lukas berichtet, wich sie nicht vom Tempel, sondern diente Gott dort Tag und Nacht mit Fasten und Beten und hatte das hohe Alter von vierundachtzig Jahren erreicht.", "patron": "Angerufen von Witwen; um den Witwenstand."},

"Blessed Andrew of Totma the Fool-For-Christ":
{"type": "Narr in Christo · 17. Jh.", "life": "Seliger Andrej von Totma, der Narr in Christo, wurde 1638 im Dorfe Ust-Totma im Wologdaer Lande geboren und beschloss noch als Kind, die Welt zu verlassen. Mit dem Segen Stefans, des Abtes des Auferstehungsklosters zu Galitsch, nahm er die harte Berufung der Torheit um Christi willen auf sich und liess sich bei der Auferstehungskirche in der Stadt Totma an der Suchona nieder.", "patron": "Angerufen um die freiwillige Armut; um das verborgene Almosen."},

"Saint Andrew, Archbishop of Crete":
{"type": "Erzbischof · 8. Jh.", "life": "Heiliger Andreas, Erzbischof von Kreta, einer der grössten Hymnendichter der Kirche, wurde zu Damaskus in eine fromme christliche Familie geboren, und es wird erzählt, dass er bis zum siebten Jahre stumm war und die Gabe der Sprache empfing, nachdem er zum ersten Male der heiligen Mysterien teilhaftig geworden war.", "patron": "Angerufen von Hymnendichtern; um die Busse."},

"Saint Makarios the Roman":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Makarij der Römer wurde am Ende des fünfzehnten Jahrhunderts in eine reiche Familie Roms geboren und erhielt eine treffliche Bildung, achtete aber irdische Ehren gering und suchte allein das Heil seiner Seele. Betrübt über die Sünden und Spaltungen, welche die abendländische Kirche seiner Tage erschütterten, betete er unter Tränen, dass Gott ihm den Weg der Wahrheit zeige.", "patron": "Angerufen von Mönchen; um die Bekehrung zur Orthodoxie."},

"Right-believing George the Great Prince of Vladimir":
{"type": "Grossfürst, Märtyrer · 13. Jh.", "life": "Heiliger rechtgläubiger Georgij, Grossfürst von Wladimir, wurde 1189 als Sohn des Grossfürsten Wsewolod, des Grossen Nestes genannt, geboren und erhielt 1212 den Thron von Wladimir; von Jugend an durch Tapferkeit im Felde und durch Frömmigkeit ausgezeichnet, regierte er das stärkste Fürstentum des russischen Nordens ein Vierteljahrhundert lang und gründete 1221 am Zusammenfluss von Wolga und Oka die Festung Nischni Nowgorod.", "patron": "Angerufen von Herrschern im Untergang; von Verteidigern der Heimat."},

"Repose of Saint Theoktistos, Archbishop of Novgorod":
{"type": "Erzbischof · 14. Jh.", "life": "Entschlafen des heiligen Feoktist, Erzbischofs von Nowgorod, der Abt des Verkündigungsklosters bei jener Stadt war, als das Volk von Nowgorod ihn nach dem Entschlafen des Erzbischofs Kliment im Jahre 1300 nach altem Brauch seiner Republik zum Hirten erwählte; am neunundzwanzigsten Juni 1300 weihte ihn Metropolit Maxim von Kiew und ganz der Rus mit den Bischöfen von Rostow und Twer.", "patron": "Angerufen von Hierarchen, die demütig zurücktreten; von Erbauern der Kirchen."},

"Hieromartyr Apollinaris, Bishop of Ravenna":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Hieromärtyrer Apollinaris war ein Jünger des Apostels Petros, dem er von Antiochien nach Rom folgte, und Petros weihte ihn zum ersten Bischof von Ravenna und sandte ihn dorthin, das Evangelium zu verkünden. Als Fremder angekommen, fand er Obdach beim Soldaten Eirenaios, dessen blinden Sohn er heilte, und so wurden Eirenaios und sein Haus die ersten Christen Ravennas.", "patron": "Angerufen um die Verkündigung unter den Völkern; um Heilung."},

"Righteous Procopius the Fool-For-Christ and Wonderworker of Ustya, Vologda":
{"type": "Narr in Christo · 14. Jh.", "life": "Heiliger Prokopij, der Narr in Christo von Ustjug, war seiner Herkunft nach ein reicher Kaufmann aus dem Abendlande, der, in Geschäften nach Nowgorod gekommen, von der Schönheit des orthodoxen Gottesdienstes so bewegt wurde, dass er den Glauben annahm, all sein Gut den Armen verteilte und den harten, demütigenden Weg der Torheit um Christi willen auf sich nahm.", "patron": "Angerufen um die Bewahrung vor dem Unglück."},

"Martyr Ariádnē of Phrygia":
{"type": "Märtyrerin · 2. Jh.", "life": "Heilige Märtyrerin Ariadne war eine Magd im Hause des Tertullus, eines angesehenen Bürgers von Prymnessos in Phrygien, in den Tagen Kaiser Hadrians; und obgleich dem Stande nach eine Dienerin, war sie frei in Christus und weiser als viele der vornehmen Frauen ihrer Stadt.", "patron": "Angerufen von Dienenden; von Verfolgten."},

"Venerable Peter of Constantinople":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Petros wurde gegen Ende des achten Jahrhunderts zu Konstantinopel in ein patrizisches Haus geboren. Als Offizier unter Kaiser Nikephoros nahm er an den Feldzügen gegen Bulgarien teil, und in der Schlacht, in welcher der Kaiser fiel, geriet er mit vielen anderen in Gefangenschaft.", "patron": "Angerufen von Gefangenen und Kerkerinsassen."},

"Return of the Relics of the Apostle Bartholomew from Anastasiopolis to Lipari":
{"type": "Apostel · 1. Jh.", "life": "Rückführung der Reliquien des heiligen Apostels Bartholomaios von Anastasiopolis nach Lipari. Der Apostel, einer der Zwölf, litt für Christus in Armenien, wo er um das Jahr 71 geschunden und enthauptet wurde, und seine Reliquien blieben in jenem Lande und wirkten viele Wunder. Unter Kaiser Anastasios brachte man sie in die neue Stadt Anastasiopolis; als feindliche Hände sie später bedrohten, legten die Gläubigen sie in einen bleiernen Schrein.", "patron": "Angerufen um Heilung."},

"Venerable Botolph of Iken":
{"type": "Abt (Igumen) · 7. Jh.", "life": "Ehrwürdiger Botolph von Iken, einer der geliebtesten Väter des orthodoxen England, mühte sich im siebten Jahrhundert in Ostanglien. Im Mönchsleben geformt und von seiner Gnade erfüllt, suchte er für seine Gründung nicht reiches, sondern wildes Land und begann im Jahre 654 sein Kloster Ikanhoe zu Iken zu bauen, auf einer einsamen Anhöhe inmitten der Gezeitensümpfe des Flusses Alde.", "patron": "Angerufen von Reisenden; von Bauern."},

"Venerable Patapius of Thebes":
{"type": "Mönch · 7. Jh.", "life": "Ehrwürdiger Patapios wurde zu Theben in Ägypten frommen christlichen Eltern geboren und floh die Ehre, die seine Tugenden anzogen; jung zog er sich in die ägyptische Wüste zurück, wo er lange in Fasten, Vigil und Gebet lebte. Als der Ruhm ihn auch dort fand, tat der Einsiedler, was nur die Weisesten wagen: er verbarg sich nicht tiefer in der Wüste, sondern in der grössten Menge der Erde und kam nach Konstantinopel.", "patron": "Angerufen von Heilkundigen; um die Heilung der Blinden und der Kranken."},

"Martyr Longinus of Asistavi":
{"type": "Märtyrer · 1. Jh.", "life": "Unter dem Namen Longinos der Asistavi begeht der georgische Kalender an diesem Tage denselben heiligen Märtyrer Longinos den Hauptmann, der am Kreuze des Herrn stand; denn asistavi, der Vorsteher von hundert, ist das georgische Wort für Hauptmann und kein Ort, sondern der Titel des Märtyrers in der Zunge jenes alten christlichen Volkes.", "patron": "Angerufen von Soldaten; bei Augenleiden."},

"Venerable Abramius the Recluse, and his niece, Blessed Mary, of Mesopotamia":
{"type": "Mönch · 4. Jh.", "life": "Ehrwürdiger Abramios der Klausner aus Mesopotamien floh in der Jugend von seinem Hochzeitsmahl und mauerte sich in eine Zelle bei Edessa ein, die nur ein kleines Fenster hatte; dort lebte er fünfzig Jahre in Fasten, Tränen und Gebet, und sein Ruf verbreitete sich durch die ganze Gegend. Als der Bischof niemanden fand, der ein heidnisches Dorf weiden wollte, das jeden Priester vertrieben hatte, weihte er den Klausner gegen dessen Willen.", "patron": "Angerufen von Priestern an schweren Orten; um die Rettung der Gefallenen."},

"Royal Passionbearers Tsar Nicholas (Nikolai), Tsaritsa Alexandra, Tsarevich Aleksy, Grand Duchesses Olga, Tatiana, Maria, Anastasia":
{"type": "Zar und Kaiserfamilie · 20. Jh.", "life": "An diesem Tage begeht die Kirche die heiligen königlichen Leidensdulder: Zar Nikolaus den Zweiten, seine Gemahlin, die Zarin Alexandra, ihren Sohn, den Zarewitsch Alexej, und ihre Töchter, die Grossfürstinnen Olga, Tatjana, Maria und Anastasija, samt den treuen Dienern, die bis zum Ende bei ihnen bleiben wollten.", "patron": "Angerufen um die Vergebung der Feinde; für die Familie."},

"Venerable Peter the Hermit of Galatia Near Antioch, in Syria":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdiger Petros der Einsiedler von Galatien begann seine Entsagung in einem Alter, in dem andere Kinder ihren Unterricht beginnen: mit neun Jahren verliess er, nach dem Leben des Geistes verlangend, das Haus seiner Eltern in Galatien und zog in die Welt Gottes hinaus, zuerst als Pilger nach Jerusalem, um die heiligen Stätten zu verehren, und dann nach Antiochien, wo er den Rest eines sehr langen Lebens blieb.", "patron": "Angerufen von Heilkundigen; von Kindern, die früh zu Gott gerufen werden."},

"Venerable Theodore the Silent of the Kyiv Caves":
{"type": "Mönch · 13. Jh.", "life": "Ehrwürdiger Feodor der Schweigsame mühte sich im dreizehnten Jahrhundert in den Fernen Höhlen des heiligen Theodosij und trägt in den Büchern der Lawra den Beinamen, der sein ganzes überliefertes Leben ist: der Schweigsame. Er nahm die Mühe auf sich, welche die Väter die Hesychia der Zunge nennen, entsagte der Rede und behielt seine Stimme allein dem Gebet und dem Psalmengesang.", "patron": "Angerufen von Schweigsamen; von Hütern der Zunge."},

"Holy Martyr Euthymius":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Euthymios litt für Christus zu Nikomedeia in der grossen Verfolgung unter Diokletian und Maximian, in der die Christen jener Stadt in grosser Zahl umkamen. Als die Leiber der heiligen Märtyrer unbestattet lagen, erbarmten sich Euthymios und die Jungfrau Domna, die sich vom Heidentum zu Christus gewandt hatte, der Toten und gaben sich dem frommen Werke ihrer Bestattung hin.", "patron": "Angerufen um die Sorge für die Toten; um standhaftes Bekenntnis."},

"Uncovering of the relics of Saint Demetrius (Dmitri), Metropolitan of Rostov":
{"type": "Metropolit · 18. Jh.", "life": "Auffindung der Reliquien des heiligen Dimitrij, Metropoliten von Rostow, in der Welt Daniil Tuptalo, der 1651 bei Kiew geboren, an der Kiewer Akademie gebildet wurde und in der Jugend das Mönchsgewand empfing.", "patron": "Angerufen von Verfassern der Heiligenleben; von Schriftstellern."},

"Saint John the Merciful, Patriarch of Alexandria":
{"type": "Patriarch · 7. Jh.", "life": "Heiliger Johannes der Barmherzige, Patriarch von Alexandreia, wurde zu Amathus auf Zypern als Sohn des Statthalters der Insel geboren und heiratete im Gehorsam gegen seine Eltern und hatte Kinder; als Gott ihm aber Frau und Kinder zu sich nahm, gab er den Rest seines Lebens ganz Christus in den Armen hin.", "patron": "Angerufen von Almosengebern; von Menschenfreunden."},

"Priestmonk Jonah the Martyr of Pechenga":
{"type": "Hieromonach · 16. Jh.", "life": "Heiliger Hieromonach und Märtyrer Iona von Petschenga wurde im Dorfe Warsuga im Pomorje des fernen russischen Nordens geboren und diente zuerst als Gemeindepriester; darauf trat er, zum nördlichsten Kloster der Welt gezogen, in das Dreifaltigkeitskloster Petschenga auf der Halbinsel Kola ein, das der heilige Trifon unter den Lappen jenseits des Polarkreises gegründet hatte, und wurde einer seiner nächsten Jünger.", "patron": "Angerufen von Priestern am Altar; von Mönchen des hohen Nordens."},

"Martyrs Julian the Presbyter and Caesarius the Deacon at Terracina":
{"type": "Märtyrer · 1. Jh.", "life": "Heilige Märtyrer Julianos der Presbyter und Kaisarios der Diakon litten für Christus zu Terracina in Italien im ersten Zeitalter der Kirche. Kaisarios, ein aus Afrika gekommener Diakon, sah in jener Stadt den grausamen heidnischen Brauch, nach dem ein Jüngling, den man Monate hindurch auf Kosten der Stadt gepflegt hatte, sich als Opfer für die Götzen von einer Höhe stürzte.", "patron": "Angerufen um den Einspruch gegen die Grausamkeit; um standhaftes Bekenntnis."},

"Venerable Xenophon, his wife, Mary, and their two sons, Arcadius and John, of Constantinople":
{"type": "Mönche · 6. Jh.", "life": "Ehrwürdiger Xenophon, seine Gemahlin Maria und ihre Söhne Arkadios und Johannes waren im fünften und sechsten Jahrhundert angesehene Bürger von Konstantinopel, reich an Gut und Rang und, wie der Bericht betont, reicher an Einfalt der Seele und Güte des Herzens, ein grosses Haus, das Gott ganz in den Kalender zu versetzen gedachte.", "patron": "Angerufen von Familien; von Eltern der Verlorenen."},

"New Martyr Habakkuk":
{"type": "Mönch · 17. Jh.", "life": "Heiliger Neumärtyrer Habakuk legte im Jahre 1628 in der grossen Stadt Thessalonike Zeugnis für Christus ab, in der langen Nacht des türkischen Joches. Von seinem Leben ist fast nichts bewahrt, denn kein vollständiger Bericht seines Martyriums blieb erhalten; sein Gedächtnis ist allein aus einer kurzen Aufzeichnung in einer Handschrift der Grossen Lawra auf dem Athos bekannt.", "patron": "Angerufen um standhaftes Bekenntnis unter der Verfolgung."},

"Martyrs Maurice and his son, Photinus, and Martyrs Theodore, Philip, and 70 soldiers, at Apamea in Syria":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Maurikios, Heerführer von Apameia in Syrien, litt im Jahre 305 unter Maximian Galerius samt seinem Sohne Photinos und den siebzig Soldaten seines Befehls, von denen nur zwei Namen, Theodoros und Philippos, auf uns gekommen sind; die übrigen stehen, wie die Väter von solchen Scharen sagen, allein im Buche des Lebens.", "patron": "Angerufen von Heerführern; von Vätern und Söhnen unter den Waffen."},

"The Placing of the Honorable Robe of the Lord at Moscow":
{"type": "Fest · 17. Jh.", "life": "Gedächtnis der Niederlegung eines Teiles des kostbaren Gewandes unseres Herrn Jesus Christus in der Dormitio-Kathedrale des Moskauer Kreml im Jahre 1625. Das Gewand, das nach alter Überlieferung seit der Zeit der Kreuzigung im Osten verwahrt worden war, wurde dem Zaren Michail Feodorowitsch und dem Patriarchen Filaret zum Geschenk gesandt und nach Prüfung und Bestätigung seiner Echtheit durch Zeichen empfangen.", "patron": "Angerufen um die Verehrung des Leidens des Herrn."},

"5th Sunday of Great Lent: St Mary of Egypt":
{"type": "Fest · 6. Jh.", "life": "Ehrwürdige Maria von Ägypten, deren Leben in der Grossen Fastenzeit in der Kirche gelesen wird als ein Bild der Busse, verbrachte ihre Jugend zu Alexandreia in grosser Zügellosigkeit. Als sie nach Jerusalem zog, hielt eine unsichtbare Kraft sie am Feste der Kreuzerhöhung vom Eintritt in die Kirche zurück, und ins Herz getroffen, weinte sie vor einer Ikone der Gottesmutter und gelobte, ihr Leben zu ändern.", "patron": "Angerufen von Büssenden auf der Höhe der Fastenzeit; von allen, die an der Wandlung verzweifeln."},

"Saint Leo, Bishop of Catania in Sicily":
{"type": "Bischof · 8. Jh.", "life": "Heiliger Leon, Bischof von Catania auf Sizilien, weidete jene Stadt unter dem Ätna im achten Jahrhundert, ein Hierarch, berühmt um seines Erbarmens mit den Armen und Kranken willen, um der Heilungen willen, die auf sein Gebet geschahen, und um einer Sanftmut willen, die seine letzte Strenge umso furchtbarer machte; und sein Name ist der Kirche durch seinen Zweikampf mit dem Zauberer Heliodoros eingeprägt.", "patron": "Angerufen von Bischöfen wider die Zauberei; von Beschützern der Einfältigen in der Herde."},

"Venerable Polycarp, Archimandrite of the Kyiv Far Caves":
{"type": "Archimandrit · 12. Jh.", "life": "Ehrwürdiger Polikarp trat in das Kiewer Höhlenkloster ein, wo er eingekleidet wurde und um das Heil seiner Seele rang; und seinem Namen getreu, der viel Frucht bedeutet, brachte er reiche Früchte der Busse und der Tugend hervor. Sein Verwandter, der heilige Simon, der Bischof von Wladimir und Susdal wurde, führte ihn im geistlichen Leben, und die beiden wurden im Geiste immer inniger vereint, wie sie es im Blute waren.", "patron": "Angerufen von Mönchen; um die tugendhafte Leitung."},

"Uncovering of the relics of Venerable Athanasius, Abbot of Brest-Litovsk":
{"type": "Abt (Igumen) · 17. Jh.", "life": "Auffindung der Reliquien des ehrwürdigen Afanassij, Abtes von Brest, eines furchtlosen Streiters für die Orthodoxie in dem Zeitalter, da den Orthodoxen der polnisch-litauischen Lande die Union aufgezwungen wurde. Als Abt des Symeon-Klosters zu Brest widerstand er der Union freimütig mit Wort und Tat, verteidigte seine bedrängten Brüder und wiederholte seine Weissagung, dass die Union vergehen werde.", "patron": "Angerufen um die Verteidigung der Orthodoxie."},

"Martyrs Galaction and his wife, Epistemis, at Emesa":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Galaktion und seine Gemahlin Episteme litten im Jahre 253 zu Emesa in Syrien in der Verfolgung des Decius. Galaktion war der Sohn der vornehmen Leukippe, die lange unfruchtbar gewesen war und die ein Mönch namens Onuphrios zu Christus geführt und getauft hatte, und sie erzog ihren Sohn heimlich im Glauben.", "patron": "Angerufen von Eheleuten; von Mönchen."},

"Commemoration of the Founding of the Church of the Resurrection (Holy Sepulchre) at Jerusalem":
{"type": "Fest", "life": "Gedächtnis der Gründung, das ist der feierlichen Weihe, der Kirche der Auferstehung Christi zu Jerusalem, die der heilige Konstantin der Grosse und seine Mutter, die heilige Kaiserin Helena, über dem Grabe des Herrn und dem Hügel Golgotha errichteten. Als Helena nach Jerusalem gekommen war, die heidnischen Heiligtümer zerstört hatte, welche die heiligen Stätten entweihten, und das lebenspendende Kreuz gefunden hatte, begann der Bau.", "patron": "Angerufen um die Weihe der Kirchen."},

"Virgin Martyr Eulalia of Barcelona and the Martyr Felix":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Jungfrau und Märtyrerin Eulalia lebte bei der Stadt Barcelona in Spanien und wurde von ihren Eltern in Frömmigkeit und christlichem Glauben erzogen, sodass sie schon als junges Mädchen sich dem Gebet, der Lesung der Schrift und der stillen Arbeit im Hause hingab. Als in der Verfolgung unter Diokletian der Statthalter Dacianus nach Barcelona kam, um die Christen zu vernichten, verliess Eulalia, obgleich noch ein Mädchen, heimlich das Haus.", "patron": "Angerufen von jungen Frauen; um die Reinheit."},

"Venerable Thais of Egypt":
{"type": "Nonne · 4. Jh.", "life": "Ehrwürdige Thais von Ägypten wurde von ihrer Mutter einem Leben der Sünde überlassen, und ihre Schönheit machte sie in der Schande berühmt und reich und zog viele Seelen ins Verderben. Der grosse Älteste Paphnutios, der um sie und um die Verlorenen trauerte, legte weltliche Kleider an und kam mit einer Goldmünze zu ihr, als wäre er ein Gast.", "patron": "Angerufen von Büssenden; um die Busse."},

"Blessed Cleopatra with her son John, in Egypt":
{"type": "Gerechte · 4. Jh.", "life": "Selige Kleopatra war eine fromme Witwe aus Palästina und lebte in den Tagen der Verfolgung in Ägypten; als sie den Kampf des heiligen Märtyrers Varos sah, erlangte sie heimlich seinen Leib und trug ihn in ihr Heimatdorf Edra beim Berge Tabor, wo sie ihn ehrenvoll bestattete und über ihm eine Kirche auf den Namen des Märtyrers baute, und ihr ganzes Haus verehrte ihn als seinen Schutzherrn.", "patron": "Angerufen von Müttern; von trauernden Müttern."},

"Martyrs Proclus and Hilary of Ancyra":
{"type": "Laien · 2. Jh.", "life": "Heilige Märtyrer Proklos und Hilarios waren Verwandte aus einem Dorfe bei Ankyra und litten in der Verfolgung unter Kaiser Trajan. Proklos wurde zuerst ergriffen, und als er vor dem Statthalter Maximus freimütig Christus bekannte und voraussagte, dass der Statthalter selbst einst gezwungen sein werde, den wahren Gott anzuerkennen, wurde er grausam gefoltert und musste hinter dem Wagen des Statthalters herlaufen.", "patron": "Angerufen um das freimütige Bekenntnis."},

"Martyr Claudius, Asterius, Neon, and Theonilla of Aegæ in Cilicia":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Klaudios, Asterios und Neon samt der Märtyrerin Theonilla litten im Jahre 285 zu Aigai in Kilikien unter dem Statthalter Lysias. Die drei waren Brüder, und als ihr Vater starb, zeigte ihre Stiefmutter, nach dem Erbe begierig, die Kinder ihres Mannes bei der Obrigkeit als Christen an und lieferte sie um ihrer Güter willen der Folter aus.", "patron": "Angerufen von den Betrogenen und Verratenen; von Waisen, denen Verwandte Unrecht taten."},

"Venerable Sisoes the Schemamonk of the Kyiv Far Caves":
{"type": "Schemamönch · 13. Jh.", "life": "Ehrwürdiger Sissoi war ein Schemamönch der Kiewer Höhlen und mühte sich im dreizehnten Jahrhundert in den Fernen Höhlen. Er wird dafür erinnert, dass er die Leidenschaften des Fleisches durch strenges Fasten bezwang, und die Kirche ehrt ihn zusammen mit dem heiligen Grigorij dem Faster als einen, dem die Gnade gegeben ist, anderen in ihrem Kampfe wider die Versuchung zu helfen.", "patron": "Angerufen um die Herrschaft über die Leidenschaften."},

"Venerable Theodore Graptus, “the branded,” Confessor":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Theodoros Graptos, der Gebrandmarkte, Bekenner für die heiligen Ikonen, wurde zu Jerusalem geboren und mit seinem Bruder Theophanes in der Lawra des heiligen Sabbas zum Mönche geformt; die beiden Brüder waren so gelehrt und so heilig, dass der Patriarch von Jerusalem sie als seine Streiter gegen den wiedererstandenen Bildersturm nach Konstantinopel sandte.", "patron": "Angerufen von Schriftstellern; von Hymnendichtern."},

"Venerable Moses, Wonderworker of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Moissej lebte im dreizehnten und vierzehnten Jahrhundert im Kiewer Höhlenkloster und gab sich ganz Gott hin. Er trug schwere Ketten und ein grosses kupfernes Kreuz an sich, und seine beständige und geliebte Mühe war der Gesang der Psalmen und das Verrichten unzähliger Verneigungen, wodurch er seinen Leib um seiner Seele willen ermüdete.", "patron": "Angerufen um die asketische Mühe; um den Psalmengesang."},

"Saint Theophanes the Confessor and Hymnographer, Bishop of Nicea":
{"type": "Bischof · 9. Jh.", "life": "Heiliger Theophanes der Bekenner und Hymnendichter, Bischof von Nikaia, der Gebrandmarkte genannt, war der jüngere Bruder des heiligen Theodoros; sie waren Söhne des frommen Presbyters Jonas aus Palästina. Trefflich gebildet und in der Weisheit geschult, wurden die Brüder in der Lawra des heiligen Sabbas eingekleidet, wo Theophanes Hieromonach wurde.", "patron": "Angerufen von Hymnendichtern; von Bekennern."},

"Martyrs Eulampius and Eulampia, at Nicomedia, and 200 Martyrs with them":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Eulampios und Eulampia, Bruder und Schwester, lebten zu Beginn des vierten Jahrhunderts zu Nikomedeia. Als der Erlass Kaiser Maximians, der alle Christen zum Tode verurteilte, in der Stadt angeschlagen wurde, las der junge Eulampios ihn und klagte laut, dass der Kaiser die Waffen gegen seine eigenen unschuldigen Untertanen erhebe statt gegen die Feinde des Reiches.", "patron": "Angerufen von Brüdern und Schwestern in Christo; um den Freimut vor den Götzen."},

"Venerable Daniel, Abbot of Shuzhgorsk, Novgorod":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Daniil von Schuschgora wurde im sechzehnten Jahrhundert im Moskauer Lande geboren und empfing, nachdem er die Welt verlassen hatte, im Komeler Kloster des heiligen Kornilij das Mönchsgewand, wo er in den Überlieferungen der grossen nördlichen Asketen geformt wurde. Da er das einsame Leben begehrte, zog er in die wilde Gegend des russischen Nordens und liess sich auf dem bewaldeten Hügel Schuschgora nieder.", "patron": "Angerufen von Mönchen; um die Einsamkeit."},

"Venerable John the Silent of Saint Sabbas Monastery":
{"type": "Bischof · 6. Jh.", "life": "Ehrwürdiger Johannes der Schweigsame, auch der Hesychast genannt, wurde 454 zu Nikopolis in Armenien einem vornehmen Hause von Feldherren und Statthaltern geboren; nachdem er in der Jugend eine Gottesmutterkirche gebaut und eine kleine Bruderschaft gesammelt hatte, musste er mit achtundzwanzig Jahren das Bischofsamt von Kolonia annehmen.", "patron": "Angerufen von Hesychasten; von Bischöfen, die ihr Amt niederlegen."},

"Hieromartyr Proterius, Patriarch of Alexandria":
{"type": "Patriarch, Hieromärtyrer · 5. Jh.", "life": "Heiliger Hieromärtyrer Proterios, Patriarch von Alexandreia, war der Mann, den man auf den gefährlichsten Stuhl der Christenheit setzte, um den Glauben von Chalkedon zu halten, und er hielt ihn bis zum letzten Blutstropfen. Als Priester von Alexandreia unter dem Patriarchen Dioskoros hatte er die Furchtlosigkeit, den monophysitischen Irrtum seines eigenen Hierarchen zu verwerfen und den orthodoxen Glauben der zwei Naturen zu bekennen.", "patron": "Angerufen von Hierarchen inmitten des Aufruhrs; von Verteidigern von Chalkedon."},

"The Dormition of our Most Holy Lady the Mother of God and Ever-Virgin Mary":
{"type": "Grosses Fest", "life": "Die Entschlafung feiert das Hinübergehen der Allheiligen Gottesmutter und ihre Aufnahme mit Leib und Seele in den Himmel. Nach der Überlieferung der Kirche wurden die Apostel, als die Zeit ihres Entschlafens nahte, auf wunderbare Weise von den Enden der Erde nach Jerusalem versammelt, und der Herr selbst stieg herab, ihre Seele aufzunehmen. Ihr Leib wurde in ein Grab zu Gethsemane gelegt.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Nicholas the Monk of Bulgaria":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Nikolaos der Soldat, auch der Heerführer genannt, diente im kaiserlichen Heere auf dem Zuge, den Kaiser Nikephoros im Jahre 811 nach Bulgarien führte, und seine Heiligkeit entschied sich in einer einzigen Nacht auf dem Marsche. In einer Herberge einquartiert, wurde er nicht von einem Feinde angefallen, sondern von einer Versuchung, da die Tochter des Wirtes im Dunkeln zu ihm kam.", "patron": "Angerufen von Soldaten; von allen, die am Vorabend der Schlacht der Versuchung widerstehen."},

"Martyrs Andrew, John, and John’s children: Peter and Antonius, of Syracuse, martyred in Africa":
{"type": "Märtyrer · 9. Jh.", "life": "Heilige Märtyrer Andreas, Johannes und die Kinder des Johannes, Petros und Antoninos, stammten aus Syrakus auf Sizilien und wurden im neunten Jahrhundert nach Afrika verschleppt, als die Sarazenen die Insel verheerten. Die beiden Knaben, jung geraubt, wuchsen am Hofe des Emirs auf und wurden in der Bildung und der Religion ihrer Herren unterwiesen und äusserlich zu den Muslimen gezählt.", "patron": "Angerufen von Gefangenen; um den im fremden Lande bewahrten Glauben."},

"Venerable Jonah, Abbot of Yashezersk":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Iona von Jaschesero stammte aus den karelischen Landen und setzte im Norden die Überlieferung der grossen Einödbewohner aus der Schule des heiligen Alexander von Swir fort. Er liess sich in der Wildnis am Jaschesero nieder und lebte zuerst in völliger Einsamkeit, in Fasten, Vigil und unablässigem Gebet.", "patron": "Angerufen von Mönchen; um das Mönchtum des Nordens."},

"Prophetess Hannah the mother of the Prophet Samuel":
{"type": "Prophetin · 11. Jh. v. Chr.", "life": "Heilige Prophetin Hanna, die Mutter des Propheten Samuel, war die Frau Elkanas von Ramathaim, lange Jahre unfruchtbar und täglich von den Sticheleien ihrer Nebenbuhlerin verwundet; und als sie zum Heiligtum nach Silo hinaufzog, schüttete sie ihre Seele vor dem Herrn aus, weinte und gelobte, dass sie, wenn er ihr einen Sohn gäbe, das Kind ihm alle Tage seines Lebens zurückgeben werde.", "patron": "Angerufen von Müttern; von den Unfruchtbaren, die beten."},

"Synaxis of the Archangel Michael and the Other Bodiless Powers":
{"type": "Fest", "life": "Die Synaxis des Erzengels Michael und der übrigen körperlosen Mächte ist das Hauptfest der heiligen Engel und wurde in den frühesten Jahrhunderten der Kirche eingesetzt, die es auf den achten November legte: den neunten Monat vom März, dem alten Beginn des Jahres, wegen der neun Ordnungen der Engel, und den achten Tag als Bild des grossen Tages des Herrn.", "patron": "Angerufen um Schutz; um die Bewahrung einer jeden Seele."},

"Blessed Nicholas Kochanov the Fool-For-Christ at Novgorod":
{"type": "Narr in Christo · 14. Jh.", "life": "Seliger Nikolaj Kotschanow, der Narr in Christo von Nowgorod, wurde einem reichen und vornehmen Hause geboren und liebte von Jugend an die Kirche, das Fasten und das Gebet. Als das Volk begann, ihn um seiner Tugend willen zu preisen, floh er dieses Ansehen, indem er den schweren Weg der Torheit um Christi willen auf sich nahm und seine Heiligkeit unter dem Schein des Wahnsinns verbarg.", "patron": "Angerufen um die Versöhnung; um den Frieden im Streit."},

"Commemoration of the Great Earthquake at Constantinople":
{"type": "Fest", "life": "Gedächtnis des grossen Erdbebens, das im Jahre 740 unter Leon dem Isaurier Konstantinopel traf, als der Zorn Gottes die Kaiserstadt erschütterte, Kirchen, Wohnungen und lange Strecken der Stadtmauern samt ihren Türmen niederwarf und viele Menschen umkommen liess; die Beben hielten monatelang an, sodass die Einwohner voll Furcht unter freiem Himmel wohnten.", "patron": "Angerufen um die Bewahrung vor Erdbeben; um die Busse vor den Gerichten Gottes."},

"Virgin Martyr Juliana of Nicomedia, and 500 men and 130 women with her":
{"type": "Jungfrau und Märtyrerin · 4. Jh.", "life": "Heilige Jungfrau und Märtyrerin Juliana von Nikomedeia litt im Jahre 304 in der Verfolgung Diokletians und Maximians, und mit ihr eine Ernte, die ihr eigener Mut gesät hatte. Als Tochter des Heiden Africanus und wider ihren Willen dem Senator Eleusios verlobt, verzögerte die heimliche Christin die Ehe durch Bedingungen und stellte zuletzt die wahre: dass sie keinen Mann heiraten werde, der nicht Christus anbete.", "patron": "Angerufen von Bräuten; von jungen Frauen."},

"Martyr Anthony of Alexandria":
{"type": "Laie · 4. Jh.", "life": "Heiliger Märtyrer Antonios war ein Christ der Stadt Alexandreia und wurde um seines Bekenntnisses zu Christus willen ergriffen. An einen Baum gebunden, wurde sein Leib mit eisernen Haken zerrissen, und darauf verurteilte man ihn zum Feuertod; mitten in den Flammen aber stand er unbewegt und ermahnte gelassen die Zuschauer, nicht für den Leib zu arbeiten, der vergeht, sondern für die Seele in ihrem Aufstieg zu Gott.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Martyrs Elpidius, Marcellus, and Eustochius, who suffered under Julian the Apostate":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Elpidios, Markellos und Eustochios litten unter Julian dem Abtrünnigen in den Jahren 361 bis 363, als das Reich, das den Frieden der Kirche gekostet hatte, von seinem Herrscher zur Verehrung der Götzen zurückgezerrt wurde. Elpidios war Senator, ein Mann von hoher Würde, und wurde mit seinen Gefährten unter der Anklage, ein Christ zu sein, vor den kaiserlichen Richter geführt.", "patron": "Angerufen von Senatoren; von Beamten."},

"Venerable Diodoros, Igoumen of George Hill":
{"type": "Abt (Igumen) · 17. Jh.", "life": "Ehrwürdiger Diodor vom Georgsberge wurde im Dorfe Turtschassowo an der Onega, auf halbem Wege zwischen Kargopol und dem Weissen Meer, frommen Eltern namens Ierofej und Maria geboren, die ihren Sohn Diomid nannten. Mit fünfzehn Jahren zog er als Pilger zum grossen Solowki-Kloster im nördlichen Meer und blieb dort und empfing mit der Zeit das Mönchsgewand mit dem Namen Diodor.", "patron": "Angerufen von Mönchen; um das Einsiedlerleben des hohen Nordens."},

"Venerable Sisoes the Recluse of the Kyiv Near Caves":
{"type": "Schemamönch · 13. Jh.", "life": "Ehrwürdiger Sissoi, Schemamönch der Kiewer Höhlen, mühte sich im dreizehnten Jahrhundert in den Nahen Höhlen des heiligen Antonij und war mit dem grossen Schema bekleidet, dem höchsten Grade der mönchischen Entsagung, dessen Träger der Welt zweifach abstirbt. Er nahm die strengste Form des Kampfes der Höhlen auf sich und schloss sich in die Klause ein, wo die ganze Regel des Schemamönches das unablässige Gebet ist.", "patron": "Angerufen um den verborgenen Kampf der Klause."},

"Venerable Cyriacus of Bisericani, Romania":
{"type": "Hieroschemamonach · 17. Jh.", "life": "Ehrwürdiger Chiriac von Bisericani, einer der grössten Hesychasten des rumänischen Landes, mühte sich zu Beginn des siebzehnten Jahrhunderts im Kloster Bisericani im Lande Neamț, dessen Bruderschaft damals mehr als hundert Mönche zählte; und da er nach dem härteren Wege brannte, nahm er den Segen seines Beichtvaters und zog sich in eine Steinhöhle auf dem Berge über der Bistrița zurück.", "patron": "Angerufen von Einsiedlern; von Höhlenbewohnern."},

"Virgin Martyr Lucy of Syracuse":
{"type": "Jungfrau und Märtyrerin · 4. Jh.", "life": "Heilige Jungfrau und Märtyrerin Lucia von Syrakus, deren Name Licht bedeutet, litt im Jahre 304 auf Sizilien in der grossen Verfolgung Diokletians, und ihr Fest hat seither Licht in die dunkelsten Tage des Winters getragen. Als sie mit ihrer Mutter Eutychia, die am Blutfluss litt, zum Grabe der heiligen Agatha nach Catania beten ging, schaute Lucia die Märtyrerin in einem Gesicht, und die Mutter wurde geheilt.", "patron": "Angerufen von Blinden; von denen, die beim Lampenlicht arbeiten."},

"Holy Martyrs and Confessors Gurias, Samonas, and Habibus, of Edessa":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer und Bekenner Gurias, Samonas und Habib sind die grossen Schutzherren der Stadt Edessa und der ehrbaren Ehe. Gurias und Samonas, Verkünder des Wortes Gottes, wurden in der Verfolgung unter Diokletian ergriffen; da sie nicht opfern wollten, schlug man sie, hängte sie an den Händen auf und band schwere Gewichte an ihre Füsse und warf sie in einen erstickenden Kerker.", "patron": "Angerufen um die ehrbare Ehe; um die Befreiung aus häuslicher Not."},

"Martyr Tation (Tatio) of Claudiopolis":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Tation lebte in Bithynien und litt für Christus in der Verfolgung unter Diokletian. Als bekannt wurde, dass er Christ sei, ergriff man ihn und führte ihn in die Stadt Klaudiupolis vor den Statthalter Urbanus, der ihn vielmals zum Abfall drängte und ihn, als er nicht wollte, in den Kerker warf und verschiedenen Martern unterwarf.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Venerable John the Faster of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Johann der Faster mühte sich im zwölften Jahrhundert in den Nahen Höhlen der Kiewer Lawra, in der ersten Blüte des Klosters der heiligen Antonij und Theodosij, und trug denselben Kampf und denselben Beinamen wie der grosse Patriarch von Konstantinopel, dessen Namen er teilte: er war ein Faster, ein Kämpfer der Enthaltsamkeit in der Schule, welche das Fasten für die Grundlage jedes anderen Sieges hielt.", "patron": "Angerufen um die Herrschaft über die Begierde; um den verborgenen Kampf."},

"Martyr Paraskevi of Rome":
{"type": "Nonne · 2. Jh.", "life": "Ehrwürdige Paraskevi war die einzige Tochter frommer christlicher Eltern zu Rom und gab sich von frühen Jahren an dem Gebet und dem Studium der heiligen Schriften hin. Als ihre Eltern starben, verteilte sie ihr Erbe an die Armen und weihte ihre Jungfräulichkeit Christus, und in Nachahmung der Apostel zog sie umher, verkündete das Evangelium und wandte viele Heiden von ihren Götzen ab.", "patron": "Angerufen bei Augenleiden; von Kranken."},

"Prophet Habakkuk":
{"type": "Prophet · 7. Jh. v. Chr.", "life": "Heiliger Prophet Habakuk, der achte der zwölf kleinen Propheten, war aus dem Stamme Simeon und weissagte um das Jahr 650 vor Christus; er sah die Zerstörung des Tempels, die babylonische Gefangenschaft und die Rückkehr der Verbannten voraus. Sein Buch bewahrt das grosse Zwiegespräch des Wächters mit Gott, der auf seinen Turm tritt, um zu sehen, was der Herr über das Wohlergehen der Gottlosen antworten werde.", "patron": "Angerufen von Wächtern; um den Glauben, der auf das Gesicht wartet."},

"Repose of Venerable Abramius of Galich or Chukhloma Lake, disciple of Venerable Sergius of Radonezh":
{"type": "Gerechter · 14. Jh.", "life": "Entschlafen des ehrwürdigen Awraamij von Galitsch, eines Jüngers des heiligen Sergij von Radonesch, der sich im vierzehnten Jahrhundert im Dreifaltigkeitskloster mühte und viele Jahre als Novize diente, ehe er zum Priester geweiht wurde. Nach tieferer Stille verlangend, empfing er den Segen seines Ältesten und zog sich 1350 in die Wildnis des Galitscher Landes im Norden Russlands zurück, das damals noch ungetaufte Stämme bewohnten.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Michael Maleinos":
{"type": "Abt (Igumen) · 10. Jh.", "life": "Ehrwürdiger Michael Maleinos wurde in Kappadokien vornehmen und frommen Eltern geboren und Manuel genannt; da er mit den grossen Häusern des Reiches verwandt war, war ihm eine glänzende Laufbahn am kaiserlichen Hofe bestimmt. Doch noch als junger Mann verliess er die Welt und ihre Ehren, zog sich auf den Berg Kyminas in Bithynien zurück, wurde eingekleidet und gab sich unter einem erfahrenen Ältesten strenger Askese hin.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Saint Cosmas the Hymnographer, Bishop of Maiuma":
{"type": "Bischof · 8. Jh.", "life": "Heiliger Kosmas der Hymnendichter, Bischof von Maiuma, blieb als Waise zurück und wurde vom frommen Sergios aus Damaskus, dem Vater des heiligen Johannes von Damaskus, an Sohnes Statt angenommen, sodass die beiden Knaben als Brüder aufwuchsen; und sie wurden gemeinsam von einem gelehrten Ältesten unterrichtet, der ebenfalls Kosmas hiess, einem Mönche aus Italien, den Sergios aus der Gefangenschaft losgekauft hatte.", "patron": "Angerufen von Hymnendichtern; von Sängern."},

"Saint Niphon, Bishop of Constantia, Cyprus":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Niphon, Bischof von Konstantia auf Zypern, wurde im vierten Jahrhundert in Paphlagonien geboren und zu Konstantinopel erzogen, ein sanftes Kind, das die Gottesdienste der Kirche liebte; dann aber fiel seine Jugend in die Grube, in Jahre wilden und zügellosen Lebens, in denen der Knabe, der den Altar geliebt hatte, sich selbst fremd wurde, bis die Gnade ihm im betrübten Angesicht eines Freundes sein Bild zeigte.", "patron": "Angerufen von Büssenden; von denen, die böse Geister quälen."},

"Apostles of the Seventy Philemon and Archippus, Martyr Apphia, wife of Philemon and Equal-to-the-Apostles, and Onesimus, disciple of Saint Paul":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heilige Apostel Philemon und Archippos, die Märtyrerin Apphia, die Gemahlin des Philemon, und der heilige Onesimos, der Jünger des Apostels Paulos, sind für immer durch den kürzesten Brief des Paulos verbunden, geschrieben an Philemon, den Geliebten und Mitarbeiter, an die geliebte Apphia, an Archippos, den Mitstreiter, und an die Gemeinde in seinem Hause.", "patron": "Angerufen von Häusern des Glaubens; von Herren und Dienenden."},

"Saint Amphilokhios, Bishop of Iconium":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Amphilochios, Bischof von Ikonion, wurde um das Jahr 340 zu Kaisareia in Kappadokien geboren, jener Pflanzstätte der grossen Väter, und war ein Verwandter des Gregorios des Theologen und ein geliebter Freund des Basileios des Grossen. Ein glänzender Rechtsgelehrter zu Konstantinopel, verliess er die Gerichte um Christi willen und zog sich in ein asketisches Leben und zur Pflege seines betagten Vaters zurück.", "patron": "Angerufen von Rechtsgelehrten; von Bischöfen."},

"33 Holy Martyrs of Melitene":
{"type": "Märtyrer · 3. Jh.", "life": "Die dreiunddreissig heiligen Märtyrer von Melitene litten um das Jahr 290 unter Diokletian und Maximian, als eine Abteilung unter dem Befehlshaber Lysias nach Kappadokien gesandt wurde, um die Christen auszurotten und starke Männer für das Heer auszuheben. An ihrer Spitze steht Hieron, ein Landmann aus Tyana, von seiner Mutter fromm erzogen, ein Mann von aussergewöhnlicher Leibeskraft.", "patron": "Angerufen von Bauern; von Ausgehobenen."},

"Martyrs Dadas, Gabdelas, and Kazdoa of Persia":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Dadas, Gabdelas und Kasdoa litten für Christus in Persien unter dem König Sapor. Dadas, ein Verwandter des Königs und Oberster seines Hofes, wurde als Christ entdeckt, seiner Würden entkleidet und der Folter übergeben; als aber das für ihn bereitete Feuer sich auf sein Gebet hin abwandte und vor allen Wunder geschahen, bekannten der Sohn des Königs, Gabdelas, und seine Tochter Kasdoa Christus.", "patron": "Angerufen von Bekehrten aus dem Hause der Verfolger."},

"Martyr Juvenal of Alaska":
{"type": "Hieromonach · 18. Jh.", "life": "Heiliger Märtyrer Juvenalij, der Erzmärtyrer Amerikas, wurde 1761 zu Nertschinsk in Sibirien geboren und hiess in der Welt Iwan Feodorowitsch Goworuchin; er war Bergbauingenieur von Beruf. Nach dem Tode seiner Frau trat er in den Mönchsstand, und als Hieromonach von Walaam wurde er für die erste orthodoxe Mission nach Amerika erwählt und kam 1794 mit dem heiligen German und ihren Gefährten nach Kodiak.", "patron": "Angerufen von Glaubensboten; um die Erleuchtung Amerikas."},

"Venerable Elias of Murom, Wonderworker of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Ilja von Murom, Wundertäter der Nahen Höhlen, stammte aus der Stadt Murom an der Oka und vollendete seinen Lauf um das Jahr 1188 als Mönch der Kiewer Höhlenlawra. Die Brüder nannten ihn Tschobotok, den Stiefel, nach der Überlieferung, dass der Krieger, einmal von Feinden überrascht, sie mit der einzigen Waffe abwehrte, die zur Hand war, mit seinem eigenen Stiefel.", "patron": "Angerufen von Soldaten; von Kriegern, die Mönche werden."},

"Righteous Forefather Abraham":
{"type": "Gerechter Vorvater · 20. Jh. v. Chr.", "life": "Der heilige gerechte Vorvater Abraham, der Vater aller Glaubenden, wurde von Gott aus Ur in Chaldäa gerufen und verliess sein Land und seine Verwandtschaft auf das Wort des Herrn, der verhiess, dass in seinem Samen alle Geschlechter der Erde gesegnet werden sollten.", "patron": "Angerufen um den Glauben; um die Gastfreundschaft."},

"Uncovering of the relics of Venerable Seraphim of Sarov":
{"type": "Mönch · 20. Jh.", "life": "Auffindung der Reliquien und feierliche Verherrlichung des heiligen Serafim von Sarow, eines der geliebtesten Heiligen der russischen Kirche, im Jahre 1903, siebzig Jahre nach seinem Entschlafen. Auf das Drängen der Gläubigen und mit der nachdrücklichen Unterstützung des Zaren Nikolaus des Zweiten, der selbst nach Sarow kam, wurde die Verherrlichung vollzogen.", "patron": "Angerufen um Heilung."},

"Martyr Charitina of Amisos":
{"type": "Märtyrerin · 4. Jh.", "life": "Heilige Märtyrerin Charitina von Amisos im Pontos wurde als Kind Waise und von einem frommen Christen namens Klaudios wie eine Tochter aufgezogen; in seinem Hause wuchs sie an Schönheit, Verstand und Güte, lernte Tag und Nacht das Gesetz Gottes und gelobte Christus ihre Jungfräulichkeit, während sie durch ihr Wort viele auf den Weg des Heils führte.", "patron": "Angerufen von Dienenden; um die Reinheit."},

"Greatmartyr Euphemia the All-praised":
{"type": "Jungfrau · 4. Jh.", "life": "Gedächtnis des grossen Wunders, das durch die heilige Grossmärtyrerin Euphemia die Allgepriesene zur Verteidigung des orthodoxen Glaubens gewirkt wurde. Nachdem sie zu Chalkedon unter Diokletian das Martyrium erlitten hatte, wurde sie anderthalb Jahrhunderte später, im Jahre 451, aufs Neue verherrlicht, als das Vierte Ökumenische Konzil in eben der Kirche zusammentrat, in der ihre Reliquien lagen.", "patron": "Angerufen um die Verteidigung der orthodoxen Lehre."},

"Afterfeast of the Dormition of the Mother of God":
{"type": "Nachfest", "life": "In den Tagen des Nachfestes der Entschlafung feiert die Kirche das selige Hinübergehen unserer allheiligen Herrin, der Gottesmutter, und ihre Aufnahme in die Herrlichkeit des himmlischen Reiches weiter. Die Gesänge dieser Tage verkünden, dass sie, die den Urheber des Lebens gebar, die Welt in ihrem Entschlafen nicht verlassen hat, sondern von ihrem Sohne aufgenommen wurde, um ohne Unterlass für alle zu bitten.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Hieromartyr Anthimus, Bishop of Nicomedia and those with him":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Anthimos, Bischof von Nikomedeia, wurde in jener Stadt geboren und von Kindheit an im christlichen Glauben erzogen; da er demütig, friedfertig und voll Eifers für die Ehre Gottes war, wurde er mit der Zeit Bischof von Nikomedeia. Er weidete die Kirche dort während der harten Verfolgung unter Diokletian und Maximian, als das Blut der Christen floss.", "patron": "Angerufen um standhaftes Bekenntnis; um das treue Hirtenamt unter der Verfolgung."},

"Arrival of the Ivḗron Icon of the Mother of God in Georgia":
{"type": "Fest", "life": "An diesem Tage begeht die georgische Kirche die Ankunft der Iberischen Ikone der Allheiligen Gottesmutter in Georgien. Am sechsundzwanzigsten September des Jahres 1989 kam eine genaue Abschrift der berühmten wundertätigen Portaitissa, der Pfortenhüterin des Iberon-Klosters auf dem Athos, vom Heiligen Berge nach Tiflis, von den athonitischen Mönchen mit dem Segen des Katholikos-Patriarchen Ilia des Zweiten gemalt.", "patron": "Angerufen um den Schutz Georgiens; um den Trost in schweren Zeiten."},

"Martyr and Archdeacon Euplus of Catania":
{"type": "Diakon · 4. Jh.", "life": "Heiliger Erzdiakon Euplos litt im Jahre 304 in der sizilischen Stadt Catania in der Verfolgung unter Diokletian und Maximian. Er trug das Evangelium überallhin bei sich und verkündete den Heiden freimütig Christus, und einmal, als er dem Volke das heilige Buch las und auslegte, wurde er ergriffen und vor Gericht geführt.", "patron": "Angerufen von Diakonen; um die Verkündigung des Evangeliums."},

"Forefeast of the Dormition of the Mother of God":
{"type": "Vorfest", "life": "Vorfest der Entschlafung unserer allheiligen Herrin, der Gottesmutter, an dem die Kirche ihr seliges Hinübergehen zu feiern beginnt, das am fünfzehnten August am Ende des ihr geweihten Fastens begangen wird. Die Gesänge des Vorfestes rufen die Gläubigen zusammen, sich zu freuen, denn die Gottesmutter ist im Begriff, von der Erde in das himmlische Reich zu scheiden und von ihrem Sohne in Herrlichkeit aufgenommen zu werden.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Timothy of Symbola in Bithynia":
{"type": "Einsiedler · 8. Jh.", "life": "Ehrwürdiger Timotheos von Symbola mühte sich auf dem bithynischen Olymp, jenem heiligen Berge Kleinasiens, dessen Schluchten im achten Jahrhundert eine Gemeinschaft von Klöstern bargen, die nur den alten Wüsten nachstand; und unter seinen Gemeinschaften nahm die Symbola genannte ihn jung auf und behielt ihn bis zum Ende.", "patron": "Angerufen von Mönchen der Reinheit; von Beschwörern."},

"Venerable Theophilus the Recluse of the Kyiv Near Caves":
{"type": "Mönch · 13. Jh.", "life": "Ehrwürdiger Feofil der Schweigsame mühte sich im zwölften und dreizehnten Jahrhundert in den Nahen Höhlen der Kiewer Lawra und nahm die Mühe auf sich, die sein Beiname bewahrt: die asketische Zucht des Schweigens, mit der ein Mönch Gott das Glied darbringt, das am schwersten zu bändigen ist.", "patron": "Angerufen um das Schweigen; um das Gebet im Verborgenen."},

"Venerable Dius, Abbot of Antioch":
{"type": "Abt (Igumen) · 5. Jh.", "life": "Ehrwürdiger Dios wurde gegen Ende des vierten Jahrhunderts zu Antiochien in Syrien in ein frommes christliches Haus geboren und zeichnete sich von Jugend an durch Mässigkeit aus: er ass wenig und nicht an jedem Tage und demütigte sein Fleisch durch Vigil und unablässiges Gebet. Für diese Mühen schenkte ihm der Herr die Leidenschaftslosigkeit und die Gabe des Wunderwirkens.", "patron": "Angerufen von Mönchen; um den asketischen Kampf."},

"Confessors Barses and Eulogius, Bishops of Edessa, and Protogenes, Bishop of Carrhae":
{"type": "Bischof · 4. Jh.", "life": "Heilige Barses und Eulogios, Bischöfe von Edessa, und Protogenes, Bischof von Karrhai, waren Bekenner, die in der zweiten Hälfte des vierten Jahrhunderts von den Arianern litten, als Kaiser Valens jene Häresie auszubreiten suchte und die Orthodoxen hart bedrängte. Barses, ein standhafter Streiter des wahren Glaubens, wurde von seinem Stuhle zu Edessa vertrieben und von einem Ort zum anderen verbannt.", "patron": "Angerufen um die Orthodoxie wider die Häresie; um das Ausharren in der Verbannung."},

"Venerable Prokopios the Confessor of Decapolis":
{"type": "Bekenner · 8. Jh.", "life": "Ehrwürdiger Prokopios der Bekenner aus der Dekapolis war ein Mönch jener Landschaft Kleinasiens in den Tagen, da Kaiser Leon der Isaurier die erste grosse Verfolgung gegen die heiligen Ikonen erhob, und er erwarb seinen Namen in der vollsten Münze, die jene Zeit ausser dem Tode zu bieten hatte.", "patron": "Angerufen von Bekennern; von Mönchen unter der Verfolgung."},

"Saint Moses, Archbishop of Novgorod":
{"type": "Erzbischof · 14. Jh.", "life": "Heiliger Moissej, Erzbischof von Nowgorod, wurde in jener Stadt wohlhabenden und frommen Eltern geboren und in der Taufe Mitrofan genannt; er floh Ehe wie Erbe, wurde mit dem Namen Moissej eingekleidet, mühte sich in den Klöstern des Nowgoroder Landes und stieg um seines lauteren Rufes willen zum Archimandriten des grossen Jurjew-Klosters auf, von dem die Stadt ihn 1325 auf ihren erzbischöflichen Thron rief.", "patron": "Angerufen von Schreibern; von Erbauern der Kirchen."},

"Martyr Paramon and 370 Martyrs in Bithynia":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Paramon und die dreihundertsiebzig Märtyrer mit ihm litten im Jahre 250 in Bithynien in der Verfolgung unter Decius. Der Statthalter Aquilinus, der zu den warmen Quellen jener Gegend gekommen war, hielt eine Menge von Christen in Fesseln bei sich, dreihundertsiebzig an der Zahl.", "patron": "Angerufen um die Rede, die vor dem Unrecht nicht schweigt."},

"Venerable Anthony the Roman and Abbot of Novgorod":
{"type": "Abt (Igumen) · 12. Jh.", "life": "Ehrwürdiger Antonij wurde im Jahre 1067 zu Rom wohlhabenden Eltern geboren, die am orthodoxen Glauben festhielten, und gab sich nach ihrem Tode, mit siebzehn Jahren, dem Studium der Väter in griechischer Sprache hin. Einen Teil seines Erbes verteilte er an die Armen, den übrigen verschloss er in ein hölzernes Fass und warf es ins Meer, und wurde in einem Einödkloster Mönch, wo er zwanzig Jahre lebte.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Translation of the relics of Saint Maximus the Confessor":
{"type": "Mönch · 7. Jh.", "life": "Übertragung der Reliquien des heiligen Maximos des Bekenners, eines der grössten Theologen der Kirche, der um das Jahr 580 zu Konstantinopel geboren wurde und Kaiser Herakleios als erster Staatsschreiber diente, ehe er den Hof um des Mönchslebens willen im Kloster zu Chrysopolis verliess, wo er mit der Zeit Abt wurde.", "patron": "Angerufen von Theologen; um die orthodoxe Theologie."},

"Venerable Barlaam, Abbot of the Kyiv Near Caves":
{"type": "Abt (Igumen) · 11. Jh.", "life": "Ehrwürdiger Warlaam von den Kiewer Höhlen, der erste Abt jener grossen Lawra, war der Sohn eines vornehmen Bojaren von Kiew; und da der junge Edelmann oft zur Höhle des heiligen Antonij kam, traf ihn das Wort des Ältesten so, dass er eines Tages in seinen besten Kleidern hinausritt, abstieg, sein reiches Gewand dem Ältesten zu Füssen legte und um das Mönchsgewand bat.", "patron": "Angerufen von Äbten; von Pilgern."},

"Martyr Platon of Ancyra":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Platon litt zu Beginn des vierten Jahrhunderts zu Ankyra in Galatien, ein junger Mann aus christlichem Hause und Bruder des Märtyrers Antiochos. Er zog freimütig durch die Stadt und lehrte seine Mitbürger, die Götzen zu verachten und den wahren Gott zu erkennen; darum wurde er ergriffen und vor den Statthalter Agrippinus geführt.", "patron": "Angerufen von den Jungen; um die Weigerung jedes Handels wider Christus."},

"Martyr Anna at Rome":
{"type": "Laiin", "life": "Heilige Märtyrerin Anna litt für Christus zu Rom im Zeitalter der Verfolgungen. Wenig ist von ihr bewahrt, doch ehren die Gesänge der Kirche sie als einen hellen Stern, der Christus freimütig bekannte, die Gläubigen vom Reiz der Götzen abwandte und vom Herrn für ihre Leiden einen unvergänglichen Kranz empfing.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Commemoration of the Miracle of the Archangel Michael at Colossae":
{"type": "Fest", "life": "Gedächtnis des glorreichen Wunders, das der Erzengel Michael zu Chonai bei Kolossai in Phrygien wirkte. An jenem Orte war eine wundertätige Quelle, die der Apostel Johannes der Theologe vorausgesagt hatte, als er zu Hierapolis verkündete; und ein Mann aus Laodikeia, dessen stumme Tochter durch ihr Wasser die Sprache empfing, nachdem der Erzengel ihm im Traume erschienen war, liess sich mit seinem ganzen Hause taufen.", "patron": "Angerufen um Schutz; um Heilung."},

"The Universal Exaltation of the Precious and Life-Giving Cross":
{"type": "Grosses Fest", "life": "Die Weltweite Erhöhung des kostbaren und lebenspendenden Kreuzes ist eines der zwölf grossen Feste der Kirche und ein Tag strengen Fastens aus Ehrfurcht vor den Leiden des Herrn am Holze. Als die heilige Kaiserin Helena nach Jerusalem kam, das Kreuz Christi zu suchen, fand man es unter einem heidnischen Tempel in der Erde verborgen, zusammen mit den Kreuzen der beiden Schächer.", "patron": "Angerufen für die ganze Welt; um den Sieg über das Böse."},

"Saint John the Chozebite, Bishop of Caesarea, Palestine":
{"type": "Bischof · 6. Jh.", "life": "Heiliger Johannes der Choziba war ein Ägypter aus Theben, der sich von Jugend an dem asketischen Leben hingab; als er ins Heilige Land kam, liess er sich in der wilden Schlucht Choziba in der judäischen Wüste nieder, an der Strasse von Jerusalem nach Jericho, wo seine Heiligkeit und seine Wunder in ganz Palästina bekannt wurden.", "patron": "Angerufen von Mönchen; um die Liebe zur Stille."},

"Apostle Matthias of the Seventy":
{"type": "Apostel · 1. Jh.", "life": "Heiliger Apostel Matthias wurde zu Bethlehem aus dem Stamme Juda geboren und wurde von Kindheit an vom heiligen Symeon dem Gottesempfänger im Gesetze Gottes unterwiesen. Als der Herr Jesus Christus in der Welt erschien, glaubte Matthias an ihn als den Messias und folgte ihm treu, und er wurde zu den Siebzig gezählt, die der Herr zu zweien vor seinem Angesicht aussandte.", "patron": "Angerufen von Glaubensboten; um die verborgene Treue."},

"Martyrs Rhipsime and Gaianḗ of Armenia and those with them":
{"type": "Märtyrerinnen · 4. Jh.", "life": "Heilige Märtyrerinnen Rhipsime und Gaiane und ihre Gefährtinnen waren Jungfrauen einer Gemeinschaft zu Rom, die in den Osten flohen, als Kaiser Diokletian, der die Schönheit der Rhipsime gesehen hatte, sie zur Frau nehmen wollte; und als sie nach Armenien kamen, liessen sie sich in Armut bei der Stadt Waghatschapat nieder und lebten von der Arbeit ihrer Hände.", "patron": "Angerufen um die Reinheit; um die Bekehrung Armeniens."},

"Martyr Susanna, Queen of Georgia":
{"type": "Märtyrerin · 5. Jh.", "life": "Heilige Schuschanik, Susanna genannt, war die Gemahlin Warskens, des Herrschers von Hereti im östlichen Georgien, und von Kindheit an in einer frommen christlichen Familie erzogen. Als ihr Mann zum persischen König zog und dort Christus verleugnete, um das Feuer anzubeten, und versprach, bei seiner Rückkehr Frau und Kinder zu bekehren, traf es Schuschanik ins Herz.", "patron": "Angerufen um standhaftes Bekenntnis; von denen, die um des Glaubens willen von den Ihren verfolgt werden."},

"Consecration of the Church of the Holy Great Martyr George in Lydda":
{"type": "Fest", "life": "Gedächtnis der Weihe der Kirche des heiligen Grossmärtyrers Georgios zu Lydda in Palästina und der Niederlegung seiner kostbaren Reliquien daselbst. Der Grossmärtyrer, der im Jahre 303 unter Diokletian zu Nikomedeia litt, hatte seinen Diener vor dem Kampfe gebeten, seinen Leib nach Lydda zu bringen, in die Heimat der Familie seiner Mutter im Heiligen Lande.", "patron": "Angerufen um die Verehrung des Grossmärtyrers Georgios."},

"Venerable Philotheus, Patriarch of Constantinople":
{"type": "Patriarch · 14. Jh.", "life": "Ehrwürdiger Philotheos, Patriarch von Konstantinopel, Kokkinos genannt, stammte aus Thessalonike und empfing in der Jugend das Mönchsgewand. Nachdem er sich eine Zeitlang auf dem Sinai gemüht hatte, kam er zum Heiligen Berge Athos, wo er Abt der Grossen Lawra wurde; 1347 wurde er Metropolit von Herakleia in Thrakien und bestieg danach den ökumenischen Thron von Konstantinopel.", "patron": "Angerufen von Theologen; von Hymnendichtern."},

"Venerable Savva, Igoumen of Zvenigorod, Disciple of Venerable Sergius of Radonezh":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Sawwa von Storoschi, der Wundertäter von Swenigorod, war unter den ersten Jüngern des heiligen Sergij von Radonesch, unter dem grossen Ältesten in Schweigen, Gehorsam und unablässigem Gebet geformt und von der Bruderschaft so sehr geachtet, dass er der ganzen Dreifaltigkeitsgemeinschaft als Beichtvater diente und eine Zeitlang, nachdem Nikon sich ins Schweigen zurückgezogen hatte, als Abt der Lawra selbst.", "patron": "Angerufen von Beichtvätern; von Äbten."},

"The Holy Transfiguration of our Lord God and Savior Jesus Christ (the Second “Feast of the Savior” in August)":
{"type": "Grosses Fest", "life": "Die Verklärung feiert den Tag, an dem der Herr Petros, Jakobos und Johannes auf einen hohen Berg führte, den die Überlieferung für den Tabor hält, und vor ihnen verklärt wurde: sein Antlitz leuchtete wie die Sonne und seine Kleider wurden weiss wie das Licht. Moses und Elias erschienen und redeten mit ihm von seinem Ausgang zu Jerusalem, und eine lichte Wolke überschattete sie, aus der die Stimme des Vaters erscholl.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Chariton the Confessor, Abbot of Palestine":
{"type": "Abt (Igumen) · 4. Jh.", "life": "Ehrwürdiger Chariton der Bekenner war ein Bürger von Ikonion und bekannte Christus in der Verfolgung unter Aurelian; er erduldete solche Qualen, dass man ihn als Märtyrer zählte, obgleich er sie überlebte, und als die Verfolgung nachliess und man ihn freiliess, trug er die Male seines Bekenntnisses an seinem Leibe.", "patron": "Angerufen von Mönchen; um die Mönchsregel."},

"Venerable Tryphon, Abbot of Vyatka":
{"type": "Archimandrit · 17. Jh.", "life": "Ehrwürdiger Trifon von Wjatka wurde einer Bauernfamilie im Mesener Lande des fernen Nordens geboren und floh in der Jugend vor der Ehe, welche die Seinen ihm bestimmt hatten; er wanderte als obdachloser Pilger umher und ertrug Kälte und Spott um der Liebe Gottes willen, bis er im Pyskorer Kloster an der Kama das Mönchsgewand empfing.", "patron": "Angerufen von Glaubensboten; um die Erleuchtung der nördlichen Völker."},

"Commemoration of the Kazan Icon of the Mother of God and the deliverance from the Poles":
{"type": "Fest", "life": "Gedächtnis der Kasaner Ikone der Allheiligen Gottesmutter zur Erinnerung an die Errettung Moskaus und ganz Russlands von den Polen im Jahre 1612. In der Zeit der Wirren, als das Land von Einfall und Verrat zerrissen war und fremde Waffen Moskau selbst hielten und den orthodoxen Glauben verspotteten, rief der gefangene Patriarch Hermogen das Volk auf, sich zur Verteidigung von Kirche und Vaterland zu erheben.", "patron": "Angerufen um die Errettung der Völker; um den Schutz in der Zeit der Wirren."},

"Prophet Obadiah (Abdia)":
{"type": "Prophet · 9. Jh. v. Chr.", "life": "Heiliger Prophet Obadja, dessen Buch, das kürzeste des Alten Testamentes, unter den zwölf kleinen Propheten steht, weissagte das Gericht Gottes über Edom, das stolze Brudervolk, das sich über den Fall Jerusalems freute: Wenn du dich auch erhöbest wie ein Adler und dein Nest zwischen die Sterne setztest, so will ich dich doch von dort herabstürzen, spricht der Herr.", "patron": "Angerufen von Verwaltern; um die Demütigung des Hochmuts."},

"Venerable Sisoes the Great":
{"type": "Mönch (Einsiedler) · 5. Jh.", "life": "Ehrwürdiger Sisoes der Grosse war im fünften Jahrhundert ein einsamer Mönch der ägyptischen Wüste und nahm seine Wohnung in eben der Höhle, die einst die Mühen des heiligen Antonios des Grossen geheiligt hatten. In sechzig Jahren asketischen Kampfes erlangte er eine seltene Reinheit der Seele und wurde mit der Gabe des Wunderwirkens beschenkt und erweckte einmal sogar ein totes Kind durch sein Gebet.", "patron": "Angerufen von Mönchen; um die Demut."},

"Hieromartyr Cyprian, Virgin Martyr Justina, and Martyr Theoctistus, of Nicomedia":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Kyprianos, die heilige Jungfrau und Märtyrerin Justina und der Märtyrer Theoktistos litten im Jahre 304 zu Nikomedeia. Kyprianos war ein Weiser und Zauberer aus Antiochien, von Kindheit an in den heidnischen Mysterien auf dem Olymp und zu Argos, Memphis und Babylon geschult, bis er als Diener des Fürsten der Finsternis berühmt wurde.", "patron": "Angerufen um die Befreiung von Zauberei und bösen Geistern; um die Reinheit, die das Kreuz behütet."},

"Venerable Ephraim, Abbot of Perekop, Wonderworker of Novgorod":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Jefrem von Perekop, der Wundertäter von Nowgorod, wurde zu Kaschin geboren und hiess in der Welt Jewstafij. Von Jugend an zum Mönchsleben gezogen, verliess er das Haus seiner Eltern und wurde mit dem Namen Jefrem eingekleidet und mühte sich zuerst unter der Führung der grossen Ältesten des russischen Nordens.", "patron": "Angerufen von Mönchen; von Arbeitenden."},

"Right-believing Prince Vladimir Yaroslavich of Novgorod":
{"type": "Fürst · 11. Jh.", "life": "Heiliger rechtgläubiger Fürst Wolodymyr Jaroslawytsch von Nowgorod, der Wundertäter, war der älteste Sohn des Grossfürsten Jaroslaw des Weisen und der frommen Fürstin Irina, die ihre Tage als Nonne Anna beschloss und mit ihrem Sohne geehrt wird. Mit vierzehn Jahren vom Vater über Nowgorod gesetzt, wurde er von weisen Ratgebern und vom heiligen Bischof der Stadt geleitet.", "patron": "Angerufen von Erbauern der Kirchen; um den Kirchenbau."},

"Saint Liberius, Pope of Rome":
{"type": "Papst · 4. Jh.", "life": "Heiliger Liberius wurde im Jahre 352 nach dem Entschlafen des Papstes Julius Bischof von Rom und erwies sich als eifriger Verteidiger des orthodoxen Glaubens wider die arianische Häresie und als Streiter für den heiligen Athanasios von Alexandreia. Als Kaiser Constantius, der die Arianer begünstigte, von ihm die Verurteilung des Athanasios forderte, weigerte er sich und wurde in die Verbannung geschickt.", "patron": "Angerufen um die Orthodoxie wider die Häresie."},

"Martyr Orestes, Physician of Cappadocia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Orestes der Arzt lebte unter Diokletian zu Tyana in Kappadokien, ein gelehrter und geschickter Heiler der Leiber und von Kindheit an ein wahrer Christ. Als der Beamte Maximinus nach Tyana gesandt wurde, den Glauben zu zerschlagen, war Orestes unter den ersten, die man vor Gericht führte, und bekannte den gekreuzigten und auferstandenen Herrn offen, unbewegt von Reichtum und Ehren, die man ihm bot.", "patron": "Angerufen von Ärzten; um Heilung."},

"Venerable Hilarion, Abbot of Gdov and Pskov Lake":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Ilarion von Gdow war ein Jünger des grossen Ältesten Jewfrossin von Pskow und wurde in dessen Einödschule des strengen Fastens, des Gehorsams und des unablässigen Gebetes geformt. Mit dem Segen seines Ältesten zog er aus und gründete am Flusse Schelscha, unweit von Gdow im Seenlande von Pskow, ein Kloster zu Ehren des Schutzes der Allheiligen Gottesmutter, in einem den Einfällen ausgesetzten Grenzlande.", "patron": "Angerufen von Mönchen; für die Klöster der Grenzlande."},

"Apostles of the Seventy Archippus and Philemon, and Martyr Apphia":
{"type": "Apostel der Siebzig, Märtyrer · 1. Jh.", "life": "Heilige Apostel der Siebzig Archippos und Philemon und die Märtyrerin Apphia sind das Haus des kürzesten Briefes, jene Familie zu Kolossai, an die Paulos den Brief schrieb, der den Namen des Philemon trägt.", "patron": "Angerufen von Hausgemeinden; von Eheleuten, die gemeinsam dienen."},

"Martyrs Nestor, Tribimius, and those with them":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Nestor, Tribimios, Markellos und Antonios von Perge in Pamphylien litten unter Kaiser Decius um das Jahr 250, in der Verfolgung, die von jeder Seele im Reiche einen Opferschein forderte und aus jeder Weigerung eine Sache auf Leben und Tod machte. Die vier waren Christen von Perge und warteten nicht, bis man sie fand.", "patron": "Angerufen von Gefährten im Bekenntnis; um die vier Kränze durch das Schwert."},

"Saint Amphilochius, Bishop of Vladimir, Volhynia":
{"type": "Bischof · 12. Jh.", "life": "Heiliger Amphilochij, Bischof von Wolodymyr in Wolhynien, war der dritte Bischof jenes Stuhles, eines der ältesten im russischen Lande, der in den Tagen des heiligen Wolodymyr des Grossen errichtet wurde; seine Vorgänger waren Stefan, der unter Wolodymyr selbst erwählt wurde, und Stefan, der Abt der Kiewer Höhlen, der dem heiligen Theodosij nachgefolgt war.", "patron": "Angerufen von Glaubensboten; um die Ausrottung des Heidentums."},

"Apostle Nicanor the Deacon of the Seventy":
{"type": "Diakon · 1. Jh.", "life": "Heiliger Apostel Nikanor war einer der ersten sieben Diakone der Kirche Christi, erwählt, wie die Apostelgeschichte berichtet, als die Zwölf die Menge der Jünger zusammenriefen und sieben Männer von gutem Rufe, voll Heiligen Geistes und Weisheit, bestellten: Stephanos, Philippos, Prochoros, Nikanor, Timon, Parmenas und Nikolaos, damit sie bei Tische dienten und für die Witwen sorgten.", "patron": "Angerufen von Diakonen; von denen, die bei Tische dienen."},

"Martyrs Marcian and Martyrius, the Notaries of Constantinople":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Markianos und Martyrios dienten als Notare, das ist als Schreiber und Vorleser, dem heiligen Paulos dem Bekenner, Patriarchen von Konstantinopel, in den Jahren, da die arianische Häresie, vom kaiserlichen Hofe gestützt, gegen die Verteidiger des nizänischen Glaubens wütete. Als der heilige Patriarch verbannt und in der Verbannung heimlich erdrosselt wurde, suchten die Arianer seine treuen Notare mit Gold zu gewinnen.", "patron": "Angerufen von Notaren; von Schreibern."},

"Forefeast of the Procession of the Honorable and Lifegiving Cross of the Lord":
{"type": "Vorfest", "life": "Vorfest der Prozession des kostbaren und lebenspendenden Kreuzes des Herrn, welche die Kirche am ersten August feiert. In der Kaiserstadt Konstantinopel war es Brauch, im Monat August, wenn die Krankheit am häufigsten war, das ehrwürdige Holz des Kreuzes aus der Schatzkammer hervorzutragen.", "patron": "Angerufen um die Befreiung von Krankheit; um die Heiligung."},

"Martyrs Kyriaina and Juliana in Cilicia":
{"type": "Märtyrerinnen · 4. Jh.", "life": "Heilige Märtyrerinnen Kyriaina und Juliana litten um das Jahr 305 in Kilikien in der Verfolgung unter Maximian. Kyriaina stammte aus Tarsos und Juliana aus der Stadt Rossos, beide Frauen, die ihr Leben Christus in Reinheit und Gebet hingegeben hatten; und von Markianos, dem Statthalter Kilikiens, ergriffen, wiesen sie jede Aufforderung zum Götzenopfer zurück.", "patron": "Angerufen um die Würde unter dem Spott; von Frauen, die bis zum Tode treu sind."},

"Martyr Aboudimos of the Isle of Tenedos":
{"type": "Laie · 4. Jh.", "life": "Heiliger Märtyrer Aboudimos stammte von der Insel Tenedos, die in der Ägäis der alten Stadt Troja gegenüberliegt, und war zu Beginn des vierten Jahrhunderts unter den ersten, die in der Verfolgung unter Diokletian für Christus litten. Als man ihm gebot, die Götzen anzubeten und vom Opferfleisch zu essen, weigerte er sich standhaft und wurde dafür gebunden und grausam geschlagen.", "patron": "Angerufen um die Standhaftigkeit."},

"Virgin Martyr Anysia at Thessalonica":
{"type": "Jungfrau und Märtyrerin · 3. Jh.", "life": "Heilige Jungfrau und Märtyrerin Anysia lebte unter Maximian zu Thessalonike, die verwaiste Tochter frommer Eltern, die sie im Glauben erzogen hatten; und als sie ihr Vermögen erbte, verkaufte sie alles, verteilte den Erlös an die Armen und gab sich einem verborgenen Leben in Fasten, Vigil und Gebet hin, ein Kloster von einer einzigen in der grossen heidnischen Stadt.", "patron": "Angerufen von jungen Frauen; von denen, die auf dem Wege zur Kirche angefallen werden."},

"Hieromartyr Cornelius the Centurion":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Hieromärtyrer Kornelios der Hauptmann, der Erstling der Heiden, war ein römischer Offizier der italischen Kohorte zu Kaisareia in Palästina, ein frommer Mann, der Gott fürchtete mit seinem ganzen Hause, reichlich Almosen gab und allezeit betete, wie die Apostelgeschichte bezeugt. Ihm erschien ein Engel und sprach, dass seine Gebete und Almosen vor Gott zum Gedächtnis aufgestiegen seien.", "patron": "Angerufen von Soldaten; von Bekehrten."},

"Glorification of Saint John of Kronstadt":
{"type": "Gerechter · 20. Jh.", "life": "Verherrlichung des heiligen Johann von Kronstadt, eines der grossen Hirten der russischen Kirche, der 1829 als Iwan Sergijew in einem armen Dorfe des fernen Nordens geboren wurde und als verheirateter Gemeindepriester an der Andreas-Kathedrale zu Kronstadt bei Sankt Petersburg über fünfzig Jahre lang diente.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyrs Eudoxios, Agapios, Atticus, and those with them, at Sebaste":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Attikos, Agapios, Eudoxios, Karterios, Istukarios mit dem Beinamen Styrax, Paktobios und Niktopolion und ihre Gefährten waren Soldaten zu Sebasteia in Armenien und litten um das Jahr 320 in der Verfolgung unter Licinius, der, während er den Krieg gegen den heiligen Konstantin vorbereitete, seine Heere von Christen säuberte und von den Besatzungen das Götzenopfer forderte.", "patron": "Angerufen von Soldaten; von Soldaten, die Christus treu bleiben."},

"The Discovery of the Relics of Venerable Zosimas, Abbot of Vorbozomsk":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Auffindung der Reliquien des ehrwürdigen Sossima von Worbosomsk, eines Jüngers des grossen Ältesten Kornilij von Komel, in dessen Einödschule so viele Gründer der nördlichen Klöster geformt wurden; mit dem Segen seines Ältesten zog er aus und liess sich auf einer Insel des Worbosomsker Sees südlich von Beloosero nieder, wo er ein Kloster zu Ehren der Verkündigung der Allheiligen Gottesmutter gründete.", "patron": "Angerufen von Mönchen; von geistlichen Führern."},

"Martyrs Patermuthius, Coprius, and Alexander the Soldier, in Egypt":
{"type": "Mönch · 4. Jh.", "life": "Heilige Märtyrer Patermuthios, Koprios und Alexandros litten in Ägypten unter Kaiser Julian dem Abtrünnigen. Patermuthios war einst ein Heide und der Anführer einer Räuberbande gewesen, kam aber zur Busse, wurde getauft und zog sich in die Wüste zurück, wo er sich asketischer Mühe hingab und die Gaben der Heilung und der Weissagung empfing.", "patron": "Angerufen um die Busse; um die Beharrlichkeit."},

"Holy Confessor Emilian, Bishop of Kyzikos":
{"type": "Bischof · 9. Jh.", "life": "Heiliger Bekenner Aimilianos war zu Beginn des neunten Jahrhunderts Bischof von Kyzikos, zur Zeit des zweiten Angriffs auf die heiligen Ikonen unter dem bilderstürmerischen Kaiser Leon dem Armenier. Mit anderen Bischöfen vor den Kaiser gerufen und aufgefordert, seiner Herde die Verehrung der heiligen Bilder zu verbieten, antwortete er freimütig, dass eine Frage des Glaubens der Kirche in der Kirche zu prüfen und zu entscheiden sei.", "patron": "Angerufen um die Verehrung der Ikonen; um die Freiheit der Kirche."},

"Venerable Savva, Abbot of Vishera, Novgorod":
{"type": "Mönch · 15. Jh.", "life": "Ehrwürdiger Sawwa von Wischera war der Sohn eines Bojaren aus Kaschin und liess in der Jugend Verlobung und Erbe, empfing das Mönchsgewand und gab sich strenger Askese hin und zog sogar zum Heiligen Berge Athos, um in dessen Überlieferungen geformt zu werden. In das russische Land zurückgekehrt, liess er sich am Flusse Wischera unweit von Nowgorod nieder, wo er 1418 ein Kloster errichtete.", "patron": "Angerufen von Mönchen; um das wachsame Gebet."},

"Martyrs Trophimus, Sabbatius, and Dorymedon of Synnada":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Trophimos, Sabbatios und Dorymedon litten für Christus unter Kaiser Probus. Trophimos und Sabbatios kamen während eines lärmenden heidnischen Festes nach Antiochien, betrübten sich über das Schauspiel und beteten für die Irrenden; darauf bemerkte man sie, ergriff sie und führte sie vor den Statthalter, und da sie ohne Wanken bekannten, starb Sabbatios unter den harten Martern.", "patron": "Angerufen um die Freundschaft in Christo; um die Sorge für die Gefangenen."},

"Venerable Mary (who was called Marinus), and her father, Venerable Eugene, at Alexandria":
{"type": "Nonne · 6. Jh.", "life": "Ehrwürdige Maria, die Marinos genannt wurde, und ihr Vater Eugenios sind die erstaunliche Lehre der Kirche über die äussersten Grenzen der Geduld. Als der Witwer Eugenios beschloss, seine Tage in einem Kloster zu beenden, wollte seine junge Tochter Maria nicht in der Welt zurückbleiben, und die beiden ersannen die einzige Tür, die sie gemeinsam einliess: Maria schnitt ihr Haar, legte Männerkleider an und trat in das bithynische Kloster ein.", "patron": "Angerufen von den zu Unrecht Beschuldigten; von Frauen, die sich um Gottes willen verbergen."},

"Venerable Martyrius of Zelenets, Pskov":
{"type": "Abt (Igumen) · 17. Jh.", "life": "Ehrwürdiger Martirij von Selenez, in der Welt Mina, wurde im sechzehnten Jahrhundert zu Weliki Luki den frommen Kosma und Stefanida geboren und mit zehn Jahren Waise; sein geistlicher Vater, ein Priester der Verkündigungskirche der Stadt, zog den Knaben auf, und seine Seele hing, wie das Leben berichtet, seit jener Erziehung im Verlust an Gott, denn der Waise lernte früh, dass der eine Vater nicht stirbt.", "patron": "Angerufen von Waisen; von Gründern."},

"Venerable Andronicus, and his wife Athanasia, of Egypt":
{"type": "Gerechte · 5. Jh.", "life": "Ehrwürdiger Andronikos und seine Gemahlin Athanasia lebten im fünften Jahrhundert zu Antiochien; er war Silberschmied und teilte seinen Erwerb in drei Teile, für die Armen, für die Kirche und für sein Haus, und beide waren um ihrer Wohltätigkeit willen geliebt. Als ihre beiden Kinder an einem einzigen Tage starben, war Athanasia von Trauer zerbrochen und wollte das Grab nicht verlassen, bis der heilige Märtyrer Julianos ihr erschien.", "patron": "Angerufen von Eheleuten; von Trauernden."},

"Martyrs Sophia, Irene, and Castor of Egypt":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrerinnen Sophia und Irene litten im Zeitalter der Verfolgungen in Ägypten für Christus, und mit ihnen wird der Märtyrer Kastor begangen. Von ihrem Kampfe ist wenig bewahrt ausser dem Zeugnis der alten Kalender, die festhalten, dass die heiligen Frauen, nachdem sie vor ihren Verfolgern Christus bekannt und das Götzenopfer verweigert hatten, mit dem Schwerte enthauptet wurden.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Hieromartyr Euthymius, Bishop of Sardis":
{"type": "Bischof · 9. Jh.", "life": "Heiliger Hieromärtyrer Euthymios, Bischof von Sardeis, wurde in den Tagen Konstantins und Irenes um seines tugendhaften Lebens willen auf jenen alten Stuhl erhoben und stand 787 auf dem Siebten Ökumenischen Konzil unter den Verwerfern der bilderstürmerischen Häresie; und als die Häresie auf den Thron zurückkehrte, wurde sein Bischofsamt eine vierzigjährige Kette von Verbannungen, eine für jeden Kaiser, der forderte, was er nicht geben wollte.", "patron": "Angerufen von Bischöfen in der Verbannung; um die Verehrung der heiligen Ikonen."},

"Venerable John-Barsanuphius, Bishop of Damascus":
{"type": "Bischof, Mönch · 5. Jh.", "life": "Ehrwürdiger Johannes, Barsanuphios genannt, Bischof von Damaskus, vollbrachte die Flucht, von der viele Hierarchen geträumt und die wenige gewagt haben: er legte einen Thron in die Hände Gottes nieder, ohne es jemandem zu sagen, und beendete sein Leben als namenloser Arbeiter unter den Mönchen Ägyptens. Als Bischof des grossen Stuhles von Damaskus im fünften Jahrhundert regierte er, wie die Überlieferung hält, mit dem Fleiss eines guten Hirten.", "patron": "Angerufen von Hierarchen, die nach der Verborgenheit verlangen; von Wasserträgern und Holzhauern."},

"Finding of the relics of Venerable Cyril, Abbot of Novoezersk, Vologda":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Auffindung der Reliquien des ehrwürdigen Kirill von Nowojesero im Jahre 1649. Einem vornehmen Hause zu Galitsch geboren, floh er mit fünfzehn Jahren aus dem Hause seiner Eltern, von der Liebe zu Christus gezogen, und kam durch die Wälder zum grossen Ältesten Kornilij von Komel, der das Siegel Gottes an dem Knaben erkannte und ihn einkleidete.", "patron": "Angerufen von Mönchen; um die Weihe der Jugend."},

"Hieromartyr Hermolaus and Martyrs Hermippus and Hermocrates at Nicomedia":
{"type": "Priester · 4. Jh.", "life": "Heilige Hieromärtyrer Hermolaos, Hermippos und Hermokrates waren unter den wenigen, die überlebten, nachdem zwanzigtausend Christen in der Verfolgung unter Maximian in einer Kirche zu Nikomedeia verbrannt worden waren. Sie lebten im Verborgenen und hörten doch nicht auf, den Heiden das Evangelium zu verkünden, und der Priester Hermolaos war es, der den jungen Heiden Pantoleon an seiner Wohnung vorübergehen sah, ihn hereinrief und ihn lehrte.", "patron": "Angerufen von Katecheten."},

"Venerable Luke the Steward of the Kyiv Caves":
{"type": "Mönch · 13. Jh.", "life": "Ehrwürdiger Luka der Verwalter trug im Kiewer Höhlenkloster den Gehorsam des Ökonomen, dem die Güter, die Vorräte und die äusseren Angelegenheiten der Bruderschaft anvertraut sind; und er zeigte, dass dieser Dienst, der eine Seele so leicht in Sorgen und in die Versuchung des Gewinnes verstrickt, ein Weg der Heiligkeit sein kann, wenn er in Redlichkeit und Gebet gegangen wird.", "patron": "Angerufen von Verwaltern; von Schatzmeistern."},

"Venerable Zeno the Hermit of Antioch, disciple of Saint Basil the Great":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdiger Zenon der Einsiedler von Antiochien wurde im Pontos einer reichen Familie geboren und diente am Hofe Kaiser Valens' unter den Kurieren, welche die kaiserlichen Erlasse durch das Reich trugen, ein Mann, dessen Beruf Schnelligkeit, Strassen und die Worte der Macht waren; und der heilige Basileios der Grosse, dessen Jünger er war, hatte ihn in der Jugend geformt, sodass unter dem Mantel des Kuriers schon ein Mönch ritt.", "patron": "Angerufen von Kurieren; von Boten."},

"Martyr Cyrilla of Cyrene in Libya, a widow":
{"type": "Laiin · 4. Jh.", "life": "Heilige Märtyrerin Kyrilla litt zu Kyrene in Libyen in der Verfolgung Diokletians. Als eine Christus geweihte Witwe wurde sie ergriffen und aufgefordert, den Götzen Weihrauch darzubringen. Als man glühende Kohlen mit Weihrauch in ihre offene Hand legte, damit es beim Fortwerfen aussehe, als opfere sie den falschen Göttern, ertrug sie das Feuer, ohne zu wanken, und liess die Kohlen nicht fallen.", "patron": "Angerufen um die Beständigkeit unter der Marter."},

"Martyrs Onesiphorus and Porphyrius of Ephesus":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Onesiphoros und Porphyrios litten gegen Ende des dritten Jahrhunderts für Christus in der Verfolgung unter Diokletian. Da sie sich als Christen bekannten, wurden sie vor Gericht gestellt und harten Qualen unterworfen, geschlagen und mit Feuer gebrannt; und als weder Schmerz noch Versprechen sie von Christus abbringen konnten, banden die Peiniger die Märtyrer an wilde Pferde.", "patron": "Angerufen um das Ausharren bis ans Ende."},

"Monastic Martyr Joseph of Dionysiou, Mount Athos":
{"type": "Mönch · 19. Jh.", "life": "Ehrwürdiger Mönchsmärtyrer Joseph war Mönch des Klosters Dionysiou auf dem Athos, wo er in den Tugenden des Mönchslebens leuchtete und als Ikonenmaler arbeitete und die Ikone der heiligen Erzengel für die Ikonostase der Hauptkirche des Klosters malte. Im Gehorsam gegen seinen Abt Stephanos reiste er nach Konstantinopel als Begleiter eines gewissen Eudokimos, der zum Islam abgefallen war und nun Busse tat.", "patron": "Angerufen von Ikonenmalern; um standhaftes Bekenntnis."},

"Saint Boniface the Merciful, Bishop of Ferentino":
{"type": "Bischof · 6. Jh.", "life": "Heiliger Bonifatius der Barmherzige, Bischof von Ferentino in Italien, lebte im sechsten Jahrhundert, und seine Wunder wurden noch aus lebendiger Erinnerung vom heiligen Gregorios dem Grossen in den Dialogen aufgezeichnet, worin der Papst von Rom die Geschichten der Heiligen seines eigenen italischen Bodens bewahrte. Die Barmherzigkeit lief dem Verstande des Bonifatius von Kindheit an voraus: was dem Knaben in die Hände kam, ging an die Armen, sein eigenes Hemd nicht ausgenommen.", "patron": "Angerufen von Almosengebern; von Verwaltern geringer Mittel."},

"Uncovering of the relics of Saint Andrew, Prince of Smolensk":
{"type": "Fürst · 14. Jh.", "life": "Auffindung der Reliquien des heiligen Andrej, Fürsten von Smolensk, die im Jahre 1539 zu Perejaslawl-Salesskij durch die Mühe des heiligen Daniil von Perejaslawl geschah. Der heilige Fürst, betrübt über die Feindschaft und den Zwist seiner Verwandten, hatte sein Fürstentum heimlich verlassen und diente, als unbekannter armer Mann nach Perejaslawl gekommen, dreissig Jahre lang als Küster.", "patron": "Angerufen von Küstern; von Kirchendienern."},

"Martyr Hyacinthus of Amastridea":
{"type": "Laie · 4. Jh.", "life": "Heiliger Märtyrer Hyakinthos wurde in der Stadt Amastris in Kleinasien in ein frommes christliches Haus geboren, und es heisst, ein Engel sei erschienen und habe ihm seinen Namen gegeben. Schon als kleines Kind war er voll Gnade, und als er erst drei Jahre alt war, erweckte sein Gebet ein totes Kind zum Leben, sodass die beiden Kinder miteinander aufwuchsen und sich einem asketischen Leben hingaben.", "patron": "Angerufen um den Eifer wider den Götzendienst."},

"Venerable Pimen the Great":
{"type": "Mönch · 5. Jh.", "life": "Ehrwürdiger Poimen der Grosse wurde um das Jahr 340 in Ägypten geboren und trat mit seinen beiden Brüdern Anub und Paisios in ein Kloster ein; alle drei empfingen das Mönchsgewand und gaben sich strenger asketischer Mühe hin.", "patron": "Angerufen von Mönchen; um die Demut."},

"Venerable Agathon, Wonderworker of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Agafon, Wundertäter der Kiewer Höhlen, mühte sich im dreizehnten und vierzehnten Jahrhundert in den Fernen Höhlen des heiligen Theodosij, und die Überlieferung der Lawra bewahrt sein Bild in zwei Gaben, der Heilung und der Vorherschau, der offenen Hand und dem offenen Auge. Man brachte ihm die Kranken, und er heilte sie durch Handauflegung, die älteste und persönlichste Arznei der Kirche.", "patron": "Angerufen von Heilkundigen; von denen, die ihre Stunde erwarten."},

"Martyr Gobron (Michael) and 133 soldiers, of Georgia":
{"type": "Heerführer · 10. Jh.", "life": "Heiliger Märtyrer Gobron, in der heiligen Taufe Michael, war ein georgischer Edelmann und Heerführer und wurde um seiner Tapferkeit willen Gobron, der Tapfere, genannt; und als im Jahre 914 die muslimischen Heere die georgischen Lande überschwemmten, führte er die Verteidigung der Festung Kweli. Nach langer Belagerung fiel die Festung, und Michael wurde mit hundertdreiunddreissig seiner Soldaten gefangen.", "patron": "Angerufen von Soldaten; um die Treue in der Niederlage."},

"Martyr Dēmḗtrios of Thrace":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Demetrios von Thrakien war ein Christ des Dorfes Dabuda bei der Stadt Amapas im thrakischen Lande und litt gegen Ende des dritten Jahrhunderts, um das Jahr 298, in der Verfolgung. Als Christ ergriffen und vor den Statthalter der Provinz geführt, bekannte er den Herrn Jesus Christus schlicht und mutig, und weder Zureden noch Drohungen des Richters vermochten etwas.", "patron": "Angerufen um die Standhaftigkeit der Unbekannten."},

"Saints Martinian, Zoe, and Photina of Caesarea in Palestine":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdige Martinianos, Zoe und Photina von Kaisareia in Palästina teilen ein Fest, weil sie eine Geschichte teilen, die grosse Chronik der Kirche von einer Versuchung, die zu einem dreifachen Siege ausgefochten wurde. Martinianos zog mit achtzehn Jahren in die Wildnis bei Kaisareia und gab sich fünfundzwanzig Jahre asketischen Werken und dem Schweigen hin und empfing die Gaben der Heilung und der Dämonenaustreibung.", "patron": "Angerufen von den Versuchten; von Büssenden."},

"Venerable Theodora of Alexandria":
{"type": "Nonne · 5. Jh.", "life": "Ehrwürdige Theodora von Alexandreia lebte im fünften Jahrhundert mit ihrem Manne in Liebe und Eintracht, bis sie, von der Beharrlichkeit eines reichen Mannes umgarnt und vom Trug einer Kupplerin betrogen, die ihr sagte, Gott sehe nicht, was im Dunkeln geschieht, in Sünde fiel.", "patron": "Angerufen um die Busse; von denen, die eine falsche Anklage tragen."},

"Martyr Florentius of Thessalonica":
{"type": "Märtyrer · 2. Jh.", "life": "Heiliger Märtyrer Florentios stammte aus Thessalonike und eiferte für die Ehre Gottes; furchtlos deckte er unter seinen Mitbürgern die Finsternis des Götzendienstes auf und führte viele zum Lichte der wahren Gotteserkenntnis, indem er sie den Glauben an Christus und das Tun seines Willens lehrte.", "patron": "Angerufen um die freimütige Verkündigung."},

"Apostle Aristarchus of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Aristarchos, einer der Siebzig, war ein Makedone aus Thessalonike und einer der treuesten Gefährten des heiligen Apostels Paulos, der ihn in seinen Briefen seinen Mitarbeiter und Mitgefangenen nennt. Er teilte die Mühen und Gefahren des Apostels zu Ephesos, wo die Menge ihn im Theater ergriff.", "patron": "Angerufen von Mitarbeitern; um die Treue in der Gefährtenschaft."},

"Martyrs Perpetua, a woman of Carthage, and the Catechumens: Saturus, Revocatus, Saturninus, Secundulus and Felicitas":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrerinnen Perpetua und Felizitas litten mit den Katechumenen Saturus, Revocatus, Saturninus und Secundulus um das Jahr 203 zu Karthago, und ihr Kampf ist der innigst bekannte der alten Kirche, denn Perpetua führte im Kerker ein Tagebuch, und die Kirche liest ihre eigene Hand seit achtzehn Jahrhunderten, die früheste Schrift, die wir von einer Christin besitzen.", "patron": "Angerufen von Müttern; von werdenden Müttern."},

"Venerable Joseph the Wonderworker, Igumen of Volokolamsk":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Gedächtnis der Verherrlichung des ehrwürdigen Iossif des Wundertäters, Abtes von Wolokolamsk, den das Konzil des Jahres 1591 unter die Heiligen der ganzen russischen Kirche zählte, nachdem seine örtliche Verehrung schon 1579 eingesetzt worden war. Im Jahre 1440 geboren und unter dem heiligen Pafnutij von Borowsk geformt, gründete er in den Wäldern seines heimatlichen Wolokolamsk das berühmte Kloster.", "patron": "Angerufen von Mönchen; von Theologen."},

"Venerable Amphilochius, Abbot of Glushetsa":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Amfilochij von Gluschiza kam als Hieromonach aus Ustjug zum grossen Gründer, dem heiligen Dionisij von Gluschiza, in die Wologdaer Wildnis, da er von dessen englischem Leben gehört hatte, und bat, als sein Jünger aufgenommen zu werden. Dionisij sah in ihm einen würdigen Mitarbeiter voraus und nahm ihn mit Freuden an, und zwanzig Jahre lang teilte Amfilochij alle Mühen seines Ältesten.", "patron": "Angerufen von Mönchen; um den Gehorsam."},

"Blessed Andrew the Fool-For-Christ at Constantinople":
{"type": "Narr in Christo · 10. Jh.", "life": "Seliger Andreas, der Narr in Christo, war ein Slawe von Geburt und wurde in der Jugend als Sklave nach Konstantinopel gebracht, wo er einem Würdenträger der Stadt diente und um seiner Sanftmut und seines Fleisses in der Schrift willen geliebt wurde. Als er im Traume die Heere der Engel und der Dämonen streiten sah und den Herrn ihn zum Kampfe rufen hörte, nahm er die harte Torheit um Christi willen auf sich.", "patron": "Angerufen von den verborgenen Dienern Gottes; um die Schau der himmlischen Dinge."},

"Martyr Mercurius of Smolensk":
{"type": "Märtyrer · 13. Jh.", "life": "Heiliger Märtyrer Merkurij von Smolensk, ein Krieger vornehmer Herkunft aus den westlichen Landen, der im Heere von Smolensk diente, war ein Mann des verborgenen Gebetes und strengen Lebens; und im Jahre 1239, als die Horden Batus, welche die Rus in Blut ertränkt hatten, sich der Stadt näherten und bei Dolgomostje lagerten, erweckte die Gottesmutter selbst ihren Verteidiger.", "patron": "Angerufen von Soldaten; von Verteidigern der Städte."},

"Martyr Anthusa at Rome":
{"type": "Märtyrerin · 4. Jh.", "life": "Heilige Märtyrerin Anthusa war die Frau eines römischen Beamten in den Tagen, da die arianische Häresie, obgleich zu Nikaia verurteilt, Höfe und Paläste noch im Griff hielt; und da sie die heilige Taufe begehrte, wollte sie sie von keiner zweifelhaften Hand empfangen, sondern nahm das rettende Mysterium vom heiligen Ambrosios von Mailand selbst, dem grossen Verteidiger der Gottheit Christi.", "patron": "Angerufen von Frauen der Beamten; um die unverfälscht bewahrte Taufe."},

"Hieromartyr Seraphim (Samoilovich), Archbishop of Uglich":
{"type": "Erzbischof · 20. Jh.", "life": "Heiliger Hieromärtyrer Serafim, Erzbischof von Uglitsch, wurde 1881 als Semjon Samoilowitsch zu Mirgorod im Poltawaer Lande geboren und meldete sich nach dem Seminar freiwillig zur amerikanischen Mission; er lehrte an der Kirchenschule zu Unalaska und darauf zu Sitka, wo er eingekleidet und zum Hieromonachen geweiht wurde und den alaskischen Missionen und dem Seminar zu Sitka als eifriger Mitarbeiter des späteren Patriarchen Tichon diente.", "patron": "Angerufen von Glaubensboten; von Hierarchen."},

"Hieromartyr Athenogenes, Bishop of Heracleopolis, and his ten disciples":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Athenogenes, Bischof von Herakleopolis, litt samt seinen zehn Jüngern in der Verfolgung unter Diokletian in der Stadt Sebasteia in Kappadokien. Als der Statthalter Philomachos ein grosses Fest für die Götzen hielt und dem Volke zu opfern gebot, weigerten sich die Bürger von Sebasteia, die grösstenteils Christen waren, und viele empfingen unter den Soldaten den Kranz des Martyriums.", "patron": "Angerufen um das treue Hirtenamt."},

"Holy Righteous David the King":
{"type": "König und Prophet · 10. Jh. v. Chr.", "life": "Heiliger Prophet und König David, der süsse Sänger Israels, war der jüngste Sohn Isais von Bethlehem, ein Hirtenknabe, den man von der Herde holte, damit Samuel ihn salbe, während seine hochgewachsenen Brüder übergangen wurden, denn der Herr sieht auf das Herz. Seine Jugend ist das Heldenlied Israels: die Harfe, die Sauls Finsternis beschwichtigte, und der Stein, der den Riesen fällte.", "patron": "Angerufen von Königen; von Sängern."},

"Heiromartyr Theokteristus":
{"type": "Abt, Bekenner und Märtyrer · 9. Jh.", "life": "Heiliger Bekenner und Märtyrer Theoktistos, auch Theosteriktos genannt, Abt des Pelekete-Klosters bei Prusa, stand im Mittelpunkt einer der finstersten Untaten der bilderstürmerischen Verfolgung und gab der Kirche aus jener Finsternis eines ihrer geliebtesten Gebete. Zu Triglia in Bithynien geboren, wurde er in der Jugend Mönch im Kloster des heiligen Johannes.", "patron": "Angerufen von Äbten; von Hymnendichtern."},

"Holy King Askiot of Georgia":
{"type": "König und Märtyrer · 9. Jh.", "life": "Heiliger Aschot der Kuropalates, König von Georgien, herrschte im neunten Jahrhundert, in dem Geschlecht, da die georgischen Lande von den arabischen Einfällen verwüstet lagen, und wurde der Herrscher, unter dem das Volk sich aus seinen Trümmern zu erheben begann. Aus dem besetzten Kartlien in das bewaldete Hochland von Tao-Klardschetien zurückgewichen, war er der erste des bagratidischen Hauses, der jenen Titel trug.", "patron": "Angerufen von Herrschern, die wieder aufbauen; von Stiftern der Klöster."},

"Martyrs Basil and Theodore of the Kyiv Caves":
{"type": "Mönch · 11. Jh.", "life": "Ehrwürdige Wassilij und Feodor mühten sich im elften Jahrhundert als Asketen in den Nahen Höhlen zu Kiew. Feodor hatte sein Vermögen an die Armen verteilt und war ins Kloster eingetreten und liess sich in der Warägerhöhle nieder; nach vielen Jahren aber versuchte ihn der Feind mit dem Gedanken an einen Schatz von Gold und Silber, der dort verborgen sein sollte, und suchte ihn von seinen Gelübden abzuziehen.", "patron": "Angerufen um die Losgelöstheit vom Reichtum; wider die Habsucht."},

"Holy, Glorious Apostle Thomas":
{"type": "Apostel · 1. Jh.", "life": "Heiliger ruhmreicher Apostel Thomas, der Zwilling genannt, war ein galiläischer Fischer, den der Herr in die Schar der Zwölf rief, und das Evangelium zeigt sein glühendes Herz, denn als der Herr nach Judäa zog, um Lazaros zu erwecken, war es Thomas, der sprach: Lasset auch uns gehen, dass wir mit ihm sterben.", "patron": "Angerufen von Bauleuten; von Baumeistern."},

"Venerable Isaac the Ascetic of the Dalmatian Monastery at Constantinople":
{"type": "Abt (Igumen) · 4. Jh.", "life": "Ehrwürdiger Isaakios war ein Einsiedler der östlichen Wildnis und lebte im vierten Jahrhundert unter dem arianischen Kaiser Valens. Als er hörte, dass Valens die Orthodoxen verfolgte, ihre Bischöfe vertrieb und ihre Kirchen den Häretikern übergab, verliess er seine Einsamkeit und kam nach Konstantinopel, um dem Kaiser entgegenzutreten, der eben in den Krieg gegen die Goten zog.", "patron": "Angerufen von Mönchen; um die Verteidigung der Orthodoxie wider die Häresie."},

"Hieromartyr Hierotheus, Bishop of Athens":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Hieromärtyrer Hierotheos, Bischof von Athen, war ein Glied des Areopags und wurde zusammen mit Dionysios dem Areopagiten durch die Predigt des heiligen Apostels Paulos zu Christus geführt, der ihn zum ersten Bischof von Athen weihte; und er wiederum unterwies Dionysios vollkommener in den Geheimnissen des Glaubens, sodass sein Jünger ihn Lehrer nennt und von seinen Hymnen und Bestimmungen spricht.", "patron": "Angerufen von Theologen; von Hymnendichtern."},

"Saint Hypatius of Gangra":
{"type": "Bischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Hypatios, Bischof von Gangra in Paphlagonien, war einer der Väter des Ersten Ökumenischen Konzils zu Nikaia im Jahre 325, auf dem die Häresie des Areios verworfen wurde und die Kirche den Sohn Gottes als dem Vater wesensgleich bekannte. Als Wundertäter war er in der ganzen Gegend berühmt, weil er Dämonen austrieb und Kranke heilte.", "patron": "Angerufen um die Befreiung von Dämonen; um Heilung."},

"Martyr Callistratus and 49 companions":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Kallistratos wurde zu Karthago einer christlichen Familie geboren; sein Vorfahr Neochoros, ein Soldat in Palästina unter Pontius Pilatus, hatte die Kreuzigung und die Auferstehung des Herrn geschaut und war als Gläubiger heimgekehrt, und der Glaube wurde in seinem Hause weitergegeben. Kallistratos selbst wurde Soldat, übertraf alle an Sanftmut des Wandels und stand nachts zum Gebete auf.", "patron": "Angerufen von Soldaten; von Kriegsleuten."},

"Apostle and Evangelist Luke":
{"type": "Apostel · 1. Jh.", "life": "Heiliger Apostel und Evangelist Lukas stammte aus Antiochien, war Arzt seiner Kunst nach und auch in der Malerei bewandert; und da er zum Herrn kam, wurde er zu den Siebzig gezählt und vor seinem Angesicht ausgesandt. Er war einer der beiden Jünger, denen der auferstandene Christus auf dem Wege nach Emmaus erschien, als ihre Herzen in ihnen brannten, während er ihnen die Schriften auftat.", "patron": "Angerufen von Ärzten; von Ikonenmalern."},

"Holy Prophet Zachariah and Righteous Elizabeth, parents of Saint John the Baptist":
{"type": "Prophet · 1. Jh.", "life": "Heiliger Prophet Zacharias und die gerechte Elisabeth waren die Eltern des heiligen Johannes, des Vorläufers und Täufers des Herrn. Beide stammten aus dem Geschlechte Aarons, Zacharias diente als Priester im Tempel zu Jerusalem und Elisabeth war eine Verwandte der Allheiligen Gottesmutter; und wie das Evangelium bezeugt, wandelten sie untadelig in allen Geboten des Herrn und waren doch kinderlos alt geworden.", "patron": "Angerufen von Priestern; von kinderlosen Eheleuten."},

"Venerable John Cassian the Roman":
{"type": "Abt, Priester · 5. Jh.", "life": "Ehrwürdiger Johannes Cassianus der Römer ist der grosse Bote der Wüste, der Mann, der die Weisheit Ägyptens in zwei Bücher packte und sie ins Abendland trug, und die Kirche gibt ihm das seltenste Fest ihres Kalenders, den neunundzwanzigsten Februar, als wollte sie bezeichnen, dass solche Männer nur selten kommen.", "patron": "Angerufen von Mönchen des Abendlandes; von Schriftstellern über das Gebet."},

"Saint Alexei, Metropolitan of Moscow, Wonderworker of All Russia":
{"type": "Metropolit · 14. Jh.", "life": "Heiliger Alexij, Metropolit von Moskau und ganz Russland, der Wundertäter, wurde um das Jahr 1300 als Jelewferij dem Bojarengeschlecht der Bjakont geboren, und Gott redete ihn in der Knabenzeit durch sein eigenes Spiel an: als er mit zwölf Jahren über seinen Vogelnetzen einschlief, hörte er eine Stimme sprechen: Alexij, was mühst du dich vergebens? Ich werde dich zum Menschenfischer machen.", "patron": "Angerufen von Hierarchen; von Staatsmännern."},

"Martyrs Florus and Laurus of Illyria":
{"type": "Märtyrer · 2. Jh.", "life": "Heilige Märtyrer Floros und Lauros waren Zwillingsbrüder, verwandt nicht nur dem Fleische, sondern auch dem Geiste nach; sie lebten im zweiten Jahrhundert und liessen sich in Illyrien nieder, wo sie als Steinmetzen arbeiteten. Von ihren christlichen Meistern Proklos und Maximos hatten sie sowohl ihr Handwerk als auch die Gott wohlgefällige Lebensweise gelernt.", "patron": "Angerufen von Steinmetzen; für Pferde und Reiter."},

"Hieromartyr Lucian the Presbyter of the Kyiv Caves":
{"type": "Hieromärtyrer · 13. Jh.", "life": "Heiliger Hieromärtyrer Lukian, Presbyter der Kiewer Höhlen, diente Gott als Priestermönch der grossen Lawra in den furchtbarsten Jahren, die seine Stadt je erlebte, als die Horden Batus über die Rus hereinbrachen und Kiew, die Mutter ihrer Städte, dem Feuer und dem Gemetzel übergeben wurde. In jener Verwüstung, um das Jahr 1243, empfing der Priester Lukian den Kranz des Martyriums, von den Gottlosen erschlagen, während er auf seinem Posten blieb.", "patron": "Angerufen um die Treue bis aufs Blut."},

"Venerable Nikon, Abbot of Radonezh, disciple of Venerable Sergius":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Nikon von Radonesch, der Jünger und Nachfolger des heiligen Sergij, wurde zu Jurjew-Polski geboren und kam in der Jugend zum grossen Ältesten, der seine Demut prüfte und ihn zuerst zu seinem Jünger Afanassij nach Serpuchow sandte; dort wurde Nikon eingekleidet und geweiht und kehrte zuletzt zu Sergij zurück, der ihn so liebte, dass er ihn in seiner eigenen Zelle behielt.", "patron": "Angerufen von Äbten; von Erbauern."},

"Synaxis of the Archangel Gabriel":
{"type": "Erzengel", "life": "Dieses Fest ist ein zweites feierliches Gedächtnis des heiligen Erzengels Gabriel, eines der Ersten unter den körperlosen Mächten, der vor dem Throne Gottes steht und als Bote seiner heilbringenden Ratschlüsse zu den Menschen gesandt wird. Gabriel war es, der gesandt wurde, der allheiligen Jungfrau Maria die frohe Botschaft der Menschwerdung des Sohnes Gottes zu verkünden.", "patron": "Angerufen von Boten; um gute Nachricht."},

"Martyrs and Passion-Bearers Boris and Gleb":
{"type": "Fürsten · 11. Jh.", "life": "Heilige Boris und Gleb, in der heiligen Taufe Roman und David genannt, waren jüngere Söhne des heiligen Wolodymyr, des Täufers der Rus, und die ersten Heiligen, die im russischen Lande verherrlicht wurden. Nach dem Tode ihres Vaters im Jahre 1015 riss ihr älterer Bruder Swjatopolk den Thron von Kiew an sich und beschloss, seine Brüder zu vernichten, um ohne Nebenbuhler zu herrschen.", "patron": "Angerufen um den Verzicht auf Widerstand gegen das Böse; um die brüderliche Liebe."},

"Venerable Silvanus the Schemamonk of the Kyiv Far Caves":
{"type": "Schemamönch · 14. Jh.", "life": "Ehrwürdiger Silwan war ein Schemamönch der Kiewer Höhlen und lebte am Ende des dreizehnten und zu Beginn des vierzehnten Jahrhunderts. Er hütete eifrig die Reinheit der Seele und des Leibes, bezwang sein Fleisch durch Fasten und Vigil und reinigte seinen Sinn durch unablässiges Gebet und das Gedenken Gottes, und dafür schenkte ihm der Herr reiche geistliche Gaben.", "patron": "Angerufen um die Reinheit der Seele und des Leibes."},

"Venerable Melania the Younger of Rome":
{"type": "Nonne · 5. Jh.", "life": "Ehrwürdige Melania die Jüngere aus Rom wurde in den höchsten Adel des Reiches geboren, als Erbin der Valerier, Herrin von Gütern in Italien, Sizilien, Spanien, Afrika und Britannien, vielleicht die reichste Privatperson ihrer Zeit.", "patron": "Angerufen von Erbinnen; von Stifterinnen der Klöster."},

"Afterfeast of the Meeting of our Lord in the Temple":
{"type": "Nachfest", "life": "Das Nachfest der Begegnung des Herrn im Tempel trägt das Fest des zweiten Februar durch die folgenden Tage bis zum Abschluss am neunten, und in ihnen bleibt die Kirche mit dem Kinde auf den Armen im Tempel stehen; denn die Begegnung ist das Gelenk, an dem der ganze Kreis der Geburt sich schliesst, die Erfüllung des Gesetzes am vierzigsten Tage.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Saint Arsenius, Bishop of Tver":
{"type": "Bischof · 15. Jh.", "life": "Heiliger Arsenij, Bischof von Twer, wurde in der Kiewer Höhlenlawra zum Mönche geformt, dem Mutterhause des russischen Mönchtums, und trug ihre Überlieferung nach Norden in beiden Gestalten, die dauern, in Stein und in Tinte. In den Dienst des Metropoliten Kiprian genommen, wurde er 1390 für den Stuhl von Twer geweiht, in einem Augenblick, da jenes Fürstentum sich in den Fehden seiner Fürsten zerriss.", "patron": "Angerufen von Friedensstiftern; von Hierarchen."},

"Forefeast of the Meeting of our Lord in the Temple":
{"type": "Vorfest", "life": "Das Vorfest der Begegnung des Herrn im Tempel wird am ersten Februar begangen, ein einziger Tag der Bereitung vor dem Feste, das den ganzen Kreis der Geburt des Herrn beschliesst; und in ihm wendet die Kirche ihre Augen zum Tempel von Jerusalem, wohin morgen der Gesetzgeber als vierzig Tage altes Kind getragen wird, um sein eigenes Gesetz zu erfüllen.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Victor at Damascus":
{"type": "Märtyrer · 2. Jh.", "life": "Heiliger Märtyrer Viktor war ein Soldat aus Italien und diente unter Mark Aurel zu Damaskus; und als die Verfolgung vom Heere das Opfer forderte, erklärte er sich als Christ und weigerte sich. Der Befehlshaber übergab ihn Qualen von aussergewöhnlicher Grausamkeit: man brach und verrenkte ihm die Finger und warf ihn in einen glühenden Ofen.", "patron": "Angerufen von Soldaten; um das Ausharren über die Natur hinaus."},

"Venerable Gregory the Iconographer of the Kyiv Near Caves":
{"type": "Mönch · 12. Jh.", "life": "Ehrwürdiger Grigorij der Ikonenmaler war ein Mönch der Kiewer Höhlen und ein Gefährte des heiligen Alipij, des ersten Ikonenmalers des russischen Landes. In den Berichten über die heiligen Ikonenmaler steht geschrieben, dass er viele wundertätige Ikonen in der ganzen Rus malte, und die Gesänge des Klosters nennen ihn einen Byzantiner, was darauf deutet, dass er unter den Meistern war, die aus Konstantinopel kamen.", "patron": "Angerufen von Ikonenmalern; um die heilige Ikonenmalerei."},

"Translation of the relics of Saint Peter, Metropolitan of Moscow and All Russia":
{"type": "Metropolit · 14. Jh.", "life": "Übertragung der Reliquien des heiligen Pjotr, Metropoliten von Moskau und ganz Russland, des ersten Vorstehers der russischen Kirche, der seinen Sitz in Moskau nahm und damit den Aufstieg jener Stadt segnete, die unter seinen Nachfolgern das Herz des russischen Landes wurde. Ein Hirte von grosser Heiligkeit und Weisheit, stärkte er den Glauben seiner Herde in einer harten Zeit der Spaltung und der Tatarenherrschaft.", "patron": "Angerufen für Moskau; um die Einheit der Kirche."},

"Monastic Martyr Macarius of Dionysiou, Mount Athos":
{"type": "Hieromonach · 16. Jh.", "life": "Ehrwürdiger Mönchsmärtyrer Makarios war ein Mönch des Klosters Dionysiou auf dem Athos und ein Jünger des heiligen Patriarchen Niphon von Konstantinopel, der sich in seinen Jahren des Rückzugs in jenem Kloster mühte; von seinem Ältesten lernte Makarios den Gehorsam, das Gebet und die brennende Liebe zu Christus. Von der Sehnsucht verzehrt, seinen Herrn unter denen zu bezeugen, die ihn leugneten, empfing er den Segen des heiligen Niphon.", "patron": "Angerufen von Predigern; um die freimütige Verkündigung."},

"Venerable Alexander, Abbot of Svir":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Alexander von Swir wurde im Jahre 1448 in einem Dorfe des russischen Nordens geboren und in der Taufe Amos genannt, nach dem Propheten, an dessen Feste er zur Welt kam. Von Jugend an zum Mönchsleben gezogen, ging er heimlich nach Walaam, wo er eingekleidet wurde, und zog sich nach einigen Jahren in die tiefen Wälder am Flusse Swir zurück, um in Stille und Gebet zu leben.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Martyr Romulus and with him many others":
{"type": "Märtyrer · 2. Jh.", "life": "Heiliger Märtyrer Romulus lebte unter Kaiser Trajan und bekleidete ein hohes Amt am kaiserlichen Hofe. Als der Kaiser, der im Osten Krieg führte, die Christen in seinen Heeren zählen liess, fand man elftausend, und er gebot, sie alle ihres Ranges zu entkleiden und nach Armenien zu verbannen.", "patron": "Angerufen von Soldaten; von Kriegsleuten."},

"Venerable Herodion, Abbot of Iloezersk":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Irodion von Iloosero war ein Jünger des heiligen Kornilij von Komel, in dessen Kloster er eingekleidet und in den asketischen Überlieferungen der Wologdaer Wildnis geschult wurde. Nach dem Entschlafen seines Ältesten zog er sich, die Stille suchend, in die Wälder des Beloosero-Landes zurück und liess sich am kleinen See Ilo nieder, wo er sich eine Zelle und eine Kapelle zu Ehren der Geburt der Allheiligen Gottesmutter baute.", "patron": "Angerufen von Einsiedlern; um die Stille."},

"Venerable Moses the Hungarian of the Kyiv Near Caves":
{"type": "Mönch · 11. Jh.", "life": "Ehrwürdiger Moissej der Ungar, ein Ungar von Geburt und Bruder des heiligen Jefrem von Nowy Torg, trat mit seinen Brüdern in den Dienst des heiligen Fürsten Boris des Leidensdulders. Als Boris im Jahre 1015 an der Alta ermordet wurde und einer der Brüder mit ihm fiel, floh Moissej und fand in Kiew Zuflucht.", "patron": "Angerufen um die Keuschheit; von denen, die von der Wollust versucht werden."},

"Martyrs Eudoxius, Zeno, and Macarius":
{"type": "Heerführer · 4. Jh.", "life": "Heilige Märtyrer Eudoxios, Zenon und Makarios litten unter Maximian Galerius, dem Nachfolger Diokletians. Eudoxios war ein hoher Befehlshaber der kaiserlichen Heere und ein Christ, wie auch sein Freund Zenon und sein Verwalter Makarios; und als der Erlass wider die Gläubigen erging, zog er sich mit seiner Familie zurück, wurde aber von Soldaten gesucht, die ihn nicht erkannten und seine Gastfreundschaft genossen.", "patron": "Angerufen von Soldaten; von Kriegsleuten."},

"Repose of Saint Peter, Metropolitan of Moscow, Wonderworker of All Russia":
{"type": "Metropolit · 14. Jh.", "life": "Entschlafen des heiligen Pjotr, Metropoliten von Kiew und ganz der Rus, des Wundertäters von Moskau, der in Wolhynien geboren und mit zwölf Jahren einem Kloster übergeben wurde, wo er neben Gehorsam und Gebet die Kunst der Ikone erlernte und Bilder des Erlösers und der Gottesmutter malte, deren eines, die Petrowskaja, bis heute verehrt wird.", "patron": "Angerufen von Hierarchen; von Ikonenmalern."},

"Saint Sophronius, Archbishop of Cyprus":
{"type": "Erzbischof · 6. Jh.", "life": "Heiliger Sophronios, Erzbischof von Zypern, wurde auf jener Insel der Heiligen geboren und leuchtete von Jugend an in dem doppelten Schmucke, den seine Herde später preisen sollte: tiefer Kenntnis der göttlichen Schriften und einem Herzen, das ganz der Barmherzigkeit gehörte. Nach dem Entschlafen seines Vorgängers wurde er durch die Liebe des Volkes auf den erzbischöflichen Thron von Zypern erhoben.", "patron": "Angerufen von Waisen; von den Armen."},

"Martyr Potitus at Naples":
{"type": "Laie · 2. Jh.", "life": "Heiliger Märtyrer Potitos litt im zweiten Jahrhundert unter Kaiser Antoninus Pius. Als Knabe lernte er den christlichen Glauben kennen und wurde mit dreizehn Jahren getauft; und als sein heidnischer Vater ihn erst mit Zureden und dann mit Drohungen von Christus abzubringen suchte, wurde der Vater selbst durch die Standhaftigkeit seines Sohnes gewonnen und wurde Christ.", "patron": "Angerufen von Kranken; um die Befreiung von Dämonen."},

"Saint Clement of Ochrid, Equal of the Apostles, Bishop of Greater Macedonia, and his companions Nahum, Savva, Gorazd and Angelar":
{"type": "Bischof · 10. Jh.", "life": "Heilige Kliment, Naum, Sawa, Gorazd und Angelar waren Slawen und Jünger der heiligen apostelgleichen Kyrillos und Methodios und werden mit ihren Lehrern als Erleuchter der slawischen Völker geehrt. Zuerst mühten sie sich in Mähren, wo sie in slawischer Sprache verkündeten und die Gottesdienste feierten und dabei die von Kyrillos ersonnenen Buchstaben gebrauchten, und Gorazd folgte dem heiligen Methodios nach.", "patron": "Angerufen von Lehrern; von Übersetzern."},

"Venerable Athanasius the Recluse of the Kyiv Caves":
{"type": "Mönch · 13. Jh.", "life": "Ehrwürdiger Afanassij, Klausner der Fernen Höhlen, mühte sich im dreizehnten Jahrhundert in der Kiewer Höhlenlawra und nahm die härteste der Zuchten der Höhlen auf sich, das verschlossene Leben des Klausners, in dem der Mönch sich mit Gott allein in die Finsternis unter der Erde einmauert.", "patron": "Angerufen um das Licht in der Finsternis der Zelle; um die Heilung der Kranken."},

"Martyr Stephanida of Damascus":
{"type": "Märtyrerin · 2. Jh.", "life": "Heilige Märtyrerin Stephanida litt im zweiten Jahrhundert zu Damaskus in der Verfolgung unter Mark Aurel. Eine junge Christin spanischer Herkunft und die Frau eines Soldaten, stand sie unter den Zuschauern bei der Folterung des heiligen Märtyrers Viktor; und da sie die Gnade Gottes sah, die ihn hielt, schaute sie, wie der Bericht erzählt, zwei Kränze vom Himmel herabkommen, einen für Viktor und einen für sie selbst.", "patron": "Angerufen von jungen Ehefrauen; um das Zeugnis, das ein Zeugnis entzündet."},

"Venerable Daniel the Confessor (in Schema Stephen) of Spain, and Egypt":
{"type": "Mönch und Märtyrer · 10. Jh.", "life": "Ehrwürdiger Daniel der Bekenner, im grossen Schema Stephan, lebte im zehnten Jahrhundert, ein Würdenträger Spaniens und Statthalter der Insel Niverta, ein Mann, der die Ehren in Händen hielt, denen die meisten ihr Leben lang nachjagen; und da er den weltlichen Ruhm verachtete, legte er sein Amt und sein Land zugleich nieder und wurde zu Rom Mönch.", "patron": "Angerufen von Beamten, die ihr Amt niederlegen; von Pilgern."},

"Uncovering of the relics of Saint Joasaph, Bishop of Belgorod":
{"type": "Bischof · 18. Jh.", "life": "Auffindung der Reliquien des heiligen Joasaph, Bischofs von Belgorod, der 1705 zu Priluki im Poltawaer Lande am Feste der Geburt der Gottesmutter aus dem vornehmen ukrainischen Geschlecht der Gorlenko geboren und in der Taufe Joachim genannt wurde. An der Kiewer Geistlichen Akademie gebildet, wurde er früh zum Mönchsleben gezogen, mit dem Namen Joasaph eingekleidet und darauf Abt des Mgarsker Klosters.", "patron": "Angerufen um die Strenge des Lebens; um die Sorge für den Klerus."},

"Conception of the Most Holy Theotokos by Saint Anna":
{"type": "Fest", "life": "Dieses Fest feiert die Empfängnis der Jungfrau Maria durch ihre Mutter, die gerechte Anna, neun Monate vor dem Feste der Geburt Marias am achten September. Nach der Überlieferung der Kirche waren Joachim und Anna gerecht, aber kinderlos und hochbetagt, und ihre Kinderlosigkeit galt als Schmach.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Marinus the Elder at Anazarbus":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Marinos der Ältere litt unter Diokletian für Christus zu Anazarbos in Kilikien und war schon hochbetagt, als die Verfolgung ihn ereilte. Vor den Statthalter Lysias geführt, wurde dem Greise geraten, sein graues Haar zu schonen und zu opfern; er aber antwortete, die Länge seiner Tage habe ihn nur in der Erkenntnis des wahren Gottes bestärkt.", "patron": "Angerufen von Betagten; um den Mut im Alter."},

"Prophet Nahum":
{"type": "Prophet · 7. Jh. v. Chr.", "life": "Heiliger Prophet Nahum, dessen Name Gott tröstet bedeutet, stammte aus dem Dorfe Elkosch in Galiläa und weissagte im siebten Jahrhundert vor Christus als der siebte in der Reihe der zwölf kleinen Propheten. Sein kurzes Buch ist ein einziger brennender Spruch wider Ninive, die Hauptstadt Assyriens, die Israel zerschlagen und die zehn Stämme weggeführt hatte.", "patron": "Angerufen um den Trost der Bedrängten; von denen, die an der Seele leiden."},

"The Nativity of our Most Holy Lady the Mother of God and Ever-Virgin Mary":
{"type": "Grosses Fest", "life": "Die Geburt der Gottesmutter feiert die Geburt der Jungfrau Maria aus den gerechten Joachim und Anna, einem betagten und kinderlosen Paare aus dem königlichen Geschlechte Davids, das lange um ein Kind gebetet und die Schmach der Unfruchtbarkeit getragen hatte. Auf ihr Gebet hin verkündete ein Engel einem jeden von ihnen, dass sie ein Kind haben würden.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Saint Alexander of Guria":
{"type": "Bischof · 20. Jh.", "life": "Heiliger Hierarch Alexander von Gurien, in der Welt Alexi Okropiridse, wurde 1824 im Dorfe Disewi im Bezirk Gori als Sohn des Dorfpriesters geboren und wurde nach dem Seminar zu Tiflis Mönch und schloss sein Studium an der Geistlichen Akademie zu Kasan mit Auszeichnung ab.", "patron": "Angerufen von Lehrern; von Erziehern."},

"Venerable Titus the Presbyter of the Kyiv Near Caves":
{"type": "Hieromonach · 12. Jh.", "life": "Ehrwürdiger Tit der Presbyter aus den Kiewer Nahen Höhlen ist das eigene Gleichnis der Höhlen von der Vergebung, und das Paterikon erzählt seine Geschichte wie ein Gerichtsprotokoll des Urteils Gottes. Tit, ein Priester des Klosters, und Ewagrij, ein Diakon, waren einander so nahe befreundet, dass die Brüder ihre Liebe für ein Vorbild hielten.", "patron": "Angerufen von Entzweiten; von Priestern im Streit."},

"Martyr Peter the Aleut":
{"type": "Märtyrer · 19. Jh.", "life": "Heiliger Märtyrer Pjotr der Aleute war ein junger Ureinwohner der Gegend von Kodiak in Alaska, von den russischen Glaubensboten in den orthodoxen Glauben getauft und mit seinen Landsleuten bei den Jagdzügen der Kolonie beschäftigt. Im Jahre 1815 wurde er mit anderen Aleuten von spanischen Soldaten in Kalifornien gefangen, und dort drängte man die Gefangenen, die Orthodoxie für den lateinischen Glauben zu verlassen.", "patron": "Angerufen von Jägern; von den Ureinwohnern."},

"Blessed Nicholas (Salos) of Pskov the Fool-For-Christ":
{"type": "Narr in Christo · 16. Jh.", "life": "Seliger Nikolaj Salos von Pskow, den die Stadt Mikula den Narren nannte, trug die Mühe der Torheit um Christi willen mehr als drei Jahrzehnte, schlief auf den Vorhallen, ertrug Frost und Spott in Lumpen, redete in Rätseln, die sich erfüllten, und erlangte lange vor seinem Entschlafen die Gnade des Wunderwirkens und der Weissagung.", "patron": "Angerufen von Narren in Christo; von denen, die den Mächtigen die Wahrheit sagen."},

"Martyr Bassa of Edessa and her sons Theogonius, Agapius, and Pistus":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrerin Bassa lebte in der Stadt Edessa in Makedonien und war mit einem heidnischen Priester verheiratet, obgleich sie selbst von Kindheit an im christlichen Glauben erzogen war, den sie auch ihre drei Söhne Theognis, Agapios und Pistos lehrte. In der Verfolgung unter Maximian zeigte ihr eigener Mann sie und die Kinder an.", "patron": "Angerufen von Müttern; um die Mutterschaft."},

"Venerable Constantine of Synnada":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Konstantinos von Synnada wurde im neunten Jahrhundert in jener phrygischen Stadt jüdischen Eltern geboren, und die Gnade fand ihn durch die kleinste aller Türen. Da er unter Christen lebte, beobachtete der Jüngling, wie sie sich mit dem Zeichen des Kreuzes bezeichneten, und begann, halb aus Nachahmung, das Zeichen an sich selbst zu machen.", "patron": "Angerufen von Bekehrten aus dem Judentum; von Katechumenen."},

"Synaxis of the Hierarchs of Moscow":
{"type": "Synaxis", "life": "Synaxis der Hierarchen von Moskau, der heiligen Erzhirten der russischen Kirche, die auch jeder an seinem eigenen Tage geehrt werden: Pjotr, der den Metropolitensitz nach Moskau verlegte und dessen Grösse voraussagte; Alexij, der Hüter des Reiches in den Tagen der Horde; und die anderen nach ihnen.", "patron": "Angerufen für die russische Kirche; um die rechte Leitung der Kirche."},

"Venerable Lazarus, Wonderworker of Mount Galesius Near Ephesus":
{"type": "Hieromonach · 11. Jh.", "life": "Ehrwürdiger Lazaros der Wundertäter vom Berge Galesion wurde in Lydien in Kleinasien geboren und zog in der Jugend ins Heilige Land, wo er sich zehn Jahre in der Lawra des heiligen Sabbas mühte und vom Patriarchen von Jerusalem zum Priester geweiht wurde. In seine Heimat zurückgekehrt, liess er sich auf dem öden Berge Galesion bei Ephesos nieder.", "patron": "Angerufen von Säulenstehern; von Mönchen."},

"Venerable Martyrius the Deacon, Recluse of the Kyiv Caves":
{"type": "Diakon · 14. Jh.", "life": "Ehrwürdiger Martirij der Diakon mühte sich im vierzehnten Jahrhundert im Kiewer Höhlenkloster, diente bei den göttlichen Gottesdiensten im Range des Diakons und schmückte seinen Dienst mit Fasten, Reinheit und unablässigem Gebet. Solcher Freimut vor Gott wurde ihm gegeben, dass, wie die Überlieferung der Lawra festhält, der Herr ihm alles rasch gewährte, worum er auf dem Ambon betete.", "patron": "Angerufen von Diakonen; um das Gebet, das Gott erhört."},

"Repose of Saint Jonah, Archbishop of Novgorod":
{"type": "Erzbischof · 15. Jh.", "life": "Entschlafen des heiligen Iona, Erzbischofs von Nowgorod, der in der Welt Iwan hiess, als Kind verwaiste und von einer frommen Witwe zu Nowgorod aufgezogen wurde; und einmal, als der Knabe unter seinen Gefährten stand, ging der selige Michail von Klopsk, der Narr in Christo, vorüber, verneigte sich vor dem Kinde und sprach: Iwan, lerne fleissig dein Buch, denn du wirst Erzbischof von Gross Nowgorod sein.", "patron": "Angerufen von Waisen; von Hierarchen."},

"Uncovering of the relics of Holy Princess Juliana Olshanskaya":
{"type": "Fürstin · 16. Jh.", "life": "Auffindung der Reliquien der heiligen Julianija Olschanskaja, der Tochter des Fürsten Juri Dubrowizkij-Olschanskij, dessen Geschlecht über Olschansk herrschte, als Kiew unter dem litauischen Reiche lag. Ihr Vater, ein Wohltäter der Kiewer Höhlenlawra, bestattete sie bei der grossen Kirche des Klosters, als sie im sechzehnten Jahrhundert mit sechzehn Jahren als reine Jungfrau entschlief.", "patron": "Angerufen von Frauen; um die Heilung der Seele."},

"Saint Sergius of Malopinega":
{"type": "Priester · 16. Jh.", "life": "Heiliger Sergij von Malopinega, in der Welt Semjon, wurde 1493 als Sohn des Markian Nekljud aus dem Adel von Gross Nowgorod geboren, dessen Geschlecht in den fernen Norden zum eisigen Meer zog, als die Freiheit ihrer Stadt zu Ende ging. Mit dreissig Jahren zum Presbyter geweiht, diente er zweiunddreissig Jahre den Kirchen der Verklärung des Herrn und des Grossmärtyrers Georgios.", "patron": "Angerufen von Gemeindepriestern; von Glaubensboten."},

"Great Martyr Anastasia the Deliverer from Poisons, her teacher, Martyr Chrysogonos, and many with them":
{"type": "Grossmärtyrerin · 4. Jh.", "life": "Heilige Grossmärtyrerin Anastasia, die Befreierin von Giften, war eine Römerin vornehmer Geburt, Tochter eines heidnischen Vaters und einer heimlich christlichen Mutter, Fausta, und wurde von ihrem Lehrer, dem weisen Bekenner Chrysogonos, im Glauben geformt. Wider ihr Herz dem Heiden Publius vermählt, bewahrte sie ihre Jungfräulichkeit, indem sie Krankheit vorgab, und ging in Bettlerkleidern mit einer einzigen Dienerin durch die Kerker.", "patron": "Angerufen von Krankenpflegern; von Ärzten."},

"Venerable Arsenius, Abbot of Komel, Vologda":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Arsenij von Komel wurde zu Moskau einem vornehmen Hause geboren und in der Jugend im Dreifaltigkeitskloster des heiligen Sergij eingekleidet, wo er sich dem Abschreiben heiliger Bücher widmete, deren eines, ein von seiner Hand geschriebenes Evangelium, bis heute bewahrt wird.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Holy Wonderworkers and Unmercenaries Cyrus and John, and those with them":
{"type": "Uneigennützige Märtyrer · 4. Jh.", "life": "Heilige Wundertäter und Uneigennützige Kyros und Johannes litten im Jahre 311 zu Kanopos in Ägypten, und die Kirche stellt sie neben Kosmas und Damianos unter die Ärzte, die keinen Lohn nahmen. Kyros war ein Arzt aus Alexandreia, in ganz Ägypten berühmt für eine Kunst, die zweifach heilte, denn er behandelte den Leib ohne Bezahlung und gebrauchte das Krankenbett, um die Seele zu behandeln.", "patron": "Angerufen von Ärzten; von Krankenpflegern."},

"Saint Meletius, Archbishop of Antioch":
{"type": "Erzbischof · 4. Jh.", "life": "Heiliger Meletios, Erzbischof von Antiochien, wurde zu Melitene in Armenien einem vornehmen Hause geboren und kam 360 mit Zustimmung der Arianer auf den Thron von Antiochien, die seine Milde für ihre eigene Lehre hielten; seine erste Predigt aber täuschte sie nicht länger, denn der neue Erzbischof verkündete den Sohn als dem Vater wesensgleich, und binnen eines Monats erwirkte die Partei, die ihn eingesetzt hatte, seine Verbannung.", "patron": "Angerufen von Bischöfen geteilter Herden; von Friedensstiftern."},

"Greatmartyr Artemius at Antioch":
{"type": "Grossmärtyrer · 4. Jh.", "life": "Heiliger Grossmärtyrer Artemios von Antiochien war ein angesehener Heerführer unter dem heiligen Konstantin dem Grossen und dessen Sohn Constantius, um Tapferkeit und Dienst geehrt und zum kaiserlichen Statthalter Ägyptens gemacht, wo er viel für die Ausbreitung des Glaubens tat; und ihn sandte der Kaiser, die Reliquien des Apostels Andreas aus Patras und des Apostels Lukas aus dem boiotischen Theben nach Konstantinopel zu bringen.", "patron": "Angerufen von Soldaten; von Beamten."},

"Hieromartyr Antherus (Antheros) Pope of Rome":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Antheros, ein Grieche von Geburt, wurde in der Nachfolge des heiligen Pontianus zum Bischof von Rom erwählt, hielt den Stuhl aber nur kurze Zeit, denn er bekannte bald Christus und erlitt im Jahre 236 um des Glaubens willen den Tod. Er wurde in der Katakombe des heiligen Kallistos beigesetzt, als erster der Bischöfe von Rom an jenem geweihten Orte.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Translation of the relics of Saint Hilarion, Bishop of Meglin in Bulgaria":
{"type": "Bischof · 12. Jh.", "life": "Übertragung der Reliquien des heiligen Ilarion, Bischofs von Meglin, im Jahre 1206, als der bulgarische Zar Kalojan die heiligen Schätze des Landes sammelte und die wundertätigen Reliquien des Hierarchen in seine Hauptstadt Tarnowo bringen liess.", "patron": "Angerufen von Verteidigern des Glaubens; um die Verteidigung der Orthodoxie wider die Häresie."},

"Martyr Tryphon of Lampsacus Near Apamea in Syria":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Tryphon wurde im Dorfe Kampsada bei Apameia in Phrygien geboren, ein Bauernknabe, der Gänse hütete; und über diesen am wenigsten beglaubigten der Heiler der Kirche goss der Herr von frühen Jahren an die Kraft aus, Dämonen auszutreiben und jede Krankheit zu heilen. Seine Wunder hatten das Mass seiner Liebe: er rettete seine Heimat vor dem Hunger, indem er durch Gebet eine Heuschreckenplage abwandte.", "patron": "Angerufen von Gärtnern; von Bauern."},

"Saint Stephen the “New Light” of Constantinople":
{"type": "Priester · 10. Jh.", "life": "Heiliger Stephanos von Konstantinopel, das Neue Licht genannt, diente im neunten und zehnten Jahrhundert unter dem Klerus der Grossen Kirche der Hagia Sophia und entzündete mitten im Glanze der Welt das ältere, härtere Licht der Asketen. Er entsagte der Bequemlichkeit, ohne die Stadt zu verlassen, und nahm ein eingeschlossenes Leben von aussergewöhnlicher Strenge auf sich, in einer engen Zelle.", "patron": "Angerufen von Klerikern grosser Kirchen; um die spät leuchtende Heiligkeit."},

"Hieromartyr Peter, Archbishop of Alexandria":
{"type": "Patriarch · 4. Jh.", "life": "Heiliger Hieromärtyrer Petros, Erzbischof von Alexandreia, wurde an der grossen Katechetenschule jener Stadt erzogen, deren Vorsteher er wurde, und bestieg im Jahre 300 den Patriarchenthron, nur um seine Kirche geradewegs in die Feuer der letzten und härtesten Verfolgung zu führen. Von Ort zu Ort gehetzt, leitete er seine zerstreute Herde durch Boten und Briefe und stärkte die Bekenner.", "patron": "Angerufen von Katecheten; von Hierarchen."},

"Venerable Nilus of Stolbensk Lake":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Nil von Stolbensk, einer der strengsten Asketen des russischen Nordens, wurde im Nowgoroder Lande geboren und im Krypezker Kloster des heiligen Sawwa bei Pskow eingekleidet; und nach der Einsamkeit brennend, lebte er dreizehn Jahre als Einsiedler im Walde am Flusse Seremlja, in Fasten, Gebet und im Kampfe mit den Dämonen und mit Räubern, die er, wie die Berichte erzählen, allein durch sein Gebet vertrieb.", "patron": "Angerufen von Einsiedlern; um die Wachsamkeit bis zum Tode."},

"Monastic Martyr and Confessor Stephen the New":
{"type": "Mönch · 8. Jh.", "life": "Ehrwürdiger Mönchsmärtyrer und Bekenner Stephanos der Neue, der grosse Streiter für die heiligen Ikonen, wurde 715 zu Konstantinopel frommen Eltern geboren, die bei zwei Töchtern den Herrn um einen Sohn gebeten hatten; und seine Mutter trug das Kind, als sie es empfangen hatte, in die Blachernenkirche der Allheiligen Gottesmutter und weihte es Gott vor ihrer Ikone.", "patron": "Angerufen von Mönchen; von Verteidigern der Ikonen."},

"Martyrs Theodotus and Rufina of Caesarea, in Cappadocia":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Theodotos und Rufina, die Eltern des Grossmärtyrers Mamas, stammten aus patrizischen Häusern und wurden von allen um ihrer christlichen Frömmigkeit willen geehrt. Als der Beamte von Gangra sie vorlud, weil sie die Götzen nicht nach dem kaiserlichen Erlass anbeten wollten, weigerte sich Theodotos, und da sein vornehmer Rang dem Beamten die Strafe verbot, sandte man ihn zum Statthalter Faustus nach Kaisareia.", "patron": "Angerufen von Eheleuten; um standhaftes Bekenntnis."},

"Repose of Saint Herman, Archbishop of Kazan":
{"type": "Erzbischof · 16. Jh.", "life": "Entschlafen des heiligen German, Erzbischofs von Kasan. Als Grigorij aus dem Bojarengeschlecht der Polew zu Starizy geboren, wurde er im Wolokolamsker Kloster des heiligen Iossif eingekleidet, wo Gelehrsamkeit und Askese verbunden waren, und wurde Archimandrit des Dormitio-Klosters in seiner Heimatstadt Starizy.", "patron": "Angerufen von Glaubensboten; um die Erleuchtung Kasans."},

"Venerable Macrina, sister of Saint Basil the Great":
{"type": "Äbtissin · 4. Jh.", "life": "Ehrwürdige Makrina die Jüngere war die älteste Schwester der grossen Hierarchen Basileios des Grossen und Gregorios von Nyssa, zu Beginn des vierten Jahrhunderts in Kappadokien in ein Haus geboren, das der Kirche viele Heilige geben sollte. Vor ihrer Geburt schaute ihre Mutter, die heilige Emmelia, im Traume einen Engel, der das Kind Thekla nannte, nach der heiligen Erzmärtyrerin.", "patron": "Angerufen von Nonnen; von Mönchen."},

"Martyrs Menodora, Metrodora, and Nymphodora, at Nicomedia":
{"type": "Märtyrerinnen · 4. Jh.", "life": "Heilige Jungfrauen und Märtyrerinnen Menodora, Metrodora und Nymphodora waren Schwestern aus Bithynien in Kleinasien; da sie ihre Jungfräulichkeit Christus bewahren und der Eitelkeit der Welt entgehen wollten, zogen sie sich an einen einsamen Ort im Gebirge zurück, wo sie in Fasten und Gebet lebten, und die Kunde ihrer Heiligkeit verbreitete sich, denn auf ihr Gebet hin begannen Heilungen zu geschehen.", "patron": "Angerufen um die schwesterliche Liebe; um die Reinheit."},

"Hieromartyr Clement, Pope of Rome":
{"type": "Patriarch · 2. Jh.", "life": "Heiliger Hieromärtyrer Klemens, Papst von Rom, wurde zu Rom einem reichen und berühmten Hause geboren, das mit den Kaisern verwandt war, und wurde durch eine seltsame Fügung als Kind von seinen Eltern und Brüdern getrennt und unter Fremden aufgezogen, mit jedem Vorteil der Bildung und doch mit dem sehnenden Herzen einer Waise.", "patron": "Angerufen von Steinbrechern; von Verbannten."},

"Glorification of the Priestmartyr Alexander Hotovitzky":
{"type": "Protopresbyter · 20. Jh.", "life": "Gedächtnis der Verherrlichung des heiligen Hieromärtyrers Alexander Chotowizkij, den die Russische Orthodoxe Kirche am vierten Dezember 1994 unter die Heiligen zählte. Am elften Februar 1872 zu Kremenez in Wolhynien geboren, als Sohn eines geliebten Erzpriesters und Seminarleiters, schloss er die Geistliche Akademie zu Sankt Petersburg mit Auszeichnung ab.", "patron": "Angerufen von Gemeindepriestern; von Glaubensboten."},

"Martyr Solomonia, mother of the Holy Seven Maccabee Martyrs":
{"type": "Mutter · 2. Jh. v. Chr.", "life": "Heilige Märtyrerin Solomone war die Mutter der sieben Makkabäer-Brüder, die unter Antiochos Epiphanes um ihrer Treue zum Gesetze Gottes willen litten. Statt ihren Söhnen zu raten, ihr Leben durch den Bruch des Bundes zu retten, ermutigte diese tapfere Mutter einen jeden von ihnen, Gott auch im Angesicht des Todes treu zu bleiben, und sah mit einem Mute über ihre Natur hinaus alle sieben an einem Tage sterben.", "patron": "Angerufen von Müttern; um den Mut."},

"Saint Mariamne the sister of the Apostle Philip":
{"type": "Gerechte Jungfrau · 1. Jh.", "life": "Heilige Mariamne, die Schwester des heiligen Apostels Philippos, gab ihre Jungfräulichkeit und ihr ganzes Leben dem Apostelamte ihres Bruders hin und steht im Kalender als die Schutzherrin aller, die dem Evangelium dienen, indem sie seine Verkünder begleiten. Als die Zwölf in die Welt hinausgingen, zog Mariamne mit Philippos und mit dem Apostel Bartholomaios.", "patron": "Angerufen von Schwestern; von Frauen, die der Mission dienen."},

"Venerable Alypios, Iconographer of the Kyiv Near Caves":
{"type": "Hieromonach · 12. Jh.", "life": "Ehrwürdiger Alipij war einer der ersten und grössten Ikonenmaler der russischen Kirche. Vom Abte Nikon im Kiewer Höhlenkloster eingekleidet und später zum Hieromonachen geweiht, lernte er die heilige Kunst von den griechischen Meistern, die gekommen waren, die grosse Kathedrale der Höhlen zu schmücken, und war selbst Augenzeuge eines Wunders, als ein Bild der Gottesmutter sich in die Wand der Kirche prägte.", "patron": "Angerufen von Ikonenmalern; um die heilige Ikonenmalerei."},

"7 Holy Youths “Seven Sleepers” of Ephesus":
{"type": "Jünglinge · 5. Jh.", "life": "Die sieben heiligen Jünglinge von Ephesos, Maximilianos, Iamblichos, Martinianos, Johannes, Dionysios, Exakustodianos und Antoninos, lebten im dritten Jahrhundert und waren Söhne angesehener Bürger, von Kindheit an Freunde und gemeinsam Soldaten. Als Kaiser Decius nach Ephesos kam und allen zu opfern gebot, bekannten die sieben Christus, und man nahm ihnen die Gürtel ihres Amtes.", "patron": "Angerufen um die Auferstehung der Toten; von Kranken, die nicht schlafen können."},

"Martyr Callinicus of Gangra in Asia Minor":
{"type": "Laie · 3. Jh.", "life": "Heiliger Märtyrer Kallinikos stammte aus Kilikien und wurde von Kindheit an im christlichen Glauben erzogen; und da er darüber trauerte, dass so viele im Götzendienst zugrunde gingen, zog er durch Städte und Dörfer, verkündete Christus und wandte viele zur Wahrheit. Zu Ankyra in Galatien ergriffen, wurde er vor den harten Statthalter Sacerdon geführt und weigerte sich furchtlos zu opfern.", "patron": "Angerufen um die Verkündigung; um das Erbarmen mit den Feinden."},

"Venerable Moses the Ethiopian of Scete":
{"type": "Hieromonach · 5. Jh.", "life": "Ehrwürdiger Moses der Schwarze lebte im vierten Jahrhundert in Ägypten. Ein Äthiopier von Geburt und in der Jugend Sklave, wurde er nach einem Mord von seinem Herrn verstossen und schloss sich einer Räuberbande an, die ihn um seiner grossen Stärke und Kühnheit willen zum Anführer machte, sodass sein Name in der ganzen Gegend ein Schrecken wurde.", "patron": "Angerufen von Mönchen; um die Busse."},

"Greatmartyr Eustáthios Placidas, with his wife and children, of Rome":
{"type": "Grossmärtyrer · 2. Jh.", "life": "Heiliger Grossmärtyrer Eustathios, vor seiner Taufe Plakidas genannt, war ein berühmter römischer Feldherr unter den Kaisern Titus und Trajan und freigebig gegen die Armen, obgleich noch ein Heide; und als er eines Tages jagte, wurde ihm ein wunderbares Gesicht gewährt: ein Hirsch wandte sich ihm zu, und zwischen seinem Geweih leuchtete das strahlende Kreuz Christi, und eine Stimme rief ihn beim Namen.", "patron": "Angerufen von Soldaten; von Jägern."},

"Translation of the relics of Hieromartyr Philip, Metropolitan of Moscow":
{"type": "Metropolit · 16. Jh.", "life": "Gedächtnis der feierlichen Übertragung der Reliquien des heiligen Filipp, Metropoliten von Moskau, in die Hauptstadt im Jahre 1652. Als Feodor Kolytschew geboren, war er Abt des Solowki-Klosters, ehe er auf den Stuhl von Moskau erhoben wurde, wo er die Grausamkeiten des Zaren Iwan des Schrecklichen und die Bedrückungen seiner Leibwache furchtlos zurechtwies.", "patron": "Angerufen um die Freiheit der Kirche vor dem Staate."},

"Venerable Kyriakos the Anchorite":
{"type": "Hieromonach · 6. Jh.", "life": "Ehrwürdiger Kyriakos der Anachoret wurde im Jahre 448 zu Korinth als Sohn eines Presbyters geboren, und mit achtzehn Jahren, als er in der Kirche das Wort des Herrn hörte, wer mir nachfolgen will, der verleugne sich selbst, fuhr er ins Heilige Land und wurde vom heiligen Euthymios dem Grossen aufgenommen, der ihn einkleidete und zum heiligen Gerasimos an den Jordan sandte.", "patron": "Angerufen von Mönchen; um das strenge Fasten."},

"Martyr Eusignius of Antioch":
{"type": "Laie · 4. Jh.", "life": "Heiliger Märtyrer Eusignios wurde in der Mitte des dritten Jahrhunderts zu Antiochien geboren und diente sechzig Jahre als Soldat in den Heeren Roms unter Diokletian, Maximian, Constantius Chlorus und Konstantin dem Grossen und seinen Söhnen. Er war ein Gefährte des Märtyrers Basiliskos, dessen Leiden er aufschrieb, und war zu Beginn der Herrschaft Konstantins selbst Augenzeuge des Zeichens des Kreuzes.", "patron": "Angerufen von Soldaten; um standhaftes Bekenntnis."},

"Virgin Martyr Seraphima (Serapia) of Antioch":
{"type": "Jungfrau · 2. Jh.", "life": "Heilige Jungfrau und Märtyrerin Seraphima stammte aus Antiochien und lebte unter Kaiser Hadrian zu Rom im Hause der Sabina, einer vornehmen Senatorin, die sie zum Glauben an Christus geführt hatte. Als die Verfolgung ausbrach, liess der Statthalter Virilus sie vorladen, und da sie den Kranz des Martyriums begehrte, ging sie ohne Furcht zu ihm, ihre treue Sabina an ihrer Seite.", "patron": "Angerufen um die Reinheit; um standhaftes Bekenntnis."},

"Venerable Eusebius the Hermit of Syria":
{"type": "Einsiedler · 5. Jh.", "life": "Ehrwürdiger Eusebios der Einsiedler in Syrien mühte sich auf einem Berge beim Dorfe Asicha, und sein Gedächtnis ist durch Theodoretos von Kyrros bewahrt, den Geschichtsschreiber der syrischen Asketen, der die Kämpfer jenes Landes aus eigener Anschauung kannte; und unter ihnen allen übte Eusebios die Zucht des Lebens unter freiem Himmel vielleicht in ihrer reinsten Gestalt.", "patron": "Angerufen von Asketen unter freiem Himmel; von den Betagten im Ausharren."},

"Icon of the Mother of God of Kholm":
{"type": "Ikone der Gottesmutter", "life": "Die Cholmer Ikone der Gottesmutter ist eine der ältesten und meistverehrten Ikonen der westrussischen Lande, und fromme Überlieferung schreibt ihre Malerei dem heiligen Evangelisten Lukas zu und hält, dass sie in den Tagen des heiligen Wolodymyr aus Byzanz gebracht wurde, als das Land der Rus die heilige Taufe empfing.", "patron": "Angerufen um Schutz; um Heilung."},

"Venerable Martha, mother of Venerable Simeon Stylites the Younger":
{"type": "Laiin · 6. Jh.", "life": "Ehrwürdige Martha, die Mutter des heiligen Symeon des jüngeren Styliten, lebte im sechsten Jahrhundert und stammte aus Antiochien. Von Jugend an verlangte sie nach dem Mönchsleben, heiratete aber auf den Wunsch ihrer Eltern; ihr Mann Johannes starb bald, und sie gab all ihre Kraft der Erziehung ihres Sohnes zur Heiligkeit hin und wurde ihm ein Vorbild christlicher Tugend.", "patron": "Angerufen von Müttern und ihren Kindern."},

"Martyr Eudokia of Heliopolis":
{"type": "Mönchsmärtyrerin · 2. Jh.", "life": "Heilige Mönchsmärtyrerin Eudokia von Heliopolis ist die grosse Gestalt der Busse am Anfang des Frühlings, eine Samariterin aus dem phönizischen Heliopolis, dem heutigen Baalbek, in den Tagen Trajans, deren Schönheit sie zu einer der reichsten Frauen des Ostens gemacht hatte und deren Reichtum in Sünde erworben war, ihre Seele, wie ihr Leben schlicht sagt, ertötet und ihr Herz verhärtet.", "patron": "Angerufen von Büssenden; von Äbtissinnen."},

"Blessed Laurence the Fool-For-Christ at Kaluga":
{"type": "Narr in Christo · 16. Jh.", "life": "Seliger Lawrentij, der Narr in Christo und Wundertäter von Kaluga, lebte zu Beginn des sechzehnten Jahrhunderts bei der alten Stadt Kaluga, nahe einer Kirche der Geburt Christi auf einem hohen bewaldeten Hügel, zu der ein langer unterirdischer Gang von seiner Wohnung führte, damit er den Gottesdiensten beiwohnen konnte.", "patron": "Angerufen um die Verteidigung Kalugas."},

"Apostle James, the Brother of the Lord":
{"type": "Apostel · 1. Jh.", "life": "Heiliger Apostel Jakobos, der Bruder des Herrn, war ein Sohn des gerechten Joseph des Verlobten aus dessen erster Ehe und teilte von Kindheit an die Armut und die Wege der heiligen Familie und begleitete sie, wie die Überlieferung erzählt, auf der Flucht nach Ägypten. Als ein Gott geweihter Nasiräer trank er keinen Wein, ass kein Fleisch und trug ein einziges Gewand.", "patron": "Angerufen von Bischöfen; von Liturgen."},

"Repose of Venerable Herman of Alaska, Wonderworker of All America":
{"type": "Mönch · 19. Jh.", "life": "Entschlafen des ehrwürdigen German von Alaska, des Wundertäters von ganz Amerika, der um 1756 zu Serpuchow bei Moskau geboren und im Kloster Walaam unter dem Ältesten Nasarij zum Mönche geformt wurde; 1794 erreichte er als einer von zehn Glaubensboten, die über siebentausend Meilen Reich und Ozean gesandt wurden, nach fast einjähriger Reise die Insel Kodiak im russischen Amerika.", "patron": "Angerufen von Glaubensboten; von Waisen."},

"Venerable Pambo the Recluse of the Kyiv Far Caves":
{"type": "Hieromonach · 13. Jh.", "life": "Ehrwürdiger Pambo, Hieromonach und Klausner der Kiewer Höhlen, war ein Bekenner des Glaubens und lebte im Zeitalter der Tatareneinfälle. Während er einem klösterlichen Gehorsam nachging, wurde er von den Tataren gefangen und verschleppt, und viele Jahre erduldete er ihre Grausamkeit und ihre Forderung, Christus zu verleugnen, und hielt durch jede Bedrängnis am wahren Glauben fest.", "patron": "Angerufen um die Standhaftigkeit in der Gefangenschaft."},

"Saint John, Bishop of Suzdal":
{"type": "Bischof · 14. Jh.", "life": "Heiliger Iwan, Bischof von Susdal und Nischni Nowgorod, weidete seine Eparchie im vierzehnten Jahrhundert, in den Tagen der Fürsten von Susdal, und wurde schon zu Lebzeiten als Wundertäter gepriesen. Ein Vater der Armen, der Witwen und der Waisen, gab er ohne Mass und heilte ohne Bezahlung, sodass das Volk ihn den Barmherzigen nannte.", "patron": "Angerufen von Uneigennützigen; um die Sorge für die Armen."},

"Prophet Hosea":
{"type": "Prophet · 8. Jh. v. Chr.", "life": "Heiliger Prophet Hosea, der Sohn Beeris, weissagte im achten Jahrhundert vor Christus im nördlichen Königreich Israel, in den letzten Geschlechtern, ehe jenes Reich von Assyrien weggeführt wurde, und sein Buch steht als erstes unter den zwölf kleinen Propheten. Auf Gottes Geheiss nahm er Gomer zur Frau, eine Frau der Hurerei, und gab seinen Kindern Namen des Gerichtes, damit sein eigenes Haus ein lebendiges Zeichen sei.", "patron": "Angerufen um die Barmherzigkeit Gottes; um die Rückkehr der Untreuen."},

"Venerable Thomas of Bithynia":
{"type": "Mönch · 10. Jh.", "life": "Ehrwürdiger Thomas Dephurkinos wurde im zehnten Jahrhundert in Bithynien geboren und gab sich von Jugend an dem Mönchsleben hin; er durchlief die Gehorsame des gemeinsamen Lebens und zog sich darauf in die Einöde zurück und liess sich zuletzt auf dem Berge Kyminas nieder, einem der heiligen Berge Bithyniens, dessen Lawren und Einsiedeleien dem Olymp gleichkamen und dem Athos den Weg bereiteten.", "patron": "Angerufen von geistlichen Vätern; von Briefschreibern."},

"Venerable Serapion of Spaso-Eleazar Monastery, Pskov":
{"type": "Mönch · 15. Jh.", "life": "Ehrwürdiger Serapion von Pskow wurde zu Jurjew, dem heutigen Tartu, geboren, das damals unter der Herrschaft der Deutschen lag, die den Orthodoxen hart zusetzten; seine Eltern gehörten zur russischen Nikolaos-Kirche jener Stadt, und der Jüngling, in der Heiligen Schrift wohl bewandert, trat mehr als einmal für den orthodoxen Glauben ein.", "patron": "Angerufen von Mönchen; um die Standhaftigkeit in der Orthodoxie."},

"“Ozerianka” Icon of the Mother of God of Shuiu-Smolensk":
{"type": "Ikone der Gottesmutter", "life": "Gedächtnis der Schuja-Smolensker Ikone der Gottesmutter, die in den Jahren 1654 und 1655 in der Stadt Schuja gemalt wurde, als eine tödliche Seuche die Städte Russlands verwüstete. Die Bürger von Schuja wandten sich als an ihre letzte Zuflucht an die Gottesmutter und liessen von einem Ikonenmaler die Smolensker Hodegetria für ihre Auferstehungskirche malen.", "patron": "Angerufen um die Befreiung von der Seuche; um Schutz in Zeiten der Pest."},

"Afterfeast of the Nativity of the Mother of God":
{"type": "Nachfest", "life": "Die Tage des Nachfestes der Geburt der Allheiligen Gottesmutter, an denen die Kirche die Geburt der Gottesmutter aus den gerechten Joachim und Anna weiter feiert. Die Gesänge des Festes werden mit den täglichen Gottesdiensten gesungen und verlängern die Freude des Festes, während die Gläubigen die Lösung der Unfruchtbarkeit Annas betrachten und das Erscheinen derer, die den Erlöser gebären sollte.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Apostle Silvanus of the Seventy":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Apostel Silvanos, einer der Siebzig, verkündete das Wort Gottes zusammen mit den Erzaposteln Petros und Paulos, und der Apostel Petros nennt ihn in seinem Ersten Briefe ehrenvoll einen treuen Bruder, durch den er geschrieben habe. Da er sich in der Ausbreitung des Evangeliums mühte und die Kirchen stärkte, wurde er zum Bischof von Thessalonike bestellt, wo er die Herde Christi weidete.", "patron": "Angerufen um die Verkündigung unter den Völkern."},

"Third Day of the Nativity of our Lord":
{"type": "Fest", "life": "Der dritte Tag der Geburt unseres Herrn trägt das Fest in ungeschmälerter Herrlichkeit weiter, und die Kirche, die am zweiten Tage die Mutter zum Sohne stellte, stellt am dritten den Märtyrer zum Kinde. Dies ist der Tag des Erzmärtyrers Stephanos, und die Zusammenstellung ist die älteste Predigt dieser Zeit.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Martyr Eleutherius of Constantinople":
{"type": "Laie · 4. Jh.", "life": "Heiliger Märtyrer Eleutherios diente als Kämmerer am Hofe Kaiser Maximians, und als er zum Glauben an Christus kam, zog er sich auf ein Landgut zurück und baute auf seinem eigenen Grund eine Kirche, wo er Gott anbetete. Einer seiner Diener verriet ihn an den Kaiser, und vorgeladen und verhört, bekannte sich Eleutherios furchtlos als Christ.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Venerable Mercurius the Faster of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Merkurij der Faster mühte sich im vierzehnten Jahrhundert in der Kiewer Höhlenlawra, und sein Beiname verkündet seinen Kampf: er bezwang das Fleisch durch äusserste Enthaltsamkeit und nahm Speise mit solcher Zurückhaltung, dass das Fasten in ihm nicht eine Übung, sondern eine Natur wurde, der Leib verzehrt und der Geist leuchtend.", "patron": "Angerufen von Fastenden; um die Enthaltsamkeit."},

"Martyrs Adrian and Natalia and 23 companions, of Nicomedia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Adrian war ein heidnischer Beamter des kaiserlichen Hofes zu Nikomedeia in der Verfolgung unter Maximian; und als er zugegen war, wie dreiundzwanzig Christen um ihres Glaubens willen gefoltert wurden, staunte er über ihre Standhaftigkeit und fragte, welchen Lohn sie erhofften. Als sie von den Gütern sprachen, die Gott denen bereitet hat, die ihn lieben, erklärte er sich plötzlich selbst als Christ.", "patron": "Angerufen von Eheleuten; um die Ehe."},

"Venerable Faustus the Ascetic of the Dalmatian Monastery at Constantinople":
{"type": "Mönch · 5. Jh.", "life": "Ehrwürdiger Faustos der Asket vom Dalmatos-Kloster zu Konstantinopel wird zusammen mit den heiligen Isaakios und Dalmatos begangen, und seine Heiligkeit wuchs aus einer doppelten Wurzel, denn Dalmatos war sein Vater dem Fleische nach und wurde sein Bruder im Gewande. Dalmatos, ein Offizier der Garde unter Theodosios dem Grossen, besass Rang, Reichtum und die Gunst des Kaisers.", "patron": "Angerufen von Mönchen; um das Fasten."},

"Apostle Aristobulus of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Aristobulos, einer der Siebzig und Bruder des Apostels Barnabas, wurde auf Zypern geboren und folgte dem heiligen Apostel Paulos, der sein Haus im Römerbriefe grüsst; und von Paulos geweiht, wurde er, wie die alten Berichte erzählen, als Bischof nach Britannien gesandt, in den äussersten Westen der bekannten Welt.", "patron": "Angerufen von Glaubensboten; um die Erleuchtung der Inseln."},

"The Adoration of the Magi: Melchior, Caspar, and Balthasar":
{"type": "Gerechte · 1. Jh.", "life": "Am ersten Tage der Geburt Christi begeht die Kirche die Anbetung der Magier, der Weisen aus dem Morgenlande, die von der Überlieferung Melchior, Kaspar und Balthasar genannt werden und denen die Geburt Christi durch einen wunderbaren Stern offenbart wurde. Die Väter weigerten sich, darin ein gewöhnliches Licht des Himmels zu sehen.", "patron": "Angerufen von Sternkundigen; von Reisenden."},

"Venerable Theodora and her daughter Theopiste":
{"type": "Nonne · 9. Jh.", "life": "Ehrwürdige Theodora, die von der Insel Ägina stammte, und ihre Tochter, im Mönchsstande Theopiste genannt, lebten im neunten Jahrhundert in der Stadt Thessalonike. Noch während ihrer Ehe gaben Theodora und ihr Mann ihre einzige Tochter in ein Kloster, wo sie eingekleidet wurde und ihren neuen Namen empfing.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Hieromartyr Zenobios and his sister Zenobia, of Aegæ in Cilicia":
{"type": "Bischof · 3. Jh.", "life": "Heiliger Hieromärtyrer Zenobios, Bischof von Aigai, und seine Schwester Zenobia erlitten im Jahre 285 in Kilikien das Martyrium. Von christlichen Eltern in Frömmigkeit und Keuschheit erzogen, verschenkten sie ihr ererbtes Vermögen an die Armen, als sie mündig wurden; und der Herr belohnte Zenobios mit der Gabe der Heilung, sodass die Krankheiten vor der Berührung seiner Hände wichen.", "patron": "Angerufen von Ärzten; von denen, die an der Brust erkrankt sind."},

"Apostle Thaddeus of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Thaddaios, einer der Siebzig, war ein Hebräer von Geburt und wurde in der syrischen Stadt Edessa geboren; er ist von Judas, der auch Thaddaios heisst und einer der Zwölf war, zu unterscheiden. Als er zu einem Feste nach Jerusalem kam, hörte er die Predigt des Johannes des Vorläufers und wurde von ihm getauft, und als er den Herrn Jesus schaute, folgte er ihm nach.", "patron": "Angerufen von Glaubensboten; um die Verkündigung unter den Völkern."},

"Saint John, Patriarch of Constantinople":
{"type": "Patriarch · 6. Jh.", "life": "Heiliger Johannes, um seiner grossen Enthaltsamkeit und seines asketischen Lebens willen der Faster genannt, war in der zweiten Hälfte des sechsten Jahrhunderts Patriarch von Konstantinopel. Ein Mann tiefer Demut und des Gebetes, weidete er die Kirche der Kaiserstadt in einem Geiste der Strenge gegen sich selbst und der Milde gegen die Büssenden, und man erinnert ihn besonders als Verfasser einer Bussordnung zur Leitung der Priester.", "patron": "Angerufen um die Busse; um die Beichte."},

"Translation of the relics of Saint John Chrysostom, Archbishop of Constantinople":
{"type": "Erzbischof · 5. Jh.", "life": "Übertragung der Reliquien des heiligen Johannes Chrysostomos, Erzbischofs von Konstantinopel, die Umkehrung des grossen Unrechts seiner Zeit in Herrlichkeit. Der Goldmund war von der Feindschaft der Kaiserin Eudoxia und den Ränken seiner Gegner von seinem Throne vertrieben worden und starb 407 in der Verbannung zu Komana, von Gewaltmärschen erschöpft.", "patron": "Angerufen von Predigern; von gerechtfertigten Verbannten."},

"Glorification of Venerable Herman of Alaska, Wonderworker of All America":
{"type": "Gerechter · 19. Jh.", "life": "Ehrwürdiger German von Alaska, der erste der orthodoxen Heiligen Nordamerikas, war ein demütiger Mönch des Klosters Walaam in Russland, der sich 1794 der Mission anschloss, die das Evangelium zu den Ureinwohnern Alaskas bringen sollte. Auf der Fichteninsel, die er Neu-Walaam nannte, lebte er als Asket und wurde den Aleuten ein Vater und Beschützer und verteidigte sie gegen das Unrecht der russischen Händler.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Saint Oleg, Prince of Briansk":
{"type": "Fürst · 13. Jh.", "life": "Heiliger rechtgläubiger Fürst Oleg von Brjansk war der Enkel des heiligen Märtyrers Michail von Tschernigow und erbte mit seinem Blute die Frömmigkeit, für die sein Grossvater in der Horde gestorben war. Als er in der zweiten Hälfte des dreizehnten Jahrhunderts über das Fürstentum Brjansk herrschte, richtete er sein Herz nicht auf die Mehrung seiner Macht, sondern auf das Reich Gottes.", "patron": "Angerufen von Herrschern; um die Entsagung der Macht."},

"Venerable Hilarion the Schemamonk of the Kyiv Caves":
{"type": "Metropolit · 11. Jh.", "life": "Ehrwürdiger Ilarion der Schemamönch der Kiewer Höhlen entschlief um das Jahr 1066, und die Überlieferung der Lawra erkennt in ihm den grossen Ilarion, Metropoliten von Kiew, den ersten Gebürtigen der Rus auf dem Metropolitenthrone. Als Presbyter im fürstlichen Dorfe Berestowo, ein gelehrter und überaus frommer Mann, pflegte er sich auf einen bewaldeten Hügel über dem Dnipro zurückzuziehen, wo er sich mit eigener Hand eine Höhle grub.", "patron": "Angerufen von Predigern; von Schriftstellern."},

"Martyr Marinus of Rome":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Marinos war ein Soldat und litt im dritten Jahrhundert zu Kaisareia in Palästina, und sein Kampf entzündete sich an einer Beförderung. Ausgezeichnet im Dienste und als nächster für den Stab des Hauptmanns bestimmt, wurde er von einem Nebenbuhler als Christ angezeigt, der den Rang nicht rechtmässig führen könne, da die Beförderung den üblichen Eid bei den heidnischen Göttern und das Götzenopfer erforderte.", "patron": "Angerufen von Soldaten; von Offizieren vor dem Eid der Beförderung."},

"Venerable Niketas of the Kyiv Caves, Far Caves, Bishop of Novgorod":
{"type": "Bischof · 12. Jh.", "life": "Heiliger Nikita, Klausner der Höhlen und Bischof von Nowgorod, ist die grosse Lehre der Kirche über Täuschung und Wiederherstellung, im Paterikon mit klarer Aufrichtigkeit bewahrt, weil jedes Geschlecht sie braucht. Als junger Mönch der Kiewer Höhlen bat Nikita den Abt, den heiligen Nikon, um die Mühe der Klause.", "patron": "Angerufen von den Getäuschten und Wiederhergestellten; von Lernenden, die neu beginnen."},

"Venerable Theodosius of the Kyiv Far Caves":
{"type": "Abt (Igumen) · 11. Jh.", "life": "Ehrwürdiger Theodosij von den Höhlen war mit dem heiligen Antonij, dem Vater des Mönchtums im Lande der Rus, der Gründer des gemeinsamen Lebens unter den russischen Mönchen. Er wurde zu Wassiljewo bei Kiew geboren und war von Jugend an zu Gott gezogen, mied die Spiele und die schönen Kleider, arbeitete demütig auf dem Felde und buk Brot für die Kirche, obgleich seine Mutter, die ihn heftig liebte, ihn oft davon abzubringen suchte.", "patron": "Angerufen von Mönchen; um das gemeinsame Mönchsleben."},

"Martyr Eudokia of Persia":
{"type": "Laiin · 4. Jh.", "life": "Heilige Märtyrerin Eudokia stammte aus Anatolien und lebte im vierten Jahrhundert; sie wurde mit neuntausend Christen vom Heere des persischen Königs Sapor in die Gefangenschaft verschleppt. Da sie in der Heiligen Schrift wohl bewandert war, stärkte und unterwies sie ihre Mitgefangenen in ihrer Bedrängnis und verkündete das Evangelium selbst den persischen Frauen und führte viele von ihnen zum Glauben.", "patron": "Angerufen von Katecheten; von Gefangenen."},

"Hieromartyrs Akepsimas, Bishop in Persia, Presbyter Joseph, and Deacon Aeithalas":
{"type": "Bischof · 4. Jh.", "life": "Heilige Hieromärtyrer Akepsimas der Bischof, Joseph der Presbyter und Aithalas der Diakon leiteten die christliche Kirche in der persischen Stadt Naesson, wo die Herde ihren Hierarchen um seines asketischen Lebens und seiner unermüdlichen Hirtenmühe willen innig liebte. In der grossen Verfolgung unter König Schapur dem Zweiten wurde der betagte Bischof, damals etwa achtzig Jahre alt, von den Häschern des Königs ergriffen.", "patron": "Angerufen vom betagten Klerus; um das Ausharren in langer Gefangenschaft."},

"Venerable Longinus of Yarenga":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Longin von Jarenga war ein Mönch des grossen Solowki-Klosters im Weissen Meer und mühte sich in den Gehorsamen jener strengen nördlichen Bruderschaft in den Überlieferungen der heiligen Sossima und Sawwatij. Um das Jahr 1544 fuhr er im Dienste des Klosters mit seinem Mitbruder Iwan über das Meer, als sie ein plötzlicher Sturm überfiel und die beiden Asketen in den eisigen Wassern umkamen.", "patron": "Angerufen von Seeleuten; von denen, die auf dem Meere arbeiten."},

"Saint Onuphrius of Saint David Gareji Monastery, Georgia":
{"type": "Mönch · 18. Jh.", "life": "Ehrwürdiger Onuphrios von Gareja, in der Welt Otar Machutadse, lebte im achtzehnten Jahrhundert, ein Edelmann Kartliens, berühmt um seines Reichtums, seiner Gastfreundschaft und seiner offenen Hand für die Armen willen. Im Verborgenen nach dem asketischen Leben verlangend, trug er unter seinen prächtigen Kleidern ein härenes Hemd und betete ohne Unterlass, dass Gott ihn des englischen Gewandes würdige.", "patron": "Angerufen von Mönchen; um die Gastfreundschaft."},

"Holy Prophet and God-seer Moses":
{"type": "Prophet · 16. Jh. v. Chr.", "life": "Heiliger Prophet und Gottesschauer Moses, der grosse Gesetzgeber Israels, war aus dem Stamme Levi, und sein Leben ist in den Büchern vom Auszug bis zum fünften Buche geschrieben. In Ägypten geboren, als der Pharao geboten hatte, jedes männliche Kind der Hebräer zu töten, wurde er von seiner Mutter in einem Kästlein im Schilf des Nils verborgen, wo die Tochter des Pharao ihn fand und wie ihren eigenen Sohn aufzog.", "patron": "Angerufen von Gesetzgebern; von Propheten."},

"Apostle Mark of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Markos, einer der Siebzig, den die Kirche vom gleichnamigen Evangelisten unterscheidet, wird in der Überlieferung mit Johannes mit dem Beinamen Markos gleichgesetzt, in dessen Mutter Maria Hause zu Jerusalem sich die Gläubigen zum Gebete versammelten und wohin Petros kam, als der Engel ihn aus dem Kerker führte.", "patron": "Angerufen um Heilung; um den Dienst am Evangelium."},

"Martyr Michael, Prince of Tver":
{"type": "Fürst · 14. Jh.", "life": "Heiliger Märtyrer Michail, Grossfürst von Twer, regierte sein Fürstentum im bitteren Zeitalter des Tatarenjoches, als die Fürsten der Rus um die Gunst des Chans stritten und das Volk für jeden Zwist bezahlte. Aufrecht, dem Gebet ergeben und von seiner Stadt geliebt, empfing Michail das Grossfürstentum nach dem Rechte des Ältesten.", "patron": "Angerufen von Herrschern; von Herrschern, die für ihr Volk sterben."},

"Venerable Basil the Confessor, companion of Venerable Procopius at Decapolis":
{"type": "Bekenner · 8. Jh.", "life": "Ehrwürdiger Basileios der Bekenner war ein Mönch und litt unter dem bilderstürmerischen Kaiser Leon dem Isaurier, und sein Fest folgt im Kalender dem seines Freundes, wie sein Leben ihm im Fleische folgte; denn Basileios und Prokopios aus der Dekapolis waren Gefährten in der Askese, Gefährten im Bekenntnis und Gefährten in den Ketten, und die Kirche begeht sie an aufeinanderfolgenden Tagen als ein Zeugnis von zweien.", "patron": "Angerufen von Bekennern; von Gefährten im Leiden."},

"Conception of the Honorable Glorious Prophet, Forerunner and Baptist John":
{"type": "Fest · 1. Jh.", "life": "An diesem Tage feiert die Kirche die Empfängnis des ehrwürdigen, ruhmreichen Propheten, Vorläufers und Täufers Johannes, den Anfang der Geschichte des Evangeliums. Als der Priester Zacharias in der Ordnung seiner Abteilung in den Tempel des Herrn trat, um Weihrauch darzubringen, erschien ihm der Erzengel Gabriel zur Rechten des Räucheraltars.", "patron": "Angerufen von kinderlosen Eheleuten; um das erhörte Gebet."},

"Apostle Andrew, the Holy and All-Praised First-Called":
{"type": "Apostel · 1. Jh.", "life": "Heiliger allgepriesener Apostel Andreas der Erstberufene stammte aus Bethsaida in Galiläa, war Fischer und Bruder des Simon Petros; und als Jünger des Johannes des Vorläufers hörte er den Täufer von Jesus sagen: Siehe, das Lamm Gottes, und folgte dem Herrn als erster von allen Aposteln, weshalb die Kirche ihn den Erstberufenen nennt.", "patron": "Angerufen von Fischern; von Glaubensboten."},

"Repose of Venerable Job the Wonderworker, Abbot of Pochaiv":
{"type": "Abt (Igumen) · 17. Jh.", "life": "Entschlafen des ehrwürdigen Iow des Wundertäters, Abtes von Potschajiw, in der Welt Iwan Selso, der um 1551 in Pokutien in Galizien geboren wurde und mit zehn Jahren in das Verklärungskloster zu Uhornyky kam und mit zwölf das Mönchsgewand mit dem Namen Iow empfing. Seine Heiligkeit reifte so früh, dass man ihn noch jung zum Priester weihte und er in den westlichen Landen berühmt wurde.", "patron": "Angerufen von Buchdruckern; von Verteidigern des Glaubens."},

"Venerable Joannicius the Great":
{"type": "Mönch · 9. Jh.", "life": "Ehrwürdiger Ioannikios der Grosse wurde 752 im bithynischen Dorfe Marikat so armen Eltern geboren, dass der Knabe keinen Unterricht erhielt, sondern das Vieh der Familie hütete und die Weiden mit Gebet erfüllte; und zu Kräften gekommen, diente er viele Jahre mit Auszeichnung als Soldat des Reiches und kämpfte in den bulgarischen Kriegen.", "patron": "Angerufen von Soldaten, die Mönche werden; um die Busse nach dem Irrtum."},

"Martyr Sozon of Cilicia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Sozon, ein Lykaonier, der vor seiner Taufe Tarasios hiess, war ein Hirte und lebte am Ende des dritten Jahrhunderts; er las die Heilige Schrift, während er seine Herden hütete, und staunte über die Sanftmut seiner Schafe, die er nachzuahmen und zu übertreffen suchte.", "patron": "Angerufen von Hirten; von Viehhütern."},

"Martyr Severian of Sebaste":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Severianos, ein Edler von Sebasteia in Armenien, litt im Jahre 320 für Christus in der Verfolgung unter Kaiser Licinius. Als die vierzig Märtyrer von Sebasteia um ihres Bekenntnisses willen im Kerker lagen, erwies Severianos ihnen offen und furchtlos sein Erbarmen, besuchte sie in ihren Fesseln, ermutigte sie und stärkte sie für ihren Kampf auf dem eisigen See.", "patron": "Angerufen um die Sorge für die Gefangenen; um standhaftes Bekenntnis."},

"Martyr Emilian of Silistria in Bulgaria":
{"type": "Laie · 4. Jh.", "life": "Heiliger Märtyrer Aimilianos, ein Slawe von Geburt, litt für Christus unter Julian dem Abtrünnigen, der die Verehrung der Götzen im ganzen Reiche wiederherstellen wollte und jedem Christen den Tod androhte, der sie nicht ehrte. Aimilianos lebte in der Stadt Durostorum an der Donau, im heutigen Bulgarien, als Sklave eines grausamen und fanatischen Heiden und hielt heimlich am Glauben Christi fest.", "patron": "Angerufen um das freimütige Bekenntnis."},

"Venerable Theoktίstē of the Isle of Lesbos":
{"type": "Nonne · 9. Jh.", "life": "Ehrwürdige Theoktiste von Lesbos wurde zu Methymna auf jener Insel geboren und früh verwaist einem Kloster übergeben, wo sie in der Liebe zu Christus heranwuchs; und als sie etwa achtzehn Jahre alt war und ihre Schwester in einem nahen Dorfe besuchte, wurde sie bei einem Überfall der sarazenischen Seeräuber verschleppt, welche damals die Ägäis heimsuchten.", "patron": "Angerufen von Einsiedlern; von entkommenen Gefangenen."},

"Great Martyr Mercurius of Caesarea, in Cappadocia":
{"type": "Grossmärtyrer · 3. Jh.", "life": "Heiliger Grossmärtyrer Merkurios von Kaisareia war ein junger Soldat skythischer Abkunft im römischen Heere, der Sohn eines christlichen Offiziers; und als in den Tagen Kaiser Decius' die Barbaren über die Grenze strömten, erschien ihm ein Engel des Herrn, legte ihm ein Schwert in die Hand und verhiess ihm den Sieg und gebot ihm, des Herrn, seines Gottes, zu gedenken.", "patron": "Angerufen von Soldaten; um den Sieg, der vom Himmel gegeben wird."},

"Martyr Theodota and her three sons in Bithynia":
{"type": "Laiin · 4. Jh.", "life": "Heilige Märtyrerin Theodota und ihre drei kleinen Söhne litten in der Verfolgung unter Diokletian. Als Christin und Witwe zu Nikaia in Bithynien führte sie ein frommes Leben und erzog ihre Söhne im Glauben und war eine enge geistliche Freundin der heiligen Anastasia. Als die Verfolgung ausbrach und die heiligen Frauen ergriffen wurden, nahm der Beamte Leukadios, von Theodotas Schönheit gefesselt, sie in sein Haus.", "patron": "Angerufen von Müttern; um die Reinheit."},

"Saint Germanus, Bishop of Auxerre":
{"type": "Bischof · 5. Jh.", "life": "Heiliger Germanus wurde um das Jahr 389 zu Auxerre in Gallien geboren, studierte zu Rom Redekunst und Recht und wirkte als Anwalt, bis Kaiser Honorius ihn zurücksandte, um von seiner Vaterstadt aus eine Provinz Galliens zu verwalten. Im Jahre 418 wurde er gegen seinen Willen zum Nachfolger des heiligen Amator erwählt.", "patron": "Angerufen um die Verteidigung des wahren Glaubens."},

"The Meeting of our Lord and Savior Jesus Christ in the Temple":
{"type": "Grosses Fest", "life": "Die Begegnung, oder Darstellung, feiert den Tag vierzig Tage nach der Geburt, an dem die Gottesmutter und Joseph das Christuskind nach dem Gesetze Moses in den Tempel zu Jerusalem brachten, um es dem Herrn darzustellen und das Opfer der Armen darzubringen. Dort nahm der gerechte Greis Symeon, dem offenbart worden war, dass er den Tod nicht sehen werde, ehe er den Gesalbten des Herrn geschaut habe, das Kind in seine Arme.", "patron": "Im heiligen Kalender der Kirche begangen."},

"Venerable Paul the Obedient, of the Kyiv Caves":
{"type": "Mönch · 14. Jh.", "life": "Ehrwürdiger Pawel der Gehorsame war ein Asket der Fernen Höhlen des Kiewer Höhlenklosters. Nachdem er das Mönchsschema empfangen hatte, nahm er ohne Murren die beschwerlichsten Gehorsame auf sich, die der Vorsteher ihm auflegte, und wurde nie müssig gefunden: sooft er nicht an seiner Arbeit war, mahlte er Korn unter dem Mühlstein und zermürbte seinen Leib mit dieser schweren Mühe.", "patron": "Angerufen von Mönchen; von Arbeitenden."},

"Venerable Onuphrius the Silent and Venerable Onesimos the Recluse, of the Kyiv Caves":
{"type": "Mönch · 13. Jh.", "life": "Ehrwürdige Onuphrij der Schweigsame und Onissim der Klausner waren Asketen der Kiewer Höhlen und mühten sich im zwölften und dreizehnten Jahrhundert in den Nahen Höhlen der Lawra. Onuphrij heisst der Schweigsame um des strengen Schweigens willen, das er hielt, indem er seine Lippen und sein Herz hütete, um reiner mit Gott zu verkehren, während Onissim sich als Klausner einschloss.", "patron": "Angerufen um das Schweigen; um die Abgeschiedenheit."},

"Saint Quiricus (Kḗrykos) and his mother Julitta":
{"type": "Laien · 4. Jh.", "life": "Heilige Märtyrer Kerykos und seine Mutter Julitta lebten zu Ikonion in Kleinasien. Julitta war eine Christin vornehmer Geburt, die, jung verwitwet, ihren kleinen Sohn Kerykos allein aufzog. Als die Verfolgung Diokletians ausbrach, floh sie mit ihrem dreijährigen Kinde und zwei treuen Dienerinnen aus der Stadt, zuerst nach Seleukeia und dann nach Tarsos, wo man sie aber erkannte und ergriff.", "patron": "Angerufen um das Glück der Familie; von kranken Kindern."},

"Venerable Nίkander Wonderworker of Pskov":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Nikandr von Pskow, der Einödbewohner und Wundertäter, wurde 1507 im Dorfe Widelebje bei Pskow geboren, demselben Dorfe, das der Kirche den heiligen Jewfrossin gegeben hatte, und hiess in der Welt Nikon. Von Kindheit an verlangte er nach dem asketischen Leben, und nachdem er lesen gelernt und sein Erbteil verschenkt hatte, zog er sich in die Einöde am Flusse Demjanka zwischen Pskow und Porchow zurück.", "patron": "Angerufen von Einsiedlern; um das einsame Leben."},

"Venerable Simeon of Emessa the Fool-For-Christ, and his fellow ascetic Venerable John":
{"type": "Narr in Christo · 6. Jh.", "life": "Ehrwürdige Symeon und Johannes waren Syrer des sechsten Jahrhunderts und von Kindheit an in engster Freundschaft verbunden. Beide stammten aus wohlhabenden Häusern, Symeon der Ältere lebte bei seiner betagten Mutter und Johannes, obgleich verheiratet, bei seinem Vater und seiner jungen Frau. Als Symeon dreissig und Johannes vierundzwanzig Jahre alt war, zogen sie als Pilger nach Jerusalem.", "patron": "Angerufen um die verborgene Heiligkeit; um die Demut."},

"Saint Modestos, Archbishop of Jerusalem":
{"type": "Patriarch · 7. Jh.", "life": "Heiliger Modestos, Erzbischof von Jerusalem, wurde zu Sebasteia in Kappadokien christlichen Eltern geboren; er nahm im Heiligen Lande das Mönchsleben an und stieg zum Abte des Klosters des heiligen Theodosios auf, und Gott hatte ihn in der Wüste für die dunkelste Stunde geschult, welche die Heilige Stadt seit Titus erlebte.", "patron": "Angerufen von Viehhaltern; von Bauern."},

"Venerable Ananias the Iconographer":
{"type": "Mönch · 16. Jh.", "life": "Ehrwürdiger Ananija der Ikonenmaler war ein Mönch des Klosters des heiligen Antonij des Römers zu Nowgorod, den Gott mit einer Gabe für die Malerei der heiligen Ikonen begnadete, die er zur Ehre des Herrn übte. Man erinnert ihn um der wunderbaren Ikonen willen, die er von vielen heiligen Wundertätern schrieb, und noch mehr um seiner tiefen Beständigkeit und seiner Liebe zur Stille willen.", "patron": "Angerufen von Ikonenmalern; um die heilige Kunst."},

"Saint John the Wonderworker, Archbishop of Novgorod":
{"type": "Erzbischof · 12. Jh.", "life": "Heiliger Iwan der Wundertäter, Erzbischof von Nowgorod, wurde in jener Stadt frommen Eltern geboren und gründete mit seinem Bruder Gawriil aus ihrem Erbe ein Kloster zu Ehren der Verkündigung. Zum Bischof von Nowgorod erwählt, war er der erste seiner Hierarchen, der in den Rang eines Erzbischofs erhoben wurde, und er weidete seine Herde mit Sanftmut und Kraft.", "patron": "Angerufen um die Errettung der Städte; von Verleumdeten."},

"Venerable Constantine and Cosmas, Abbots of Kosinsk":
{"type": "Äbte · 13. Jh.", "life": "Ehrwürdige Konstantin und Kosma waren Jünger des heiligen Warlaam von Chutyn und seines Nachfolgers, des heiligen Antonij von Dymsk, in dessen Kloster sie im Mönchsleben geschult wurden. Um das Jahr 1220 verliessen sie Chutyn, grössere Einsamkeit suchend, und liessen sich auf einer wilden Halbinsel unweit der Stadt Staraja Russa nieder, wo sie ein Kloster gründeten.", "patron": "Angerufen von Mönchen; um das monastische Leben."},

"Translation of the relics of Blessed James of Borovichi, Wonderworker of Novgorod":
{"type": "Gerechter · 16. Jh.", "life": "Übertragung der Reliquien des seligen Jakow von Borowitschi, des Wundertäters von Nowgorod, der der Kirche nicht durch den Bericht seines Lebens, sondern durch die Herrlichkeit seiner Reliquien offenbar wurde. Im Frühjahr 1540 trieb an den Stromschnellen der Msta bei der Siedlung Borowitschi eine grosse Eisscholle den Fluss hinauf gegen die Strömung und trug einen Sarg aus versengtem Holze, in dem der Leib eines Jünglings lag.", "patron": "Angerufen von Schiffern; von den unbekannten Gerechten."},

"Martyrs Elias, Probus, and Ares in Cilicia":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Elias, Probos und Ares waren Ägypter von Geburt, und ihr Verbrechen war die Barmherzigkeit: in der Verfolgung unter Maximian zogen sie, ohne auf ihre eigene Sicherheit zu achten, aus Ägypten nach Kilikien, um den dort gefangenen und zu den Bergwerken verurteilten Bekennern Christi zu dienen und denen Trost zu bringen, die das Reich weggeworfen hatte.", "patron": "Angerufen von denen, die Gefangene besuchen; von denen, die den Verfolgten dienen."},

"Venerable Pelagia the Penitent":
{"type": "Nonne · 5. Jh.", "life": "Ehrwürdige Pelagia die Büsserin war die berühmteste Tänzerin und Buhlerin Antiochiens und wurde um ihrer Schönheit und ihres Schmuckes willen Margarita, die Perle, genannt; und als sie eines Tages in Pracht mit ihrem Gefolge vor den Türen vorüberzog, wo eine Versammlung von Bischöfen sass, zog sie aller Augen auf sich, und der heilige Bischof Nonnos weinte und sprach, diese Frau sorge mehr um ihren Schmuck für die Menschen als wir um den Schmuck unserer Seelen.", "patron": "Angerufen von Schauspielerinnen; von Büssenden."},

"Repose of Saint Innocent, first Bishop of Irkutsk":
{"type": "Bischof · 18. Jh.", "life": "Gedächtnis des heiligen Innokentij, ersten Bischofs von Irkutsk, des Erleuchters Ostsibiriens. Um 1680 dem vornehmen Hause der Kultschizkij im Tschernigower Lande geboren, wurde Iwan an der Kiewer Akademie gebildet, empfing das Mönchsgewand mit dem Namen Innokentij und lehrte an den Schulen zu Moskau und Sankt Petersburg.", "patron": "Angerufen von Glaubensboten; von Lehrern."},

"Martyr Gemellus of Paphlagonia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Gemellos von Paphlagonien litt im Jahre 361 unter Julian dem Abtrünnigen, dem Kaiser, der den Christus verleugnet hatte, in dem er erzogen war, und die Verehrung der Götzen wiederherstellen wollte. Als er dem Kaiser zu Ankyra in Galatien begegnete, hielt Gemellos ihm seinen Abfall ins Angesicht vor, mit dem Freimut eines Mannes, der Gott mehr fürchtet als die Könige.", "patron": "Angerufen um den Freimut vor abtrünnigen Herrschern."},

"Martyrs Theodotus, Asclepiodotus, and Maximus, of Adrianopolis":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Theodotos, Asklepiodote und Maximos litten zu Beginn des vierten Jahrhunderts in der Verfolgung unter Maximian Galerius. Maximos und Asklepiodote waren angesehene Bürger von Markianopolis in Thrakien und führten ein frommes christliches Leben, und samt Theodotos wurden sie um des Glaubens willen angezeigt und vor Gericht gestellt.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Venerable Dionysius the Recluse of the Kyiv Caves":
{"type": "Hieromonach · 15. Jh.", "life": "Ehrwürdiger Dionisij der Klausner, Schtschepa genannt, war ein Hieromonach und diente im fünfzehnten Jahrhundert den heiligen Höhlen. Im Jahre 1463, am Tage des heiligen Pascha, als er mit dem Rauchfass durch die Fernen Höhlen ging und die Reliquien der dort ruhenden Heiligen beräucherte, wurde er von der Freude des Festes erfüllt.", "patron": "Angerufen um die österliche Freude; um die Ehrfurcht vor den Heiligen."},

"Holy Unmercenary Physician Diomedes":
{"type": "Arzt · 3. Jh.", "life": "Heiliger uneigennütziger Arzt Diomedes wurde zu Tarsos in Kilikien geboren und in der Heilkunde ausgebildet, doch blähte seine Gelehrsamkeit ihn nicht auf, denn er bewahrte die Frömmigkeit, in der seine Eltern ihn erzogen hatten. In Nachahmung Christi, des Arztes der Seelen und der Leiber, übte er seine Heilkunst frei und ohne Bezahlung und sorgte, während er die Leiber pflegte, auch für die Seelen.", "patron": "Angerufen von Ärzten; von Kranken."},

"Saint Theophanó the Wonderworker, wife of Emperor Leo the Wise":
{"type": "Kaiserin · 9. Jh.", "life": "Heilige Theophano die Wundertäterin, Kaiserin der Römer, wurde zu Konstantinopel dem Konstantin Martinakios und seiner Frau Anna geboren und fromm erzogen; und da Kaiser Basileios der Makedone sie zur Braut seines Sohnes Leon des Weisen erwählte, trat sie in den vergoldetsten und bittersten aller Käfige.", "patron": "Angerufen von Kaiserinnen und Frauen der Herrschenden; von denen, die in unglücklicher Ehe leben."},

"Saint Mardarije (Uskokovic) of Libertyville":
{"type": "Bischof · 20. Jh.", "life": "Heiliger Mardarije von Libertyville, erster serbischer Bischof von Amerika und Kanada, wurde als Ivan Uskoković am zweiten November 1889 im Dorfe Kornet in Montenegro geboren; und da er von Kindheit an für das Mönchsleben brannte, verliess er mit sechzehn Jahren sein Haus, wurde mit dem Namen Mardarije eingekleidet und nach Russland gesandt, wo er seine theologische Bildung vollendete.", "patron": "Angerufen von den Gemeinden der Auswanderer; von Erbauern der Kirchen."},

"Saint Justinian the Emperor":
{"type": "Kaiser · 6. Jh.", "life": "Heiliger Kaiser Justinian, eine der grossen Gestalten des christlichen Reiches, wurde 483 zu Tauresium in Illyrien aus bäuerlichem Geschlecht und, wie eine alte Überlieferung hält, slawischer Abkunft geboren; und 527 als Neffe und Erbe Kaiser Justins auf den Thron erhoben, regierte er achtunddreissig Jahre in der Anschauung, dass das Reich der irdische Diener des himmlischen Reiches sei.", "patron": "Angerufen von Gesetzgebern; von Erbauern."},

"Hieromartyr Sadoc (Sadoth), Bishop of Persia, and 128 Martyrs with him":
{"type": "Bischof, Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Sadok, Bischof in Persien, litt um das Jahr 342 mit hundertachtundzwanzig Gefährten in der grossen Verfolgung Schapurs des Zweiten, als das persische Reich sich vornahm, die Kirche des Ostens auszurotten; er war dem Hieromärtyrer Symeon nachgefolgt, dem ersten Bischof, den die Verfolgung krönte, und erbte mit dem Throne die nahe Gewissheit desselben Endes.", "patron": "Angerufen von Bischöfen unter der Verfolgung; von Scharen der Bekenner."},

"Martyr Marinus, his wife Martha, their children, and those with them at Rome":
{"type": "Laien · 3. Jh.", "life": "Gedächtnis der heiligen Märtyrer Marinus, seiner Frau Martha und ihrer Söhne Audifax und Habakuk samt den anderen, die mit ihnen zu Rom unter Kaiser Claudius dem Zweiten litten. Als fromme Familie aus Persien zogen sie nach Rom, um die Gräber der Apostel Petros und Paulos zu verehren, und gaben sich dort dem Dienste der verfolgten Kirche hin und sammelten bei Nacht die Leiber der Märtyrer.", "patron": "Angerufen von christlichen Familien; um die Bestattung der Toten."},

"Venerable Karion (Cyrion) and his son, Venerable Zachariah, of Egypt":
{"type": "Mönche · 4. Jh.", "life": "Ehrwürdige Karion und sein Sohn Zacharias mühten sich im vierten Jahrhundert zu Sketis in Ägypten, und ihre Geschichte ist eine der seltsamsten und zartesten der Wüste. Karion verliess Frau und zwei Kinder um des Mönchslebens willen; und als eine Hungersnot Ägypten traf, brachte seine Frau die Kinder an die Klosterpforte, und der Mönch nahm seinen Sohn Zacharias zu sich, um ihn in der Skite aufzuziehen.", "patron": "Angerufen von Vätern und Söhnen; um die angenommene Demütigung."},

"Saint Archippus of Herapolis":
{"type": "Gerechter · 4. Jh.", "life": "Heiliger Archippos wurde zu Hierapolis in Phrygien frommen christlichen Eltern geboren, und als er mit zehn Jahren zur Kirche des Erzstrategen Michael über der wundertätigen Quelle bei Kolossai kam, um zu beten, blieb er dort und diente ihr sein Leben lang als Hüter.", "patron": "Angerufen von Küstern; um den treuen Dienst."},

"Venerable Onesiphorus the Confessor of the Kyiv Near Caves":
{"type": "Hieromonach · 12. Jh.", "life": "Ehrwürdiger Onissifor der Bekenner war im zwölften Jahrhundert ein Priestermönch des Kiewer Höhlenklosters, mit Fasten und jeder Tugend geschmückt und von Gott mit der Gabe begnadet, die Geheimnisse der Herzen zu erkennen; und doch liess der Herr zu, dass auch dieser Seher getäuscht wurde, allen zur Unterweisung.", "patron": "Angerufen von Beichtvätern; von geistlichen Vätern."},

"Glorification of Saint Tikhon, Patriarch of Moscow and All Russia, Enlightener of North America":
{"type": "Patriarch · 20. Jh.", "life": "Gedächtnis der Verherrlichung des heiligen Tichon, Patriarchen von Moskau und ganz Russland, den das Bischofskonzil der Russischen Orthodoxen Kirche am neunten Oktober 1989 unter die Heiligen zählte. Im Jahre 1865 als Wassilij Bellawin geboren, der Sohn eines Dorfpriesters von Toropez, war er um seiner Sanftmut willen so geliebt, dass seine Mitschüler im Seminar ihn im Scherz Patriarch nannten.", "patron": "Angerufen von Hierarchen; von Glaubensboten."},

"Apostle Crescens of the Seventy":
{"type": "Bischof · 2. Jh.", "life": "Heiliger Apostel Kreskes, einer der Siebzig, war ein Jünger des Erlösers, den der Apostel Paulos in seinem Zweiten Briefe an Timotheos erwähnt und von dem er festhält, dass er nach Galatien gegangen sei, um dort zu verkünden. Dort wurde er zum Bischof gemacht und trug darauf das Evangelium nach Gallien im Abendlande, wo er zu Vienne seinen eigenen Jünger Zacharias als Bischof einsetzte.", "patron": "Angerufen um die Verkündigung unter den Völkern."},

"Saints Zenon and Zoilus":
{"type": "Gerechte · 4. Jh.", "life": "Die gerechten Zenon und Zoilos werden an diesem Tage gemeinsam begangen, ein Paar, das die Synaxarien mit den kürzesten Notizen tragen, zwei Namen, die der Kalender verbindet, wie sie, wie die Kirche vertraut, im Leben und in Gott verbunden waren; und ihr Fest gehört zu jener stillen Schar von Gedächtnissen, mit denen die Kirche bekennt, dass das Verzeichnis der Heiligen länger ist als jedes Buch.", "patron": "Angerufen von den still Gläubigen; um die Gerechtigkeit ohne Aufzeichnung."},

"Apostle Justus of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Justus, einer der Siebzig, der Joseph Barsabas genannt wird, war nach der Überlieferung der Kirche ein Sohn des gerechten Joseph des Verlobten und wurde darum zu den Brüdern des Herrn gezählt und wuchs im Schatten des fleischgewordenen Wortes auf. Nach der Himmelfahrt, als die Elf den Platz des Judas füllen wollten, stellte man zwei aus denen auf, die mit dem Herrn gewandelt waren.", "patron": "Angerufen um die Zufriedenheit ohne Ehren; um die Treue derer, die nicht erwählt wurden."},

"Saint Gregory, Archbishop of Alexandria":
{"type": "Patriarch · 9. Jh.", "life": "Heiliger Gregorios, Erzbischof von Alexandreia, lebte im neunten Jahrhundert, in den Jahren, da die von den Kaisern wiederbelebte bilderstürmerische Häresie die Kirche aufs Neue verwirrte. Von Jugend an um der Reinheit seines Lebens und der Liebe zu Gott willen berühmt, wurde er gegen seinen Willen auf den Thron von Alexandreia erwählt, wo er seine Herde im apostolischen Glauben weidete.", "patron": "Angerufen von Hierarchen; um die Verehrung der heiligen Ikonen."},

"Martyr Philoumenus of Ancyra":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Philumenos litt im Jahre 274 für Christus in der Verfolgung unter Kaiser Aurelian. Ein Lykaonier und Bäcker von Beruf, lieferte er den Städten Galatiens Brot, verdiente sein Brot redlich und bekannte Christus offen; und neidische Männer zeigten ihn beim Statthalter Felix zu Ankyra als Christen an.", "patron": "Angerufen von Bäckern; von Kaufleuten."},

"Holy, Righteous Simeon the God-Receiver":
{"type": "Gerechter · 1. Jh.", "life": "Heiliger gerechter Symeon der Gottesempfänger ist der Greis der Begegnung, der Mann, den Gott bestellte, an der Grenze der beiden Testamente zu stehen und das zweite in seine Arme zu nehmen; das Evangelium des Lukas zeichnet ihn vollständig in drei Strichen: gerecht und gottesfürchtig, wartend auf den Trost Israels, und der Heilige Geist war auf ihm.", "patron": "Angerufen von Betagten; von Übersetzern."},

"Prophet Ezekiel":
{"type": "Prophet · 6. Jh. v. Chr.", "life": "Heiliger Prophet Ezechiel war aus dem Stamme Levi, ein Priester und der Sohn des Priesters Busi, und wurde mit fünfundzwanzig Jahren zusammen mit dem König Jojachin nach Babylon in die Gefangenschaft weggeführt, als das Volk Juda in die Verbannung ging. Dort, unter den Verbannten am Flusse Kebar, erging das Wort des Herrn an ihn, und er weissagte viele Jahre und rief das Volk zur Busse und tröstete es.", "patron": "Angerufen um die Busse; um die Hoffnung auf die Auferstehung."},

"Venerable Paisios Velichkovsky":
{"type": "Archimandrit · 18. Jh.", "life": "Ehrwürdiger Paissij Welitschkowskij, der Vater der grossen Erneuerung des orthodoxen Mönchtums, wurde 1722 als Pjotr Welitschkowskij zu Poltawa in der Ukraine geboren, der Sohn eines Kathedralpriesters; und da er die Kiewer Akademie verliess, deren Schulgelehrsamkeit seinen Durst nach der lebendigen Überlieferung nicht stillen konnte, suchte er Gott in den Klöstern der Ukraine und der Moldau, bis er mit vierundzwanzig Jahren den Heiligen Berg erreichte.", "patron": "Angerufen von Übersetzern; von geistlichen Vätern."},

"Martyrs Anicetus and Photius of Nicomedia, and those with them":
{"type": "Laien · 4. Jh.", "life": "Heilige Märtyrer Aniketos und Photios, ein Oheim und sein Neffe, stammten aus Nikomedeia. Als Kaiser Diokletian auf dem öffentlichen Platze ein Werkzeug der Hinrichtung aufstellte, um die Christen zu schrecken, tadelte Aniketos, ein Beamter des Hofes, ihn offen, und der erzürnte Kaiser übergab ihn der Folter.", "patron": "Angerufen um standhaftes Bekenntnis."},

"Saint Proclus, Archbishop of Constantinople":
{"type": "Patriarch · 5. Jh.", "life": "Heiliger Proklos, Erzbischof von Konstantinopel, gab seine frühen Jahre dem Gebete und dem Studium der Schriften hin und wurde des grossen Segens gewürdigt, ein Jünger des heiligen Johannes Chrysostomos zu sein, der ihn zum Diakon und zum Priester weihte; und Proklos war es, der den Apostel Paulos über seinen Lehrer gebeugt sah, wie er ihm zuflüsterte, während Chrysostomos seine Homilien über die Briefe schrieb.", "patron": "Angerufen von Hierarchen; von Predigern."},

"Monastic Martyrs and Confessors Auxentius, Basil, Gregory, another Gregory, John, Andrew, Peter and many others":
{"type": "Märtyrer · 8. Jh.", "life": "Heilige Märtyrer und Bekenner Auxentios, Basileios, Gregorios, ein zweiter Gregorios, Johannes, Andreas, Petros und viele andere litten samt dem Mönchsmärtyrer Stephanos dem Neuen für die Verehrung der heiligen Ikonen in der Verfolgung Konstantins Kopronymos. Es waren Bekenner, meist Mönche, die der bilderstürmerische Kaiser aus dem ganzen Reiche in die Kerker von Konstantinopel zusammengetrieben hatte.", "patron": "Angerufen von Mönchen; um die heiligen Ikonen."},

"Saint Sebastiana the Martyr, disciple of Saint Paul the Apostle, at Heraclea":
{"type": "Märtyrerin · 1. Jh.", "life": "Heilige Märtyrerin Sebastiana war eine Jüngerin des heiligen Apostels Paulos, vom grossen Apostel der Völker selbst im Glauben unterwiesen, und mühte sich im ersten Zeitalter der Kirche für das Evangelium. In der Verfolgung unter Kaiser Domitian wurde sie zu Markianopolis ergriffen und um ihres Bekenntnisses zu Christus willen vor Gericht gestellt.", "patron": "Angerufen von Jüngerinnen; um standhaftes Bekenntnis."},

"Repose of Saint Nikolai of Zhicha":
{"type": "Bischof, Bekenner · 20. Jh.", "life": "Entschlafen des heiligen Nikolaj von Žiča, des neuen Chrysostomos der serbischen Kirche, der 1880 als Nikola Velimirović im Dorfe Lelić geboren wurde, das älteste von vielen Kindern frommer Bauern, und der durch gottgegebene Begabung durch die Schulen Serbiens und die Universitäten Europas aufstieg und im Abendlande Doktorwürden erwarb und doch ganz ein Kind des serbischen Dorfes und seines Glaubens blieb.", "patron": "Angerufen von Predigern; von Schriftstellern."},

"Venerable Nikon, Abbot of the Kyiv Far Caves":
{"type": "Abt (Igumen) · 11. Jh.", "life": "Ehrwürdiger Nikon, Abt der Kiewer Höhlen, von der Überlieferung der Lawra der Grosse genannt, kam bereits als Priester zur Höhle des heiligen Antonij, der erste dieser Würde in der kleinen Bruderschaft unter dem Hügel, und wurde die rechte Hand des Gründers: durch Nikons priesterliche Hand empfingen auf Antonijs Segen die ersten Brüder das Mönchsgewand, und unter ihnen der junge Theodosij.", "patron": "Angerufen von denen, die Mönche einkleiden und formen; von Chronisten."},

"Venerable Macarius the Wonderworker, Abbot of Kalyazin":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Makarij der Wundertäter, Abt von Kaljasin, wurde als Matwej Koschin einem Bojarenhause zu Kaschin geboren und heiratete im Gehorsam gegen seine Eltern eine Jungfrau namens Jelena, obgleich sein Herz längst zum Kloster neigte; die jungen Eheleute kamen überein, dass der Überlebende das Mönchsgewand nehmen solle, und als Jelena im dritten Jahre der Ehe starb, tat er es.", "patron": "Angerufen von Witwern; von Gründern."},

"Martyr Onesimus of Isauria":
{"type": "Märtyrer · 1. Jh.", "life": "Heiliger Märtyrer Onesimos, auch Onisios genannt, wird zu den frühen Zeugen Christi gezählt, die ihr Bekenntnis mit dem Schwerte besiegelten. Die erhaltenen Berichte über ihn sind von grösster Kürze und stimmen nicht einmal über sein Land überein, denn während die Kalender ihn als Onesimos von Isaurien begehen und ihn neben den Märtyrer Konon jener Gegend stellen, nennen andere ihn anders.", "patron": "Angerufen von den Standhaften im Verhör; um das mit dem Schwerte besiegelte Bekenntnis."},

"Martyr Sabinus (Abibus) of Egypt":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Sabinus, auch Abibos genannt, war ein angesehener Mann aus Hermupolis in Ägypten, von hohem Stande und um seiner Wohltätigkeit willen bekannt; und als die Verfolgung unter Diokletian über die ägyptische Kirche kam, baten die Christen der Stadt ihn, sich zu bewahren, und Sabinus zog sich mit einigen Gefährten in eine Hütte vor der Stadt zurück, wo sie verborgen blieben.", "patron": "Angerufen von Verratenen; von Wohltätern, denen man mit Bösem lohnte."},

"The Holy Hieromartyrs of Cherson: Basil, Ephraim, Capito, Eugene, Aetherius, Elpidius, and Agathodorus":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heilige Hieromärtyrer von Cherson, Basileios, Ephraim, Eugenios, Elpidios, Agathodoros, Aitherios und Kapiton, trugen das Evangelium in die Lande am nördlichen Schwarzen Meer, von der Donau bis zum Dnipro und zur Krim, und dienten im frühen vierten Jahrhundert nacheinander als Bischöfe von Cherson, einer nach dem anderen von Hermon, dem Bischof von Jerusalem, in ein Missionsfeld gesandt, das seine Hirten verzehrte.", "patron": "Angerufen von Missionsbischöfen; für die Kirche an feindlichen Grenzen."},

"Martyr Philetus the Senator, his wife and sons, and those with them in Illyria":
{"type": "Märtyrer · 2. Jh.", "life": "Heilige Märtyrer Philetos der Senator, seine Gemahlin Lydia, ihre Söhne Makedon und Theoprepios, der Heerführer Amphilochios und der Notar Kronides litten zu Beginn des zweiten Jahrhunderts unter Kaiser Hadrian, und ihr Kampf ist einer von denen, welche die Kirche um der seltsamen Sanftmut ihres Endes willen erinnert.", "patron": "Angerufen von Familien, die gemeinsam bekennen; von bekehrten Beamten."},

"Martyr Drosίs, daughter of Emperor Trajan":
{"type": "Jungfrau und Märtyrerin · 2. Jh.", "life": "Heilige Jungfrau Drosis, die Tochter des Kaisers Trajan selbst, ist der Kirche ein Zeugnis dafür, dass das Evangelium in seinem ersten Jahrhundert bis an den Herd seines Verfolgers stieg. In den Jahren, da das Reskript ihres Vaters den Umgang mit den Christen regelte und die Leiber der Märtyrer unbestattet hinausgeworfen wurden, um ihre Schmach zu vollenden, schloss Drosis sich heimlich den Gläubigen an.", "patron": "Angerufen von Töchtern feindlicher Häuser; von denen, welche die Märtyrer bestatten."},

"Saint Sophronius, Patriarch of Jerusalem":
{"type": "Patriarch · 7. Jh.", "life": "Heiliger Sophronios, Patriarch von Jerusalem, wurde um 560 zu Damaskus geboren, ein Sophist der Bildung nach und Meister der ganzen Gelehrsamkeit der Griechen; und da er die Schulen gegen die Wüste tauschte, wurde er der unzertrennliche Gefährte des Mönches Johannes Moschos, mit dem er jahrzehntelang durch die Klöster Palästinas, des Sinai und Ägyptens zog und ihre Sprüche sammelte.", "patron": "Angerufen von Patriarchen; von Theologen."},

"Saint Artemon, Bishop of Seleucia":
{"type": "Bischof · 1. Jh.", "life": "Heiliger Artemon, erster Bischof von Seleukeia in Pisidien, gehört zu dem Geschlecht, das die Apostel mit eigenen Händen bestellten, und seine Weihe ist der leuchtende Mittelpunkt seines Lebens: als der Apostel Paulos auf seinen Missionsreisen durch das Hochland Kleinasiens nach Seleukeia kam und dort Christus verkündete, fand er in Artemon einen Mann, der für die Ernte schon reif war.", "patron": "Angerufen von ersten Bischöfen; von denen, die durch apostolische Hände geweiht sind."},

"1st Sunday of Great Lent: Sunday of Orthodoxy":
{"type": "Fest · 9. Jh.", "life": "Am ersten Sonntag der Grossen Fastenzeit begeht die Kirche den Sonntag der Orthodoxie, das Fest des Sieges des wahren Glaubens, eingesetzt im Jahre 843, als die heilige Kaiserin Theodora und der heilige Patriarch Methodios die Verehrung der Ikonen wiederherstellten und die letzte grosse Häresie der alten Welt beendeten.", "patron": "Angerufen für die ganze streitende Kirche; für alle, die den Glauben der Väter bewahren."},

"Beginning of Great Lent":
{"type": "Fest · 4. Jh.", "life": "An diesem Tage tritt die Kirche in die Grosse Fastenzeit ein, in die heiligen vierzig Tage, die älteste und grösste ihrer Zeiten der Busse, die von den frühesten Geschlechtern an als der Zehnte des Jahres Gott dargebracht und als der gemeinsame Weg aller Gläubigen zum Pascha gehalten wurde. Ihre Wurzeln reichen an die Anfänge: der Herr selbst fastete vierzig Tage.", "patron": "Angerufen für alle Gläubigen; für die Katechumenen, die sich auf die Taufe bereiten."},

"Venerable Zachariah the Recluse":
{"type": "Mönch, Klausner · 9. Jh.", "life": "Ehrwürdiger Zacharias der Klausner wird an diesem Tage begangen, und das byzantinische Synaxarion selbst bekennt mit redlicher Sorgfalt, dass unter den vielen Heiligen dieses Namens nicht genau zu bestimmen ist, welchen die Kirche hier ehrt; es hält allein an der überlieferten Meinung fest, dass er das eingeschlossene Leben in einem Kloster zu Konstantinopel beim Charsios-Tore führte.", "patron": "Angerufen von Klausnern; von den Verborgenen."},

"Finding of the relics of Saint Theodore, Prince of Smolensk and Yaroslavl, and his children":
{"type": "Fürst · 13. Jh.", "life": "Auffindung der Reliquien des rechtgläubigen Fürsten Feodor von Smolensk und Jaroslawl, des Schwarzen genannt, samt seinen Söhnen David und Konstantin, die am fünften März 1463 zu Jaroslawl geschah; sein Entschlafen wird im September begangen, dieser Tag aber gehört der Auffindung seines unverwesten Leibes.", "patron": "Angerufen von Herrschern; von Familien."},

"Venerable Benedict of Nursia":
{"type": "Abt (Igumen) · 6. Jh.", "life": "Ehrwürdiger Benedikt von Nursia, der Vater der Mönche des Abendlandes, wurde um 480 in den umbrischen Bergen geboren und zum Studium nach Rom gesandt; und als er das Verderben seiner Mitschüler sah, hielt der Jüngling den Preis jener Gelehrsamkeit für zu hoch und floh die Stadt, wissend ungelehrt und weise unbelehrt, wie der heilige Gregorios von ihm schreibt, und wollte allein Gott gefallen.", "patron": "Angerufen von Mönchen des gemeinsamen Lebens; von Äbten."},

"Martyr Nikon and 199 disciples with him in Sicily":
{"type": "Hieromärtyrer · 3. Jh.", "life": "Heiliger Märtyrer Nikon und seine hundertneunundneunzig Jünger litten um das Jahr 251 auf Sizilien in der Verfolgung des Decius, und sein Weg zu jener Schar begann in einem Heere. Soldat von Beruf, Sohn eines heidnischen Vaters und einer christlichen Mutter, zog Nikon ungetauft, doch nicht unbelehrt in den Krieg, denn seine Mutter hatte den Samen des Glaubens in ihn gelegt.", "patron": "Angerufen von Bischöfen samt ihren Herden; von Lehrern und ihren Schülern."},

"Venerable Alexis the Man of God":
{"type": "Gerechter · 5. Jh.", "life": "Ehrwürdiger Alexios, der Mann Gottes, war der einzige Sohn des römischen Senators Euphemianus, eines Hauses, das um seines Reichtums und seines Erbarmens mit den Armen willen berühmt war, und das ersehnte Kind der Gebete seiner Mutter Aglais.", "patron": "Angerufen von Bettlern und Obdachlosen; von den Unerkannten."},

"Saint James the Confessor, Bishop of Catania":
{"type": "Bischof, Bekenner · 9. Jh.", "life": "Heiliger Jakobos der Bekenner, Bischof von Catania, war von Jugend an Asket, im Mönchsleben in Gelehrsamkeit und Strenge geformt, und wurde um seiner Tugenden willen auf den Bischofsthron von Catania auf Sizilien erhoben, wo er seine Herde in den Jahren weidete, da die bilderstürmerischen Kaiser ihren Krieg gegen die heiligen Bilder jeder Provinz des Reiches aufdrängten.", "patron": "Angerufen von Bischöfen in der Verbannung; von Verteidigern der Ikonen."},

"Hieromartyr Publius, Bishop of Athens":
{"type": "Hieromärtyrer · 2. Jh.", "life": "Heiliger Hieromärtyrer Publius, Bischof von Athen, tritt durch eine Tat der Gastfreundschaft in die Schrift: er ist der Publius der Apostelgeschichte, der Erste der Insel Malta, der den Apostel Paulos und seine Gefährten aufnahm und drei Tage freundlich beherbergte, als der Schiffbruch auf der Fahrt nach Rom sie dort an Land warf.", "patron": "Angerufen von Gastgebern und Gastfreien; von Bischöfen alter Stühle."},

"Venerable Stephen, Wonderworker, Abbot of Triglia":
{"type": "Abt (Igumen), Bekenner · 9. Jh.", "life": "Ehrwürdiger Stephanos der Wundertäter, Abt des Klosters Triglia an der bithynischen Küste bei Prusa, war von Jugend an Gott geweiht und übertraf im asketischen Leben, in Reinheit, Fasten und Gebet so sehr, dass man ihn über die Bruderschaft von Triglia als Abt setzte, die er in Heiligkeit leitete, von Gott, wie sein Beiname festhält, mit der Gnade der Wunder geschmückt.", "patron": "Angerufen von Äbten unter der Verfolgung; von Verbannten."},

"Hieromartyr Basil of Ancyra":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Basileios, Priester zu Ankyra in Galatien, war der Hüter der Herde jener Stadt durch zwei Stürme nacheinander, den arianischen und den heidnischen, und fiel im zweiten. In den Jahren, da die Arianer die Macht hielten und die Kirchen Galatiens verwirrt waren, mühte sich der Presbyter Basileios unermüdlich für den nizänischen Glauben und stärkte die Wankenden.", "patron": "Angerufen von Gemeindepriestern; von Verteidigern der Herde wider Häresie und Abfall."},

"Martyr Marinus":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Marinos der Soldat litt im Jahre 262 zu Kaisareia in Palästina, und sein Kampf, den Eusebios jener Stadt bewahrt hat, dreht sich um eine einzige Wahl von unerträglicher Klarheit. Marinos war ein angesehener Soldat vornehmer Geburt, und als der Posten des Hauptmanns frei wurde, stand er als erster zur Beförderung an.", "patron": "Angerufen von Soldaten am Scheidewege des Gewissens; um das Evangelium, das dem Schwerte vorgezogen wird."},

"Martyr Pancharius at Nicomedia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Pancharios war ein angesehener Römer, ein Günstling Kaiser Maximians und ein Christ; und sein Kampf ist der Kirche kostbar, weil er mit einem Falle beginnt. Als die Verfolgung Glauben und Gunst unvereinbar machte, verbarg Pancharios, der seinen Platz an der Seite des Kaisers nicht verlieren wollte, sein Christentum und verleugnete es damit und behielt den Hof und liess Christus fahren.", "patron": "Angerufen von denen, die verleugnet haben und zurückkehren wollen; von Söhnen fern der Heimat."},

"Saint Cyril, Bishop of Catania":
{"type": "Bischof · 2. Jh.", "life": "Heiliger Kyrillos, Bischof von Catania, wurde zu Antiochien geboren, in der Stadt, wo die Jünger zuerst Christen genannt wurden, und gehörte zu dem Geschlecht, das die Apostel unmittelbar geformt haben, aus dem Kreise der Jünger des Apostels Petros; und er wurde gesandt, die Kirche von Catania auf Sizilien zu weiden, einen jener ersten Missionsstühle an den Kreuzwegen des Meeres.", "patron": "Angerufen von Bischöfen der Missionsstühle; von Dürstenden."},

"Martyr Urpasianus of Nicomedia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Urpasianos litt in der Stadt Nikomedeia unter Kaiser Maximian Galerius, der die Christen in seinem Heere und an seinem Hofe grausam verfolgte; und in jener Sichtung begannen, wie die Leben berichten, einige Kleinmütige zu wanken und die heidnischen Götter anzubeten, während die Starken bis ans Ende ausharrten, und Urpasianos stand an der Spitze der Starken.", "patron": "Angerufen von Höflingen; von denen, die um Christi willen ihren Rang niederlegen."},

"42 Martyrs of Ammoria in Phrygia":
{"type": "Märtyrer · 9. Jh.", "life": "Die zweiundvierzig heiligen Märtyrer von Amorion waren die Befehlshaber und Edlen des byzantinischen Heeres, die gefangen wurden, als die grosse Stadt Amorion in Phrygien im Jahre 838 den Sarazenen fiel, unter ihnen Konstantin, Aetios, Theophilos, Theodoros, Melissenos, Kallistos und Basoes, die Blüte der Führung des Reiches, nach Mesopotamien verschleppt.", "patron": "Angerufen von Soldaten; von Heerführern."},

"Martyrs Agapius, Publius, Timolaus, Romulus, two named Dionysius, and two named Alexander, at Caesarea in Palestine":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Agapios, Publios, Timolaos, Romulos, die beiden Dionysios und die beiden Alexandros litten zu Kaisareia in Palästina beim Ausbruch der grossen Verfolgung und wurden nach der Rechnung des Eusebios und des griechischen Synaxarions am vierundzwanzigsten März des Jahres 304 enthauptet, nach den slawischen Berichten 303; und ihr Kampf ist der Kirche durch einen Augenzeugen bewahrt.", "patron": "Angerufen von den Jungen; von denen, die sich freiwillig zum Bekenntnis stellen."},

"Martyr Papas of Lyconia":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Papas von Lykaonien litt in der Verfolgung zu Beginn des vierten Jahrhunderts, als die Erlasse Diokletians und Maximians in das Hochland des inneren Kleinasiens reichten, wo Paulos und Barnabas zuerst das Wort gesät hatten; und der Kampf des Papas wird um seines Weges und seines Baumes willen erinnert.", "patron": "Angerufen von denen, die über ihre Kraft hinaus getrieben werden; um den Marsch in den benagelten Schuhen."},

"40 Holy Martyrs of Sebaste":
{"type": "Märtyrer · 4. Jh.", "life": "Die vierzig heiligen Märtyrer von Sebasteia waren Soldaten der berühmten Zwölften Legion, der Donnernden genannt, und lagen um das Jahr 320 zu Sebasteia in Armenien in Garnison, welches das byzantinische Synaxarion als 322 oder 323 rechnet, als Kaiser Licinius seinen Frieden mit der Kirche brach und seinen Heeren zu opfern gebot.", "patron": "Angerufen von Soldaten; von Scharen und Bruderschaften."},

"Hieromartyr Mark, Bishop of Arethusa, who suffered under Julian the Apostate":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Markos, Bischof von Arethusa in Syrien, war schon ein Greis voller Jahre und Ehren, als Julian der Abtrünnige die Heiden auf die Kirche losliess, und sein Kampf, den der heilige Gregorios der Theologe den Zeiten bewahrt hat, ist einer der seltsamsten und herrlichsten jener seltsamen Verfolgung.", "patron": "Angerufen von Betagten in der Prüfung; von denen, die sich für andere ausliefern."},

"Monastic Martyrs Conon and his son, Conon, of Iconium":
{"type": "Hieromärtyrer und sein Sohn · 3. Jh.", "life": "Heilige Mönchsmärtyrer Konon und sein Sohn Konon litten unter Kaiser Aurelian zu Ikonion in Kleinasien. Der ältere Konon, als Witwer zurückgeblieben, trat mit seinem Sohne in ein Kloster ein und empfing um seines heiligen Lebens willen die Gnade von oben: er trieb Dämonen aus, heilte Kranke, gab Blinden das Gesicht und verkündete den Heiden Christus und bekehrte dadurch viele.", "patron": "Angerufen von verwitweten Vätern; von Vätern und Söhnen."},

"Saint Thomas, Patriarch of Constantinople":
{"type": "Patriarch · 7. Jh.", "life": "Heiliger Thomas, Patriarch von Konstantinopel, diente der Grossen Kirche zuerst als Diakon und Sakellarios unter dem heiligen Patriarchen Johannes dem Faster und zeichnete sich durch Klugheit und Ehrfurcht in der Verwaltung der Kirchen aus; im Jahre 607 wurde er unter Phokas auf den Patriarchenthron erhoben, als das Reich, ohne dass jemand es wusste, an der Schwelle des Verhängnisses stand.", "patron": "Angerufen von denen, die sich vor den kommenden Tagen fürchten; von Hirten, die um Verschonung beten."},

"Saint Paul the Confessor, Bishop of Plousias in Bithynia":
{"type": "Bischof, Bekenner · 9. Jh.", "life": "Heiliger Paulos der Bekenner war Bischof der Stadt Plusias in der Provinz Bithynien in Kleinasien und weidete seine Herde in den Jahren, da die Bilderstürmer zum zweiten Male gegen die Kirche Christi wüteten und die Kaiser des neunten Jahrhunderts den Krieg gegen die heiligen Bilder erneuerten, den das Siebte Ökumenische Konzil beigelegt hatte.", "patron": "Angerufen von Verteidigern der Ikonen; von verbannten Hierarchen."},

"Saint Innocent of Komél and Vologda disciple of Saint Nilus of Sora":
{"type": "Abt (Igumen) · 16. Jh.", "life": "Ehrwürdiger Innokentij von Komel und Wologda wurde zu Moskau aus dem Fürstengeschlecht der Ochljabinin geboren und liess Rang und Erbe um des Mönchsgewandes willen im Kloster des heiligen Kirill am Weissen See, jener grossen Pflanzstätte der nördlichen Mönche; und dort gab Gott ihm den Schatz seines Lebens, denn er wurde der Jünger des heiligen Nil von Sora, des Meisters des Skitenlebens und des inneren Gebetes.", "patron": "Angerufen von Jüngern, die das Erbe eines Lehrers hüten; von Gründern."},

"2nd Sunday of Great Lent: St Gregory Palamas":
{"type": "Fest · 14. Jh.", "life": "Am zweiten Sonntag der Grossen Fastenzeit begeht die Kirche das Gedächtnis des heiligen Gregorios Palamas, Erzbischofs von Thessalonike, und der Tag heisst mit Recht der zweite Sieg der Orthodoxie, denn er führt den ersten weiter: wie der erste Sonntag verkündet, dass Gott dargestellt werden kann, weil er wahrhaft Mensch geworden ist, so verkündet der zweite, dass Gott erfahren werden kann, weil er sich wahrhaft selbst gibt.", "patron": "Angerufen von Hesychasten und allen, die beten; von Theologen der Erfahrung."},

"Saint Theophylactus, Bishop of Nicomedia":
{"type": "Bischof, Bekenner · 9. Jh.", "life": "Heiliger Theophylaktos, Bischof von Nikomedeia, lebte zu Konstantinopel im Zeitalter der bilderstürmerischen Häresie und gehörte zu den vertrauten Männern des heiligen Patriarchen Tarasios, der auf den Thron gekommen war, nachdem der Patriarch Paulos ihn niedergelegt hatte, weil ihm die Kraft fehlte, die Herde im Angesicht des Bildersturms zu leiten.", "patron": "Angerufen von Bischöfen, die den Armen dienen; von Pflegern der Aussätzigen."},

"Martyrs Chrysanthus and Daria, and those with them at Rome":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Chrysanthos und Daria litten nach römischer und griechischer Rechnung im Jahre 283 zu Rom, während die Bücher, die sie unter Valerian setzen, etwa das Jahr 253 nennen, und ihr Kampf sammelte eine ganze Ernte von Gefährten, ehe er sich schloss. Chrysanthos, der Sohn des Senators Polemios, kam mit seinem Vater aus Alexandreia nach Rom und begegnete während seiner Studien der Schrift.", "patron": "Angerufen von Eheleuten, die der Reinheit gelobt sind; von Bekehrten der Bekehrten."},

"Icon of the Mother of God of Mount Athos, “Sweet Kissing”":
{"type": "Ikone der Gottesmutter · 9. Jh.", "life": "Die Ikone der Gottesmutter mit dem Namen Süsser Kuss, die Glykophilousa, ist einer der Schätze des Klosters Philotheou auf dem Athos und zeigt die Mutter und das Kind in der Fülle der Zärtlichkeit, Wange an Wange gedrückt, sodass die gegenseitige Liebe der Jungfrau und ihres Gottes der ganze Gegenstand des Bildes ist.", "patron": "Angerufen von denen, die hingeben müssen, was sie lieben, um es zu retten; von Pilgern."},

"Martyr Cyril the Deacon of Heliopolis, and those with him, who suffered under Julian the Apostate":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Märtyrer Kyrillos der Diakon von Heliopolis und die mit ihm litten, waren Opfer der heidnischen Rückkehr unter Julian dem Abtrünnigen im Jahre 362, als die Wiederherstellung der Götzen durch den Kaiser den Anhängern der alten Religion erlaubte, mit den Christen abzurechnen, die sie unter Konstantin gedemütigt hatten.", "patron": "Angerufen von Diakonen; von denen, die für einen längst vergangenen Eifer leiden."},

"Virgin Martyrs Alexandria, Claudia, Euphrasia, Matrona, Juliana, Euphemia, and Theodora":
{"type": "Jungfrauen und Märtyrerinnen · 4. Jh.", "life": "Heilige Jungfrauen und Märtyrerinnen Alexandria, Klaudia, Euphrasia, Matrona, Juliana, Euphemia und Theodosia litten im Jahre 310 gemeinsam zu Amisos an der pontischen Küste des Schwarzen Meeres, in der letzten Wut der Verfolgung unter Maximian, als die östlichen Provinzen Haus für Haus nach den Christen durchsucht wurden, welche die früheren Erlasse übersehen hatten.", "patron": "Angerufen von Scharen von Frauen; von den gemeinsam Standhaften."},

"Translation of the relics of the Martyr Epimachus of Pelusium":
{"type": "Märtyrer · 3. Jh.", "life": "Übertragung der Reliquien des heiligen Märtyrers Epimachos von Pelusion, auch der von Alexandreia genannt, dessen Hauptfest am Ende des Oktober begangen wird; das Gedächtnis im März bezeichnet die Überführung seiner heiligen Reliquien nach Konstantinopel, wo die Stadt den ägyptischen Märtyrer unter ihre Schätze aufnahm und dieses jährliche Gedenken seiner Ankunft einsetzte.", "patron": "Angerufen von den Eifrigen; von denen, welche die Märtyrer geheilt haben."},

"Prophet Joad":
{"type": "Prophet · 10. Jh. v. Chr.", "life": "Heiliger Prophet Joad ist der Name, den die Überlieferung dem Manne Gottes aus Juda gibt, dessen Sendung nach Bethel das Buch der Könige erzählt, eine der feierlichsten und eindringlichsten aller prophetischen Geschichten. Vom Worte des Herrn zu dem abtrünnigen Altar gesandt, den Jerobeam errichtet hatte, rief Joad gegen den Altar selbst und nannte drei Jahrhunderte im Voraus den König Josia beim Namen.", "patron": "Angerufen von Boten mit schwerem Auftrag; von denen, die nicht abweichen dürfen."},

"Repose of Saint Innocent, Metropolitan of Moscow, Enlightener of the Aleuts, Apostle to the Americas":
{"type": "Metropolit, Apostelgleicher · 19. Jh.", "life": "Entschlafen des heiligen Innokentij, Metropoliten von Moskau und Erleuchters Nordamerikas, der 1797 als Iwan Popow im Dorfe Anga im Irkutsker Lande Sibiriens geboren wurde, ein armer Priestersohn, der im Seminar den Namen Weniaminow annahm; und 1824 meldete sich der junge verheiratete Priester, dessen Gaben jede Hauptstadt geschmückt hätten, freiwillig für den Auftrag, den niemand wollte: die Aleuten am Rande der Welt.", "patron": "Angerufen von Glaubensboten; von Übersetzern."},

"Saint Euschemon the Confessor, Bishop of Lampsacus":
{"type": "Bischof, Bekenner · 9. Jh.", "life": "Heiliger Euschemon der Bekenner war Bischof von Lampsakos, der alten Stadt am asiatischen Ufer des Hellespont, und weidete seine Herde im letzten Geschlecht der bilderstürmerischen Verfolgung, als Kaiser Theophilos den von seinem Hause ererbten Krieg gegen die heiligen Bilder mit neuer Härte erneuerte.", "patron": "Angerufen von Bischöfen im Kerker; von Freunden der Verfolgten."},

"26 Martyrs in the Crimea":
{"type": "Märtyrer · 4. Jh.", "life": "Die sechsundzwanzig heiligen Märtyrer, deren Reliquien die Krim geheiligt haben, litten um das Jahr 375 im Lande der Goten jenseits der Donau, als der heidnische Gotenkönig eine Verfolgung gegen die Christen seines Volkes erhob und die junge gotische Kirche, von Gefangenen und Glaubensboten gepflanzt, ihren ersten grossen Preis in Blut bezahlte.", "patron": "Angerufen von Gemeinden im Gottesdienst; von neubekehrten Völkern."},

"Leavetaking of the Annunciation":
{"type": "Fest · 1. Jh.", "life": "An diesem Tage begeht die Kirche den Abschluss der Verkündigung und singt noch einmal und zum letzten Male in diesem Jahre die Gesänge der Botschaft Gabriels, ehe sie sie beiseitelegt und zur Fastenzeit zurückkehrt.", "patron": "Angerufen von allen, die das Fest gehalten haben; um das Geheimnis, das in die Seele eingesiegelt wird."},

"Monastic Martyr Euthymius of Prodromou, Mount Athos":
{"type": "Neumärtyrer · 19. Jh.", "life": "Heiliger Neumärtyrer Euthymios aus der Skite Prodromou auf dem Athos wurde als Eleutherios zu Demitsana auf der Peloponnes frommen Eltern geboren und fiel in der Jugend auf jenem Wege, den viele der Neumärtyrer gingen: auf seinen Wanderungen unter die Türken geraten, bedrängt und umgarnt, verleugnete der junge Mann in einer Stunde der Schwäche Christus und nahm den Islam an.", "patron": "Angerufen von denen, die verleugnet haben und zurückkehren wollen; von der Jugend in der Busse."},

"Martyred Holy Fathers who were slain at the Monastery of Saint Savva":
{"type": "Mönchsmärtyrer · 8. Jh.", "life": "Die heiligen Väter, die im Kloster des heiligen Sabbas erschlagen wurden, litten im Jahre 796, nach anderen Berichten 797, als Scharen arabischer Räuber in einer Zeit der Gesetzlosigkeit in Palästina über die Grosse Lawra in der judäischen Wüste herfielen; und ihr Martyrium ist der Kirche in seltener Ausführlichkeit bekannt, denn einer der Überlebenden schrieb alles als Augenzeuge nieder.", "patron": "Angerufen von Mönchen unter dem Überfall; von Gemeinschaften, die sich nicht zerstreuen."},

"Venerable Seraphim of Vyritsa":
{"type": "Mönch, Ältester · 20. Jh.", "life": "Ehrwürdiger Serafim von Wyriza, einer der grossen Ältesten der russischen Kirche in ihrem gekreuzigten Jahrhundert, wurde 1866 als Wassilij Murawjow Bauern des Jaroslawler Landes geboren und als Knabe nach Petersburg geschickt, um Brot zu verdienen.", "patron": "Angerufen von Kaufleuten und Geschäftsleuten, die sich Gott zuwenden; von den geistlichen Kindern der Ältesten."},

"Saint Caesarius, brother of Saint Gregory the Theologian":
{"type": "Gerechter · 4. Jh.", "life": "Heiliger Kaisarios, der Bruder des heiligen Gregorios des Theologen, war der jüngere Sohn Gregorios' des Älteren, des Bischofs von Nazianz, und der gerechten Nonna, in jenes eine Haus geboren, das der Kirche eine ganze Familie von Heiligen gab; und wo sein Bruder den Weg der Wissenschaften und des Altars ging, ging Kaisarios den Weg der Naturkunde und studierte zu Alexandreia Heilkunde, Geometrie und Sternkunde.", "patron": "Angerufen von Ärzten; von Naturforschern."},

"Righteous Tarasius of Liconium":
{"type": "Gerechter · 4. Jh.", "life": "Der gerechte Tarasios von Lykaonien, aus dem lykaonischen Lande des inneren Kleinasiens, wird an diesem Tage unter jener stillen Schar des Kalenders begangen, deren Namen die Synaxarien treu über die Jahrhunderte getragen haben, während die daran hängenden Geschichten fallen gelassen wurden; und die Kirche hält sein Fest ohne Verlegenheit über das Schweigen.", "patron": "Angerufen von den still Gläubigen; um die Gerechtigkeit, die ohne Aufzeichnung bewahrt wird."},

"Martyrs Africanus, Publius, and Terence, of Carthage":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Africanus, Publius und Terentius litten um das Jahr 250 zu Karthago in der Verfolgung des Decius, drei Namen, die an diesem Tage aus einer grösseren Schar von Bekennern begangen werden, deren Hauptgedächtnis die Kirche im April hält; und die Gottesdienste ihnen zu Ehren wurden vor alters im Kloster Paulopetrion gefeiert, sodass die Hauptstadt des Ostens das Fest der Märtyrer Afrikas beging.", "patron": "Angerufen von Scharen der Bekenner; um die Grube der Schlangen, die nicht schadete."},

"Monastic Martyr Euphrosynus of Blue Jay Lake, Novgorod":
{"type": "Mönchsmärtyrer · 17. Jh.", "life": "Ehrwürdiger Mönchsmärtyrer Jewfrossin vom Blauen See war ein Karelier von Geburt, bei Ladoga im Umkreis des grossen Klosters Walaam aufgewachsen, und diente der Kirche zuerst als Vorleser, ehe er im Dormitio-Kloster zu Tichwin das Mönchsgewand empfing.", "patron": "Angerufen von denen, die bleiben, wenn andere fliehen müssen; von Einsiedlern des Grenzlandes."},

"Apostle Aristobulus of the Seventy, Bishop of Britain":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Aristobulos, einer der Siebzig, wurde auf Zypern geboren, der Bruder des Apostels Barnabas, und begleitete mit seinem Bruder den Apostel Paulos auf seinen Missionsreisen, einer jener Apostel zweiten Ranges, die der Herr vor seinem Angesicht aussandte und welche die Zwölf nach Pfingsten über die Welt verteilten.", "patron": "Angerufen von Glaubensboten an fernen Grenzen; von den ersten Verkündern eines Landes."},

"Saint John of Khakhuli the Oqropiri, also called Chrysostom":
{"type": "Mönch · 11. Jh.", "life": "Ehrwürdiger Iwane von Chachuli, der Okropiri genannt, das ist der Goldmund, war eine der Leuchten des Klosters Chachuli, das König Dawit Kuropalates in der zweiten Hälfte des zehnten Jahrhunderts in der geschichtlichen Landschaft Tao errichtete, an der Schlucht, wo der Fluss Chachuli in den Tortumi mündet.", "patron": "Angerufen von Predigern; von Lehrern."},

"Venerable Hilarion the New, Abbot of Pelekete":
{"type": "Abt (Igumen) · 8. Jh.", "life": "Ehrwürdiger Hilarion der Neue, Abt des Klosters Pelekete bei Prusa in Bithynien, war von Jugend an Gott gegeben, und nachdem er die ganze Schulung des Mönchslebens durchlaufen hatte, Schweigen, Gehorsam, Fasten und den Psalter auswendig, wurde er zum Priester geweiht und mit der Zeit zum Abte von Pelekete gemacht, einem der berühmten Klöster des bithynischen Landes.", "patron": "Angerufen von Äbten in bösen Tagen; von denen, die um Regen und Ernte beten."},

"Saint Patrick, Bishop of Armagh, Enlightener of Ireland":
{"type": "Bischof, Apostelgleicher · 5. Jh.", "life": "Heiliger Patrick, Bischof von Armagh und Erleuchter Irlands, wurde um 387 im römischen Britannien einem christlichen Hause geboren, Sohn des Diakons Calpurnius und Enkel eines Priesters, und lernte mit sechzehn Jahren den Preis des Glaubens, als irische Räuber die Küste überfielen und ihn in die Sklaverei auf jene Insel verschleppten, die er einst in die Kirche führen sollte.", "patron": "Angerufen von Glaubensboten; von Gefangenen und ehemaligen Sklaven."},

"Venerable Paul the Simple, disciple of Venerable Anthony the Great":
{"type": "Mönch · 4. Jh.", "life": "Ehrwürdiger Paulos der Einfältige aus Ägypten hiess der Einfältige um seiner Herzenseinfalt und seiner Sanftmut willen, und er kam durch die Tür eines zerbrochenen Hauses in die Wüste: als Landmann von schon sechzig Jahren entdeckte er die Untreue seiner Frau und antwortete auf das Unrecht weder mit Gewalt noch mit Klage, sondern verliess sie ohne Bitterkeit und ging zum heiligen Antonios dem Grossen.", "patron": "Angerufen von den Alten, die spät beginnen; von den Einfältigen des Herzens."},

"Right-believing Great Prince Rostislav-Michael, Prince of Kyiv":
{"type": "Fürst · 12. Jh.", "life": "Heiliger rechtgläubiger Grossfürst Rostislaw von Kiew, in der heiligen Taufe Michail genannt, war der Sohn Mstislaws des Grossen und der Enkel Wolodymyr Monomachs und trug das Beste jenes Geschlechtes, seine Frömmigkeit und seine Friedfertigkeit, durch eines der streitsüchtigsten Geschlechter der Rus. Als Fürst von Smolensk mehr als dreissig Jahre war er der wahre Gründer jenes Fürstentums.", "patron": "Angerufen von Herrschern; von Friedensstiftern."},

"Martyr Quadratus and those with him at Nicomedia":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Kodratos von Nikomedeia litt mit Saturninus, Rufinus und anderen in den Verfolgungen Kaiser Decius' und seines Nachfolgers Valerian. Aus berühmtem Hause und von beträchtlichem Vermögen, schonte Kodratos sein Gut nicht um Christi willen, sondern wandte es an die Gefangenen: als die Kerker von Nikomedeia sich mit Christen füllten, kam er offen zu ihnen und bestach die Wächter.", "patron": "Angerufen von denen, die Gefangene besuchen; von Reichen, die sich selbst verausgaben."},

"Martyrs Manuel and Theodosius":
{"type": "Märtyrer · 4. Jh.", "life": "Heilige Märtyrer Manuel und Theodosios litten im Jahre 304, auf der Höhe der grossen Verfolgung, und gehören zu jener Schar von Zeugen, die der Tod anderer geworben hat: als sie die Beständigkeit der Märtyrer ihrer Gegend sahen, die mit Freude ertragenen Qualen und die vor der Menge empfangenen Kränze, erschraken die beiden jungen Männer nicht, wie die Verfolger es allen Zuschauern zugedacht hatten.", "patron": "Angerufen von denen, die das Beispiel der Märtyrer bewegt; um das freiwillige Bekenntnis."},

"Venerable Gerasimus of the Jordan":
{"type": "Abt (Igumen) · 5. Jh.", "life": "Ehrwürdiger Gerasimos vom Jordan war eine der grossen Leuchten der palästinischen Wüste, zu Beginn des fünften Jahrhunderts in Lykien einem reichen Hause geboren; er entsagte in der Jugend der Welt und wurde zuerst in den Wüsten der ägyptischen Thebais vollendet und liess sich dann, um das Jahr 450 ins Heilige Land gekommen, am Jordan nieder, wo er eine grosse Lawra gründete.", "patron": "Angerufen von Mönchen der strengen Regel; von denen, die Wildes zähmen."},

"Venerable John the Clairvoyant, Anchorite, of Egypt":
{"type": "Anachoret · 4. Jh.", "life": "Ehrwürdiger Johannes der Hellsichtige, der grosse Anachoret von Lykopolis in der ägyptischen Thebais, war in der Jugend ein Handwerker, ein Bauarbeiter, der als junger Mann die Welt verliess; und nach Jahren der Formung unter den Ältesten schloss er sich um sein vierzigstes Jahr in eine Zelle ein, die er im Felsen über Lykopolis vorbereitet hatte, drei kleine zugemauerte Kammern.", "patron": "Angerufen von Klausnern; von Ratgebern der Herrscher."},

"Saint Sophronius, Bishop of Irkutsk":
{"type": "Bischof · 18. Jh.", "life": "Heiliger Sofronij, Bischof von Irkutsk, wurde 1704 als Stefan Kristalewskij zu Beresan im Poltawaer Lande der Ukraine geboren, einer frommen Familie bescheidener Mittel, und in der blühenden kirchlichen Bildung seiner Heimat geformt.", "patron": "Angerufen von Missionsbischöfen; für die Völker Sibiriens."},

"Monastic Martyr Adrian of Poshekhonye, Yaroslavl":
{"type": "Abt (Igumen), Mönchsmärtyrer · 16. Jh.", "life": "Ehrwürdiger Mönchsmärtyrer Adrian von Poschechonje wurde im Kloster des heiligen Kornilij von Komel zum Mönchsleben geformt, wo er ein geschickter Ikonenmaler wurde, einer aus einer Schar begabter Brüder, die sich um jenen grossen Ältesten sammelten.", "patron": "Angerufen von Ikonenmalern; von Gründern."},

"Apostle Hermes of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Hermes, einer der Siebzig, ist einer der Männer, welche die Schrift mit einem einzigen Worte unsterblich gemacht hat: der Apostel Paulos schreibt am Schluss seines Römerbriefes in der Namensliste der Brüder, die er liebte: Grüsset Asynkritos, Phlegon, Hermas, Patrobas, Hermes und die Brüder bei ihnen; und mit diesem Grusse trat Hermes in den Kanon der Schrift.", "patron": "Angerufen von den Gegrüssten und Unerinnerten; von Bischöfen stiller Stühle."},

"Saint Eustathius (Eustace) the Confessor, Bishop of Bithynia":
{"type": "Bischof, Bekenner · 9. Jh.", "life": "Heiliger Eustathios der Bekenner, Bischof eines Stuhles in Bithynien, weidete seine Herde im Zeitalter der bilderstürmerischen Verfolgung und gehört zu der grossen Schar von Hierarchen, deren gemeinsame Standhaftigkeit die heiligen Ikonen durch den langen Krieg des Reiches gegen sie trug. Von Jugend an in Frömmigkeit und asketischer Mühe geformt, wurde er um seiner Tugenden willen zum Bischof erhoben.", "patron": "Angerufen von Bischöfen, die von ihren Stühlen vertrieben werden; um die Ikonen, die im Entbehren bewahrt werden."},

"Venerable Isaac the Confessor, Founder of the Dalmatian Monastery at Constantinople":
{"type": "Abt (Igumen), Bekenner · 4. Jh.", "life": "Ehrwürdiger Isaakios der Bekenner, Gründer des Dalmatos-Klosters, war ein Einsiedler der syrischen Wildnis, den die Not der Kirche aus seiner Einsamkeit auf den Weg eines Kaisers zog. In den Tagen, da Valens, ein Arianer, die Kirchen von Konstantinopel den Häretikern gegeben und die Orthodoxen vertrieben hatte, kam Isaakios in die Hauptstadt, um die Verfolgten zu stärken.", "patron": "Angerufen von Mönchen, die der Macht entgegentreten; von Gründern."},

"Venerable Simeon the New Theologian":
{"type": "Abt (Igumen) · 11. Jh.", "life": "Ehrwürdiger Symeon der Neue Theologe, den die Kirche als den dritten Träger jenes höchsten Titels neben Johannes den Evangelisten und Gregorios von Nazianz gestellt hat, wurde 949 als Georgios einem vornehmen Hause Galatiens in Paphlagonien geboren und als Knabe nach Konstantinopel gebracht, für die Laufbahn, welche die Stellung seines Oheims am Hofe versprach.", "patron": "Angerufen von Theologen; von geistlichen Vätern."},

"Hieromartyr Irenaeus, Bishop of Sirmium":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Eirenaios, Bischof von Sirmium in Pannonien, litt im Jahre 304 in der grossen Verfolgung, und sein Kampf ist in Akten erster Echtheit bewahrt, unter den kostbarsten der alten Märtyrerberichte. Für sein Amt ein junger Mann und nach der Zucht jener Zeit verheiratet und Vater, wurde Eirenaios als Bischof ergriffen und vor den Statthalter Probus geführt.", "patron": "Angerufen von Bischöfen mit Familien; von denen, deren Liebste gegen ihr Bekenntnis flehen."},

"Saint Theognostus, Metropolitan of Kyiv and All Russia":
{"type": "Metropolit · 14. Jh.", "life": "Heiliger Feognost, Metropolit von Kiew und ganz Russland, war ein Grieche, zu Konstantinopel geboren und gebildet, und wurde 1328 als Nachfolger des heiligen Pjotr für die weite Metropolie der Rus geweiht, dessen frisches Grab zu Moskau den Lauf seines ganzen Vorsteheramtes bestimmte: der neue Metropolit liess sich nieder, wo sein Vorgänger lag, und bestätigte Moskau als Sitz.", "patron": "Angerufen von Vorstehern der Kirche; von Verteidigern ihrer Freiheit."},

"Saint Gregory Dialogus, Pope of Rome":
{"type": "Papst · 7. Jh.", "life": "Heiliger Gregorios der Dialogos, Papst von Rom, wurde um 540 einem Senatorenhause geboren, das der Kirche schon einen Papst gegeben hatte, und stieg durch blosse Tüchtigkeit zum Stadtpräfekten auf, dem höchsten weltlichen Amte, das Rom vergeben konnte; und auf dem Gipfel legte er alles nieder, machte den Familienpalast auf dem Caelius zum Andreas-Kloster, verkaufte die Güter für die Armen und wurde Mönch.", "patron": "Angerufen von Päpsten und Hirten; von Sängern."},

"Martyr Conon of Isauria":
{"type": "Märtyrer · 1. Jh.", "life": "Heiliger Märtyrer Konon von Isaurien wurde im Dorfe Badine bei der Stadt Isauria in Kleinasien geboren, deren Volk den Glauben vom Apostel Paulos empfangen hatte; und von Jugend an stand er unter dem besonderen Schutze des Erzengels Michael, des Führers der himmlischen Heerscharen, der ihm erschien und ihm durch sein ganzes Leben beistand.", "patron": "Angerufen von Eheleuten, die zur Enthaltsamkeit gerufen sind; von denen, die Dämonen bedrängen."},

"Saint Emilian of Rome":
{"type": "Mönch · 6. Jh.", "life": "Ehrwürdiger Aimilianos von Rom, in der Welt Viktorinus, war ein geborener Römer und verbrachte fast sein ganzes Leben in Sünde, und die Kirche bewahrt sein Gedächtnis eben darum, weil die Geschichte dort nicht endete: im Alter kam er zu sich, tat Busse und trat, die Welt verlassend, die seine Jahre verzehrt hatte, in ein Kloster, wo er das Mönchsgewand mit dem Namen Aimilianos empfing.", "patron": "Angerufen von Büssenden im Alter; von denen, die im Verborgenen Busse tun."},

"Saint Hypatius the Wonderworker, Bishop of Gangra":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Hypatios der Wundertäter, Bischof von Gangra in Paphlagonien, stand unter den dreihundertachtzehn gottragenden Vätern des Ersten Ökumenischen Konzils zu Nikaia, ein Bekenner des wesensgleichen Sohnes wider Areios; und sein Volk kannte ihn nicht als Theologen der Konzilien, sondern als den Mann, durch den Gott Wunder tat, denn sein Gebet heilte die Kranken und wandte die Plagen ab.", "patron": "Angerufen von den Vätern von Nikaia; von denen, die Verbitterte angreifen."},

"Forefeast of the Annunciation":
{"type": "Vorfest · 1. Jh.", "life": "An diesem Tage begeht die Kirche das Vorfest der Verkündigung, den einen Tag der Bereitung vor dem Feste, welches die Väter die Krone unseres Heils und den Anfang aller Feste nannten, und die Gesänge des Tages stehen auf Zehenspitzen: heute, singen sie, naht das grosse Geheimnis, der Erzengel wird gesandt, die Jungfrau ist im Gebet, und die Freude der ganzen Schöpfung ist einen Abend entfernt.", "patron": "Angerufen von allen, die sich auf grosse Freude bereiten; um den Vorabend der grossen frohen Botschaft."},

"Saint Cyril, Archbishop of Jerusalem":
{"type": "Erzbischof · 4. Jh.", "life": "Heiliger Kyrillos, Erzbischof von Jerusalem, wurde um 315 in der Heiligen Stadt oder in ihrer Nähe geboren und von Jugend an dem Dienste der Kirche gegeben; zum Priester geweiht, wurde ihm der Unterricht der Katechumenen anvertraut, und aus jener Pflicht ging das Werk hervor, das ihn für immer zum Katecheten der ganzen Kirche gemacht hat, die Katechesen.", "patron": "Angerufen von Katecheten; von Lehrern der Neuerleuchteten."},

"Venerable Hilarion of Pskov, Lake Gdov":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Ilarion von Pskow, auch der von Gdow genannt, war ein Jünger des grossen Jewfrossin von Pskow, des Vaters der Pskower Einödüberlieferung, und trug die Schule seines Ältesten in Strenge und Stille nordwärts bis an den äussersten Rand des russischen Landes.", "patron": "Angerufen von Gründern der Grenzlande; von Jüngern grosser Ältester."},

"Martyr Quadratus and those with him at Corinth":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Kodratos von Korinth wurde in der Wildnis geboren und vom Himmel selbst aufgezogen: während einer Verfolgung des dritten Jahrhunderts floh seine Mutter, eine fromme Frau namens Rufina, aus Korinth in die Berge, um ihren Verfolgern zu entgehen, und gebar dort einen Sohn und starb bald darauf.", "patron": "Angerufen von Ärzten; von Waisen."},

"Synaxis of the Venerable Fathers of the Kyiv Caves Lavra":
{"type": "Synaxis · 11. Jh.", "life": "An diesem Tage feiert die Kirche die Synaxis der ehrwürdigen Väter der Kiewer Höhlenlawra und sammelt die ganze leuchtende Schar jenes Klosters in ein Fest, das dem Mönchtum der ganzen Rus Mutter war; das gemeinsame Gedächtnis wird in der Grossen Fastenzeit begangen, und dabei nennt die Kirche keinen einzelnen Heiligen, weil sie Hunderte nennt.", "patron": "Angerufen von allen Mönchen der Überlieferung der Rus; von den Pilgern zu den Höhlen."},

"Venerable Joasaph of Snetogorsk, Pskov":
{"type": "Abt (Igumen), Hieromärtyrer · 13. Jh.", "life": "Heiliger Hieromärtyrer Ioassaf, Abt des Snetogorsker Klosters bei Pskow, litt mit einer Schar seiner Mönche beim deutschen Einfall, der am Ende des dreizehnten Jahrhunderts über das Pskower Land kam. Snetogorsk, der Geburt der Allheiligen Gottesmutter geweiht, gehörte zu den ältesten Klöstern jener Gegend, und Ioassaf leitete es als Vater und hielt darin ein strenges gemeinsames Leben.", "patron": "Angerufen von Äbten; von Mönchen bedrängter Häuser."},

"Icon of the Mother of God of Lubyatov":
{"type": "Ikone der Gottesmutter · 16. Jh.", "life": "Die Ljubjatower Ikone der Gottesmutter, ein Bild der Zärtlichkeit, wurde im Nikolaos-Kloster zu Ljubjatowo vor den Toren Pskows verwahrt, und ihr Fest bewahrt das Gedächtnis einer einzigen Nacht, in der, wie die Überlieferung des Pskower Landes hält, die Gottesmutter den Untergang einer Stadt abwandte.", "patron": "Angerufen für Städte unter dem Zorn; von Fürbittern für die Verurteilten."},

"Venerable Athanasius of Murom":
{"type": "Abt (Igumen) · 15. Jh.", "life": "Ehrwürdiger Afanassij von Murom war Abt des Klosters, das der heilige Lasar auf der Insel Murom im Onegasee gegründet hatte, und mühte sich dort in der Mitte des fünfzehnten Jahrhunderts, zwei Geschlechter nach dem Gründer; und von seinem gottgefälligen Leben ist, wie die Heiligenleben freimütig festhalten, keine Nachricht bewahrt, denn das schriftliche Gedächtnis des Mannes ging in den Bränden des Nordens unter.", "patron": "Angerufen von verborgenen Asketen; von denen, deren Taten allein Gott erinnert."},

"Hieromartyrs Pionius and Limnus of Smyrna and those with them: Asclepiades, Macedonia, and Sabina":
{"type": "Hieromärtyrer · 3. Jh.", "life": "Heilige Hieromärtyrer Pionios und Limnos, Presbyter, und die Märtyrer Sabina, Makedonia und Asklepiades litten zu Smyrna in der Verfolgung des Decius, in der Kirche, die der Apostel Johannes der Theologe gegründet und das Blut des Polykarpos verherrlicht hatte; und der Kampf des Pionios, in einer der kostbarsten alten Märtyrerakten bewahrt, beginnt mit einer im Martyrologium unerreichten Einzelheit.", "patron": "Angerufen von Presbytern; von Verteidigern des Glaubens."},

"Saint Euthymius, Bishop of Novgorod":
{"type": "Erzbischof · 15. Jh.", "life": "Heiliger Jewfimij, Erzbischof von Nowgorod, war der Sohn eines Nowgoroder Priesters, vor seiner Geburt Gott gelobt, und trat mit fünfzehn Jahren in den Mönchsstand und mühte sich im Kloster Wjaschischtschi bei der Stadt; 1429 auf den erzbischöflichen Thron erwählt, leitete er den grössten Stuhl des russischen Nordens nahezu drei Jahrzehnte und hinterliess ihn verwandelt.", "patron": "Angerufen von Erbauern; von Erneuerern der Heiligtümer."},

"Saint Anastasia the Patrician of Alexandria":
{"type": "Nonne · 6. Jh.", "life": "Ehrwürdige Anastasia die Patrizierin lebte zu Konstantinopel, aus einem vornehmen Hause stammend, ein Bild der Tugend, das die grosse Achtung Kaiser Justinians selbst genoss; und eben jene Achtung wurde die Gefahr ihres Lebens. Jung verwitwet und des Neides und der Ränke müde, die ihre Gunst am Hofe erzeugt hatte, beschloss Anastasia, die Welt zu verlassen und ihre Seele fern der Hauptstadt zu retten.", "patron": "Angerufen von Witwen; von Frauen, die unerwünschte Ehren fliehen."},

"Martyrs Trophimus and Eucarpus of Nicomedia":
{"type": "Märtyrer · 3. Jh.", "life": "Heilige Märtyrer Trophimos und Eukarpos waren Soldaten zu Nikomedeia in den Tagen der grossen Verfolgung um das Jahr 300 und begannen auf der falschen Seite: stolze, gewalttätige Männer, eifrig in der Jagd auf die Christen, unter den Verfolgern durch ihre Grausamkeit hervorstechend, wenn sie die Gläubigen aufspürten, vor die Gerichte schleppten und sich am Schrecken bereicherten.", "patron": "Angerufen von bekehrten Verfolgern; von Soldaten, die von der Grausamkeit lassen."},

"Saint Serapion, Archbishop of Novgorod":
{"type": "Erzbischof · 16. Jh.", "life": "Heiliger Serapion, Erzbischof von Nowgorod, wurde bei Moskau frommen Eltern geboren und diente zuerst als verheirateter Gemeindepriester; verwitwet, empfing er das Mönchsgewand, und die Heiligkeit seines Lebens hob ihn gegen seinen Willen durch die Ämter der Kirche: Abt des Dormitio-Hauses zu Stromyn, dann Abt des grossen Dreifaltigkeitsklosters des heiligen Sergij selbst.", "patron": "Angerufen von abgesetzten Hierarchen; von denen, denen in kirchlichem Streit Unrecht geschieht."},

"Martyr Matrona of Thessalonica":
{"type": "Märtyrerin · 4. Jh.", "life": "Heilige Märtyrerin Matrona von Thessalonike war eine Magd im Hause der Pautila, in den griechischen Berichten Pantila geschrieben, einer vornehmen Jüdin und Frau eines Befehlshabers jener Stadt, und ihr Martyrium vollzog sich ganz innerhalb der Mauern eines Hauses, ohne Gericht, Statthalter oder Erlass, die Verfolgung auf ihr kleinstes und innerstes Mass gebracht, eine Herrin und ein dienendes Mädchen.", "patron": "Angerufen von Dienenden und Versklavten; von denen, die um ihres Gebetes willen bestraft werden."},

"Martyr Sabinus of Egypt":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Sabinus von Ägypten, den die griechischen Kalender an diesem Tage und die slawischen am dreizehnten März begehen, war ein angesehener Bürger von Hermupolis, in der Stadt geachtet und gegen ihre Armen freigebig; und als die Verfolgung unter Diokletian über Ägypten hereinbrach, überredeten ihn die Christen von Hermupolis, sich um der Herde willen zu bewahren, und er zog sich mit wenigen Gefährten zurück.", "patron": "Angerufen von Verratenen; von Wohltätern, denen man mit Bösem lohnte."},

"Martyr Nicander of Egypt":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Nikandros von Ägypten war Arzt und machte in der Verfolgung Diokletians aus seinem Berufe einen doppelten Dienst, den die Erlasse zweifach mit dem Tode bedrohten: er besuchte die gefangenen Christen, behandelte ihre Wunden von den Foltern und brachte ihnen Speise und Trost in die Kerker, wo das Reich sie zwischen den Verhören verkommen lassen wollte.", "patron": "Angerufen von Ärzten; von denen, welche die Toten bestatten."},

"Venerable Arcadius of Cyprus":
{"type": "Mönch · 4. Jh.", "life": "Ehrwürdiger Arkadios von Zypern widmete sich von Jugend an dem Mönchsleben und mühte sich in den Tagen Kaiser Konstantins des Grossen als Asket auf der Insel Zypern; und obgleich die Mühen seiner eigenen Einsamkeit in dem Schweigen bewahrt sind, das die Wüste vorzieht, ist sein Gedächtnis der Kirche für immer durch die beiden Jünger verbunden, die er heranzog, die heiligen Märtyrer Julianos den Arzt und Eubolos.", "patron": "Angerufen von Lehrern; von geistlichen Vätern."},

"Hieromartyr Alexander of Sίdē, in Pamphylia":
{"type": "Hieromärtyrer · 3. Jh.", "life": "Heiliger Hieromärtyrer Alexandros war Priester der Stadt Side in Pamphylien an der Südküste Kleinasiens und litt unter Kaiser Aurelian, im letzten Zucken der Verfolgungen des dritten Jahrhunderts vor dem grossen Sturme Diokletians. Vor den Statthalter Antoninus geführt, wurde der Priester nach Namen und Stand gefragt und antwortete mit dem Bekenntnis, das alles Übrige unausweichlich machte.", "patron": "Angerufen von Priestern vor Gericht; um die freimütige Antwort unter Aurelian."},

"Venerable Theophanes the Confessor of Sigriane":
{"type": "Abt (Igumen), Bekenner · 9. Jh.", "life": "Ehrwürdiger Theophanes der Bekenner von Sigriane wurde um 760 einem vornehmen Hause zu Konstantinopel geboren, früh verwaist und der Vormundschaft des Kaisers selbst anvertraut und auf die höchste Bahn des Hofes gesetzt.", "patron": "Angerufen von Chronisten; von Geschichtsschreibern."},

"Venerable Gerasimus of Vologda":
{"type": "Abt (Igumen) · 12. Jh.", "life": "Ehrwürdiger Gerassim, der erste Wundertäter von Wologda, empfing am vierten März im Dormitio-Kloster zu Gnilez bei Kiew das Mönchsgewand und nahm nach dem Brauche jener Zeit den Namen des Heiligen an, der am Tage seiner Einkleidung begangen wurde, Gerasimos vom Jordan, dessen Fest er fortan teilte.", "patron": "Angerufen von Gründern; von Glaubensboten des Nordens."},

"1st Saturday of Great Lent: The Miracle of the Boiled Wheat":
{"type": "Fest · 4. Jh.", "life": "Am ersten Samstag der Grossen Fastenzeit begeht die Kirche das Wunder des gekochten Weizens, der Kolyva, das der Grossmärtyrer Theodoros der Rekrut ein halbes Jahrhundert nach seinem eigenen Martyrium wirkte, als der tote Streiter Christi über die erste Fastenwoche der Kirche Wache hielt.", "patron": "Angerufen von allen, welche die Fastenzeit halten; von den Versuchten und Getäuschten."},

"Uncovering of the Precious Cross and the Precious Nails by Empress Saint Helen in Jerusalem":
{"type": "Fest · 4. Jh.", "life": "Gedächtnis der Auffindung des kostbaren Kreuzes und der kostbaren Nägel durch die heilige Kaiserin Helena, die Mutter des heiligen Konstantin des Grossen, im Jahre 326. Von ihrem Sohne, dem Kaiser, und von ihrer eigenen grossen Liebe zu Christus bewegt, zog die betagte Helena nach Jerusalem, um die heiligen Stätten zu suchen, welche die Heiden lange entweiht und verschüttet hatten.", "patron": "Angerufen von allen, die das Verschüttete suchen; von Pilgern."},

"Right-believing Prince Basil (Vasilko) of Rostov":
{"type": "Fürst, Leidensdulder · 13. Jh.", "life": "Heiliger rechtgläubiger Fürst Wassilko von Rostow gehörte zur Susdaler Linie der Monomachowitschi, ein Enkel Wsewolods, des Grossen Nestes genannt, und Sohn des frommen Fürsten Konstantin von Rostow; und die Chroniken des Nordens erinnern ihn als die Blüte seines Geschlechts, schön, tapfer, freigebig und fromm, von seinem Volke und vom Klerus geliebt, dessen Rat er hielt.", "patron": "Angerufen von Herrschern unter der Eroberung; von den Jungen."},

"Righteous Phineas the grandson of Aaron":
{"type": "Gerechter, Priester · 15. Jh. v. Chr.", "life": "Der gerechte Pinhas, der Enkel Aarons und Sohn des Hohenpriesters Eleasar, steht in der Schrift als das Vorbild des heiligen Eifers, der Priester, dessen einzige Tat eine Plage zum Stehen brachte und einen Bund erwarb. In der Wüste zu Sittim, als Israel sich an Baal-Peor hängte und in offene Befleckung mit den Töchtern Moabs fiel und die Plage des Zornes des Herrn das Lager verzehrte, stand er auf.", "patron": "Angerufen von Priestern; von denen, die um die Ehre Gottes eifern."},

"Monastic Martyr Eustratius of the Kyiv Near Caves":
{"type": "Mönchsmärtyrer · 11. Jh.", "life": "Ehrwürdiger Mönchsmärtyrer Ewstratij aus den Kiewer Nahen Höhlen, der Faster genannt, war ein Kiewer, der sein Gut den Armen gab und in den Höhlen das Mönchsgewand empfing, wo sein Fasten so streng war, dass die Brüder ihm den Namen gaben, den er trägt.", "patron": "Angerufen von Gefangenen; von Fastenden."},

"Venerable Lazarus of Murom":
{"type": "Abt (Igumen) · 14. Jh.", "life": "Ehrwürdiger Lasar von Murom war ein Grieche, zu Konstantinopel geboren, der in seiner Vaterstadt im Hochberg-Kloster unter dem Ältesten Athanasios Diskotes Mönch wurde, einem Erbauer vieler Klöster, und nach acht Jahren unter die Führung des Bischofs Basileios von Kaisareia trat; und 1343 sandte jener Bischof den schon als Ikonenmaler bekannten Lasar mit Mönchen und Gaben in die Rus.", "patron": "Angerufen von Ikonenmalern; von Glaubensboten des Nordens."},

"Translation of the relics of Saint Nikephoros, Patriarch of Constantinople":
{"type": "Patriarch, Bekenner · 9. Jh.", "life": "Übertragung der Reliquien des heiligen Nikephoros, Patriarchen von Konstantinopel, eines der grossen Bekenner der heiligen Ikonen, dessen Hauptfest im Juni begangen wird; das Gedächtnis im März bezeichnet den Tag seiner triumphalen Rückkehr in die Stadt, der nach Gottes genauer Rechnung auch der Tag seiner Vertreibung aus ihr gewesen war.", "patron": "Angerufen von Patriarchen; von Theologen der Ikone."},

"Apostle Sosthenes of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Sosthenes, einer der Siebzig, tritt zweimal in die Schrift, einmal geschlagen und einmal segnend, und der Abstand zwischen beiden ist die Geschichte seiner Seele. In der Apostelgeschichte ist er Vorsteher der Synagoge zu Korinth, als die Juden sich gegen Paulos erhoben und ihn vor den Richterstuhl des Prokonsuls Gallio schleppten.", "patron": "Angerufen von Bekehrten aus den Reihen der Gegner; von denen, die zu Unrecht geschlagen werden."},

"Venerable John the Anchorite of Egypt":
{"type": "Anachoret · 4. Jh.", "life": "Ehrwürdiger Johannes der Anachoret aus Ägypten wird an diesem Tage unter den Vätern der Wüste begangen, deren Namen die Kirche bewahrt hat, während die Wüsten ihre Geschichten behielten, einer aus dem grossen namenlosen Heere der Anachoreten, jener Männer, die noch über die Skiten und Lawren hinaus in die völlige Einsamkeit zogen und deren Berufung es war, keine Zeugen zu hinterlassen.", "patron": "Angerufen von Einsiedlern; von den Verborgenen."},

"120 Martyrs of Persia":
{"type": "Märtyrer · 4. Jh.", "life": "Die hundertzwanzig heiligen Märtyrer Persiens litten um das Jahr 344 in der grossen Verfolgung des Königs Sapor des Zweiten, in den Jahren, da das persische Reich, im Kriege mit dem neu christlich gewordenen Reiche der Römer, sich gegen die Kirche in seinen eigenen Grenzen wandte wie gegen eine feindliche Ansiedlung, und die Bekenner Christi in Mesopotamien und Persien zu Tausenden ergriffen wurden.", "patron": "Angerufen von Gefangenen; von Scharen der Bekenner."},

"3rd Sunday of Great Lent: Veneration of the Cross":
{"type": "Fest · 4. Jh.", "life": "Am dritten Sonntag der Grossen Fastenzeit trägt die Kirche das kostbare und lebenspendende Kreuz hervor und stellt es, mit Blumen geschmückt, zur Verehrung für die folgende Woche inmitten der Gläubigen auf; und die Stellung ist die ganze Theologie des Tages, denn das Kreuz wird genau in die Mitte der Fastenzeit gepflanzt, in die Mitte der vierzig Tage, als ein Baum der Rast auf halbem, hartem Wege.", "patron": "Angerufen von allen, die Kreuze tragen; von den Müden auf halbem Wege."},

"4th Sunday of Great Lent: St John Climacus (of the Ladder)":
{"type": "Fest · 7. Jh.", "life": "Am vierten Sonntag der Grossen Fastenzeit stellt die Kirche ihren Kindern den heiligen Johannes Klimakos vor Augen, den Abt des Sinai und Verfasser der Leiter zum Paradies, und die Anordnung ist bedachte Unterweisung: über die Mitte der Fastenzeit hinaus, mit dem verehrten Kreuze und dem noch nicht sichtbaren Pascha, bringt die Kirche ihren Meister der geistlichen Landkarte hervor.", "patron": "Angerufen von allen, die zu Gott aufsteigen; von den Kämpfenden in der Mitte der Fastenzeit."},

"5th Saturday of Great Lent: of the Akathist to the Theotokos":
{"type": "Fest · 7. Jh.", "life": "Am fünften Samstag der Grossen Fastenzeit begeht die Kirche das Fest des Akathistos und singt in einer feierlichen Nacht den ganzen grossen Hymnus an die Allheilige Gottesmutter, den sie im übrigen Jahr in Teilen singt; und das Fest ist ebenso sehr ein Denkmal des Krieges wie ein Gottesdienst, denn es wurde zum Danke für die Errettungen Konstantinopels eingesetzt.", "patron": "Angerufen von allen, die zur Gottesmutter fliehen; von belagerten Städten."},

"Apostle and Evangelist Luke of the Seventy":
{"type": "Apostel, Evangelist · 1. Jh.", "life": "Heiliger Apostel und Evangelist Lukas, den die Kalender dieses Tages mit den Aposteln Nathanael und Klemens begehen und dessen Hauptfest die Kirche im Oktober hält, war ein Grieche aus Antiochien, Arzt von Beruf und, wie die Überlieferung hinzufügt, Maler, sodass die beiden Künste des Leibes und des Auges ganz in den Dienst des Evangeliums traten.", "patron": "Angerufen von Ärzten; von Ikonenmalern und Malern."},

"Apostle Herodion of the Seventy, and those with Him":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "An diesem Tage begeht die Kirche sechs Apostel der Siebzig gemeinsam, Herodion, Agabos, Rufus, Asynkritos, Phlegon und Hermes, eine Schar, die vor allem aus einer einzigen Seite der Schrift gesammelt ist, dem sechzehnten Kapitel des Römerbriefes, wo der Apostel Paulos, als er die Kirche der Hauptstadt Namen für Namen grüsste, unwissentlich ein Stück des Kalenders der Kirche diktierte.", "patron": "Angerufen von Bischöfen der ersten Pflanzung; von Propheten."},

"Apostle James the Brother of Saint John the Theologian":
{"type": "Apostel, Märtyrer · 1. Jh.", "life": "Heiliger Apostel Jakobos, der Sohn des Zebedaios und Bruder des Johannes des Theologen, wurde mit seinem Bruder in einem einzigen Rufe von den Netzen Galiläas gerufen, und die beiden liessen auf ein Wort hin ihren Vater im Boote; und der Herr gab dem Paare den Beinamen Boanerges, Söhne des Donners, um des Feuers willen, das in ihnen war.", "patron": "Angerufen von Aposteln und Glaubensboten; von den Söhnen des Donners."},

"Apostle Nathaniel of the Seventy":
{"type": "Apostel · 1. Jh.", "life": "Heiliger Apostel Nathanael, der an diesem Tage mit Lukas und Klemens begangen wird, ist der Mann aus Kana in Galiläa, dessen Berufung das Evangelium des Johannes als eines seiner Kleinode bewahrt: als Philippos ihn mit der Kunde fand, man habe den gefunden, von dem Moses und die Propheten geschrieben haben, Jesus von Nazareth, antwortete Nathanael mit dem redlichen Vorurteil eines redlichen Mannes: Kann aus Nazareth etwas Gutes kommen?", "patron": "Angerufen von den Arglosen; von Schülern der Schrift."},

"Apostle Pudens of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Pudens, einer der Siebzig, war ein Römer senatorischen Ranges und steht in der Schrift in einem einzigen Gruss, denn der Apostel Paulos sendet Timotheos in seinem letzten Briefe aus dem römischen Kerker die Grüsse des Eubulos, des Pudens, des Linos und der Klaudia, den verbliebenen Kreis des verurteilten Apostels in der Hauptstadt in vier Namen zusammengefasst.", "patron": "Angerufen von Gastgebern der Kirche; von Häusern, die zu Kirchen werden."},

"Apostle Trophimus of the Seventy":
{"type": "Apostel der Siebzig · 1. Jh.", "life": "Heiliger Apostel Trophimos, einer der Siebzig, war ein Grieche aus Ephesos, einer jener Heidenchristen, die der Apostel Paulos als Weggefährten an sich band, und die Schrift zeigt ihn dreimal, und jeder Blick ist eine Station der Jüngerschaft. Zuerst erscheint er unter den Abgesandten, die Paulos aus Griechenland mit der Sammlung für die armen Heiligen nach Jerusalem begleiteten.", "patron": "Angerufen von Gefährten der Grossen; von den Kranken, die zurückbleiben."},

"Apostles Jason and Sosipater of the Seventy, the Virgin Kerkyra, and those with them":
{"type": "Apostel der Siebzig, Märtyrer · 1. Jh.", "life": "Heilige Apostel Jason und Sosipatros, aus den Siebzig, samt der Jungfrau Kerkyra und den Ihren schenkten der Kirche eine der vollständigsten Inselbekehrungen des apostolischen Zeitalters; Jason stammte aus Tarsos, der erste Christ der Vaterstadt des Apostels Paulos, und Sosipatros aus Achaia, und Paulos nennt sie im Römerbriefe seine Verwandten.", "patron": "Angerufen von Inselkirchen; von Gefangenen und denen, die sie bekehren."},

"Childmartyr Gabriel of Bialystok":
{"type": "Kind und Märtyrer · 17. Jh.", "life": "Heiliger Kindmärtyrer Gawriil von Białystok wurde 1684 im Dorfe Swerki bei Białystok geboren, der Sohn frommer orthodoxer Dorfleute, Pjotr und Anastasija, und lebte die sechs kurzen Jahre, die ihm gegeben waren, in der gewöhnlichen Heiligkeit einer geliebten Bauernkindheit: Gebete am Knie der Mutter, die Feste der Kirche, die Felder.", "patron": "Angerufen von Kindern; von den Unschuldigen und Wehrlosen."},

"Constantinople Icon of the Mother of God":
{"type": "Ikone der Gottesmutter · 1. Jh.", "life": "An diesem Tage begeht die Kirche die Konstantinopler Ikone der Allheiligen Gottesmutter, ein Bild, das die Überlieferung zu jenen zählt, die der heilige Apostel und Evangelist Lukas selbst gemalt hat, der Arzt und Ikonenmaler der Gottesmutter, dessen Pinsel, wie die Kirche hält, den Gläubigen zuerst ihr Abbild gab und ihren eigenen Segen über das Werk empfing.", "patron": "Angerufen von Ikonenmalern; von allen, welche die Ikonen der Gottesmutter ehren."},

"Hieromartyr Antipas, Bishop of Pergamum and Disciple of Saint John the Theologian":
{"type": "Hieromärtyrer · 1. Jh.", "life": "Heiliger Hieromärtyrer Antipas, Bischof von Pergamon, trägt eine Auszeichnung, die kein anderer Märtyrer der Kirche teilt: dass sein Zeugnis in der Schrift durch die Stimme Christi selbst bestätigt wird; denn in der Offenbarung, im Sendschreiben an die Gemeinde zu Pergamon, spricht der Herr: Ich weiss, wo du wohnst, da des Satans Thron ist, und hältst an meinem Namen und hast meinen Glauben nicht verleugnet.", "patron": "Angerufen von Bischöfen der apostolischen Pflanzung; von denen, die an den Zähnen leiden."},

"Hieromartyr Artemon of Laodikeia":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Artemon, Presbyter von Laodikeia in Syrien, gab der Kirche ein ganzes Leben, ehe er ihr sein Blut gab: christlichen Eltern geboren, diente er sechzehn Jahre als Vorleser, achtundzwanzig als Diakon und dreiunddreissig als Priester, siebenundsiebzig Jahre in den aufsteigenden Ordnungen des Heiligtums, sodass die Verfolgung Diokletians zu Laodikeia einen Ältesten fand, den drei Geschlechter kannten.", "patron": "Angerufen von Vorlesern, Diakonen und Priestern; von den lange Dienenden."},

"Hieromartyr Basil, Bishop of Amasea":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Basileios, Bischof von Amaseia im Pontos, gewann seinen Kranz in der allerletzten Stunde der Verfolgung unter Licinius, als der Mitkaiser des Ostens seine Zusagen der Duldung brach und sich aus Eifersucht auf Konstantin wieder gegen die Christen wandte; und der Kampf des Basileios erwuchs aus einer Tat der Zuflucht.", "patron": "Angerufen von Bischöfen, die Gejagte bergen; von Beschützern gefährdeter Frauen."},

"Hieromartyr Desan, Bishop in Persia, and 272 others with him":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Desan, Bischof in Persien, litt mit zweihundertzweiundsiebzig Gefährten in der Verfolgung des Königs Sapor des Zweiten, etwa in den Jahren 362 bis 364, und ihr Kampf bewahrt das Gedächtnis einer der bezeichnenden Grausamkeiten jener Verfolgung, des Martyriums der Verschleppten. Als die persischen Heere die römischen Grenzfestungen Mesopotamiens nahmen, führten sie die Christen fort.", "patron": "Angerufen von verschleppten Gemeinden; von Klerikern samt ihrem Volke."},

"Hieromartyr Januarius, Bishop of Benevento, and his companions, at Pozzuoli":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Januarius, Bischof von Benevent, litt mit seinen Gefährten im Jahre 305 zu Puteoli, auf dem Höhepunkt der Verfolgung Diokletians, und sein Leiden ist ein Bild von den Banden der Liebe in der alten Kirche, denn er wurde eines Besuches wegen ergriffen: als sein Diakon Sossius von Misenum und andere Kleriker gefangen lagen, ging er zu ihnen.", "patron": "Angerufen von Bischöfen samt ihren Diakonen; von Städten und ihren Schutzherren."},

"Hieromartyr Nikḗtas":
{"type": "Hieromärtyrer · 19. Jh.", "life": "Heiliger Hieromärtyrer Niketas der Neue, den die Kalender dieses Tages begehen, war ein Hieromonach der Skite der heiligen Anna auf dem Heiligen Berge und gehört zu der leuchtenden Schar der athonitischen Neumärtyrer, jener Mönche, welche der Heilige Berg in den Jahrhunderten des türkischen Joches mit Bedacht reifte und ins Martyrium entliess.", "patron": "Angerufen von Hieromonachen; von Predigern unter feindlicher Macht."},

"Hieromartyr Paphnutius of Jerusalem":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Hieromärtyrer Paphnutios von Jerusalem litt in der letzten grossen Verfolgung, in den Jahren Diokletians und seiner Mitkaiser, und die Kalender bewahren sein Gedächtnis mit einem Titel und einer Schar: als Bischof durchlief er, wie die Berichte festhalten, die ganze aufsteigende Reihe der Argumente des Gerichtes, mit Feuer gefoltert, den wilden Tieren vorgeworfen und zuletzt mit dem Schwerte enthauptet.", "patron": "Angerufen von Bischöfen in den Bergwerken und Kerkern; von Scharen der Verbannten."},

"Hieromartyr Patriarch Gregory V of Constantinople":
{"type": "Hieromärtyrer, Patriarch · 19. Jh.", "life": "Heiliger Hieromärtyrer Gregorios der Fünfte, Patriarch von Konstantinopel, wurde 1746 als Georgios Angelopoulos zu Dimitsana auf der Peloponnes armen und frommen Eltern geboren und stieg durch Gelehrsamkeit und Strenge über die Klöster und die Metropolie von Smyrna auf den ökumenischen Thron, den er dreimal einnahm, mit Verbannungen auf dem Athos dazwischen.", "patron": "Angerufen von Patriarchen; für das griechische Volk."},

"Hieromartyr Simeon, Bishop in Persia, and those with him":
{"type": "Hieromärtyrer, Erzbischof · 4. Jh.", "life": "Heiliger Hieromärtyrer Symeon, Erzbischof von Seleukeia-Ktesiphon und Vorsteher der Kirche Persiens, stand an ihrer Spitze, als König Sapor der Zweite, im Kriege mit dem christlichen Reiche der Römer, über seine eigenen christlichen Untertanen jene Verfolgung eröffnete, die vierzig Jahre währen und ungezählte Tausende ernten sollte.", "patron": "Angerufen von Vorstehern unter der Verfolgung; von Klerikern, die mit ihrem Bischof erschlagen werden."},

"Hieromartyr Simeon, kinsman of the Lord, second Bishop of Jerusalem":
{"type": "Hieromärtyrer, Apostel · 2. Jh.", "life": "Heiliger Hieromärtyrer Symeon, ein Verwandter des Herrn und zweiter Bischof von Jerusalem, war der Sohn des Klopas, des Bruders des gerechten Joseph des Verlobten, und so nach der Rechnung des Gesetzes ein Vetter des Herrn dem Fleische nach, einer aus jenem Familienkreise, den der Unglaube einst zum Anstoss nahm und die Gnade zu einer Pflanzstätte von Bischöfen machte.", "patron": "Angerufen von Bischöfen langer Amtszeit; von den Verwandten des Herrn."},

"Hieromartyr Theodore of Perge in Pamphylia, his mother, Philippa, and Martyrs Dioscorus, Socrates, and Dionysius":
{"type": "Märtyrer · 2. Jh.", "life": "Heiliger Märtyrer Theodoros von Perge in Pamphylien litt im zweiten Jahrhundert unter Antoninus samt seiner Mutter Philippa und den Märtyrern Dioskoros, Sokrates und Dionysios, und sein Leiden sammelt in einem Kampfe die drei liebsten Bekehrungen der Kirche: den Sohn, die Mutter und die Henker.", "patron": "Angerufen von jungen Ausgehobenen; von Müttern der Märtyrer."},

"Hieromartyr Zeno, Bishop of Verona":
{"type": "Hieromärtyrer · 4. Jh.", "life": "Heiliger Zeno, Bischof von Verona, stammte, wie die Überlieferung hält, aus Afrika und brachte in den italischen Norden das Feuer der afrikanischen Kirche, die dem lateinischen Abendlande seine ersten grossen Stimmen gegeben hatte; um das Jahr 362 auf den Stuhl von Verona erhoben, führte er die Stadt durch die letzten Zuckungen des Heidentums und die Hochflut der arianischen Wirren, und seine Waffen waren zwei: das Taufbecken und die Predigt.", "patron": "Angerufen von Predigern; von Fischern und Anglern."},

"Holy Virgin Martyr Theodosίa of Tyre":
{"type": "Jungfrau und Märtyrerin · 4. Jh.", "life": "Heilige Jungfrau und Märtyrerin Theodosia von Tyros war ein Mädchen von noch nicht achtzehn Jahren, und ihr Martyrium, das Eusebios aufzeichnete, der jene Tage zu Kaisareia durchlebte, begann mit einer Tat der Ehrfurcht. Eine Schar von Bekennern sass in Ketten vor dem Richterstuhl des Statthalters zu Kaisareia und wartete auf das Urteil.", "patron": "Angerufen von den Jungen; von denen, welche die Bekenner ehren."},

"Martyr Abraham of Bulgaria":
{"type": "Märtyrer · 13. Jh.", "life": "Heiliger Märtyrer Awraamij von Bulgarien, der Wundertäter von Wladimir, war ein Sohn der Wolgabulgaren, unter den Muslimen des Kama- und Wolgalandes geboren und in ihrem Glauben erzogen, ein reicher Kaufmann, der schon vor seiner Bekehrung um einer Güte gegen die Armen und Notleidenden willen bekannt war, die seinem Bekenntnis vorauslief.", "patron": "Angerufen von Kaufleuten; von Bekehrten aus dem Islam."},

"Martyr Alexandra the Empress, wife of Diocletian":
{"type": "Märtyrerin · 4. Jh.", "life": "Heilige Märtyrerin Alexandra die Kaiserin, welche die Überlieferung als die Gemahlin Diokletians selbst nennt, gewann ihren Kranz im Mittelpunkt der Verfolgung, in dem Saale, in dem sie geführt wurde; denn während der Tage des Kampfes des Grossmärtyrers Georgios sah die Kaiserin von ihrem Platze neben dem Throne zu, und was das Schauspiel den Speerträgern und den Dienern lehrte, lehrte es auch sie.", "patron": "Angerufen von Frauen der Verfolger; von Kaiserinnen und Hochgestellten."},

"Martyr Ardalion the Actor":
{"type": "Märtyrer · 4. Jh.", "life": "Heiliger Märtyrer Ardalion der Schauspieler gewann seinen Kranz mitten in einer Vorstellung, und die Kirche hat seinen Kampf immer als einen der kühnsten Überfälle der Gnade in Ehren gehalten. Als begabter Mime des Theaters unter Maximian Galerius wurde er in einem Schauspiel besetzt, das die Menge auf Kosten der Christen belustigen sollte: er sollte einen Christen im Verhör spielen.", "patron": "Angerufen von Schauspielern und Künstlern; von allen, deren Kunst zur Wahrheit wird."},

"Martyr Crescens of Myra in Lycia":
{"type": "Märtyrer · 3. Jh.", "life": "Heiliger Märtyrer Kreskes von Myra in Lykien war ein Mann vornehmen Geschlechts und hohen Alters, der nicht zusehen konnte, wie seine Stadt anbetete, was ihre eigenen Hände gemacht hatten: als er den Götzendienst siegreich und seine Nachbarn den leblosen Dingen unterworfen sah, ging der Greis aus eigenem Antrieb in ihre Mitte und ermahnte sie, den eitlen Irrtum zu lassen und zu dem Gott zurückzukehren, den die Christen anbeten.", "patron": "Angerufen von Betagten im Zeugnis; von denen, die zur Verstellung gedrängt werden."},
}
